/** The BLS series ID behind an OEWS row: OEU + area + industry 000000 + SOC + datatype. */
function oewsSeriesId(areaKey, soc, datatype = '08') {
  const area = WAGE_AREAS[areaKey];
  if (!area) return null;
  return `OEU${area.bls_area}000000${String(soc).replace('-', '')}${datatype}`;
}

const OEWS_MEDIAN_WAGES = Object.freeze(
  OEWS_ROWS.map(([area, soc, hourly, annual]) =>
    Object.freeze({
      area,
      area_name: WAGE_AREAS[area]?.name,
      soc,
      occupation: OCCUPATIONS[soc],
      median_hourly_usd: hourly,
      median_annual_usd: annual,
      series_id: oewsSeriesId(area, soc, '08'),
      source: 'bls_oews_may2025',
    }),
  ),
);

