/** The finest area key a table carries for a place: metro, then state, then national. */
function areaKeyFor(table, place = {}) {
  if (place.cbsa_code && table[`CBSA:${place.cbsa_code}`]) return { key: `CBSA:${place.cbsa_code}`, level: 'metro' };
  if (place.state_code && table[`ST:${place.state_code}`]) return { key: `ST:${place.state_code}`, level: 'state' };
  return { key: 'US', level: 'national' };
}

/**
 * Model policy choices. These are not benchmarks, and they are printed as assumptions.
 * Each carries the reason it is set where it is.
 */
const MODEL_ASSUMPTIONS = Object.freeze({
  hours_per_fte_year: { value: 2080, basis: 'assumption', rationale: 'The same full-time year BLS uses to annualize OEWS hourly wages.' },
  part_time_fte: { value: 0.5, basis: 'assumption', rationale: 'A role described only as part-time is modeled at 20 hours a week until hours are stated.' },
  weekend_fte: { value: 0.4, basis: 'assumption', rationale: 'A weekend-only role is modeled at 16 hours a week (two 8-hour days) until hours are stated.' },
  health_benefit_min_fte: { value: 0.75, basis: 'assumption', rationale: 'The employer health contribution is applied only to roles at or above 30 hours a week, and only in industries where offering it is the norm for hiring.' },
  target_operating_margin: { value: 0.12, basis: 'assumption', rationale: 'Steady-state revenue is sized to cover the modeled costs with a modest margin. This is a sizing target, not a market forecast.' },
  contingency_share: { value: 0.1, basis: 'assumption', rationale: 'Held back from any raise or loan as an unallocated reserve against cost overruns.' },
  software_month12_fraction_of_steady_state: { value: 0.2, basis: 'assumption', rationale: 'Subscription revenue accumulates customer by customer, so a new software product is modeled at one fifth of its cost-covering run rate after the first year, not at the full rate a storefront reaches.' },
  dscr_flag_threshold: { value: 1.25, basis: 'assumption', rationale: 'A coverage level many lenders underwrite to. SBA program minimums can be lower, so this is the conservative line to plan against. Confirm with the lender.' },
  pre_opening_utilities_share: { value: 0.25, basis: 'assumption', rationale: 'While the space is being built out the business pays utilities at about a quarter of the full-operation level (lighting, heat and trade use, no cooking or service). From the lease start to opening.' },
  street_front_rent_factor: { value: 2, low: 1.5, high: 3, basis: 'assumption', rationale: 'Published retail asking rents cover shopping centers. Street-front space in the central city of a large metro leases well above them, so the plan carries rent as an allowance at twice the published shopping-center rate, within a planning range of 1.5 to 3 times, until a lease quote replaces it.' },
  // How far the capital need reaches. A professional plan does not borrow to fund years of losses:
  // the need is start-up, pre-opening and the operating losses until monthly cash break-even, capped
  // at this many months after opening, plus the contingency. No published SBA or SBDC figure sets
  // the cap, so it is a planning convention and printed as one.
  runway_horizon_months_after_opening: { value: 12, basis: 'assumption', rationale: 'The capital need covers start-up and pre-opening costs and the operating losses until the business reaches monthly cash break-even, up to 12 months after opening, plus the contingency. A plan that is not cash-positive by then shows the further shortfall instead of borrowing to fund it. This is a planning convention, not an SBA rule.' },
  equity_runway_months_default: { value: 18, basis: 'assumption', rationale: 'An equity raise is sized to a runway, not to break-even. With no runway stated, the plan funds 18 months from the raise, the short end of the 18 to 24 months early-stage rounds are commonly sized for. A planning convention.' },
  equity_injection_min_share: { value: 0.1, basis: 'assumption', rationale: 'The owner-equity line the plan checks against: SBA 7(a) loans to a start-up require the owners to inject at least 10% of total project costs (SOP 50 10 8). Lenders often ask for 15% to 20%.', reference: 'sba_sop_50_10_8' },
  default_loan_term_years: { value: 10, basis: 'assumption', rationale: 'The SBA 7(a) maximum for working capital, equipment and leasehold improvements, used when no term has been quoted.' },
  // Straight-line book lives. IRS Publication 946 gives tax recovery periods (5 years for restaurant
  // and retail equipment and for computers, 7 for furniture and fixtures, 15 for qualified
  // improvement property) and section 195 amortizes start-up costs over 180 months. A plan's book
  // depreciation is a management choice; these lives sit between the tax periods and the assets'
  // class lives, and are printed as assumptions.
  depreciation_life_equipment_years: { value: 7, basis: 'assumption', rationale: 'Commercial kitchen, studio and service equipment, straight line over 7 years (IRS class life 9 years, tax recovery 5 years).', reference: 'irs_p946_2025' },
  depreciation_life_furniture_years: { value: 7, basis: 'assumption', rationale: 'Furniture and fixtures, straight line over 7 years (the IRS recovery period for furniture and fixtures).', reference: 'irs_p946_2025' },
  depreciation_life_technology_years: { value: 5, basis: 'assumption', rationale: 'Computers and point-of-sale hardware, straight line over 5 years (the IRS recovery period for computers).', reference: 'irs_p946_2025' },
  depreciation_life_buildout_years: { value: 10, basis: 'assumption', rationale: 'Leasehold improvements, straight line over 10 years, assuming a lease of at least that length (tax recovery 15 years for qualified improvement property).', reference: 'irs_p946_2025' },
  depreciation_life_startup_years: { value: 15, basis: 'assumption', rationale: 'Licenses, branding, launch marketing and other start-up costs, amortized straight line over 15 years, the 180-month period section 195 uses.', reference: 'irs_i4562_2025' },
});

/**
 * The finest-grained wage row available for an occupation in a place.
 * Order: the metro (CBSA), then the state, then the national median. The level used is returned
 * so the caller can say so.
 *
 * @param {string} soc
 * @param {{ cbsa_code?: string|null, state_code?: string|null }} place
 */
function lookupMedianWage(soc, place = {}) {
  const tries = [];
  if (place.cbsa_code) tries.push({ key: `CBSA:${place.cbsa_code}`, level: 'metro' });
  if (place.state_code) tries.push({ key: `ST:${place.state_code}`, level: 'state' });
  tries.push({ key: 'US', level: 'national' });
  for (const t of tries) {
    const row = OEWS_MEDIAN_WAGES.find((r) => r.area === t.key && r.soc === soc);
    if (row) return { ...row, level: t.level };
  }
  return null;
}

/** Every data row in the table, flattened, for the provenance test and the plan's source list. */
function allBenchmarkRows() {
  const rows = [];
  for (const r of OEWS_MEDIAN_WAGES) rows.push({ table: 'oews', id: `${r.area}/${r.soc}`, source: r.source });
  for (const [k, v] of Object.entries(FEDERAL_PAYROLL_TAX)) rows.push({ table: 'federal_payroll_tax', id: k, source: v.source });
  for (const [k, v] of Object.entries(STATE_UNEMPLOYMENT_INSURANCE)) rows.push({ table: 'state_ui', id: k, source: v.source });
  for (const [k, v] of Object.entries(WORKERS_COMP_INDEX.states)) rows.push({ table: 'workers_comp', id: k, source: v.source });
  rows.push({ table: 'workers_comp', id: 'median', source: WORKERS_COMP_INDEX.median.source });
  for (const [k, v] of Object.entries(HEALTH_BENEFIT)) rows.push({ table: 'health_benefit', id: k, source: v.source });
  for (const [k, v] of Object.entries(SOI_EXPENSE_RATIOS)) rows.push({ table: 'soi_ratios', id: k, source: v.source });
  for (const [k, v] of Object.entries(INDUSTRY_RATIOS)) rows.push({ table: 'industry_ratios', id: k, source: v.source });
  SBA_7A.spreads.forEach((s, i) => rows.push({ table: 'sba_7a', id: `spread_${i}`, source: s.source }));
  for (const [k, v] of Object.entries(INDUSTRY_MARKET_DATA)) {
    rows.push({ table: 'industry_market', id: `${k}/cbp`, source: v.cbp.source });
    if (v.econ) rows.push({ table: 'industry_market', id: `${k}/econ`, source: v.econ.source });
    if (v.ep) rows.push({ table: 'industry_market', id: `${k}/ep`, source: v.ep.source });
  }
  rows.push({ table: 'industry_market', id: 'restaurant_outlook', source: RESTAURANT_INDUSTRY_OUTLOOK.source });
  for (const [k, v] of Object.entries(AREA_DEMOGRAPHICS)) rows.push({ table: 'area_demographics', id: k, source: v.source });
  for (const [k, v] of Object.entries(CONSUMER_SPENDING)) rows.push({ table: 'consumer_spending', id: k, source: v.source });
  for (const [k, v] of Object.entries(REGIONAL_PRICE_PARITIES)) rows.push({ table: 'regional_price_parities', id: k, source: v.source });
  for (const [k, v] of Object.entries(RETAIL_ASKING_RENT)) rows.push({ table: 'retail_asking_rent', id: k, source: v.source });
  for (const [k, v] of Object.entries(STARTUP_COST_BENCHMARKS)) {
    if (v.source) rows.push({ table: 'startup_costs', id: k, source: v.source });
    for (const also of v.also || []) rows.push({ table: 'startup_costs', id: `${k}/${also}`, source: also });
    if (v.space_factor_source) rows.push({ table: 'startup_costs', id: `${k}/space_factor`, source: v.space_factor_source });
  }
  for (const [k, v] of Object.entries(MODEL_ASSUMPTIONS)) if (v.reference) rows.push({ table: 'depreciation_reference', id: k, source: v.reference });
  for (const [k, v] of Object.entries(FLOOR_AREA_SQ_FT)) if (v.source) rows.push({ table: 'floor_area', id: k, source: v.source });
  for (const k of ['max_term_years_non_real_estate', 'max_term_years_real_estate', 'prime_rate']) {
    rows.push({ table: 'sba_7a', id: k, source: SBA_7A[k].source });
  }
  return rows;
}


/**
 * When the business can open, when each licensed product line can start selling, and when the
 * pre-opening costs begin.
 *
 * The plan's own licensing research (compliance-calendar.js) gives each permit a planning lead time,
 * counted from month 1 of the plan. A business cannot open before the permits it needs to open at
 * all (a food business needs its health permit and certificate of occupancy), and a product that
 * needs its own license (wine or beer needs the alcohol license) cannot be sold before that license
 * is expected. So:
 *
 *   opening month = the latest of: the month the founder asked for, the earliest month a business
 *                   at this stage can open, and the approval month of every permit required to open
 *   product start = the later of the opening month and the approval month of its license
 *
 * Before opening the business carries pre-opening costs only: rent from the lease start (the
 * buildout period before opening), utilities at a reduced level while the space is built out,
 * insurance from possession, and the owner's pay if the owner works in the business full time.
 * No sales, no staff, no running overheads.
 */

/** Earliest month a business at this stage can open (formation, financing, fit-out). */
const OPENING_FLOOR_MONTH = Object.freeze({ idea: 3, pre_launch: 1, launched: 1, existing: 1 });

/** Months of buildout before opening, during which the lease runs, by the space the founder named. */
const BUILDOUT_MONTHS = Object.freeze({ turnkey: 1, light_buildout: 3, full_buildout: 5 });
const DEFAULT_BUILDOUT_MONTHS = 3;

/**
 * Product lines that need their own license before they can be sold, by license track. A product
 * whose name matches is not sold before that license's expected approval.
 */
const LICENSED_PRODUCT_PATTERNS = Object.freeze({
  alcohol_license: /\b(wine|wines|beer|beers|cocktails?|spirits|liquor|alcohol|alcoholic|cider|sake|mead|taproom|brew(?:s|ery|pub)?|bar service|happy hour)\b/i,
});

/**
 * The lead time the schedule plans on. A permit whose filing window is open (or rolling) is
 * scheduled on its typical processing time; the screen's longer planning allowance is the risk
 * the plan discloses. A license whose application window is closed waits for the next posted
 * cycle, so it is scheduled on the planning allowance, which covers that wait.
 */
function scheduledDays(track) {
  const typical = Number(track.typical_days);
  const planning = Number(track.planning_days);
  if (track.cycle_status === 'closed' || !Number.isFinite(typical) || typical <= 0) return { days: planning, basis: 'next_cycle' };
  return { days: typical, basis: 'typical' };
}

/** The documents print a lead time as "about N months" with this rounding; the schedule matches it. */
function leadMonths(days) {
  return Math.max(1, Math.round((Number(days) || 0) / 30));
}

/** The plan month a permit filed in month 1 is expected to be approved (and the business can use it). */
function approvalMonth(days) {
  return 1 + leadMonths(days);
}

/**
 * Whether a license track must be in hand before the business opens its doors at all.
 *   - Food service / health permit and the municipal license / certificate of occupancy: yes.
 *   - Childcare or education facility license: yes.
 *   - Alcohol license: only for a business whose trade is alcohol (a bar or taproom with no food
 *     service); a cafe or restaurant opens without it and adds its alcohol lines later.
 *   - Entity formation and the EIN are done in the first weeks; a professional license is held by
 *     the practitioner; a federal contractor registration does not stop trading. None gates opening.
 */
function requiredToOpen(trackId, ctx) {
  if (trackId === 'food_service_permit' || trackId === 'childcare_or_education_license') return true;
  if (trackId === 'local_business_license') return !ctx.remote;
  if (trackId === 'alcohol_license') return !ctx.serves_food;
  return false;
}

/**
 * @param {{
 *   stage?: string,
 *   requested_month?: number|null,   // the founder's answer, as a month of the plan; null = none given
 *   request_source?: 'date'|'asap'|'timing'|null,
 *   tracks?: Array<{ id: string, label: string, planning_days?: number|null }>,
 *   space_type?: string|null,
 *   remote?: boolean,
 *   serves_food?: boolean,
 *   max_month?: number,
 *   force_opening_month?: number|null, // scenarios only
 * }} input
 */
function buildOpeningSchedule(input = {}) {
  const floor = OPENING_FLOOR_MONTH[input.stage] || OPENING_FLOOR_MONTH.idea;
  const maxMonth = input.max_month || 12;
  const hasRequest = Number.isFinite(Number(input.requested_month)) && Number(input.requested_month) >= 1;
  const requested = hasRequest ? Math.round(Number(input.requested_month)) : null;
  const ctx = { remote: Boolean(input.remote), serves_food: input.serves_food !== false };

  const tracks = (input.tracks || []).filter((t) => t && t.id && t.planning_days != null);
  const required = tracks
    .filter((t) => requiredToOpen(t.id, ctx))
    .map((t) => {
      const used = scheduledDays(t);
      return { id: t.id, label: t.label, lead_months: leadMonths(used.days), lead_basis: used.basis, allowance_months: leadMonths(t.planning_days), approval_month: approvalMonth(used.days), allowance_approval_month: approvalMonth(t.planning_days) };
    })
    .sort((a, b) => b.approval_month - a.approval_month);
  const permitMonth = required.length ? required[0].approval_month : 0;

  // The founder's own ramp is anchored on the month they expected to open (never earlier than a
  // business at this stage can); every product's volumes then run from its real start.
  const intended = Math.max(requested || floor, floor);
  const unconstrained = Math.max(intended, permitMonth);
  // A scenario can hold the opening at a given month (what if a permit comes sooner or later).
  const forced = Number.isFinite(Number(input.force_opening_month)) && Number(input.force_opening_month) >= 1 ? Math.round(Number(input.force_opening_month)) : null;
  const opening = Math.min(maxMonth, forced || unconstrained);

  let binding = 'founder';
  if (permitMonth > intended && permitMonth >= opening) binding = 'permit';
  else if (requested != null && floor > requested) binding = 'stage';
  else if (requested == null) binding = permitMonth > floor ? 'permit' : 'stage';

  const productLicenses = tracks
    .filter((t) => LICENSED_PRODUCT_PATTERNS[t.id] && !requiredToOpen(t.id, ctx))
    .map((t) => {
      const used = scheduledDays(t);
      const approval = approvalMonth(used.days);
      return { id: t.id, label: t.label, lead_months: leadMonths(used.days), lead_basis: used.basis, allowance_months: leadMonths(t.planning_days), approval_month: approval, start_month: Math.max(opening, approval) };
    });

  const buildout = ctx.remote ? 0 : BUILDOUT_MONTHS[input.space_type] || DEFAULT_BUILDOUT_MONTHS;
  const leaseStart = ctx.remote ? null : Math.max(1, opening - buildout);

  return {
    stage_floor_month: floor,
    requested_month: requested,
    request_source: hasRequest ? input.request_source || 'timing' : null,
    intended_month: intended,
    opening_month: opening,
    unconstrained_opening_month: unconstrained,
    capped: unconstrained > maxMonth,
    binding: forced ? 'scenario' : binding,
    required_permits: required,
    product_licenses: productLicenses,
    buildout_months: buildout,
    lease_start_month: leaseStart,
    pre_opening_months: opening - 1,
  };
}

/** Whether a product needs this license. The schedule is plain data (it is saved with the plan). */
function licenseCovers(lic, productName) {
  const re = LICENSED_PRODUCT_PATTERNS[lic && lic.id];
  return Boolean(re && re.test(String(productName || '')));
}

/** The month a product line starts selling: its license's start where one applies, else opening. */
function productStartMonth(schedule, productName) {
  if (!schedule) return 1;
  let start = schedule.opening_month;
  for (const lic of schedule.product_licenses || []) {
    if (licenseCovers(lic, productName)) start = Math.max(start, lic.start_month);
  }
  return start;
}

/** The license a product waits on, or null. */
function productLicense(schedule, productName) {
  for (const lic of schedule?.product_licenses || []) {
    if (licenseCovers(lic, productName) && lic.start_month > schedule.opening_month) return lic;
  }
  return null;
}


/**
 * Cost model: a monthly cost base built up from what the founder said and from cited benchmarks.
 *
 * It replaces the four fixed business profiles. Under those, a Boston cafe with four named roles
 * carried $1,430 a month of wages, and a five-person software team carried $2,380 a month in
 * total. Costs now come from four inputs:
 *   - industry: a NAICS-style category read from the description;
 *   - location: the metro, then the state, then the national median. "Not decided" uses the
 *     national figures and is flagged;
 *   - the team: the roles the founder named, or a labeled default for the stage and industry;
 *   - the founder's own figures: a lease, insurance or marketing number overrides the benchmark,
 *     and a large divergence is flagged. A stated spending ceiling is compared against the
 *     build-up. It is never used to shrink it.
 *
 * Wages are BLS OEWS medians for the occupation and area. Employer payroll burden is FICA, FUTA,
 * state unemployment insurance at the state's new-employer rate, and a workers' compensation
 * estimate. Health coverage is added only where the industry normally offers it. Every other
 * operating line is a published ratio of revenue: IRS SOI sole-proprietorship expense ratios, or
 * industry-specific figures from the National Restaurant Association and SaaS Capital. Each line
 * names its source.
 *
 * Steady-state revenue is still a sizing target: the revenue at which these costs are covered
 * with the modeled margin. The ratio lines are fixed monthly costs set at that run rate, which is
 * how rent, insurance and a marketing budget behave. Cost of goods moves with sales.
 */

function costRound2(n) {
  return Math.round((Number(n) + Number.EPSILON) * 100) / 100;
}

function costUsd(n) {
  return `$${Math.round(Number(n) || 0).toLocaleString('en-US')}`;
}

