/**
 * The industry for a business, from its description and revenue channels.
 *
 * @param {{ business_description?: string, revenue_model?: any }} ctx
 */
function classifyIndustry(ctx = {}) {
  const text = String(ctx.business_description || '').toLowerCase();
  const channels = Array.isArray(ctx.revenue_model?.channels)
    ? ctx.revenue_model.channels.map((c) => String(c).toLowerCase())
    : typeof ctx.revenue_model === 'string'
      ? [ctx.revenue_model.toLowerCase()]
      : [];
  const matches = (cfg) => cfg.match.test(text) || (cfg.channel_match && channels.some((c) => cfg.channel_match.test(c)));
  const software = INDUSTRY_CONFIGS.find((c) => c.id === 'software_saas');
  if (software && matches(software)) return software;
  // Someone who advises an industry is not in it. "Operations consultant helping small
  // manufacturers" matched retail/manufacturing first and was costed as a shop: a retail
  // supervisor and a salesperson on payroll and $171k to launch, for a one-person consultancy.
  if (ADVISER_RE.test(text)) return INDUSTRY_CONFIGS.find((c) => c.id === 'professional_services');
  for (const cfg of INDUSTRY_CONFIGS) {
    if (matches(cfg)) return cfg;
  }
  return INDUSTRY_CONFIGS.find((c) => c.id === 'general');
}

const ADVISER_RE = /\b(consultant|consulting|consultancy|advisor|adviser|advisory|agency|coach|coaching|bookkeep\w*|accountant|freelanc\w*)\b/;

const COUNT_WORDS = { one: 1, a: 1, an: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8 };

/** Splits the founder's key-roles answer into role phrases. Parentheticals are dropped first so
 * "CEO (finance and sales)" stays one role instead of becoming "CEO" and a salesperson. */
function splitRolePhrases(text) {
  return String(text || '')
    .replace(/\([^)]*\)/g, ' ')
    .split(/[,;.]|\band\b|\bplus\b/i)
    .map((s) => s.trim())
    .filter((s) => s.length > 1 && /[a-z]/i.test(s));
}

/**
 * Reads the founder's key-roles answer into a staffing plan.
 * Returns [] when nothing usable was said.
 */
function parseNamedRoles(text, cfg, firstRevenueMonth) {
  const roles = [];
  for (const phrase of splitRolePhrases(text)) {
    const p = phrase.toLowerCase();
    const countMatch = p.match(/^(?:(\d+)|(one|two|three|four|five|six|seven|eight|a|an))\s/);
    const count = countMatch ? Number(countMatch[1]) || COUNT_WORDS[countMatch[2]] || 1 : 1;
    const contractor = /\bcontract(or|ed)?\b|freelanc|consultant/.test(p) && cfg.id !== 'professional_services';
    const partTime = /part[\s-]?time/.test(p);
    const weekend = /weekend/.test(p);
    const fte = weekend ? MODEL_ASSUMPTIONS.weekend_fte.value : partTime ? MODEL_ASSUMPTIONS.part_time_fte.value : 1;
    const toHire = /to (be )?hire|still to hire|to recruit|will hire|future|later|planned|open role/.test(p);
    const isFounder = /founder|owner|\bceo\b|\bcto\b|\bcoo\b|president|proprietor/.test(p);
    let soc = null;
    for (const [re, code] of cfg.roles) {
      if (re.test(p)) {
        soc = code;
        break;
      }
    }
    const mapped = soc != null;
    if (!soc) soc = isFounder ? cfg.founder_soc : cfg.staff_soc;
    roles.push({
      title: phrase.replace(/\s+is still to hire|\s+still to hire|\s+to be hired|\s+to hire/i, '').replace(/^(a|an|one)\s+/i, ''),
      soc,
      count,
      fte,
      fte_basis: weekend ? 'weekend_fte' : partTime ? 'part_time_fte' : 'full_time',
      contractor,
      is_founder: isFounder,
      start_month: toHire ? Math.max(1, firstRevenueMonth) : 1,
      hire_timing: toHire ? 'at first revenue' : 'from opening',
      basis: 'founder',
      mapped,
    });
  }
  return roles;
}

const TEAM_BAND = Object.freeze({ solo: [1, 1], '1_2': [1, 2], '3_5': [3, 5], '6_plus': [6, 99] });

/** A default team when the founder has not named roles, sized from the team-size answer. */
function defaultRoles(cfg, teamNow, description = '') {
  const extraStaff = { solo: 0, '1_2': 1, '3_5': 2, '6_plus': 5 }[teamNow] ?? cfg.default_staff_unknown_team ?? 0;
  const roles = [
    {
      title: 'Founder / owner-operator',
      soc: cfg.founder_soc,
      count: 1,
      fte: 1,
      fte_basis: 'full_time',
      contractor: false,
      is_founder: true,
      start_month: 1,
      hire_timing: 'from opening',
      basis: 'default',
      mapped: true,
    },
  ];
  if (extraStaff > 0) {
    roles.push({
      title: (cfg.staff_title && cfg.staff_title(String(description).toLowerCase())) || OCCUPATIONS[cfg.staff_soc] || 'Staff',
      soc: cfg.staff_soc,
      count: extraStaff,
      fte: 1,
      fte_basis: 'full_time',
      contractor: false,
      is_founder: false,
      start_month: 1,
      hire_timing: 'from opening',
      basis: 'default',
      mapped: true,
    });
  }
  return roles;
}

function medianOf(values) {
  const v = values.filter((x) => Number.isFinite(x)).sort((a, b) => a - b);
  if (!v.length) return null;
  const mid = Math.floor(v.length / 2);
  return v.length % 2 ? v[mid] : (v[mid - 1] + v[mid]) / 2;
}

/** State unemployment insurance parameters, with the fallback used and why. */
function stateUiFor(stateCode) {
  const rows = Object.values(STATE_UNEMPLOYMENT_INSURANCE);
  const medianRate = medianOf(rows.map((r) => r.new_employer_rate));
  const medianBase = medianOf(rows.map((r) => r.taxable_wage_base_usd));
  const row = stateCode ? STATE_UNEMPLOYMENT_INSURANCE[stateCode] : null;
  if (row && row.new_employer_rate != null) {
    return { rate: row.new_employer_rate, wage_base_usd: row.taxable_wage_base_usd, basis: 'state', state: stateCode, source: row.source };
  }
  if (row) {
    return { rate: medianRate, wage_base_usd: row.taxable_wage_base_usd, basis: 'state_base_median_rate', state: stateCode, source: row.source };
  }
  return { rate: medianRate, wage_base_usd: medianBase, basis: 'median_of_states', state: null, source: 'dol_ui_significant_provisions_2026' };
}

function workersCompFor(stateCode) {
  const row = stateCode ? WORKERS_COMP_INDEX.states[stateCode] : null;
  if (row) return { per_100_usd: row.per_100_payroll_usd, basis: 'state', state: stateCode, source: row.source };
  return { per_100_usd: WORKERS_COMP_INDEX.median.per_100_payroll_usd, basis: 'median_of_states', state: null, source: WORKERS_COMP_INDEX.median.source };
}

/** Annual employer cost for one person in one role: wage plus each burden line. */
function annualRoleCost(role, wage, ctx) {
  const annualWage = costRound2(wage.median_hourly_usd * MODEL_ASSUMPTIONS.hours_per_fte_year.value * role.fte);
  if (role.contractor) {
    return { annual_wage_usd: annualWage, social_security_usd: 0, medicare_usd: 0, futa_usd: 0, suta_usd: 0, workers_comp_usd: 0, health_usd: 0, total_usd: annualWage };
  }
  const ss = costRound2(FEDERAL_PAYROLL_TAX.social_security_rate.value * Math.min(annualWage, FEDERAL_PAYROLL_TAX.social_security_wage_base_usd.value));
  const medicare = costRound2(FEDERAL_PAYROLL_TAX.medicare_rate.value * annualWage);
  const futa = costRound2(FEDERAL_PAYROLL_TAX.futa_net_rate.value * Math.min(annualWage, FEDERAL_PAYROLL_TAX.futa_wage_base_usd.value));
  const suta = costRound2(ctx.ui.rate * Math.min(annualWage, ctx.ui.wage_base_usd));
  const wc = costRound2((ctx.wc.per_100_usd / 100) * annualWage);
  const health =
    ctx.cfg.offers_health && role.fte >= MODEL_ASSUMPTIONS.health_benefit_min_fte.value
      ? HEALTH_BENEFIT.employer_contribution_usd.value
      : 0;
  return {
    annual_wage_usd: annualWage,
    social_security_usd: ss,
    medicare_usd: medicare,
    futa_usd: futa,
    suta_usd: suta,
    workers_comp_usd: wc,
    health_usd: health,
    total_usd: costRound2(annualWage + ss + medicare + futa + suta + wc + health),
  };
}

/**
 * A monthly or annual dollar figure in a founder's free-text answer, as a monthly amount.
 * "$6,500 a month", "$78,000 per year", "about $4k/mo". Returns null if no amount has a period.
 */
function parseMonthlyAmount(text) {
  const t = String(text || '').toLowerCase();
  const m = t.match(/\$\s?(\d[\d,]*(?:\.\d+)?)\s*(k|m)?\s*(?:\/|per|a|each|every)?\s*(month|mo\b|monthly|year|yr\b|annual|annually)/);
  if (!m) return null;
  let v = Number(m[1].replace(/,/g, ''));
  if (m[2] === 'k') v *= 1e3;
  if (m[2] === 'm') v *= 1e6;
  if (!Number.isFinite(v) || v <= 0) return null;
  return /year|yr|annual/.test(m[3]) ? costRound2(v / 12) : costRound2(v);
}

/**
 * How the one-time start-up total splits into categories, for industries whose items differ from
 * the generic profile lists. Shares are an allocation (no neutral source splits a start-up budget
 * this finely); each carries the asset class that sets how it is depreciated.
 */
const STARTUP_SPLITS = Object.freeze({
  food_service: [
    { label: 'Buildout, leasehold improvements and signage', share: 0.35, asset_class: 'buildout' },
    { label: 'Kitchen and beverage equipment', share: 0.3, asset_class: 'equipment' },
    { label: 'Furniture and fixtures (tables, chairs, seating)', share: 0.1, asset_class: 'furniture' },
    { label: 'Technology (POS system, displays, computers)', share: 0.04, asset_class: 'technology' },
    { label: 'Smallwares and opening inventory', share: 0.06, asset_class: 'inventory' },
    { label: 'Licenses, permits and professional fees (one-time)', share: 0.05, asset_class: 'startup' },
    { label: 'Security deposits (rent, utilities)', share: 0.05, asset_class: 'deposit' },
    { label: 'Branding and website', share: 0.02, asset_class: 'startup' },
    { label: 'Pre-opening marketing', share: 0.03, asset_class: 'startup' },
  ],
  retail: [
    { label: 'Buildout and signage', share: 0.2, asset_class: 'buildout' },
    { label: 'Store fixtures and shelving', share: 0.2, asset_class: 'furniture' },
    { label: 'Opening inventory', share: 0.35, asset_class: 'inventory' },
    { label: 'Technology (POS system, computers)', share: 0.08, asset_class: 'technology' },
    { label: 'Licenses, permits and professional fees (one-time)', share: 0.05, asset_class: 'startup' },
    { label: 'Security deposits (rent, utilities)', share: 0.06, asset_class: 'deposit' },
    { label: 'Branding and website', share: 0.03, asset_class: 'startup' },
    { label: 'Pre-opening marketing', share: 0.03, asset_class: 'startup' },
  ],
});

/**
 * Rent from the place, not from revenue: floor area for the industry times the published retail
 * asking rent for the metro. Outside the metros carried, the national asking rent is scaled by the
 * state's housing price parity (BEA). Null where the business needs no premises.
 */
/** Industries that lease street-level space for walk-in customers. */
const STREET_FRONT_INDUSTRIES = new Set(['food_service', 'retail', 'personal_services', 'fitness_recreation']);

function buildRentBenchmark(cfg, place, opts = {}) {
  const typical = FLOOR_AREA_SQ_FT[cfg.id] || FLOOR_AREA_SQ_FT.general;
  if (!(typical.value > 0)) return null;
  // The floor area the founder named (a quote, or a smaller-space track) replaces the typical one.
  const area = opts.square_feet > 0 ? { value: Math.round(opts.square_feet), basis: 'founder', note: null, source: null } : typical;
  const metro = areaKeyFor(RETAIL_ASKING_RENT, place);
  let perSqFt;
  let basisText;
  const sources = [RETAIL_ASKING_RENT[metro.key].source];
  if (metro.level === 'metro') {
    perSqFt = RETAIL_ASKING_RENT[metro.key].annual_per_sq_ft_usd;
    basisText = `retail asking rent for ${RETAIL_ASKING_RENT[metro.key].area}`;
  } else {
    const rpp = areaKeyFor(REGIONAL_PRICE_PARITIES, place);
    const factor = rpp.level === 'national' ? 1 : REGIONAL_PRICE_PARITIES[rpp.key].housing / REGIONAL_PRICE_PARITIES.US.housing;
    perSqFt = costRound2(RETAIL_ASKING_RENT.US.annual_per_sq_ft_usd * factor);
    basisText = rpp.level === 'national' ? 'national retail asking rent' : 'national retail asking rent scaled by the state housing price parity';
    if (rpp.level !== 'national') sources.push(REGIONAL_PRICE_PARITIES[rpp.key].source);
  }
  if (area.source) sources.push(area.source);
  // Street-front space in the central city: the shopping-center figure is the floor of what it
  // leases for, not an estimate of it. With no citable street-retail rate, the rent is an
  // allowance with a range, stated as such, until a lease quote replaces it.
  const row = metro.level === 'metro' ? RETAIL_ASKING_RENT[metro.key] : null;
  const city = String(place.city || '').trim().toLowerCase();
  // A neighborhood or shopping-center site (a founder's choice, or the cheaper-location track) leases at
  // the published rate itself.
  if (row && row.principal_city && city === row.principal_city.toLowerCase() && STREET_FRONT_INDUSTRIES.has(cfg.id) && opts.premises_setting !== 'neighborhood') {
    const f = MODEL_ASSUMPTIONS.street_front_rent_factor;
    const rate = (x) => costRound2(perSqFt * x);
    const monthly = (x) => costRound2((area.value * rate(x)) / 12);
    return {
      basis: 'allowance',
      square_feet: area.value,
      floor_area_basis: area.basis,
      floor_area_note: area.note || null,
      published_per_sq_ft_usd: perSqFt,
      published_area: row.area,
      annual_per_sq_ft_usd: rate(f.value),
      annual_per_sq_ft_low_usd: rate(f.low),
      annual_per_sq_ft_high_usd: rate(f.high),
      factor: f.value,
      monthly_usd: monthly(f.value),
      monthly_low_usd: monthly(f.low),
      monthly_high_usd: monthly(f.high),
      level: 'metro',
      basis_text: `allowance for street-front space in central ${row.principal_city}`,
      sources,
    };
  }
  return {
    basis: 'benchmark',
    square_feet: area.value,
    floor_area_basis: area.basis,
    floor_area_note: area.note || null,
    annual_per_sq_ft_usd: perSqFt,
    monthly_usd: costRound2((area.value * perSqFt) / 12),
    level: metro.level === 'metro' ? 'metro' : 'derived',
    basis_text: basisText,
    sources,
  };
}

/**
 * The one-time start-up budget: a cited benchmark where one exists (scaled by the regional price
 * parity for the place and, for food service, by how much buildout the space needs), otherwise a
 * labeled allowance.
 */
function buildStartupCosts(cfg, place, spaceType, remote, quotedSquareFeet = null) {
  const b = STARTUP_COST_BENCHMARKS[cfg.id] || STARTUP_COST_BENCHMARKS.general;
  const rpp = areaKeyFor(REGIONAL_PRICE_PARITIES, place);
  const locationFactor = b.basis === 'benchmark' && !remote ? Math.round((REGIONAL_PRICE_PARITIES[rpp.key].all_items / 100) * 1000) / 1000 : 1;
  let base;
  let squareFeet = null;
  let spaceFactor = 1;
  if (b.method === 'per_sq_ft') {
    // The premises the founder has quoted, when given; otherwise the typical floor area.
    squareFeet = quotedSquareFeet > 0 ? Math.round(quotedSquareFeet) : (FLOOR_AREA_SQ_FT[cfg.id] || FLOOR_AREA_SQ_FT.general).value;
    spaceFactor = (b.space_factor && b.space_factor[spaceType]) || 1;
    base = b.per_sq_ft_usd * squareFeet;
  } else {
    base = b.total_usd;
  }
  const total = Math.round(base * locationFactor * spaceFactor);
  const sources = [b.source, ...(b.also || [])].filter(Boolean);
  if (locationFactor !== 1) sources.push(REGIONAL_PRICE_PARITIES[rpp.key].source);
  if (squareFeet && !(quotedSquareFeet > 0) && FLOOR_AREA_SQ_FT[cfg.id]?.source) sources.push(FLOOR_AREA_SQ_FT[cfg.id].source);
  if (spaceFactor !== 1 && b.space_factor_source) sources.push(b.space_factor_source);
  return {
    basis: b.basis,
    method: b.method,
    total_usd: total,
    per_sq_ft_usd: b.per_sq_ft_usd || null,
    square_feet: squareFeet,
    square_feet_basis: squareFeet && quotedSquareFeet > 0 ? 'quoted' : squareFeet ? 'typical' : null,
    location_factor: locationFactor,
    location_level: rpp.level,
    space_factor: Math.round(spaceFactor * 1000) / 1000,
    space_type: spaceType || null,
    note: b.note || null,
    sources: [...new Set(sources)],
    categories_split: STARTUP_SPLITS[cfg.id] || null,
  };
}

/** A business that serves food (and so opens before an alcohol license, if it has one coming). */
const SERVES_FOOD = /(caf[eé]|coffee|espresso|restaurant|bistro|bakery|kitchen|food|pizza|deli|diner|eatery|breakfast|lunch|dinner|small plates|menu|brunch|sandwich|pastr)/;

/** Month revenue first arrives, from the founder's first-revenue answer. */
const FIRST_REVENUE_MONTH = Object.freeze({ already: 1, under_30_days: 1, '1_3_months': 2, '3_6_months': 4, '6_plus_months': 7 });

/** First month with revenue in the finance engine's stage ramp (idea-stage businesses open in
 * month 3). Kept beside the ramp's own definition in finance-engine.js; a test holds them equal. */
const STAGE_OPENING_MONTH = Object.freeze({ idea: 3, pre_launch: 1, launched: 1, existing: 1 });

/**
 * Builds the cost base.
 *
 * @param {{
 *   business_description?: string,
 *   revenue_model?: any,
 *   stage?: string,
 *   location?: { status?: string, state_code?: string|null, cbsa_code?: string|null, cbsa_name?: string|null, city?: string|null },
 *   key_roles?: string|null,
 *   staffing_plan?: string|null,
 *   team_now?: string|null,
 *   space_type?: string|null,
 *   monthly_burn_ceiling_usd?: number|null,
 *   first_revenue_timing?: string|null,
 *   opening_month?: number|null,
 *   facility_text?: string|null,
 *   insurance_text?: string|null,
 *   marketing_budget_text?: string|null,
 *   cost_overrides?: { square_feet?: number, monthly_rent_usd?: number, monthly_insurance_usd?: number, monthly_marketing_usd?: number }|null,
 * }} input
 */
function buildCostModel(input = {}) {
  const cfg = classifyIndustry(input);
  const flags = [];
  const flag = (code, severity, message) => flags.push({ code, severity, message });

  // --- Place -----------------------------------------------------------------------------
  const loc = input.location || {};
  const decided = loc.status !== 'not_decided' && (loc.state_code || loc.cbsa_code);
  const place = decided
    ? { status: 'decided', state_code: loc.state_code || null, cbsa_code: loc.cbsa_code || null, city: loc.city || null, label: loc.cbsa_name || (loc.city && loc.state_code ? `${loc.city}, ${loc.state_code}` : loc.city) || loc.state_name || loc.state_code }
    : { status: 'not_decided', state_code: null, cbsa_code: null, label: 'United States (national median)' };
  if (!decided) {
    flag(
      'location_not_decided',
      'warning',
      'No operating location has been chosen, so wages use national medians and payroll taxes use the median state rates. Local wages and rent can differ by 30% or more in either direction.',
    );
  }

  // --- Team --------------------------------------------------------------------------------
  // An opening date past the model's first year is modeled as opening in month 12: the monthly
  // statements run twelve months, and a later opening is a reason to revisit the plan, not to
  // show a year of zeros.
  const openingMonth0 = Number.isFinite(Number(input.opening_month)) && Number(input.opening_month) >= 1 ? Math.round(Number(input.opening_month)) : null;
  const remote = ['online_only', 'home'].includes(input.space_type);
  // The opening month: the founder's request, held back to the stage's earliest opening and to the
  // approval of every permit the business needs before it can open (opening-schedule.js). A
  // business already trading holds its permits, so nothing gates it.
  const trading = input.stage === 'launched' || input.stage === 'existing';
  const schedule = buildOpeningSchedule({
    stage: input.stage,
    requested_month: FIRST_REVENUE_MONTH[input.first_revenue_timing] || openingMonth0 || null,
    request_source: FIRST_REVENUE_MONTH[input.first_revenue_timing] ? 'timing' : openingMonth0 ? input.opening_request_source || 'date' : null,
    tracks: trading ? [] : input.permit_tracks || [],
    space_type: input.space_type,
    remote,
    serves_food: SERVES_FOOD.test(String(input.business_description || '').toLowerCase()),
    max_month: 12,
    force_opening_month: input.force_opening_month || null,
  });
  if (schedule.capped) {
    flag('opening_beyond_year1', 'warning', `The permits this business needs to open are expected to take until month ${schedule.unconstrained_opening_month}, past the first year the monthly statements cover. The plan opens in month 12 for modeling; revisit the timeline with the issuing offices before relying on it.`);
  }
  const openingMonth = schedule.opening_month;
  const firstRevenueMonth = openingMonth;
  let roles = parseNamedRoles(input.key_roles || input.staffing_plan, cfg, openingMonth);
  const teamBasis = roles.length ? 'founder' : 'default';
  if (!roles.length) {
    roles = defaultRoles(cfg, input.team_now, input.business_description);
    for (const r of roles) if (!r.is_founder && cfg.staff_start_at_opening) r.start_month = openingMonth;
    flag(
      'team_defaulted',
      'info',
      `No roles were named, so the team is modeled as ${roles.map((r) => (r.count > 1 ? `${r.count} × ${r.title.toLowerCase()}` : r.title.toLowerCase())).join(' plus ')} (a default for this stage and team size, not a hiring plan).`,
    );
  } else {
    const heads = roles.reduce((a, r) => a + r.count, 0);
    const band = TEAM_BAND[input.team_now];
    if (band && (heads < band[0] || heads > band[1])) {
      flag(
        'team_size_differs',
        'info',
        `The ${heads} roles named differ from the team size given in the interview; the model staffs the named roles.`,
      );
    }
    const unmapped = roles.filter((r) => !r.mapped);
    if (unmapped.length) {
      flag('role_occupation_defaulted', 'info', `No close occupation match for: ${unmapped.map((r) => r.title).join(', ')}; modeled at the ${OCCUPATIONS[cfg.staff_soc] || 'staff'} median.`);
    }
  }

  // Where the business has a physical opening, staff are paid from opening day. Founders are paid
  // from month 1, since they are building the business before it opens.
  if (cfg.staff_start_at_opening) {
    for (const r of roles) {
      if (!r.is_founder && r.start_month < openingMonth) {
        r.start_month = openingMonth;
        r.hire_timing = 'at opening';
      }
    }
  }
  // An owner who keeps outside income for a while (the part-time-start track, or the founder's own
  // choice) draws no pay from the business until the month given; within the first year, so the
  // later years still carry the owner's pay.
  const ownerPayStart = Number(input.cost_overrides?.owner_pay_start_month);
  if (ownerPayStart > 1) {
    for (const r of roles) {
      if (r.is_founder) {
        r.start_month = Math.min(12, Math.round(ownerPayStart));
        r.hire_timing = `from month ${r.start_month}`;
      }
    }
  }
  const ui = stateUiFor(place.state_code);
  const wc = workersCompFor(place.state_code);
  if (ui.basis !== 'state') {
    flag('suta_fallback', 'info', ui.basis === 'state_base_median_rate'
      ? `${ui.state} sets new-employer unemployment insurance rates by industry average, so the median published state rate is used against ${ui.state}'s wage base.`
      : 'State unemployment insurance uses the median new-employer rate and wage base across states until a location is chosen.');
  }
  const ctx = { cfg, ui, wc };
  const wageLevels = new Set();
  const staffing = roles.map((role) => {
    const wage = lookupMedianWage(role.soc, place) || lookupMedianWage(cfg.staff_soc, place);
    wageLevels.add(wage.level);
    const perPerson = annualRoleCost(role, wage, ctx);
    const annualTotal = costRound2(perPerson.total_usd * role.count);
    return {
      ...role,
      occupation: OCCUPATIONS[role.soc],
      median_hourly_usd: wage.median_hourly_usd,
      wage_area: wage.area_name,
      wage_level: wage.level,
      wage_series_id: wage.series_id,
      wage_source: wage.source,
      per_person: perPerson,
      annual_wages_usd: costRound2(perPerson.annual_wage_usd * role.count),
      annual_employer_cost_usd: annualTotal,
      monthly_employer_cost_usd: costRound2(annualTotal / 12),
    };
  });
  if (decided && (wageLevels.has('national') || wageLevels.has('state'))) {
    flag(
      'wage_area_fallback',
      'info',
      `Metro wage data for ${place.label} is not in the embedded table for every role; ${[...wageLevels].filter((l) => l !== 'metro').join(' and ')} medians are used where it is missing.`,
    );
  }
  if (staffing.some((r) => r.is_founder)) {
    flag('founder_pay_at_market', 'info', 'Founder roles are paid at the local median for the occupation. A lender will want to see the business support the owner; lower founder pay would reduce costs dollar for dollar.');
  }
  if (staffing.some((r) => r.contractor)) {
    flag('contractor_no_burden', 'info', 'Contractors are costed at the employee median wage with no employer payroll taxes or benefits. Contract rates often run higher than employee wages.');
  }

  const payrollAtMonth = (m) =>
    costRound2(staffing.reduce((sum, r) => sum + (m >= r.start_month ? r.monthly_employer_cost_usd : 0), 0));
  const payrollSteady = payrollAtMonth(12);

  // --- Benchmark ratio lines -------------------------------------------------------------
  const soiRow = SOI_EXPENSE_RATIOS[cfg.soi];
  const lines = [];
  if (cfg.occupancy) {
    const key = place.cbsa_code ? cfg.occupancy.metro : cfg.occupancy.other;
    lines.push({ key: 'occupancy', label: 'Rent and occupancy', ratio: INDUSTRY_RATIOS[key].value, source: INDUSTRY_RATIOS[key].source, benchmark_id: key });
  } else if (cfg.premises_lines && !remote) {
    for (const k of cfg.premises_lines) {
      lines.push({ key: k === 'rent_property' ? 'occupancy' : k, label: SOI_LINE_LABELS[k], ratio: soiRow[k], source: soiRow.source, benchmark_id: `${cfg.soi}.${k}` });
    }
  }
  if (remote && cfg.premises_lines) {
    flag('no_premises', 'info', 'The team works remotely or from home, so no rent or utilities are modeled.');
  }
  for (const extra of cfg.extra_ratio_lines || []) {
    lines.push({ key: extra.key, label: extra.label, ratio: INDUSTRY_RATIOS[extra.key].value, source: INDUSTRY_RATIOS[extra.key].source, benchmark_id: extra.key });
  }
  for (const k of cfg.soi_lines) {
    lines.push({ key: k, label: SOI_LINE_LABELS[k], ratio: soiRow[k], source: soiRow.source, benchmark_id: `${cfg.soi}.${k}` });
  }

  // Cost of goods sold moves with sales.
  const cogsComponents = cfg.cogs_keys
    ? cfg.cogs_keys.map((k) => ({ label: INDUSTRY_RATIOS[k].note, ratio: INDUSTRY_RATIOS[k].value, source: INDUSTRY_RATIOS[k].source, benchmark_id: k }))
    : [{ label: `cost of sales excluding labor, ${soiRow.column}`, ratio: soiRow.cogs_ex_labor, source: soiRow.source, benchmark_id: `${cfg.soi}.cogs_ex_labor` }];
  const cogsRatio = Math.round(cogsComponents.reduce((a, c) => a + c.ratio, 0) * 10000) / 10000;

  // --- Founder overrides -----------------------------------------------------------------
  const overrides = input.cost_overrides || {};
  const founderMonthly = {
    occupancy: overrides.monthly_rent_usd ?? parseMonthlyAmount(input.facility_text),
    insurance: overrides.monthly_insurance_usd ?? parseMonthlyAmount(input.insurance_text),
    advertising: overrides.monthly_marketing_usd ?? parseMonthlyAmount(input.marketing_budget_text),
  };
  if (founderMonthly.advertising != null && !lines.some((l) => l.key === 'advertising')) {
    // Software keeps marketing on the SaaS Capital line; the founder's budget replaces that.
    const mk = lines.find((l) => l.key === 'saas_marketing');
    if (mk) mk.key = 'advertising';
  }
  if (founderMonthly.occupancy != null && !lines.some((l) => l.key === 'occupancy')) {
    lines.unshift({ key: 'occupancy', label: 'Rent and occupancy', ratio: 0, source: null, benchmark_id: null });
  }
  // Rent comes from the place (floor area times the local asking rent), not from a share of
  // revenue, unless the founder gave a figure. A new business's rent is a lease, and a lease does
  // not scale with sales the business has not made yet.
  const rent = remote ? null : buildRentBenchmark(cfg, place, { square_feet: Number(overrides.square_feet) || null, premises_setting: overrides.premises_setting || null });
  const occupancyLine = lines.find((l) => l.key === 'occupancy');
  if (rent && founderMonthly.occupancy == null) {
    if (occupancyLine) {
      occupancyLine.ratio_benchmark_id = occupancyLine.benchmark_id;
      occupancyLine.ratio_source = occupancyLine.source;
      occupancyLine.ratio_value = occupancyLine.ratio;
      occupancyLine.rent_benchmark_monthly_usd = rent.monthly_usd;
      occupancyLine.source = rent.sources[0];
      occupancyLine.benchmark_id = 'retail_asking_rent';
      occupancyLine.label = 'Rent';
    } else {
      lines.unshift({ key: 'occupancy', label: 'Rent', ratio: 0, source: rent.sources[0], benchmark_id: 'retail_asking_rent', rent_benchmark_monthly_usd: rent.monthly_usd });
    }
  }

  // --- Solve steady-state revenue ---------------------------------------------------------
  // Two sizing methods, and the model says which it used.
  //  - Where the industry publishes a labor share of sales (restaurants), revenue is what a team
  //    of this cost supports at that share. The margin is whatever is left over, which for a
  //    restaurant is thin, as it is in practice.
  //  - Otherwise revenue is sized to cover the modeled costs with the target margin.
  let fixedDollars = payrollSteady;
  let ratioSum = 0;
  for (const l of lines) {
    const f = founderMonthly[l.key];
    if (f != null) {
      l.founder_monthly_usd = f;
      fixedDollars += f;
    } else if (l.rent_benchmark_monthly_usd != null) {
      fixedDollars += l.rent_benchmark_monthly_usd;
    } else ratioSum += l.ratio;
  }
  let steadyRevenue;
  let sizing;
  const DENOM_FLOOR = 0.1;
  if (cfg.labor_check_key) {
    const share = INDUSTRY_RATIOS[cfg.labor_check_key].value;
    steadyRevenue = costRound2(payrollSteady / share);
    sizing = { method: 'labor_share', labor_share: share, source: INDUSTRY_RATIOS[cfg.labor_check_key].source };
  } else {
    const margin = MODEL_ASSUMPTIONS.target_operating_margin.value;
    let denom = 1 - cogsRatio - margin - ratioSum;
    if (denom < DENOM_FLOOR) {
      flag('ratio_stack_capped', 'warning', 'Benchmark cost ratios for this industry leave little room for payroll, so steady-state revenue is capped rather than allowed to grow without bound. Treat revenue as unreliable until priced from volume.');
      denom = DENOM_FLOOR;
    }
    steadyRevenue = costRound2(fixedDollars / denom);
    sizing = { method: 'target_margin', target_operating_margin: margin };
  }

  for (const l of lines) {
    const benchMonthly = costRound2(l.ratio * steadyRevenue);
    l.benchmark_monthly_usd = benchMonthly;
    if (l.founder_monthly_usd != null) {
      l.monthly_usd = costRound2(l.founder_monthly_usd);
      l.basis = 'founder';
      if (benchMonthly > 0) {
        const diff = l.founder_monthly_usd / benchMonthly - 1;
        if (Math.abs(diff) >= 0.5) {
          flag(
            `founder_${l.key}_diverges`,
            'warning',
            `The founder's ${l.label.toLowerCase()} figure of ${costUsd(l.founder_monthly_usd)} a month is ${Math.round(Math.abs(diff) * 100)}% ${diff > 0 ? 'above' : 'below'} the benchmark of ${costUsd(benchMonthly)}. The founder's figure is used; confirm it with a quote.`,
          );
        }
      }
    } else if (l.rent_benchmark_monthly_usd != null) {
      // What the old share-of-revenue rule would have given, kept for the owner's cross-check.
      l.ratio_monthly_usd = l.ratio_value != null ? costRound2(l.ratio_value * steadyRevenue) : null;
      l.monthly_usd = costRound2(l.rent_benchmark_monthly_usd);
      l.basis = 'benchmark_rent';
    } else {
      l.monthly_usd = benchMonthly;
      l.basis = 'benchmark';
    }
  }
  // Before opening only the pre-opening costs run: rent and insurance from the lease start,
  // utilities at a reduced level while the space is built out, and the owner's pay (founders are
  // paid from month 1, staff from opening; see payrollAtMonth). Everything else starts at opening.
  const preOpeningUtilities = MODEL_ASSUMPTIONS.pre_opening_utilities_share.value;
  const leaseStart = schedule.lease_start_month;
  const lineAtMonth = (l, m) => {
    if (m >= openingMonth) return l.monthly_usd;
    if (leaseStart != null && m >= leaseStart) {
      if (l.key === 'occupancy' || l.key === 'insurance') return l.monthly_usd;
      if (l.key === 'utilities') return costRound2(l.monthly_usd * preOpeningUtilities);
    }
    return 0;
  };
  const linesAtMonth = (m) => costRound2(lines.reduce((a, l) => a + lineAtMonth(l, m), 0));
  const opexAtMonth = (m) => costRound2(payrollAtMonth(m) + linesAtMonth(m));
  const steadyOpex = opexAtMonth(12);

  // --- Payroll burden summary -------------------------------------------------------------
  const burden = { social_security_usd: 0, medicare_usd: 0, futa_usd: 0, suta_usd: 0, workers_comp_usd: 0, health_usd: 0 };
  let annualWages = 0;
  for (const r of staffing) {
    annualWages += r.per_person.annual_wage_usd * r.count;
    for (const k of Object.keys(burden)) burden[k] += r.per_person[k] * r.count;
  }
  for (const k of Object.keys(burden)) burden[k] = costRound2(burden[k]);
  annualWages = costRound2(annualWages);

  // --- Ceiling ----------------------------------------------------------------------------
  const ceiling = Number(input.monthly_burn_ceiling_usd);
  let ceilingCheck = null;
  if (Number.isFinite(ceiling) && ceiling > 0) {
    const ratio = steadyOpex / ceiling;
    ceilingCheck = {
      ceiling_usd: ceiling,
      modeled_monthly_opex_usd: steadyOpex,
      ratio: Math.round(ratio * 100) / 100,
      status: ratio > 1.1 ? 'above_ceiling' : ratio < 0.5 ? 'well_below_ceiling' : 'within_ceiling',
    };
    if (ceilingCheck.status === 'above_ceiling') {
      flag(
        'costs_exceed_founder_ceiling',
        'warning',
        `At local median wages and benchmark overheads this team costs about ${costUsd(steadyOpex)} a month to run, ${Math.round((ratio - 1) * 100)}% above the founder's stated ceiling of ${costUsd(ceiling)}. The plan shows the build-up, not the ceiling. Fitting under the ceiling means fewer hours, fewer roles, or lower founder pay, and the plan should say which.`,
      );
    } else if (ceilingCheck.status === 'well_below_ceiling') {
      flag(
        'ceiling_well_above_model',
        'info',
        `The founder expects to spend up to ${costUsd(ceiling)} a month, about ${Math.round(1 / ratio * 10) / 10}× the ${costUsd(steadyOpex)} this cost build-up carries. Either the team or overhead planned is larger than named here, or the ceiling has room in it.`,
      );
    }
  }

  // --- Labor share cross-check ------------------------------------------------------------
  let laborCheck = null;
  if (cfg.labor_check_key) {
    const b = INDUSTRY_RATIOS[cfg.labor_check_key];
    const share = steadyRevenue > 0 ? payrollSteady / steadyRevenue : null;
    laborCheck = { modeled_share: share == null ? null : Math.round(share * 1000) / 1000, benchmark_share: b.value, source: b.source };
  }

  const startup = buildStartupCosts(cfg, place, input.space_type, remote, Number(overrides.square_feet) || null);
  // The curated industry pack's priced must-have equipment, when one matches this business: the
  // launch model uses its midpoint for the equipment line unless the founder listed their own.
  startup.industry_pack = remote ? null : industryEquipmentRange({ business_description: input.business_description, revenue_model: input.revenue_model, naics: input.naics || null, industry: cfg }, { asOf: input.as_of || undefined });
  const sourcesUsed = new Set(['bls_oews_may2025', 'bls_oews_technical_notes', 'irs_topic_751', 'irs_topic_759', ui.source, wc.source]);
  for (const id of startup.sources) sourcesUsed.add(id);
  if (rent && founderMonthly.occupancy == null) for (const id of rent.sources) sourcesUsed.add(id);
  sourcesUsed.add('irs_p946_2025');
  sourcesUsed.add('irs_i4562_2025');
  for (const l of lines) if (l.source) sourcesUsed.add(l.source);
  for (const c of cogsComponents) sourcesUsed.add(c.source);
  if (burden.health_usd > 0) sourcesUsed.add('kff_ehbs_2025');
  if (laborCheck) sourcesUsed.add(laborCheck.source);
  if (cfg.growth_key) sourcesUsed.add(INDUSTRY_RATIOS[cfg.growth_key].source);

  return {
    version: COST_BENCHMARKS_VERSION,
    industry: { id: cfg.id, label: cfg.label, naics: cfg.naics, profile: cfg.profile },
    place,
    team_basis: teamBasis,
    first_revenue_month: firstRevenueMonth,
    opening_month: openingMonth,
    // Carried for the launch model, which reads the founder's equipment list (setup_items).
    cost_overrides: input.cost_overrides || null,
    staffing,
    payroll: {
      steady_state_monthly_usd: payrollSteady,
      annual_wages_usd: annualWages,
      annual_burden_usd: burden,
      suta: ui,
      workers_comp: wc,
      health_benefit_offered: Boolean(cfg.offers_health),
    },
    payroll_by_month: Array.from({ length: 12 }, (_, i) => payrollAtMonth(i + 1)),
    opex_by_month: Array.from({ length: 12 }, (_, i) => opexAtMonth(i + 1)),
    // Each operating line month by month for Year 1, so the pre-opening months can be shown.
    lines_by_month: Array.from({ length: 12 }, (_, i) => linesAtMonth(i + 1)),
    schedule,
    lines,
    cogs_ratio: cogsRatio,
    cogs_components: cogsComponents,
    revenue_sizing: sizing,
    steady_state_operating_margin:
      steadyRevenue > 0 ? Math.round(((steadyRevenue * (1 - cogsRatio) - steadyOpex) / steadyRevenue) * 1000) / 1000 : null,
    stabilized_monthly_revenue_usd: steadyRevenue,
    steady_state_monthly_opex_usd: steadyOpex,
    // A published growth rate to hold the model's implied growth against. It is a cross-check
    // only: the software ramp sets revenue, not this rate.
    growth_check: cfg.growth_key ? { benchmark_rate: INDUSTRY_RATIOS[cfg.growth_key].value, source: INDUSTRY_RATIOS[cfg.growth_key].source, note: INDUSTRY_RATIOS[cfg.growth_key].note } : null,
    ramp: cfg.ramp || 'stage',
    ceiling: ceilingCheck,
    labor_check: laborCheck,
    rent: founderMonthly.occupancy != null
      ? { basis: 'founder', monthly_usd: costRound2(founderMonthly.occupancy) }
      : rent,
    startup,
    flags,
    sources_used: [...sourcesUsed].filter(Boolean).map((id) => ({ id, ...COST_SOURCES[id] })),
  };
}


/**
 * Revenue build-up: revenue from price times volume, product by product.
 *
 * Until this, revenue was sized from the cost base (the sales a payroll supports at the industry
 * labor share, or the revenue that covers costs at a 12% margin). That answers "what would this
 * business need to sell", not "what will it sell", and a lender's first question is the second
 * one. The founder can now list what they sell: each product or tier with its price, how it is
 * billed, how many customers or units a month they expect (a ramp from a starting month to month
 * 12 and month 36, or a monthly growth rate), and the variable cost of each unit (ingredients,
 * cloud compute, payment fees). When they do, this drives the projections; when they do not, the
 * cost-derived figure stays and is labeled as implied by costs, not a sales forecast.
 *
 * Billing units:
 *   - per_unit:  price per unit sold; volume is units sold in the month (drinks, seats, jobs).
 *   - one_time:  price per sale to a new customer; volume is new customers in the month.
 *   - monthly:   subscription price per month; volume is active subscribers that month.
 *   - annual:    subscription price per year; volume is active subscribers. Revenue and unit cost
 *                are recognized evenly, one twelfth a month (the model is cash-basis with no
 *                deferred revenue, and says so).
 *
 * Nothing here invents a volume. Every figure is the founder's, multiplied out.
 */

function revRound2(n) {
  return Math.round((Number(n) + Number.EPSILON) * 100) / 100;
}

const BILLING_UNITS = Object.freeze({
  one_time: { label: 'One-time', price_suffix: 'per sale', volume_label: 'new customers a month', per_year: 1 },
  monthly: { label: 'Per month', price_suffix: 'a month', volume_label: 'active subscribers', per_year: 12 },
  annual: { label: 'Per year', price_suffix: 'a year', volume_label: 'active subscribers', per_year: 1 },
  per_unit: { label: 'Per unit', price_suffix: 'per unit', volume_label: 'units a month', per_year: 1 },
});

/** Model policy for the sanity checks, kept apart from the founder's figures. */
const REVENUE_CHECKS = Object.freeze({
  /** Customers implied at month 36 above this share of the serviceable market are flagged. */
  serviceable_share_flag: 0.1,
  /** Year 2 average monthly revenue this many times the cost-implied revenue, or more, is flagged. */
  above_cost_implied_ratio: 2,
  /** ...and this fraction of it, or less. */
  below_cost_implied_ratio: 0.5,
  /** At most this many products or tiers are read. */
  max_tiers: 12,
  horizon_months: 36,
});

function num(v) {
  if (v == null || v === '') return null;
  const n = Number(String(v).replace(/[$,\s%]/g, ''));
  return Number.isFinite(n) ? n : null;
}

/**
 * Clean up a build-up as the intake stores it. Rows without a price or any volume are dropped
 * and reported, not guessed at. Returns null when nothing usable is left, which is the same as
 * no build-up: the cost-derived revenue stays.
 *
 * @param {object|null} raw { tiers: [...], serviceable_customers?, market_basis? }
 */
function normalizeRevenueBuildup(raw) {
  if (!raw || typeof raw !== 'object' || !Array.isArray(raw.tiers)) return null;
  const tiers = [];
  const dropped = [];
  raw.tiers.slice(0, REVENUE_CHECKS.max_tiers).forEach((t, i) => {
    if (!t || typeof t !== 'object') return;
    const name = String(t.name || '').trim().slice(0, 80) || `Product ${i + 1}`;
    const price = num(t.price_usd);
    const billing = BILLING_UNITS[t.billing] ? t.billing : 'per_unit';
    const start = num(t.volume?.start ?? t.start);
    const m12 = num(t.volume?.month12 ?? t.month12);
    const m36 = num(t.volume?.month36 ?? t.month36);
    const growth = num(t.volume?.monthly_growth_pct ?? t.monthly_growth_pct);
    const unitCost = num(t.unit_cost_usd);
    const buys = num(t.purchases_per_customer_month);
    const hasVolume = [start, m12, m36].some((v) => v != null && v > 0);
    if (!(price > 0) || !hasVolume) {
      dropped.push({ index: i, name, reason: !(price > 0) ? 'no price' : 'no volume' });
      return;
    }
    const useGrowth = growth != null && m12 == null && m36 == null;
    const s = Math.max(0, start ?? 0);
    const volume = useGrowth
      ? { mode: 'growth', start: s, monthly_growth_pct: Math.max(-50, Math.min(100, growth)) }
      : (() => {
          const v12 = Math.max(0, m12 ?? s);
          return { mode: 'points', start: s, month12: v12, month36: Math.max(0, m36 ?? v12) };
        })();
    tiers.push({
      id: String(t.id || `tier_${i + 1}`),
      name,
      price_usd: revRound2(price),
      billing,
      volume,
      unit_cost_usd: revRound2(Math.max(0, unitCost ?? 0)),
      purchases_per_customer_month: buys > 0 ? buys : null,
    });
  });
  if (!tiers.length) return null;
  const sam = num(raw.serviceable_customers);
  return {
    tiers,
    serviceable_customers: sam > 0 ? Math.round(sam) : null,
    market_basis: raw.market_basis ? String(raw.market_basis).trim().slice(0, 400) : null,
    dropped,
  };
}

/**
 * Volume in each of the 36 months. Zero before the product's first month. On a start / month-12 /
 * month-36 ramp, straight lines join the three points; with a growth rate, the start compounds
 * monthly from the first month.
 *
 * `plannedFirst` is the month the founder expected sales to begin, which their month-12 and
 * month-36 volumes were set against. When the product starts later (the opening waits on a
 * permit, or the product on its own license), the whole ramp moves with it: the founder's volume
 * for "month 12" is reached twelve months into the plan plus the delay, not in fewer months of
 * trading. With no delay this is the founder's ramp exactly.
 */
function tierVolumeSeries(tier, firstMonth = 1, plannedFirst = firstMonth) {
  const n = REVENUE_CHECKS.horizon_months;
  const f = Math.max(1, Math.min(n, Math.round(firstMonth) || 1));
  const p = Math.max(1, Math.min(f, Math.round(plannedFirst) || f));
  const d = f - p;
  const v = tier.volume;
  const out = [];
  for (let m = 1; m <= n; m++) {
    if (m < f) {
      out.push(0);
      continue;
    }
    let x;
    if (v.mode === 'growth') {
      x = v.start * (1 + v.monthly_growth_pct / 100) ** (m - f);
    } else if (p >= 12) {
      const end = n + d;
      x = end === f ? v.month36 : v.start + ((v.month36 - v.start) * (m - f)) / (end - f);
    } else if (m <= 12 + d) {
      x = v.start + ((v.month12 - v.start) * (m - f)) / (12 - p);
    } else {
      x = v.month12 + ((v.month36 - v.month12) * (m - 12 - d)) / 24;
    }
    out.push(revRound2(Math.max(0, x)));
  }
  return out;
}

const sumRange = (arr, from, to) => revRound2(arr.slice(from - 1, to).reduce((a, x) => a + x, 0));

/**
 * The build-up multiplied out: per tier and in total, month by month for 36 months, with the
 * annual figures the documents print. Tie-outs hold by construction: each total is the sum of the
 * tiers, and each annual figure the sum of its months.
 *
 * @param {object} buildup normalized (normalizeRevenueBuildup)
 * @param {{ firstMonth?: number }} opts
 */
function buildRevenueModel(buildup, opts = {}) {
  if (!buildup?.tiers?.length) return null;
  const firstMonth = opts.firstMonth || 1;
  const plannedFirst = opts.plannedFirstMonth || firstMonth;
  const startOf = typeof opts.tierStartMonth === 'function' ? opts.tierStartMonth : () => firstMonth;
  const n = REVENUE_CHECKS.horizon_months;
  const revenueByMonth = new Array(n).fill(0);
  const cogsByMonth = new Array(n).fill(0);
  const tiers = buildup.tiers.map((t) => {
    const start = Math.max(firstMonth, startOf(t) || firstMonth);
    const volumes = tierVolumeSeries(t, start, plannedFirst);
    const perMonthFactor = t.billing === 'annual' ? 1 / 12 : 1;
    const revenue = volumes.map((q) => revRound2(q * t.price_usd * perMonthFactor));
    const cogs = volumes.map((q) => revRound2(q * t.unit_cost_usd * perMonthFactor));
    revenue.forEach((r, i) => (revenueByMonth[i] = revRound2(revenueByMonth[i] + r)));
    cogs.forEach((c, i) => (cogsByMonth[i] = revRound2(cogsByMonth[i] + c)));
    const annual = [1, 2, 3].map((y) => {
      const rev = sumRange(revenue, (y - 1) * 12 + 1, y * 12);
      const cg = sumRange(cogs, (y - 1) * 12 + 1, y * 12);
      return { year: y, revenue_usd: rev, cogs_usd: cg, gross_margin_usd: revRound2(rev - cg), units: sumRange(volumes, (y - 1) * 12 + 1, y * 12) };
    });
    const unitMargin = revRound2(t.price_usd - t.unit_cost_usd);
    // Customers this tier implies at month 36, for the market check. Subscribers are customers; a
    // one-time sale is a new customer, so a year of them; units need purchases per customer.
    const q36 = volumes[n - 1];
    let customers36 = null;
    if (t.billing === 'monthly' || t.billing === 'annual') customers36 = q36;
    else if (t.billing === 'one_time') customers36 = revRound2(q36 * 12);
    else if (t.purchases_per_customer_month) customers36 = revRound2(q36 / t.purchases_per_customer_month);
    return {
      ...t,
      billing_label: BILLING_UNITS[t.billing].label,
      volume_label: BILLING_UNITS[t.billing].volume_label,
      volumes,
      revenue_by_month: revenue,
      cogs_by_month: cogs,
      start_month: start,
      volume_month1: volumes[start - 1],
      volume_month12: volumes[11],
      volume_month36: volumes[n - 1],
      monthly_revenue_month12_usd: revenue[11],
      monthly_revenue_month36_usd: revenue[n - 1],
      annual,
      unit_margin_usd: unitMargin,
      gross_margin_pct: t.price_usd > 0 ? Math.round((unitMargin / t.price_usd) * 1000) / 1000 : null,
      implied_customers_month36: customers36,
    };
  });
  const annual = [1, 2, 3].map((y) => {
    const rev = revRound2(tiers.reduce((a, t) => a + t.annual[y - 1].revenue_usd, 0));
    const cg = revRound2(tiers.reduce((a, t) => a + t.annual[y - 1].cogs_usd, 0));
    return {
      year: y,
      revenue_usd: rev,
      cogs_usd: cg,
      gross_margin_usd: revRound2(rev - cg),
      gross_margin_pct: rev > 0 ? Math.round(((rev - cg) / rev) * 1000) / 1000 : null,
    };
  });
  return {
    first_revenue_month: firstMonth,
    planned_first_month: plannedFirst,
    tiers,
    revenue_by_month: revenueByMonth,
    cogs_by_month: cogsByMonth,
    annual,
    monthly_revenue_month12_usd: revenueByMonth[11],
    monthly_revenue_month36_usd: revenueByMonth[n - 1],
    serviceable_customers: buildup.serviceable_customers,
    market_basis: buildup.market_basis,
    dropped: buildup.dropped || [],
  };
}

/**
 * Sanity checks a reader would run: customers implied against the market the founder named, and
 * price times volume against what the cost base implies. They flag; they never change a figure.
 *
 * @param {object} model buildRevenueModel output
 * @param {{ costImpliedMonthlyRevenueUsd?: number, breakEvenMonthlyRevenueUsd?: number }} ctx
 */
function revenueModelFlags(model, ctx = {}) {
  const flags = [];
  const flag = (code, severity, message, extra = {}) => flags.push({ code, severity, message, ...extra });
  const usd = (n) => `$${Math.round(Number(n) || 0).toLocaleString('en-US')}`;

  for (const t of model.tiers) {
    if (t.unit_cost_usd >= t.price_usd) {
      flag('unit_cost_at_or_above_price', 'warning', `${t.name}: the variable cost per unit (${usd(t.unit_cost_usd)}) is not below the price (${usd(t.price_usd)}), so every sale loses money before overheads.`, { tier_id: t.id });
    }
  }

  // The market check uses the largest single tier: customers of different tiers overlap, so the
  // biggest one is the fewest distinct customers the plan can mean.
  const counted = model.tiers.filter((t) => t.implied_customers_month36 != null);
  const uncounted = model.tiers.filter((t) => t.implied_customers_month36 == null);
  const peak = counted.length ? Math.max(...counted.map((t) => t.implied_customers_month36)) : null;
  const sam = model.serviceable_customers;
  let share = null;
  if (sam && peak != null) {
    share = peak / sam;
    if (share > REVENUE_CHECKS.serviceable_share_flag) {
      flag(
        'customers_implausible_vs_market',
        'warning',
        `By month 36 the build-up implies at least ${Math.round(peak).toLocaleString('en-US')} customers, ${Math.round(share * 1000) / 10}% of the ${sam.toLocaleString('en-US')} the founder counts as reachable. Above ${Math.round(REVENUE_CHECKS.serviceable_share_flag * 100)}% of a serviceable market is rarely won by a new business; check the volumes or the market size.`,
      );
    }
  } else if (!sam) {
    flag('no_serviceable_market', 'info', 'No serviceable market size was given, so the customer counts are not checked against the market.');
  }
  if (sam && uncounted.length) {
    flag('units_without_customer_count', 'info', `${uncounted.map((t) => t.name).join(', ')}: sold by the unit with no purchases-per-customer figure, so not included in the market check.`);
  }

  const y2Monthly = model.annual[1].revenue_usd / 12;
  const costImplied = ctx.costImpliedMonthlyRevenueUsd;
  let ratio = null;
  if (costImplied > 0) {
    ratio = Math.round((y2Monthly / costImplied) * 100) / 100;
    if (ratio >= REVENUE_CHECKS.above_cost_implied_ratio) {
      flag(
        'far_above_cost_implied',
        'warning',
        `Year 2 revenue averages ${usd(y2Monthly)} a month, ${ratio}× the ${usd(costImplied)} the cost base implies. The team and overheads are costed for the smaller figure; volume this high usually needs more staff, space or marketing than the plan carries.`,
      );
    } else if (ratio <= REVENUE_CHECKS.below_cost_implied_ratio) {
      flag(
        'far_below_cost_implied',
        'warning',
        `Year 2 revenue averages ${usd(y2Monthly)} a month, ${ratio}× the ${usd(costImplied)} the cost base implies. At these volumes the cost base is heavy for the sales; the plan shows the losses that follow.`,
      );
    }
  }
  const be = ctx.breakEvenMonthlyRevenueUsd;
  if (be > 0 && model.monthly_revenue_month36_usd < be) {
    flag(
      'below_break_even',
      'warning',
      `At month 36 the build-up reaches ${usd(model.monthly_revenue_month36_usd)} a month, below the ${usd(be)} a month that covers operating costs at these margins. The business does not break even on these volumes.`,
    );
  }
  if (model.dropped.length) {
    flag('rows_dropped', 'info', `Left out of the build-up for want of a price or a volume: ${model.dropped.map((d) => d.name).join(', ')}.`);
  }
  return {
    flags,
    market_check: { serviceable_customers: sam, implied_customers_month36: peak, share: share == null ? null : Math.round(share * 1000) / 1000 },
    cost_check: { year2_average_monthly_revenue_usd: revRound2(y2Monthly), cost_implied_monthly_revenue_usd: costImplied || null, ratio },
  };
}


/**
 * Industry-pack equipment prices for the model's start-up budget.
 *
 * The curated industry Research Packs price each item of equipment a business of that kind needs
 * (commercial listings, low and high). The model uses them, in this order:
 *   1. the founder's own equipment and build-out lines (quotes first), when given;
 *   2. otherwise, for the equipment line only, the midpoint of the pack's must-have equipment range;
 *   3. otherwise the existing cited benchmark split.
 * Build-out, furniture, technology, inventory, fees and deposits stay on the benchmark: the packs
 * do not price them. Founder's Notes states the difference between what the model uses and the
 * benchmark (or the founder's figure and the pack range).
 *
 * The pack comes from the same verified digest the Operating Plan reads, matched to the business
 * the same way (opResolveNaics / opFindIndustryPack), so the plan, the model and the Operating
 * Plan always name the same pack. Top-level names are prefixed ic: scripts/build-foundry-engines.js
 * inlines this file into the browser bundle.
 */

/**
 * @param {{ business_description?: string, revenue_model?: any, naics?: string, industry?: { naics?: string } }} ctx
 * @param {{ digest?: object, asOf?: string }} [opts]
 * @returns {null | { id: string, title: string, version: string, naics: string, low_usd: number, high_usd: number,
 *   mid_usd: number, items: number, retrieved: string|null }}
 */
function industryEquipmentRange(ctx, opts = {}) {
  const digest = opts.digest || OP_RESEARCH_DIGEST;
  if (!digest || !digest.packs) return null;
  const pseudo = {
    intake: { business_description: ctx.business_description || '', revenue_model: ctx.revenue_model || null, naics: ctx.naics || null },
    finance: { cost_model: { industry: ctx.industry || null } },
  };
  const naics = opResolveNaics(pseudo, digest);
  const pack = opFindIndustryPack(digest, naics.code);
  if (!pack || !Array.isArray(pack.data.equipment)) return null;
  const asOf = opts.asOf || new Date().toISOString().slice(0, 10);
  if (opPackStatus(pack, asOf) === 'expired') return null;
  let low = 0;
  let high = 0;
  let items = 0;
  let url = null;
  for (const r of pack.data.equipment) {
    if (!r || !r.value || !r.value.must_have) continue;
    if (!(Number(r.value.low_usd) >= 0) || !(Number(r.value.high_usd) >= Number(r.value.low_usd))) continue;
    low += Number(r.value.low_usd);
    high += Number(r.value.high_usd);
    items += 1;
    if (!url && r.url) url = r.url;
  }
  if (!items || !(high > 0)) return null;
  return {
    id: pack.id,
    title: pack.title,
    version: pack.version,
    naics: String(pack.data.industry.naics),
    low_usd: Math.round(low),
    high_usd: Math.round(high),
    mid_usd: Math.round((low + high) / 2),
    items,
    retrieved: pack.retrieved_max || pack.retrieved_min || null,
    // A listing behind the first priced item, so the lender documents can cite where prices come from.
    url,
  };
}

/**
 * The benchmark split with its equipment line set to the pack midpoint; the other lines keep their
 * dollar amounts. Returns null when the split has no equipment line.
 * @param {number} total the benchmark start-up total
 * @param {{ label: string, asset_class?: string, share: number }[]} split
 * @param {{ mid_usd: number, title: string }} range
 */
function icPackFedSetup(total, split, range) {
  const eqShare = (split || []).filter((c) => c.asset_class === 'equipment').reduce((a, c) => a + c.share, 0);
  if (!(eqShare > 0) || !(total > 0) || !range) return null;
  const benchEquipment = Math.round(total * eqShare);
  const newTotal = Math.round(total - benchEquipment + range.mid_usd);
  const newSplit = split.map((c) =>
    c.asset_class === 'equipment'
      ? { ...c, share: (range.mid_usd * (c.share / eqShare)) / newTotal, basis: 'industry_pack', source: `Industry research: ${range.title}` }
      : { ...c, share: (total * c.share) / newTotal },
  );
  return { total: newTotal, split: newSplit, benchmark_equipment_usd: benchEquipment };
}


/**
 * Finance engine — indicative launch model.
 * Instant #6 personal_capital is founder investment available now.
 * This engine estimates launch cost / reserve / gap separately. Never merge fields.
 */

const BAND_TO_USD = Object.freeze({
  under_1k: 500,
  '1k_5k': 3000,
  '5k_25k': 15000,
  '25k_100k': 60000,
  '100k_plus': 150000,
});

/**
 * @param {unknown} personalCapital
 */
function normalizePersonalCapital(personalCapital) {
  if (personalCapital == null) {
    return { available_usd: null, disclosure: 'missing', labeled: 'not provided' };
  }
  if (typeof personalCapital === 'number' && Number.isFinite(personalCapital)) {
    return {
      available_usd: Math.max(0, personalCapital),
      disclosure: 'amount',
      labeled: `$${Math.max(0, personalCapital).toLocaleString('en-US')}`,
    };
  }
  if (typeof personalCapital === 'string') {
    const raw = personalCapital.trim().toLowerCase();
    if (!raw || raw === 'unknown' || raw.includes('prefer')) {
      return {
        available_usd: null,
        disclosure: 'unknown',
        labeled: personalCapital.trim() || 'unknown',
      };
    }
    if (raw === '0' || raw === '$0' || raw === 'zero') {
      return { available_usd: 0, disclosure: 'zero', labeled: '$0' };
    }
    const n = Number(String(personalCapital).replace(/[$,\s]/g, ''));
    if (Number.isFinite(n)) {
      return {
        available_usd: Math.max(0, n),
        disclosure: 'amount',
        labeled: `$${n.toLocaleString('en-US')}`,
      };
    }
    return { available_usd: null, disclosure: 'unparsed', labeled: personalCapital.trim() };
  }
  if (typeof personalCapital === 'object') {
    const pc = /** @type {Record<string, unknown>} */ (personalCapital);
    const disclosure = String(pc.disclosure || pc.status || 'unknown');
    if (disclosure === 'zero') {
      return { available_usd: 0, disclosure: 'zero', labeled: '$0' };
    }
    if (
      (disclosure === 'amount' || pc.amount_usd != null) &&
      typeof pc.amount_usd === 'number'
    ) {
      return {
        available_usd: Math.max(0, pc.amount_usd),
        disclosure: 'amount',
        labeled: `$${pc.amount_usd.toLocaleString('en-US')}`,
      };
    }
    if (disclosure === 'band' && typeof pc.band === 'string' && BAND_TO_USD[pc.band] != null) {
      return {
        available_usd: BAND_TO_USD[pc.band],
        disclosure: 'band',
        labeled: `band ${pc.band} (~$${BAND_TO_USD[pc.band].toLocaleString('en-US')})`,
      };
    }
    if (disclosure === 'unknown' || disclosure === 'prefer_not') {
      return { available_usd: null, disclosure, labeled: disclosure };
    }
  }
  return { available_usd: null, disclosure: 'unknown', labeled: 'unknown' };
}

/**
 * @param {{ business_description?: string, revenue_model?: any }} ctx
 */
function profileBusiness(ctx = {}) {
  const text = String(ctx.business_description || '').toLowerCase();
  const channels = Array.isArray(ctx.revenue_model?.channels)
    ? ctx.revenue_model.channels.map((c) => String(c).toLowerCase())
    : typeof ctx.revenue_model === 'string'
      ? [ctx.revenue_model.toLowerCase()]
      : [];

  // Whole words: the bare substrings matched "capital", "therapist" and "rapid" (api), and
  // "happy" or "approach" (app), and filed those businesses as software.
  if (
    /\b(software|saas|apps?|platform|api)\b/.test(text) ||
    channels.some((c) => /saas|subscription|software/.test(c))
  ) {
    return 'software_product';
  }
  // Someone who advises an industry is not in it: "consultant helping small manufacturers" was
  // costed as a manufacturer (physical operations, $171k to launch) because of "manufactur".
  if (/\b(consultant|consulting|consultancy|advisor|advisory|agency|coach|coaching|bookkeep\w*|accountant|freelanc\w*)\b/.test(text)) {
    return 'lean_service';
  }
  if (/(retail|restaurant|cafe|store|shop|warehouse|manufactur)/.test(text)) {
    return 'physical_ops';
  }
  if (/(studio|clinic|salon|gym|sleep|wellness)/.test(text)) {
    return 'local_studio';
  }
  return 'lean_service';
}

/**
 * Cost bases sit in the low–mid band (not rock-bottom, not aggressive high).
 * Banks and investors discount optimistic decks. We start conservative.
 */
const PROFILE_BASE = Object.freeze({
  lean_service: { fixed_setup: 2200, monthly_burn: 700, variable_buffer: 450, months_reserve: 2 },
  software_product: {
    fixed_setup: 10000,
    monthly_burn: 2800,
    variable_buffer: 1600,
    months_reserve: 3,
  },
  local_studio: {
    fixed_setup: 15000,
    monthly_burn: 3800,
    variable_buffer: 2500,
    months_reserve: 3,
  },
  physical_ops: {
    fixed_setup: 28000,
    monthly_burn: 6500,
    variable_buffer: 5000,
    months_reserve: 3,
  },
});

/** Explicit low–mid posture for narrative math (never top-of-range). */
const REALISM_POSTURE = Object.freeze({
  id: 'low_mid_conservative',
  label: 'Low–mid conservative',
  growth_haircut: 0.45,
  customer_acquisition_haircut: 0.4,
  note:
    'Plans and financials use low–mid assumptions. Do not write best-case growth as the base case for banks or investors.',
});

/**
 * @param {{
 *   business_description?: string,
 *   stage?: string,
 *   revenue_model?: any,
 *   personal_capital?: any,
 *   outside_money?: any,
 *   location_micro_place?: boolean,
 *   current_financial_position?: { monthly_revenue_usd: number, monthly_costs_usd: number, cash_on_hand_usd?: number, target_monthly_revenue_usd?: number, target_monthly_costs_usd?: number },
 *   update_goal?: 'grow'|'stabilize'|'shrink'|'survive',
 * }} input
 */
function estimateLaunchFinance(input = {}) {
  const capital = normalizePersonalCapital(input.personal_capital);
  let profile = profileBusiness(input);

  const stage = input.stage || 'idea';
  // An existing/launched business with real current numbers gets a revision plan anchored to
  // those numbers instead of the cost-derived launch model below — see buildRevisionProjections.
  const revisionMode = input.current_financial_position != null;

  let fixed_setup_usd, monthly_burn_usd, variable_buffer_usd, reserve_usd, reserveMonths;
  let estimated_launch_cost_usd, costLabel, revisionProjections;

  if (revisionMode) {
    const pos = input.current_financial_position;
    revisionProjections = buildRevisionProjections({
      profile,
      current_financial_position: pos,
      update_goal: input.update_goal,
    });
    fixed_setup_usd = 0;
    variable_buffer_usd = 0;
    monthly_burn_usd = pos.monthly_costs_usd;
    reserve_usd = pos.cash_on_hand_usd ?? 0;
    reserveMonths = null;
    // The plan's capital need comes from its own cash-flow trough (computed above), not a
    // cost-model guess — a self-funding plan under the modeled trajectory needs $0.
    estimated_launch_cost_usd = revisionProjections.additional_reserve_needed_usd;
    costLabel = "plan's additional capital need";
  }

  const outside = input.outside_money || {};
  const outsideIntent =
    typeof outside === 'string'
      ? outside
      : outside.intent || outside.outside_money_intent || 'unknown';
  const kinds = financingKindsFromOutsideMoney(outside);
  const available = capital.available_usd;

  let costModel = null;
  let launchModel = null;
  let costInput = null;
  let launchInput = null;
  let funding_gap_usd;
  if (revisionMode) {
    funding_gap_usd = available == null ? null : Math.max(0, estimated_launch_cost_usd - available);
  } else {
    // The launch cost base is built up from industry, place, team and the founder's own figures
    // (see cost-model.js). The profile survives only as the setup-cost and gap-coaching bucket.
    const pd = input.plan_detail || {};
    const ops = input.interview_deepen?.operational || {};
    const finDeep = input.interview_financial || input.interview_deepen?.financial || {};
    costInput = {
      business_description: input.business_description,
      revenue_model: input.revenue_model,
      stage,
      location: input.location || null,
      key_roles: pd.team?.key_roles || null,
      staffing_plan: pd.team?.staffing_plan || null,
      team_now: ops.team_now || null,
      space_type: ops.space_type || null,
      monthly_burn_ceiling_usd: finDeep.monthly_burn_comfort_usd ?? null,
      first_revenue_timing: finDeep.first_revenue_timing || null,
      // The opening date the founder gave (Instant question 9 or the Guided Interview), as a
      // month of the model. Their first-revenue answer, when they gave one, still wins.
      opening_month: input.opening?.model_month ?? null,
      opening_request_source: input.opening ? (input.opening.source === 'founder' ? (input.opening.choice === 'asap' ? 'asap' : 'date') : 'default') : null,
      permit_tracks: input.compliance?.tracks || [],
      facility_text: pd.operations?.facility || null,
      insurance_text: pd.operations?.insurance || null,
      marketing_budget_text: pd.marketing?.budget || null,
      cost_overrides: pd.financials?.cost_overrides || null,
    };
    costModel = buildCostModel(costInput);
    profile = costModel.industry.profile;
    launchInput = {
      stage,
      capital,
      kinds,
      outsideIntent,
      statedAmount: typeof outside === 'object' ? outside.approximate_amount_usd : null,
      founderTermsText: pd.funding?.terms || null,
      revenueBuildup: normalizeRevenueBuildup(pd.financials?.revenue_buildup),
      // The runway an equity raise is sized to, when the founder gave one (months).
      // A phased launch: the license-dependent lines and their share of equipment and staff come later.
      phasing: pd.phasing || null,
      runwayMonths: parseRunwayMonths(pd.funding?.runway_months ?? pd.funding?.runway),
      existingAnnualDebtServiceUsd: money2((Array.isArray(input.existing_debts) ? input.existing_debts : []).reduce((a, d) => a + (Number(d?.monthly_payment_usd) || 0), 0) * 12),
    };
    launchModel = buildLaunchModel({ costModel, ...launchInput });
    fixed_setup_usd = launchModel.setup;
    variable_buffer_usd = launchModel.buffer;
    monthly_burn_usd = money2(costModel.steady_state_monthly_opex_usd);
    reserve_usd = launchModel.contingency;
    reserveMonths = monthly_burn_usd > 0 ? Math.round((reserve_usd / monthly_burn_usd) * 10) / 10 : null;
    estimated_launch_cost_usd = launchModel.totalSources;
    costLabel = 'modeled capital requirement';
    // Unknown owner capital leaves the gap unknown, unless the founder has named the raise.
    funding_gap_usd = available == null ? (launchModel.stated != null ? launchModel.outside : null) : launchModel.outside;
  }

  /** @type {Array<{ path: string, value: unknown, origin_type: string, founder_confirmed: boolean }>} */
  const facts = [
    {
      path: 'finance.model.profile',
      value: profile,
      origin_type: 'ASSUMED',
      founder_confirmed: false,
    },
    {
      path: 'finance.model.estimated_launch_cost_usd',
      value: estimated_launch_cost_usd,
      origin_type: 'ASSUMED',
      founder_confirmed: false,
    },
    {
      path: 'finance.model.monthly_burn_usd',
      value: monthly_burn_usd,
      origin_type: 'ASSUMED',
      founder_confirmed: false,
    },
    {
      path: 'finance.model.reserve_usd',
      value: reserve_usd,
      origin_type: 'ASSUMED',
      founder_confirmed: false,
    },
    {
      path: 'finance.founder_investment.normalized',
      value: capital,
      origin_type: 'FOUNDER',
      founder_confirmed:
        capital.disclosure === 'amount' ||
        capital.disclosure === 'zero' ||
        capital.disclosure === 'band',
    },
  ];

  if (funding_gap_usd != null) {
    facts.push({
      path: 'finance.model.funding_gap_usd',
      value: funding_gap_usd,
      origin_type: 'ASSUMED',
      founder_confirmed: false,
    });
  }

  const funding_realism = assessFundingRealism({
    personal_capital: capital,
    funding_gap_usd,
    estimated_launch_cost_usd,
    outside_money_intent: outsideIntent,
    stage,
    location_micro_place: Boolean(input.location_micro_place),
    compliance: input.compliance || null,
    cost_label: costLabel,
  });

  const gap_options = suggestGapOptions({
    funding_gap_usd,
    estimated_launch_cost_usd,
    line_items: {
      fixed_setup_usd,
      variable_buffer_usd,
      monthly_burn_usd,
      reserve_months: reserveMonths,
      reserve_usd,
    },
    profile,
    funding_path_interest: input.funding_path_interest || [],
    interview_financial: input.interview_financial || null,
    cost_label: revisionMode ? costLabel : 'launch estimate',
  });

  const business_improvements = suggestBusinessImprovements({
    profile,
    stage,
    funding_gap_usd,
    outside_money_intent: outsideIntent,
    funding_path_interest: input.funding_path_interest || [],
    interview_deepen: input.interview_deepen || null,
    location_micro_place: Boolean(input.location_micro_place),
  });

  const existingDebts = Array.isArray(input.existing_debts) ? input.existing_debts : [];
  const projections = revisionProjections || buildLaunchProjections(launchModel, costModel, stage);
  let debt_service;
  let sensitivity;
  if (revisionMode) {
    debt_service = buildDebtServiceAnalysis({
      loan_amount_usd: funding_gap_usd,
      years: projections?.years || [],
      existing_debts: existingDebts,
    });
    sensitivity = buildRevenueSensitivity(projections, debt_service);
  } else {
    debt_service =
      buildLaunchDebtService(launchModel, projections.years, existingDebts) || {
        applicable: false,
        // Why there is no coverage to show, which is not always "owner capital covers it".
        reason: !(funding_gap_usd > 0)
          ? 'no_outside_debt_modeled'
          : kinds.debt && outsideIntent === 'yes'
            ? 'loan_size_unknown'
            : outsideIntent === 'yes'
              ? 'financing_not_debt'
              : outsideIntent === 'none'
                ? 'no_outside_money_sought'
                : 'financing_not_decided',
        reference_minimum: DSCR_REFERENCE_MINIMUM,
        existing_debts_disclosed: existingDebts.length > 0,
        existing_annual_debt_service_usd: money2(existingDebts.reduce((a, d) => a + (Number(d?.monthly_payment_usd) || 0), 0) * 12),
        scenarios: [],
      };
    sensitivity = buildLaunchSensitivity(launchModel, projections, debt_service);
    projections.revenue_model = summarizeRevenueModel(launchModel, costModel, projections);
  }
  // When the business opens and why, with the model re-run for a permit that takes its full
  // allowance and for the opening the founder asked for; and the ways to bring coverage to the
  // lender's line, each computed from the same model. Both are for the owner's notes.
  const opening_analysis = launchModel ? buildOpeningAnalysis(costModel, launchModel, costInput, launchInput) : null;
  const financing_options = launchModel ? buildFinancingOptions(launchModel, projections, debt_service, costModel) : null;
  const fundingLevers = launchModel && !input.skip_funding_levers && !launchModel.fundingNeed.works && launchModel.horizon.basis === 'break_even' ? buildFundingLevers(costModel, launchModel, launchInput) : [];
  if (revisionMode) {
    // Same owner-capital-vs-gap split the launch model uses, just attached to the current
    // position the founder actually disclosed instead of a fresh set of numbers.
    projections.current_position.additional_capital_needed_usd = estimated_launch_cost_usd;
    projections.current_position.funding_gap_usd = funding_gap_usd;
  }

  facts.push({
    path: 'finance.model.realism_posture',
    value: REALISM_POSTURE.id,
    origin_type: 'ASSUMED',
    founder_confirmed: false,
  });
  facts.push({
    path: 'finance.funding_realism',
    value: {
      loan_band: funding_realism.loan_band,
      financing_band: funding_realism.financing_band,
      investor_band: funding_realism.investor_band,
    },
    origin_type: 'ASSUMED',
    founder_confirmed: false,
  });
  if (gap_options) {
    facts.push({
      path: 'finance.gap_options',
      value: {
        gap_usd: gap_options.gap_usd,
        option_count: gap_options.options.length,
        free_money_offered: gap_options.free_money_paths.length > 0,
      },
      origin_type: 'ASSUMED',
      founder_confirmed: false,
    });
  }

  return {
    ok: true,
    status: 'indicative',
    profile,
    currency: 'USD',
    realism_posture: REALISM_POSTURE,
    line_items: {
      fixed_setup_usd,
      variable_buffer_usd,
      monthly_burn_usd,
      reserve_months: reserveMonths,
      reserve_usd,
    },
    estimated_launch_cost_usd,
    personal_capital: capital,
    funding_gap_usd,
    outside_money_intent: outsideIntent,
    funding_realism,
    gap_options,
    business_improvements,
    projections,
    // Whether the plan can carry the debt it is asking for. Computed here rather than inside
    // either projection builder because it needs the funding gap, which is only known once
    // owner capital has been set against the cost — and it is the same question in both modes.
    debt_service,
    opening_analysis,
    financing_options,
    // How much of the plan rests on the revenue line: the same model re-run with revenue above
    // and below the base case, costs held.
    sensitivity,
    // Where revenue comes from: the founder's price-times-volume build-up per product, with its
    // sanity checks, or the cost-derived figure labeled as such. Null for a revision.
    revenue_model: projections?.revenue_model || null,
    // The cost build-up behind the launch model: roles and wages, payroll burden, every overhead
    // line with its source, and the flags a reader should see. Null for a revision.
    cost_model: costModel,
    // What the capital raised or borrowed pays for, and how long it lasts. Null for a revision.
    use_of_proceeds: launchModel ? buildUseOfProceeds(launchModel, costModel) : null,
    // The capital need and whether the plan works as structured, with the levers that would make it
    // work when it does not. Null for a revision.
    funding_need: launchModel ? { ...launchModel.fundingNeed, levers: fundingLevers } : null,
    // Industry size and outlook, local demographics and market sizing, each sentence carrying its
    // published source. Null for a revision, which has no cost model.
    market_context: launchModel
      ? buildMarketContext({ costModel, revenueModel: projections?.revenue_model?.basis === 'buildup' ? projections.revenue_model.market_check && { serviceable_customers: projections.revenue_model.market_check.serviceable_customers } : null, years: projections?.years, description: input.business_description })
      : null,
    benchmarks_version: COST_BENCHMARKS_VERSION,
    // Every published source behind a figure in this result, with URL and retrieval date, for the
    // documents' source list.
    data_sources: costModel
      ? [
          ...costModel.sources_used,
          // The SBA start-up equity minimum is cited wherever a loan is modeled.
          ...[...(launchModel?.loan?.terms?.sources || []), ...(launchModel?.loan ? ['sba_sop_50_10_8'] : [])]
            .filter((id) => !costModel.sources_used.some((x) => x.id === id))
            .map((id) => ({ id, ...COST_SOURCES[id] })),
          // The equipment line's prices, when the model took them from the industry research.
          ...(launchModel?.packSetup && launchModel.packRange
            ? [
                {
                  id: 'industry_pack_equipment',
                  short: 'Industry equipment prices',
                  publisher: 'Commercial equipment suppliers (list prices)',
                  title: `Must-have equipment for ${launchModel.packRange.title.replace(/ \(NAICS \d+\)$/, '').toLowerCase()}: ${launchModel.packRange.items} items priced from product listings, compiled in the industry research`,
                  reference_period: launchModel.packRange.retrieved ? launchModel.packRange.retrieved.slice(0, 4) : null,
                  url: launchModel.packRange.url,
                  retrieved: launchModel.packRange.retrieved,
                },
              ]
            : []),
        ]
      : [],
    // What the founder personally owns and owes, and what secures the loan. Neither is
    // derivable from anything here — the workspace supplies the lender's own structure, adds up
    // what is entered, and reports what is still blank.
    lender_package: buildLenderPackage({
      personal_financial_statement: input.personal_financial_statement || null,
      collateral: Array.isArray(input.collateral) ? input.collateral : [],
      loan_amount_usd: funding_gap_usd,
    }),
    labels: {
      launch_cost: revisionMode
        ? 'ASSUMED: additional capital need from the cash-flow model, not a quote'
        : 'ASSUMED: low-mid estimate, not a quote',
      personal_capital: 'FOUNDER: Instant answer #6',
      funding_gap:
        available == null
          ? 'BLOCKED: need personal capital amount or band'
          : 'ASSUMED',
      funding_odds: 'ASSUMED: planning screen, not a lender decision',
      gap_options: 'ASSUMED: planning options only, not a promise of capital',
    },
    assumption_review_required: true,
    facts,
    notes: [
      'Personal capital is never treated as launch cost.',
      'Figures are labeled ASSUMED until founder confirms or replaces with actuals.',
      'Finance binds the math. It does not invent traction.',
      REALISM_POSTURE.note,
      'Grant, incubator, and loan paths appear only when selected in Instant.',
    ],
  };
}

/**
 * Industry and local-market context for the plan, from the cited offline tables. Every sentence
 * is built from a figure in INDUSTRY_MARKET_DATA, RESTAURANT_INDUSTRY_OUTLOOK, AREA_DEMOGRAPHICS or
 * CONSUMER_SPENDING and names its publisher; nothing here is estimated. Market sizing uses the
 * founder's reachable-customer count where one was given, and the forecast's own Year 3 revenue.
 */
function marketBillions(k) {
  const usd = k * 1000;
  return usd >= 1e12 ? `$${(usd / 1e12).toFixed(2)} trillion` : usd >= 1e9 ? `$${(usd / 1e9).toFixed(1)} billion` : `$${Math.round(usd / 1e6).toLocaleString('en-US')} million`;
}

function joinMarketLabels(items) {
  return items.length <= 1 ? items.join('') : `${items.slice(0, -1).join(', ')} and ${items[items.length - 1]}`;
}

function marketPeople(n) {
  return n >= 1e6 ? `${(n / 1e6).toFixed(1)} million` : Math.round(n).toLocaleString('en-US');
}

const INDUSTRY_MARKET_CODES = Object.freeze({
  food_service: (text) => ['722', ...(/(coffee|espresso|caf[eé]|tea|juice|smoothie|bakery|pastry)/.test(text) ? ['722515'] : []), ...(/(wine|beer|\bbar\b|cocktail|brewpub|tavern|pub\b)/.test(text) ? ['7224'] : [])],
  software_saas: () => ['513210'],
  cleaning_services: () => ['561720'],
  personal_services: () => ['8121'],
  fitness_recreation: () => ['713940'],
  retail: () => ['44-45'],
  professional_services: () => ['541'],
  general: () => [],
});

function buildMarketContext({ costModel, revenueModel, years, description }) {
  if (!costModel) return null;
  const industryId = costModel.industry.id;
  const text = String(description || '').toLowerCase();
  const codes = (INDUSTRY_MARKET_CODES[industryId] || INDUSTRY_MARKET_CODES.general)(text).filter((c) => INDUSTRY_MARKET_DATA[c]);
  const used = new Set();
  const paragraphs = [];
  let headline = null;
  if (industryId === 'food_service') {
    const o = RESTAURANT_INDUSTRY_OUTLOOK;
    headline = `The National Restaurant Association projects U.S. restaurant and foodservice sales of $${(o.sales_usd / 1e12).toFixed(2)} trillion in ${o.year}, with real growth of ${o.real_growth_pct}%.`;
    paragraphs.push(`${headline} The industry is expected to employ ${marketPeople(o.employment)} people.`);
    used.add(o.source);
  }
  codes.forEach((code, i) => {
    const d = INDUSTRY_MARKET_DATA[code];
    const cbp = d.cbp;
    const econ = d.econ;
    used.add(cbp.source);
    if (econ) used.add(econ.source);
    const sentence =
      i === 0
        ? `In 2023 the United States had ${cbp.estab.toLocaleString('en-US')} ${d.label} establishments employing ${marketPeople(cbp.emp)} people, with an annual payroll of ${marketBillions(cbp.payann_k)} (Census Bureau, County Business Patterns).${econ ? ` The 2022 Economic Census recorded ${marketBillions(econ.receipts_k)} in sales.` : ''}`
        : `${d.label.replace(/^./, (c) => c.toUpperCase())} numbered ${cbp.estab.toLocaleString('en-US')} establishments with ${cbp.emp.toLocaleString('en-US')} employees in 2023${econ ? `, and recorded ${marketBillions(econ.receipts_k)} in 2022 sales` : ''}.`;
    paragraphs.push(sentence);
    if (!headline && i === 0) headline = `The U.S. ${d.label} industry recorded ${econ ? `${marketBillions(econ.receipts_k)} in sales in 2022` : `${cbp.estab.toLocaleString('en-US')} establishments in 2023`}.`;
  });
  // Two paragraphs: the industry as a whole and its outlook, then the specific categories.
  const umbrellaCount = industryId === 'food_service' ? 2 : 1;
  const detailSentences = paragraphs.splice(umbrellaCount);
  const epCode = codes.find((c) => INDUSTRY_MARKET_DATA[c].ep);
  if (epCode) {
    const ep = INDUSTRY_MARKET_DATA[epCode].ep;
    used.add(ep.source);
    paragraphs.push(
      ep.change_pct >= 0
        ? `The Bureau of Labor Statistics projects employment in ${ep.ep_label} to grow ${ep.change_pct}% between 2025 and 2035.`
        : `The Bureau of Labor Statistics projects employment in ${ep.ep_label} to decline ${Math.abs(ep.change_pct)}% between 2025 and 2035.`,
    );
  }

  // Local market.
  let local = null;
  const place = costModel.place || {};
  if (place.status !== 'not_decided') {
    const k = areaKeyFor(AREA_DEMOGRAPHICS, place);
    const a = AREA_DEMOGRAPHICS[k.key];
    const us = AREA_DEMOGRAPHICS.US;
    used.add(a.source);
    local = {
      level: k.level,
      area: a.name,
      population: a.population,
      median_household_income_usd: a.median_household_income_usd,
      paragraph:
        k.level === 'national'
          ? `Nationally, median household income was $${us.median_household_income_usd.toLocaleString('en-US')} in 2024 (Census Bureau, American Community Survey).`
          : `${a.name.replace(/^./, (c) => c.toUpperCase())} had ${a.population.toLocaleString('en-US')} residents in 2024 and a median household income of $${a.median_household_income_usd.toLocaleString('en-US')}, ${a.median_household_income_usd >= us.median_household_income_usd ? 'above' : 'below'} the national median of $${us.median_household_income_usd.toLocaleString('en-US')} (Census Bureau, American Community Survey).`,
    };
  }

  // Household spending, where the business sells food and drink.
  let consumer = null;
  const alcohol = codes.includes('7224');
  if (industryId === 'food_service') {
    const f = CONSUMER_SPENDING.food_away_from_home_usd;
    const al = CONSUMER_SPENDING.alcoholic_beverages_usd;
    used.add(f.source);
    consumer = {
      per_household_usd: alcohol ? f.value + al.value : f.value,
      sentence: `U.S. households spent an average of $${f.value.toLocaleString('en-US')} on food away from home${alcohol ? ` and $${al.value.toLocaleString('en-US')} on alcoholic beverages` : ''} in ${f.year} (Bureau of Labor Statistics, Consumer Expenditure Survey).`,
    };
  }

  // Market size: total, serviceable, obtainable.
  let sizing = null;
  const reachable = revenueModel?.serviceable_customers || null;
  const y3 = years?.find((y) => y.year === 3);
  // The total market is the most specific categories the business belongs to (coffee shops and
  // drinking places for a cafe-wine bar), not the whole umbrella industry.
  const detailCodes = (codes.length > 1 ? codes.slice(1) : codes).filter((c) => INDUSTRY_MARKET_DATA[c].econ);
  if (reachable && y3 && detailCodes.length) {
    const tamK = detailCodes.reduce((a, c) => a + INDUSTRY_MARKET_DATA[c].econ.receipts_k, 0);
    const tamLabel = joinMarketLabels(detailCodes.map((c) => INDUSTRY_MARKET_DATA[c].label.replace(/\s*\(.*\)$/, '')));
    const rows = [
      { label: 'Total market', basis: `U.S. ${tamLabel} sales, 2022 (Economic Census)`, value: marketBillions(tamK), value_usd: tamK * 1000 },
    ];
    let sam = null;
    if (consumer) {
      sam = reachable * consumer.per_household_usd;
      rows.push({
        label: 'Serviceable market',
        basis: `${reachable.toLocaleString('en-US')} reachable customers × $${consumer.per_household_usd.toLocaleString('en-US')} average annual household spending on food away from home${alcohol ? ' and alcoholic beverages' : ''} (BLS, 2024)`,
        value: `$${Math.round(sam).toLocaleString('en-US')}`,
        value_usd: sam,
      });
    }
    rows.push({
      label: 'Obtainable share',
      basis: `Year 3 forecast revenue${sam ? `, ${((y3.revenue_usd / sam) * 100).toFixed(1)}% of the serviceable market` : ''}`,
      value: `$${Math.round(y3.revenue_usd).toLocaleString('en-US')}`,
      value_usd: y3.revenue_usd,
    });
    sizing = {
      reachable_customers: reachable,
      lead: `Management estimates about ${reachable.toLocaleString('en-US')} potential customers within reach of the business. The table sizes the market from that count and published figures.`,
      rows,
      obtainable_share_of_serviceable: sam ? Math.round((y3.revenue_usd / sam) * 10000) / 10000 : null,
      note: consumer ? 'Household spending is applied per reachable customer, so the serviceable market is an order-of-magnitude figure; it overstates the market where several reachable customers share a household and understates it for visitors who spend more.' : null,
    };
  }

  const sources = [...used].map((id) => ({ id, ...COST_SOURCES[id] })).filter((s) => s.url);
  const merged = [paragraphs.join(' '), detailSentences.join(' ')].filter(Boolean);
  return { industry: { codes, headline, paragraphs: merged }, local, consumer, sizing, sources };
}

/**
 * Gap options: name the gap, suggest cuts / deferrals / smaller goals.
 * Grant/loan/incubator/equity avenues only when funding_path_interest selects them.
 *
 * @param {{
 *   funding_gap_usd: number|null,
 *   estimated_launch_cost_usd: number,
 *   line_items: Record<string, number>,
 *   profile: string,
 *   funding_path_interest?: string[],
 *   interview_financial?: Record<string, unknown>|null,
 *   cost_label?: string,
 * }} input
 */
function suggestGapOptions(input) {
  const gap = input.funding_gap_usd;
  const costLabel = input.cost_label || 'launch estimate';
  if (gap == null || gap <= 0) {
    return {
      has_gap: false,
      gap_usd: gap == null ? null : 0,
      headline:
        gap == null
          ? 'The funding gap cannot be worked out until you say how much of your own money goes in.'
          : `There is no funding gap: your own money covers the ${costLabel}.`,
      needed_vs_wanted: [],
      options: [],
      free_money_paths: [],
      notes: [
        'Confirm the figures with quotes; they are estimates.',
        'Grant, loan, incubator and licensing research is incomplete. Confirm with the offices that run them.',
      ],
    };
  }

  const launch = input.estimated_launch_cost_usd || 0;
  const items = input.line_items || {};
  const prefs = new Set(input.funding_path_interest || []);
  const fin = input.interview_financial || {};
  const skipFree = prefs.has('skip_for_now') || prefs.size === 0;

  /**
   * @type {Array<{
   *   kind: string, title: string, detail: string, estimated_relief_usd?: number|null,
   *   time_weeks?: number, risk?: 'low'|'medium'|'high', durability?: 'low'|'medium'|'high',
   * }>}
   * time_weeks/risk/durability are only set on options meant to be weighed against each other
   * by decision-council's rankRoutes (the founder's "best route, not cheapest, not fanciest
   * unless asked" instruction) — protect/needed_vs_wanted below are guardrails and a sorting
   * framework, not alternatives to rank against these three.
   */
  const options = [];

  const deferFixed = Math.round((items.fixed_setup_usd || 0) * 0.25);
  options.push({
    kind: 'defer',
    title: 'Put off setup you can open without',
    detail:
      fin.can_defer_spend
        ? `You listed these as able to wait: ${String(fin.can_defer_spend).replace(/\.$/, '')}. Buy them after the first sales.`
        : 'Hold trademark filings, premium branding and equipment you do not need to open until sales come in.',
    estimated_relief_usd: deferFixed || null,
    time_weeks: 0,
    risk: 'low',
    durability: 'high',
  });

  const cutBurn = Math.round((items.monthly_burn_usd || 0) * 0.2 * (items.reserve_months || 2));
  options.push({
    kind: 'cut',
    title: 'Cut running costs by 15% to 25% until sales build',
    detail:
      fin.monthly_burn_comfort_usd != null
        ? `You said you are comfortable spending about $${Number(fin.monthly_burn_comfort_usd).toLocaleString('en-US')} a month. Size the plan to that ceiling.`
        : 'Trim marketing tests, unused software seats and overlapping tools before asking for more money.',
    estimated_relief_usd: cutBurn || null,
    time_weeks: 0,
    risk: 'medium',
    durability: 'medium',
  });

  options.push({
    kind: 'smaller_goal',
    title: 'Open with a smaller first version',
    detail:
      input.profile === 'physical_ops' || input.profile === 'local_studio'
        ? 'Choose a ready-to-use or light build-out space over a full build-out, and open with a shorter menu or fewer services.'
        : 'Start with a narrower offer (one channel, one kind of customer) before the full version.',
    estimated_relief_usd: Math.round(gap * 0.35),
    time_weeks: 4,
    risk: 'low',
    durability: 'high',
  });

  if (fin.must_have_spend) {
    options.push({
      kind: 'protect',
      title: 'Protect what you must spend',
      detail: `Keep these funded: ${String(fin.must_have_spend).replace(/\.$/, '')}. Cut around them, not through them.`,
      estimated_relief_usd: null,
    });
  }

  options.push({
    kind: 'needed_vs_wanted',
    title: 'Sort every cost into needed, wanted and can wait',
    detail:
      'For each line: needed to open, wanted for polish, or able to wait 90 days. Borrow or raise money only for the first.',
    estimated_relief_usd: null,
  });

  /** @type {Array<{ path: string, title: string, detail: string }>} */
  const free_money_paths = [];
  if (!skipFree) {
    if (prefs.has('grants')) {
      free_money_paths.push({
        path: 'grants',
        title: 'Check local, state and federal grant lists',
        detail:
          'Grants are competitive and slow. Check that you qualify before counting on the timing; no award is assumed in this plan.',
      });
    }
    if (prefs.has('loans')) {
      free_money_paths.push({
        path: 'loans',
        title: 'Prepare a careful loan application',
        detail:
          'Use the figures in this plan, show your own equity clearly, and list what the money is for. Community and SBA lenders still review every application closely.',
      });
    }
    if (prefs.has('incubators')) {
      free_money_paths.push({
        path: 'incubators',
        title: 'Shortlist incubators and accelerators that fit your stage',
        detail:
          'Look for space, mentoring or small grants rather than publicity, and read any equity terms carefully.',
      });
    }
    if (prefs.has('equity')) {
      free_money_paths.push({
        path: 'equity',
        title: 'Look for investors only if giving up ownership is intended',
        detail:
          'Investors discount optimistic pitches. Claim only the traction you can show, and lead with the problem and a careful plan.',
      });
    }
  }

  const needed_vs_wanted = [
    {
      bucket: 'needed',
      examples:
        fin.must_have_spend ||
        'Formation basics, required licenses, and the minimum space and tools to serve the first customers',
    },
    {
      bucket: 'wanted',
      examples: 'Brand polish, extra inventory, marketing campaigns, a nicer build-out',
    },
    {
      bucket: 'can_do_without',
      examples:
        fin.can_defer_spend ||
        'Trademark filings, extra software seats, non-essential contractors',
    },
  ];

  // What the options are actually worth, together, against the gap they are offered for.
  //
  // Without this the section reads as a way out that it is not: on the sample cafe the three
  // quantified options come to $24,025 against a $37,500 gap, so a founder doing every one of
  // them is still $13,475 short — and the heading says "ways to close the gap". Trimming helping
  // and trimming finishing the job are different claims, and only the reader can tell them
  // apart if the arithmetic is stated.
  const combinedRelief = money2(
    options.reduce((sum, o) => sum + (Number.isFinite(o.estimated_relief_usd) ? o.estimated_relief_usd : 0), 0),
  );
  const remainingAfterOptions = money2(Math.max(0, gap - combinedRelief));

  return {
    has_gap: true,
    gap_usd: gap,
    headline: `The plan needs about $${Math.round(gap).toLocaleString('en-US')} from outside your own money, of about $${Math.round(launch).toLocaleString('en-US')} in all.`,
    needed_vs_wanted,
    options,
    combined_relief_usd: combinedRelief,
    remaining_after_options_usd: remainingAfterOptions,
    options_close_the_gap: remainingAfterOptions <= 0,
    free_money_paths,
    notes: [
      'The gap is worked out from estimates; replace them with quotes.',
      skipFree
        ? 'Grant, loan, incubator and investor paths are shown only when you choose them in Instant Build.'
        : 'The funding paths below follow what you chose in Instant Build. None is a promise of money.',
      'This grant, loan, incubator and investor research is incomplete. Confirm with the office that runs each program before you apply or spend.',
    ],
  };
}

/**
 * Financial / operational / strategic improvements from interview answers.
 * Advice only — never invents traction or awards.
 *
 * @param {{
 *   profile: string,
 *   stage?: string,
 *   funding_gap_usd?: number|null,
 *   outside_money_intent?: string,
 *   funding_path_interest?: string[],
 *   interview_deepen?: Record<string, any>|null,
 *   location_micro_place?: boolean,
 * }} input
 */
function suggestBusinessImprovements(input) {
  const deepen = input.interview_deepen || {};
  const fin = deepen.financial || {};
  const ops = deepen.operational || {};
  const strat = deepen.strategic || {};

  /** @type {Array<{ domain: string, title: string, detail: string, source: string }>} */
  const items = [];

  // Financial
  if ((input.funding_gap_usd || 0) > 0) {
    items.push({
      domain: 'financial',
      title: 'Line up the money before you fix an opening date',
      detail:
        'Lenders and partners read an optimistic opening date as risk. Set the date once your own contribution and the financing are confirmed.',
      source: 'finance_screen',
    });
  }
  if (fin.first_revenue_timing === '6_plus_months' || fin.first_revenue_timing === 'unknown') {
    items.push({
      domain: 'financial',
      title: 'Bring the first sale forward',
      detail:
        'A pre-order, a paid pilot or a soft opening often beats waiting for the perfect launch. Put a dated test on the To-Do List.',
      source: 'interview_financial',
    });
  } else if (fin.first_revenue_timing === 'already' || fin.first_revenue_timing === 'under_30_days') {
    items.push({
      domain: 'financial',
      title: 'Keep clean records of early sales',
      detail:
        'Keep invoices, deposits and refund policies in order. Early sales count with a lender only when the books can show them.',
      source: 'interview_financial',
    });
  }
  if (fin.monthly_burn_comfort_usd != null) {
    items.push({
      domain: 'financial',
      title: 'Hold monthly spending to the limit you set',
      detail: `Treat about $${Number(fin.monthly_burn_comfort_usd).toLocaleString('en-US')} a month as a hard ceiling until sales cover it.`,
      source: 'interview_financial',
    });
  }

  // Operational
  if (ops.space_type === 'full_buildout') {
    items.push({
      domain: 'operational',
      title: 'Compare a full build-out with a ready-to-use space',
      detail:
        'A full build-out stretches the timeline and the capital. Price a ready-to-use or light build-out space that still serves the first customers.',
      source: 'interview_operational',
    });
  } else if (ops.space_type === 'home' || ops.space_type === 'online_only') {
    items.push({
      domain: 'operational',
      title: 'Treat low overhead as an advantage',
      detail:
        'Working from home or online keeps fixed costs low. Present that in the Business Plan as a strength.',
      source: 'interview_operational',
    });
  } else if (ops.space_type === 'turnkey' || ops.space_type === 'light_buildout') {
    items.push({
      domain: 'operational',
      title: 'Replace estimated rent and fit-out with quotes',
      detail:
        'Get landlord and contractor quotes before you share the Financial Statements.',
      source: 'interview_operational',
    });
  }

  if (ops.team_now === 'solo' && (ops.weekly_hours === 'under_10' || ops.weekly_hours === '10_20')) {
    items.push({
      domain: 'operational',
      title: 'Match scope to available hours',
      detail:
        'Owners working alone part time do best with one offer and one way of finding customers. Wait on a second product until the first sells repeatedly.',
      source: 'interview_operational',
    });
  }
  if (ops.first_customer_path) {
    items.push({
      domain: 'operational',
      title: 'Make finding the first customers someone’s job',
      // The path itself is stated wherever this item is shown — the Operations playbook leads
      // with it and the Business Plan's marketing section carries it — so repeating it verbatim
      // here put the same sentence twice on one page. What this item adds is the instruction.
      detail: 'Give the first-customer plan an owner and a weekly routine, so it happens rather than staying an intention.',
      source: 'interview_operational',
    });
  } else {
    items.push({
      domain: 'operational',
      title: 'Name the first ten customers',
      detail:
        'Write a concrete path (referrals, local partnerships, an outreach list). Vague “marketing” does not survive a conversation with a lender.',
      source: 'profile_default',
    });
  }

  if (input.location_micro_place) {
    items.push({
      domain: 'operational',
      title: 'Use your local network',
      detail:
        'In a small place, one trusted referral network often beats broad advertising. Note local partnerships in the Business Plan.',
      source: 'location_screen',
    });
  }

  // Strategic
  if (strat.ninety_day_goal) {
    items.push({
      domain: 'strategic',
      title: 'Aim the next 90 days at your goal',
      detail: `Your 90-day goal: ${String(strat.ninety_day_goal).replace(/\.$/, '')}. Line up the open actions behind it, or put them off.`,
      source: 'interview_strategic',
    });
  } else {
    items.push({
      domain: 'strategic',
      title: 'Set one measurable 90-day goal',
      detail:
        'Example: first 10 paying customers, license filed, or soft-open weekend. Not “build the brand.”',
      source: 'profile_default',
    });
  }
  if (strat.edge_one_liner) {
    items.push({
      domain: 'strategic',
      title: 'Say your edge the same way everywhere',
      detail: `Use this line in the plan and the pitch alike: “${String(strat.edge_one_liner).replace(/\.$/, '')}.”`,
      source: 'interview_strategic',
    });
  }
  if (strat.biggest_risk) {
    items.push({
      domain: 'strategic',
      title: 'Plan for the risk you named',
      detail: `You named this risk: ${String(strat.biggest_risk).replace(/\.$/, '')}. Put who will handle it, and by when, on the To-Do List.`,
      source: 'interview_strategic',
    });
  }

  if (input.stage === 'idea') {
    items.push({
      domain: 'strategic',
      title: 'Prove demand before heavy spend',
      detail:
        'At the idea stage, talk to customers, take a waitlist and run small tests before buying inventory or signing a long lease.',
      source: 'stage',
    });
  } else if (input.stage === 'launched' || input.stage === 'existing') {
    items.push({
      domain: 'strategic',
      title: 'Keep day-to-day money apart from growth spending',
      detail:
        'Keep working capital for the current business separate from expansion tests in the Financial Statements.',
      source: 'stage',
    });
  }

  const prefs = new Set(input.funding_path_interest || []);
  if (prefs.has('grants') || prefs.has('incubators') || prefs.has('loans') || prefs.has('equity')) {
    items.push({
      domain: 'financial',
      title: 'Prepare only the applications you chose',
      detail:
        'Grant, incubator and lender extras stay out of the core documents until you select them. Keep the package focused.',
      source: 'funding_prefs',
    });
  }

  return {
    status: 'advisory',
    label: 'Improvement notes from your answers. Review them before sharing.',
    items,
    domains: {
      financial: items.filter((i) => i.domain === 'financial'),
      operational: items.filter((i) => i.domain === 'operational'),
      strategic: items.filter((i) => i.domain === 'strategic'),
    },
  };
}

/**
 * Conservative funding-odds screen for banks / other financing / investors.
 * Bands are deliberately cautious; never promises capital.
 *
 * @param {{
 *   personal_capital: { available_usd: number|null },
 *   funding_gap_usd: number|null,
 *   estimated_launch_cost_usd: number,
 *   outside_money_intent?: string,
 *   stage?: string,
 *   location_micro_place?: boolean,
 *   compliance?: { closed_cycle_count?: number, planning_horizon_days?: number } | null,
 *   cost_label?: string,
 * }} input
 */
function assessFundingRealism(input) {
  const available = input.personal_capital?.available_usd;
  const gap = input.funding_gap_usd;
  const launch = input.estimated_launch_cost_usd || 0;
  const costLabel = input.cost_label || 'indicative launch cost';
  const equityRatio =
    available == null || launch <= 0 ? null : Math.min(1, Math.max(0, available / launch));

  let loanScore = 40; // start mid-low
  let financingScore = 38;
  let investorScore = 28;

  if (available === 0) {
    loanScore -= 18;
    financingScore -= 12;
    investorScore -= 8;
  } else if (available == null) {
    loanScore -= 15;
    financingScore -= 10;
    investorScore -= 6;
  } else if (equityRatio != null && equityRatio >= 0.3) {
    loanScore += 12;
    financingScore += 8;
  } else if (equityRatio != null && equityRatio < 0.1) {
    loanScore -= 12;
    financingScore -= 6;
  }

  if (gap != null && gap > launch * 0.7) {
    loanScore -= 10;
    investorScore -= 4;
  }

  if (input.stage === 'idea') {
    loanScore -= 14;
    financingScore -= 8;
    investorScore -= 6;
  } else if (input.stage === 'pre_launch') {
    loanScore -= 8;
    financingScore -= 4;
  }

  if (input.location_micro_place) {
    // Rural / micro-place: some SBA / community lenders exist, but investor density is lower.
    investorScore -= 8;
    financingScore += 2;
  }

  if (input.compliance?.closed_cycle_count > 0) {
    loanScore -= 10;
    financingScore -= 8;
    investorScore -= 6;
  }
  if ((input.compliance?.planning_horizon_days || 0) > 180) {
    loanScore -= 6;
    financingScore -= 4;
  }

  if (input.outside_money_intent === 'none') {
    investorScore -= 10;
  } else if (input.outside_money_intent === 'yes') {
    investorScore += 6;
    financingScore += 4;
  }

  const clamp = (n) => Math.max(5, Math.min(70, n)); // never imply high certainty
  loanScore = clamp(loanScore);
  financingScore = clamp(financingScore);
  investorScore = clamp(investorScore);

  const band = (score) =>
    score < 28 ? 'low' : score < 48 ? 'low_mid' : score < 62 ? 'mid' : 'mid'; // cap narrative at mid

  const loan_band = band(loanScore);
  const financing_band = band(financingScore);
  const investor_band = band(investorScore);

  const council_summary = [
    `Funding realism (${REALISM_POSTURE.label}): bank loan odds screen ${loan_band.replace('_', '–')}, other financing ${financing_band.replace('_', '–')}, investor odds ${investor_band.replace('_', '–')}.`,
    'These are cautionary screens for plan writing, not predictions or offers of capital.',
    equityRatio == null
      ? 'Owner equity share unknown or thin. Lenders usually want more clarity and skin in the game.'
      : `Owner capital covers ~${Math.round(equityRatio * 100)}% of ${costLabel} (low–mid model).`,
    input.compliance?.closed_cycle_count
      ? 'Closed or scarce license cycles weaken near-term repayment stories. Fix the calendar before implying loan readiness.'
      : 'No closed license cycle flagged in the compliance screen.',
  ].join(' ');

  return {
    posture: REALISM_POSTURE,
    loan_band,
    financing_band,
    investor_band,
    scores: {
      loan: loanScore,
      financing: financingScore,
      investor: investorScore,
    },
    owner_equity_ratio: equityRatio,
    council_summary,
    guidance: [
      'Write base-case revenue and customer counts in the low–mid band.',
      'Do not use best-case growth as the bank or investor base case.',
      'Tie launch dates to confirmed license cycles, not hopeful calendars.',
      'Never invent traction, deposits, collateral, or term sheets.',
    ],
  };
}

