/**
 * Straight-line book lives, in years, by asset class. Opening inventory and deposits are not
 * depreciated. The lives are planning choices, disclosed as assumptions: equipment and furniture
 * over 7 years, computers and point-of-sale over 5, leasehold improvements over 10 (never longer
 * than the lease in practice), and start-up and organizational costs over 15 years, the period the
 * tax code uses for start-up cost amortization.
 */
function assetLifeYears(assetClass) {
  const key = `depreciation_life_${assetClass}_years`;
  return MODEL_ASSUMPTIONS[key] ? MODEL_ASSUMPTIONS[key].value : null;
}

/** A setup total split into its categories, rounding landing on the last line so it foots. */
function splitSetupCategories(total, split) {
  const rows = split.map((c) => ({ label: c.label, asset_class: c.asset_class || null, amount_usd: money2(total * c.share), basis: c.basis || null, source: c.source || null }));
  const drift = money2(total - rows.reduce((a, c) => a + c.amount_usd, 0));
  if (drift !== 0 && rows.length) rows[rows.length - 1].amount_usd = money2(rows[rows.length - 1].amount_usd + drift);
  return rows;
}

/**
 * Straight-line depreciation and amortization of the setup assets over 36 months, starting in the
 * month the business opens (when the assets are placed in service).
 */
function buildDepreciationSchedule(categories, startMonth) {
  const start = Math.max(1, startMonth || 1);
  const monthly = Array.from({ length: 36 }, () => 0);
  const rows = categories.map((c) => {
    const life = assetLifeYears(c.asset_class);
    if (!life || !(c.amount_usd > 0)) return { ...c, life_years: life, monthly_usd: 0 };
    const perMonth = c.amount_usd / (life * 12);
    for (let m = start; m <= 36; m++) monthly[m - 1] += perMonth;
    return { ...c, life_years: life, monthly_usd: money2(perMonth) };
  });
  const rounded = monthly.map(money2);
  const sum = (a, b) => money2(rounded.slice(a, b).reduce((x, y) => x + y, 0));
  const byYear = { 1: sum(0, 12), 2: sum(12, 24), 3: sum(24, 36) };
  const depreciable = money2(rows.filter((r) => r.life_years).reduce((a, r) => a + r.amount_usd, 0));
  return {
    start_month: start,
    categories: rows,
    monthly: rounded,
    by_year: byYear,
    depreciable_cost_usd: depreciable,
    non_depreciable_cost_usd: money2(rows.reduce((a, r) => a + r.amount_usd, 0) - depreciable),
    accumulated_by_year_end: { 1: byYear[1], 2: money2(byYear[1] + byYear[2]), 3: money2(byYear[1] + byYear[2] + byYear[3]) },
  };
}

/**
 * A dollar figure for prose, or a stated absence when there is no figure.
 *
 * Exists because a raw `$${Math.round(x).toLocaleString()}` renders NaN as the four characters
 * "$NaN", and that is what the Business Plan printed when a free-text answer landed in a field
 * this engine reads as a structured object. The document-pack side already guards its own
 * `money()`; this is the same guarantee for figures the engine writes into its assumption strings.
 *
 * Callers that would rather not print the sentence at all should check the value first — this
 * only guarantees that whatever prints is never NaN or Infinity.
 */
function proseMoney(n, absent = 'not yet quantified') {
  // null and '' coerce to 0 through Number(), and zero is a claim while absent is not — the same
  // reason an unfilled personal financial statement prints no net worth rather than $0.
  if (n == null || n === '') return absent;
  const v = Number(n);
  if (!Number.isFinite(v)) return absent;
  const rounded = Math.round(v);
  return rounded < 0
    ? `-$${Math.abs(rounded).toLocaleString('en-US')}`
    : `$${rounded.toLocaleString('en-US')}`;
}

/** Month-by-month ramp (fraction of stabilized monthly revenue), by stage. Idea ramps slowest. */
const STAGE_RAMP = Object.freeze({
  idea: [0, 0, 0.05, 0.1, 0.2, 0.3, 0.45, 0.6, 0.72, 0.83, 0.92, 1],
  pre_launch: [0.05, 0.1, 0.2, 0.32, 0.45, 0.58, 0.7, 0.8, 0.88, 0.94, 0.98, 1],
  launched: [0.5, 0.55, 0.6, 0.66, 0.72, 0.78, 0.84, 0.89, 0.93, 0.96, 0.98, 1],
  existing: [0.6, 0.63, 0.67, 0.71, 0.75, 0.8, 0.84, 0.88, 0.92, 0.95, 0.98, 1],
});

/** Low-mid conservative YoY growth for years 2-3, consistent with REALISM_POSTURE. */
const ANNUAL_GROWTH_RATE = 0.18;
/** Share of revenue growth that flows into opex growth; the rest is treated as operating leverage. */
const OPEX_SCALE_WITH_REVENUE = 0.4;
/** Modest steady-state operating margin used to size the cost-based revenue target. */
const TARGET_OPERATING_MARGIN = 0.12;
/**
 * Flat estimated income-tax rate applied to positive operating income only, for a bottom-line
 * "after estimated taxes" figure — a rough planning placeholder, not a real tax calculation.
 * Actual liability depends on entity structure (sole prop / LLC pass-through / S-corp / C-corp),
 * state, deductions, and credits, none of which are collected here; a real accountant is still
 * required before this number is relied on. Never applied to a loss (no fabricated tax benefit).
 */
const INCOME_TAX_RATE = 0.25;

/**
 * Debt-service coverage minimum a lender is commonly looking for. Confirm the figure with the
 * actual lender — it varies by programme and by bank, and it moves. Reported as a reference line
 * on the analysis rather than as a verdict.
 */
const DSCR_REFERENCE_MINIMUM = MODEL_ASSUMPTIONS.dscr_flag_threshold.value;

/**
 * Rate and term scenarios used when the founder has no quoted terms yet.
 *
 * A single invented rate would be the one number in this workspace that was made up, and the
 * answer moves a lot with it — so the analysis is run across a spread and presented as a
 * sensitivity, which is what a lender conversation actually sounds like before terms are offered.
 */
const DEBT_SERVICE_SCENARIOS = Object.freeze([
  { label: 'Favorable', annual_rate: 0.08, term_years: 10 },
  { label: 'Mid', annual_rate: 0.105, term_years: 7 },
  { label: 'Conservative', annual_rate: 0.13, term_years: 5 },
]);

/**
 * Level monthly payment on an amortising loan.
 *
 * @param {number} principalUsd
 * @param {number} annualRate  e.g. 0.105 for 10.5%
 * @param {number} termYears
 */
function monthlyLoanPayment(principalUsd, annualRate, termYears) {
  const principal = Number(principalUsd);
  const months = Math.round(Number(termYears) * 12);
  if (!(principal > 0) || !(months > 0)) return 0;
  const monthlyRate = Number(annualRate) / 12;
  // An interest-free loan is just the principal spread over the term; the formula below divides
  // by zero there.
  if (!(monthlyRate > 0)) return money2(principal / months);
  return money2((principal * monthlyRate) / (1 - Math.pow(1 + monthlyRate, -months)));
}

/**
 * Debt-service coverage on the modelled years, across rate and term scenarios.
 *
 * This is the ratio a lender decides on, and the workspace previously did not compute it at all —
 * it asked for a loan and never showed whether the plan could carry one. Coverage is operating
 * income over annual debt service.
 *
 * That numerator already is EBITDA. No depreciation is charged anywhere in this model: the
 * monthly P&L runs revenue, COGS, operating expenses, operating income, tax, net income, and
 * none of the twelve opex categories is depreciation, while the equipment and buildout spend
 * sits on the balance sheet as a fixed asset and is never written down. So operating income is
 * earnings before interest, tax, depreciation and amortisation by construction, and a lender
 * underwriting on EBITDA arrives at the same coverage shown here.
 *
 * This comment, and the note printed beside the table, used to say the opposite — that the
 * figure was "before any depreciation add-back" and that a lender would "calculate slightly
 * higher coverage than shown". Both were wrong: nothing was deducted, so there is nothing to add
 * back, and a document telling a bank its own coverage figure is understated is worse than
 * saying nothing.
 *
 * The real consequence runs the other way and is now what gets disclosed: with the fixed asset
 * never depreciated, net income and the tax provision below it are higher than they would be
 * for a business writing those assets down.
 *
 * A year that loses money cannot service debt at any rate. That is reported as null coverage
 * rather than a negative ratio dressed up as a number.
 *
 * Debt the founder already carries counts. A lender adds every obligation to the new loan before
 * dividing, so coverage computed on the new loan alone reads better than the business actually
 * is — the same flattery as quoting a later year. Existing payments are included when disclosed,
 * and their absence is reported so it is not mistaken for zero.
 *
 * @param {{ loan_amount_usd: number|null, years: Array<{year:number, operating_income_usd:number}>, existing_debts?: Array<{creditor?:string, monthly_payment_usd?:number}>, scenarios?: Array<{label:string, annual_rate:number, term_years:number}> }} input
 */
function buildDebtServiceAnalysis(input) {
  const loanAmount = input.loan_amount_usd;
  const years = Array.isArray(input.years) ? input.years : [];
  const existingDebts = Array.isArray(input.existing_debts) ? input.existing_debts : [];
  const existingMonthly = money2(
    existingDebts.reduce((sum, d) => sum + (Number(d?.monthly_payment_usd) || 0), 0),
  );
  const existingAnnual = money2(existingMonthly * 12);
  const debtsDisclosed = existingDebts.length > 0;

  if (!(loanAmount > 0) || !years.length) {
    return {
      applicable: false,
      reason: !(loanAmount > 0) ? 'no_outside_debt_modeled' : 'no_projection_years',
      reference_minimum: DSCR_REFERENCE_MINIMUM,
      existing_debts_disclosed: debtsDisclosed,
      existing_annual_debt_service_usd: existingAnnual,
      scenarios: [],
    };
  }

  const scenarios = (input.scenarios || DEBT_SERVICE_SCENARIOS).map((sc) => {
    const monthly = monthlyLoanPayment(loanAmount, sc.annual_rate, sc.term_years);
    const newLoanAnnual = money2(monthly * 12);
    // Everything the business owes, not just what it is asking for.
    const annualDebtService = money2(newLoanAnnual + existingAnnual);
    const coverage = years.map((y) => {
      // EBITDA where the year carries depreciation (operating income plus the non-cash charge);
      // for a year with none, operating income is already EBITDA.
      const operatingIncome = money2(y.ebitda_usd ?? y.operating_income_usd);
      // Below zero there is nothing to cover payments with, at any rate or term.
      const ratio = operatingIncome > 0 && annualDebtService > 0
        ? Math.round((operatingIncome / annualDebtService) * 100) / 100
        : null;
      return {
        year: y.year,
        operating_income_usd: operatingIncome,
        annual_debt_service_usd: annualDebtService,
        dscr: ratio,
        meets_reference_minimum: ratio != null && ratio >= DSCR_REFERENCE_MINIMUM,
      };
    });
    // Payments start when the loan is drawn, so what matters first is whether year one can make
    // them — not whether some later year could. A plan that cannot needs a different structure
    // (an interest-only period, a deferred start, or more reserve), and saying "clears in year
    // two" instead would bury that.
    const yearOne = coverage.find((c) => c.year === 1);
    const yearOneShortfall = yearOne
      ? money2(Math.max(0, annualDebtService - Math.max(0, yearOne.operating_income_usd)))
      : null;

    return {
      label: sc.label,
      annual_rate: sc.annual_rate,
      term_years: sc.term_years,
      monthly_payment_usd: monthly,
      new_loan_annual_debt_service_usd: newLoanAnnual,
      existing_annual_debt_service_usd: existingAnnual,
      annual_debt_service_usd: annualDebtService,
      coverage,
      // The first modelled year that clears the reference line, if any.
      first_year_meeting_minimum: coverage.find((c) => c.meets_reference_minimum)?.year ?? null,
      // What year one is short by, on top of whatever the cash-flow trough already asks for.
      year_one_shortfall_usd: yearOneShortfall,
    };
  });

  const servicesFromYearOne = scenarios.every((sc) => sc.first_year_meeting_minimum === 1);
  return {
    applicable: true,
    loan_amount_usd: money2(loanAmount),
    reference_minimum: DSCR_REFERENCE_MINIMUM,
    // Absent is not the same as zero, and only one of those is safe to assume.
    existing_debts_disclosed: debtsDisclosed,
    existing_debts: existingDebts,
    existing_annual_debt_service_usd: existingAnnual,
    scenarios,
    // Whether the plan can make payments from the moment the loan is drawn. This is the
    // headline; a plan that only covers later needs its loan structured around that.
    services_debt_from_year_one: servicesFromYearOne,
    // The worst year-one gap across the scenarios, so the ask is sized off the hardest terms
    // rather than the most flattering.
    worst_year_one_shortfall_usd: scenarios.reduce(
      (worst, sc) => (sc.year_one_shortfall_usd != null && sc.year_one_shortfall_usd > worst ? sc.year_one_shortfall_usd : worst),
      0,
    ),
    // The cash-flow trough elsewhere in this model is computed before any debt payments, so a
    // plan servicing a loan needs more reserve than that trough alone implies.
    note: 'Coverage is operating income over annual debt service. The cash-flow trough shown elsewhere excludes these payments.',
  };
}

function money2(n) {
  return Math.round((n + Number.EPSILON) * 100) / 100;
}

/**
 * Year-end balance sheets and an annual cash summary for Years 1–3 of a launch plan.
 *
 * A lender's projection set is three statements, not two: profit and loss, cash flow, and the
 * balance sheet at each year end. Only the opening balance sheet existed, so nothing showed what
 * the business would own and owe once it had been trading — and nothing proved the three
 * statements agreed with each other.
 *
 * Every figure is carried from something already in the model, which is what makes it a tie-out
 * rather than a fourth estimate:
 *   - Year 1 ending cash is the month-12 ending cash of the Year 1 cash-flow projection.
 *   - Years 2–3 add that year's net income, because this model is cash-basis with no receivables,
 *     payables, inventory build, or depreciation — net income and operating cash flow are the
 *     same number by construction.
 *   - Fixed assets stay at cost (the model charges no depreciation, as its assumptions disclose).
 *   - Financing payable stays at the amount drawn: no loan terms have been quoted, so principal
 *     repayment is not modeled — the Debt Service section sizes the payments separately.
 *   - Equity is owner capital plus cumulative net income.
 * Assets equal liabilities plus equity every year, and that is enforced by test.
 *
 * @param {{ balance_sheet: object, year1_cash_flow: Array<{ending_cash_usd:number}>, years: Array<{year:number, net_income_usd:number}> }} proj
 */
function buildProjectedPosition(proj) {
  const bs = proj.balance_sheet;
  if (!bs || !Array.isArray(proj.years) || !proj.years.length || !proj.year1_cash_flow?.length) return null;
  const openingCash = bs.assets.cash_usd;
  const fixedAssets = bs.assets.fixed_assets_usd;
  const financing = bs.liabilities.financing_payable_usd;
  const ownerCapital = bs.equity.owner_capital_usd;

  const annual_cash_summary = [];
  const projected_balance_sheets = [];
  let cash = openingCash;
  let retained = 0;
  for (const y of proj.years) {
    const beginning = cash;
    const netIncome = money2(y.net_income_usd);
    const ending =
      y.year === 1 ? money2(proj.year1_cash_flow[proj.year1_cash_flow.length - 1].ending_cash_usd) : money2(beginning + netIncome);
    annual_cash_summary.push({
      year: y.year,
      beginning_cash_usd: money2(beginning),
      net_cash_from_operations_usd: money2(ending - beginning),
      ending_cash_usd: ending,
    });
    cash = ending;
    retained = money2(retained + netIncome);
    const totalAssets = money2(ending + fixedAssets);
    const totalEquity = money2(ownerCapital + retained);
    projected_balance_sheets.push({
      year: y.year,
      cash_usd: ending,
      fixed_assets_usd: money2(fixedAssets),
      total_assets_usd: totalAssets,
      financing_payable_usd: money2(financing),
      total_liabilities_usd: money2(financing),
      owner_capital_usd: money2(ownerCapital),
      retained_earnings_usd: retained,
      total_equity_usd: totalEquity,
      total_liabilities_and_equity_usd: money2(financing + totalEquity),
    });
  }
  return { annual_cash_summary, projected_balance_sheets };
}

/** Revenue scenarios for the sensitivity table: a shortfall of a fifth, a tenth, the base, and a
 * tenth better. Costs are held at the base case in every row, which is the conservative reading —
 * a business that sells less rarely spends proportionally less in its first year. */
const SENSITIVITY_REVENUE_FACTORS = Object.freeze([0.8, 0.9, 1, 1.1]);

/**
 * What the plan looks like if revenue lands above or below the base case.
 *
 * Every row re-runs the same monthly P&L, tax and cash-flow code the base projection uses, with
 * the revenue series scaled and nothing else changed. Nothing new is estimated: the point is to
 * show a reader how much of the plan rests on the revenue line, which is the question a lender or
 * investor asks first of a projection built before any sales exist.
 *
 * @param {object} proj           Launch or revision projection.
 * @param {object} [debtService]  buildDebtServiceAnalysis output, for Year 2 coverage.
 */
function buildRevenueSensitivity(proj, debtService) {
  if (!proj || !Array.isArray(proj.year1_monthly) || proj.year1_monthly.length !== 12) return null;
  const cogsRatio = proj.cogs_ratio;
  const baseRevenue = proj.year1_monthly.map((m) => m.revenue_usd);
  const opex = proj.year1_monthly.map((m) => m.opex_usd);
  const openingCash =
    proj.mode === 'revision' ? proj.current_position?.cash_on_hand_usd ?? 0 : proj.balance_sheet?.assets?.cash_usd ?? 0;
  const mid = debtService?.applicable ? debtService.scenarios.find((s) => s.label === 'Mid') || debtService.scenarios[0] : null;

  const rows = SENSITIVITY_REVENUE_FACTORS.map((factor) => {
    const monthly = buildYear1Monthly(baseRevenue.map((r) => r * factor), opex, cogsRatio);
    const totals = buildYear1Totals(monthly);
    const years = buildYears2And3(monthly, totals, cogsRatio);
    const cash = buildYear1CashFlow(monthly, openingCash);
    const contribution = 1 - cogsRatio;
    const breakEvenRevenue = proj.break_even?.break_even_monthly_revenue_usd ?? money2(opex[11] / contribution);
    const beIdx = monthly.findIndex((m) => m.revenue_usd >= breakEvenRevenue);
    const y2 = years.find((y) => y.year === 2);
    const y2Dscr =
      mid && y2 && y2.operating_income_usd > 0 && mid.annual_debt_service_usd > 0
        ? Math.round((y2.operating_income_usd / mid.annual_debt_service_usd) * 100) / 100
        : null;
    return {
      revenue_change_pct: Math.round((factor - 1) * 100),
      year1_revenue_usd: totals.revenue_usd,
      year1_operating_income_usd: totals.operating_income_usd,
      year1_low_cash_usd: cash.cash_flow_trough_usd,
      break_even_month: beIdx === -1 ? null : beIdx + 1,
      year2_revenue_usd: y2 ? y2.revenue_usd : null,
      year2_operating_income_usd: y2 ? y2.operating_income_usd : null,
      year2_dscr_mid: y2Dscr,
    };
  });
  return {
    basis: 'Revenue scaled by the stated percentage in every month; costs held at the base case.',
    dscr_terms: mid ? { label: mid.label, annual_rate: mid.annual_rate, term_years: mid.term_years } : null,
    rows,
  };
}

/**
 * Cost-based stabilized monthly revenue target: sized so the business can sustainably cover
 * its own modeled cost structure with a modest margin. This is a planning target derived from
 * cost structure, not a market-validated sales forecast — actual revenue depends on price and
 * volume the founder has not specified in Instant Build.
 */
function stabilizedMonthlyRevenue(monthlyBurnUsd, cogsRatio) {
  const denom = 1 - cogsRatio - TARGET_OPERATING_MARGIN;
  if (denom <= 0) return monthlyBurnUsd / Math.max(0.05, 1 - cogsRatio);
  return monthlyBurnUsd / denom;
}

/**
 * Builds the Year-1 monthly P&L from a 12-value revenue series and a 12-value opex series.
 * Shared by the from-scratch launch model and the existing-business revision model — the only
 * difference between them is how the revenue/opex series were derived, not how P&L math works.
 *
 * Tax accrues against cumulative year-to-date operating income, not each month in isolation: an
 * early loss month owes nothing, and a later month "catches up" once the year turns cumulatively
 * profitable. This mirrors how estimated quarterly tax payments true up against year-to-date
 * income, and it is the only way the monthly rows stay consistent with the annual total (summed
 * independently, a loss year could still show tax owed).
 */
function buildYear1Monthly(revenueSeries, opexSeries, cogsRatio, interestSeries = [], cogsSeries = null, depreciationSeries = []) {
  let cumulativePretax = 0;
  let cumulativeTaxAccrued = 0;
  return revenueSeries.map((rawRevenue, idx) => {
    const revenue = money2(rawRevenue);
    // A revenue build-up carries its own cost of goods (each tier's variable cost per unit); the
    // cost-derived model applies the industry ratio.
    const cogs = cogsSeries ? money2(cogsSeries[idx] || 0) : money2(revenue * cogsRatio);
    const grossProfit = money2(revenue - cogs);
    const opex = money2(opexSeries[idx]);
    // EBITDA is gross profit less cash operating costs. Depreciation of the equipment, buildout and
    // start-up assets is a non-cash charge below it (zero where no assets are capitalised, which is
    // every revision plan and the legacy profile path).
    const ebitda = money2(grossProfit - opex);
    const depreciation = money2(depreciationSeries[idx] || 0);
    const operatingIncome = money2(ebitda - depreciation);
    // Loan interest is a real expense below operating income. It is zero when no loan is modeled,
    // so a plan without debt produces exactly the figures it always did.
    const interest = money2(interestSeries[idx] || 0);
    const pretax = money2(operatingIncome - interest);
    cumulativePretax = money2(cumulativePretax + pretax);
    const cumulativeTaxOwed = cumulativePretax > 0 ? money2(cumulativePretax * INCOME_TAX_RATE) : 0;
    const estimatedIncomeTax = money2(cumulativeTaxOwed - cumulativeTaxAccrued);
    cumulativeTaxAccrued = cumulativeTaxOwed;
    return {
      month: idx + 1,
      revenue_usd: revenue,
      cogs_usd: cogs,
      gross_profit_usd: grossProfit,
      opex_usd: opex,
      ebitda_usd: ebitda,
      depreciation_usd: depreciation,
      operating_income_usd: operatingIncome,
      interest_expense_usd: interest,
      pretax_income_usd: pretax,
      estimated_income_tax_usd: estimatedIncomeTax,
      net_income_usd: money2(pretax - estimatedIncomeTax),
    };
  });
}

/** Year 1 totals, with tax computed directly from the full-year pre-tax income (like Years
 * 2-3), so the annual tax figure can never disagree in sign with the income it is taxing. */
function buildYear1Totals(year1Monthly) {
  const totals = year1Monthly.reduce(
    (acc, m) => ({
      revenue_usd: acc.revenue_usd + m.revenue_usd,
      cogs_usd: acc.cogs_usd + m.cogs_usd,
      gross_profit_usd: acc.gross_profit_usd + m.gross_profit_usd,
      opex_usd: acc.opex_usd + m.opex_usd,
      ebitda_usd: acc.ebitda_usd + (m.ebitda_usd ?? m.operating_income_usd),
      depreciation_usd: acc.depreciation_usd + (m.depreciation_usd || 0),
      operating_income_usd: acc.operating_income_usd + m.operating_income_usd,
      interest_expense_usd: acc.interest_expense_usd + (m.interest_expense_usd || 0),
    }),
    { revenue_usd: 0, cogs_usd: 0, gross_profit_usd: 0, opex_usd: 0, ebitda_usd: 0, depreciation_usd: 0, operating_income_usd: 0, interest_expense_usd: 0 },
  );
  for (const k of Object.keys(totals)) totals[k] = money2(totals[k]);
  totals.pretax_income_usd = money2(totals.operating_income_usd - totals.interest_expense_usd);
  totals.estimated_income_tax_usd =
    totals.pretax_income_usd > 0 ? money2(totals.pretax_income_usd * INCOME_TAX_RATE) : 0;
  totals.net_income_usd = money2(totals.pretax_income_usd - totals.estimated_income_tax_usd);
  return totals;
}

/** Years 2-3, extrapolated from Year 1's ending run-rate (not its average) at the annual growth
 * rate for this business: the house low-mid rate, or a published industry median where one is
 * carried in the benchmark table. Interest for each year comes from the loan schedule. */
function buildYears2And3(year1Monthly, year1Totals, cogsRatio, growthRate = ANNUAL_GROWTH_RATE, interestByYear = {}, revenueByYear = null, cogsByYear = null, depreciationByYear = {}, opexAddByYear = {}) {
  const years = [{ year: 1, ...year1Totals }];
  let priorAnnualRevenue = year1Monthly[11].revenue_usd * 12;
  let priorAnnualOpex = year1Monthly[11].opex_usd * 12;
  for (const year of [2, 3]) {
    // A software ramp that is still building supplies its own Year 2-3 revenue; otherwise the
    // year grows from the prior run rate.
    const revenue = money2(revenueByYear?.[year] ?? priorAnnualRevenue * (1 + growthRate));
    const cogs = money2(cogsByYear?.[year] ?? revenue * cogsRatio);
    const grossProfit = money2(revenue - cogs);
    const opex = money2(priorAnnualOpex * (1 + growthRate * OPEX_SCALE_WITH_REVENUE) + (opexAddByYear[year] || 0));
    const ebitda = money2(grossProfit - opex);
    const depreciation = money2(depreciationByYear[year] || 0);
    const operatingIncome = money2(ebitda - depreciation);
    const interest = money2(interestByYear[year] || 0);
    const pretax = money2(operatingIncome - interest);
    const estimatedIncomeTax = pretax > 0 ? money2(pretax * INCOME_TAX_RATE) : 0;
    years.push({
      year,
      revenue_usd: revenue,
      cogs_usd: cogs,
      gross_profit_usd: grossProfit,
      opex_usd: opex,
      ebitda_usd: ebitda,
      depreciation_usd: depreciation,
      operating_income_usd: operatingIncome,
      interest_expense_usd: interest,
      pretax_income_usd: pretax,
      estimated_income_tax_usd: estimatedIncomeTax,
      net_income_usd: money2(pretax - estimatedIncomeTax),
    });
    priorAnnualRevenue = revenue;
    priorAnnualOpex = opex;
  }
  return years;
}

/** Year 1 cash flow and trough, starting from whatever cash the model actually starts with.
 * Loan principal and interest are paid in cash each month when a loan is modeled. */
function buildYear1CashFlow(year1Monthly, startingCashUsd, principalSeries = [], capexSeries = []) {
  let cash = money2(startingCashUsd);
  let troughUsd = cash;
  let troughMonth = 0;
  const year1_cash_flow = year1Monthly.map((m, idx) => {
    const beginning = cash;
    const operatingPaidOut = money2(m.cogs_usd + m.opex_usd);
    // Tax is a cash outflow, and an SBA-style projection carries it as one. It uses the same
    // monthly figure the P&L reports, so the two statements reconcile exactly; a month where
    // cumulative income turns back negative reverses an earlier accrual and shows as a credit.
    const taxPaid = money2(m.estimated_income_tax_usd);
    const interestPaid = money2(m.interest_expense_usd || 0);
    const principalPaid = money2(principalSeries[idx] || 0);
    const debtService = money2(interestPaid + principalPaid);
    const capitalSpent = money2(capexSeries[idx] || 0);
    const totalPaidOut = money2(operatingPaidOut + taxPaid + debtService + capitalSpent);
    const ending = money2(beginning + m.revenue_usd - totalPaidOut);
    cash = ending;
    if (ending < troughUsd) {
      troughUsd = ending;
      troughMonth = m.month;
    }
    return {
      month: m.month,
      beginning_cash_usd: beginning,
      cash_receipts_usd: m.revenue_usd,
      cash_paid_out_usd: operatingPaidOut,
      estimated_income_tax_paid_usd: taxPaid,
      interest_paid_usd: interestPaid,
      loan_principal_paid_usd: principalPaid,
      debt_service_paid_usd: debtService,
      capital_spending_usd: capitalSpent,
      total_cash_paid_out_usd: totalPaidOut,
      ending_cash_usd: ending,
    };
  });
  return {
    year1_cash_flow,
    cash_flow_trough_usd: troughUsd,
    cash_flow_trough_month: troughMonth,
    additional_reserve_needed_usd: troughUsd < 0 ? money2(-troughUsd) : 0,
  };
}

/** Which kinds of outside money the founder described. It reads the answer the same way
 * plan-requirements does, so the engine and the documents agree on whether a loan is sought. */
function financingKindsFromOutsideMoney(outside) {
  const om = outside && typeof outside === 'object' ? outside : { raw: outside };
  const text = [om.raw, ...(Array.isArray(om.types) ? om.types : [])].filter(Boolean).join(' ').toLowerCase();
  return {
    debt: /\b(loans?|sba|7\(a\)|504|bank|credit|debt|line of credit|financing|microloan|cdfi)\b/.test(text),
    equity: /\b(equity|investors?|angels?|venture|vc|seed|pre-seed|series [a-d]|crowdfund\w*|shares|stake|safe)\b/.test(text),
    grant: /\bgrants?\b/.test(text),
  };
}

/**
 * Loan terms the founder stated in their own words, such as "10 years at 11.5%". It needs both a
 * rate and a term; half a set of terms is not terms.
 */
function parseFounderLoanTerms(text) {
  const t = String(text || '').toLowerCase();
  const rate = t.match(/(\d{1,2}(?:\.\d+)?)\s*%/);
  const term = t.match(/(\d{1,2})\s*-?\s*(?:years?|yrs?)\b/);
  if (!rate || !term) return null;
  const annualRate = Number(rate[1]) / 100;
  const termYears = Number(term[1]);
  if (!(annualRate > 0 && annualRate < 0.4 && termYears > 0 && termYears <= 30)) return null;
  return { annual_rate: annualRate, term_years: termYears };
}

/**
 * The terms a loan is modeled on. The founder's terms are used if stated. Otherwise the model
 * uses the SBA 7(a) maximum variable rate for the loan size (prime plus the allowed spread) and
 * the 7(a) maximum term for working capital and equipment. The maximum rate is the conservative
 * choice: a lender may quote lower, and a plan that works at the ceiling also works at the quote.
 */
function resolveLoanTerms(principalUsd, founderTermsText) {
  const founder = parseFounderLoanTerms(founderTermsText);
  if (founder) {
    return { ...founder, basis: 'founder', label: 'Founder-stated terms', sources: [] };
  }
  const tier = SBA_7A.spreads.find((t) => principalUsd <= t.max_amount_usd) || SBA_7A.spreads[SBA_7A.spreads.length - 1];
  const prime = SBA_7A.prime_rate.value;
  return {
    annual_rate: Math.round((prime + tier.spread) * 10000) / 10000,
    term_years: MODEL_ASSUMPTIONS.default_loan_term_years.value,
    basis: 'assumed_sba_7a_max',
    label: 'Assumed terms (SBA 7(a) maximum rate)',
    prime_rate: prime,
    spread: tier.spread,
    rate_as_of: SBA_7A.prime_rate.as_of,
    sources: ['sba_7a_terms', 'fred_dprime'],
  };
}

/**
 * Month-by-month amortization of a level-payment loan. The last payment absorbs rounding, so the
 * principal repaid always sums to the amount borrowed and the balance ends at exactly zero.
 */
function buildAmortizationSchedule(principalUsd, annualRate, termYears) {
  const principal = money2(principalUsd);
  const n = Math.round(Number(termYears) * 12);
  const payment = monthlyLoanPayment(principal, annualRate, termYears);
  const r = Number(annualRate) / 12;
  const schedule = [];
  let balance = principal;
  for (let k = 1; k <= n && balance > 0; k++) {
    const interest = money2(balance * r);
    const principalPaid = k === n ? balance : Math.min(balance, money2(payment - interest));
    balance = money2(balance - principalPaid);
    schedule.push({
      month: k,
      payment_usd: money2(interest + principalPaid),
      interest_usd: interest,
      principal_usd: money2(principalPaid),
      ending_balance_usd: balance,
    });
  }
  const total = (key, from, to) => money2(schedule.slice(from, to).reduce((a, row) => a + row[key], 0));
  return {
    principal_usd: principal,
    annual_rate: annualRate,
    term_years: termYears,
    monthly_payment_usd: payment,
    total_interest_usd: total('interest_usd', 0, schedule.length),
    schedule,
    annual: [1, 2, 3].map((y) => ({
      year: y,
      interest_usd: total('interest_usd', (y - 1) * 12, y * 12),
      principal_usd: total('principal_usd', (y - 1) * 12, y * 12),
      debt_service_usd: total('payment_usd', (y - 1) * 12, y * 12),
      ending_balance_usd: schedule[Math.min(schedule.length, y * 12) - 1]?.ending_balance_usd ?? 0,
    })),
  };
}

/**
 * Years 2-3 revenue for a software ramp. The ramp keeps building in a straight line from its
 * month-12 level to the full cost-covering run rate at month 36, rather than growing at a flat
 * percentage from a base that is still a fraction of where it is heading.
 */
function softwareLaterYearRevenue(ramp, ssr) {
  const f12 = ramp[11];
  const frac = (m) => f12 + (1 - f12) * ((m - 12) / 24);
  const sum = (from, to) => {
    let t = 0;
    for (let m = from; m <= to; m++) t += frac(m);
    return t;
  };
  return { 2: money2(ssr * sum(13, 24)), 3: money2(ssr * sum(25, 36)) };
}

/**
 * Years 2 and 3 for the cost-derived stage ramp. The ramp keeps building past month 12 when the
 * opening came late (it reaches the full run rate twelve months after its first month), and the
 * full run rate then grows at the planning rate each year. With an opening early enough to finish
 * the ramp inside Year 1 this is Year 1's closing run rate grown a year, as before.
 */
function stageLaterYearRevenue(stage, firstRevenueMonth, ssr, growthRate) {
  const base = STAGE_RAMP[stage] || STAGE_RAMP.idea;
  const firstNonZero = base.findIndex((f) => f > 0) + 1;
  const shift = Math.max(0, (firstRevenueMonth || 1) - firstNonZero);
  const frac = (m) => {
    const i = m - 1 - shift;
    return i < 0 ? 0 : i < 12 ? base[i] : 1;
  };
  const year = (y) => {
    let t = 0;
    for (let m = (y - 1) * 12 + 1; m <= y * 12; m++) t += frac(m);
    return money2(ssr * t * (1 + growthRate) ** (y - 1));
  };
  return { 2: year(2), 3: year(3) };
}

/** Revenue for each month as a fraction of the steady-state run rate. */
function revenueRamp(stage, firstRevenueMonth, rampKind) {
  const base = STAGE_RAMP[stage] || STAGE_RAMP.idea;
  const firstNonZero = base.findIndex((f) => f > 0) + 1;
  // The founder's answer can only make the ramp later than the stage default, never earlier. If
  // they expect revenue sooner, the conservative reading keeps the default.
  const shift = Math.max(0, (firstRevenueMonth || 1) - firstNonZero);
  let ramp = base.map((_, i) => (i - shift >= 0 ? base[i - shift] : 0));
  if (rampKind === 'software' && ramp[11] > 0) {
    const target = MODEL_ASSUMPTIONS.software_month12_fraction_of_steady_state.value;
    const scale = target / ramp[11];
    ramp = ramp.map((f) => Math.round(f * scale * 10000) / 10000);
  }
  return ramp;
}

/**
 * One run of the launch model for a given opening cash and loan: the P&L, the cash flow, and the
 * 36-month cash path. The base case and the sensitivity rows both come through here, so they
 * cannot drift apart.
 */
function runLaunchProjection({ revenueSeries, opexSeries, cogsRatio, growthRate, openingCash, loan, revenueByYear = null, cogsSeries = null, cogsByYear = null, depreciation = null, opexAddByYear = {}, capexByMonth = [] }) {
  const capex = (m) => capexByMonth[m - 1] || 0;
  const sched = loan ? loan.schedule : [];
  const interest = (m) => sched[m - 1]?.interest_usd || 0;
  const principal = (m) => sched[m - 1]?.principal_usd || 0;
  const dep = (m) => depreciation?.monthly?.[m - 1] || 0;
  const months12 = Array.from({ length: 12 }, (_, i) => i + 1);
  const year1Monthly = buildYear1Monthly(revenueSeries, opexSeries, cogsRatio, months12.map(interest), cogsSeries, months12.map(dep));
  const year1Totals = buildYear1Totals(year1Monthly);
  const interestByYear = loan ? { 2: loan.annual[1].interest_usd, 3: loan.annual[2].interest_usd } : {};
  const depreciationByYear = depreciation ? { 2: depreciation.by_year[2], 3: depreciation.by_year[3] } : {};
  const years = buildYears2And3(year1Monthly, year1Totals, cogsRatio, growthRate, interestByYear, revenueByYear, cogsByYear, depreciationByYear, opexAddByYear);
  const cashFlow = buildYear1CashFlow(year1Monthly, openingCash, months12.map(principal), months12.map(capex));

  // Months 13-36 each take their year's average month. Years 2-3 are annual in the statements.
  // Spreading them evenly lets the runway and the funding need look past Year 1 without inventing
  // a monthly shape the model does not have.
  const net36 = cashFlow.year1_cash_flow.map((m) => money2(m.ending_cash_usd - m.beginning_cash_usd));
  for (const y of [2, 3]) {
    const yr = years[y - 1];
    for (let k = 1; k <= 12; k++) {
      const m = (y - 1) * 12 + k;
      // Depreciation is non-cash: it lowers net income (and the tax on it) but not the cash spent.
      net36.push(money2((yr.net_income_usd + (yr.depreciation_usd || 0)) / 12 - principal(m) - capex(m)));
    }
  }
  // Break-even is read from operating cash: second-phase equipment is an investment, not a loss.
  const net36Operating = net36.map((n, i) => money2(n + capex(i + 1)));
  let cash = money2(openingCash);
  let min = cash;
  let minMonth = 0;
  const path36 = net36.map((n, i) => {
    cash = money2(cash + n);
    if (cash < min) {
      min = cash;
      minMonth = i + 1;
    }
    return cash;
  });
  return { year1Monthly, year1Totals, years, cashFlow, net36, net36Operating, path36, min36: min, min36Month: minMonth };
}

/** The opening month from the schedule, or the first revenue month. */
function openingMonthOf(schedule, firstRevenueMonth) {
  return schedule?.opening_month || firstRevenueMonth;
}

/**
 * Two depreciation schedules as one (the opening assets and a phased launch's second-phase
 * assets). The categories stay the opening ones, for the start-up cost table; the second phase's
 * are kept apart.
 */
function mergeDepreciation(a, b) {
  const monthly = a.monthly.map((v, i) => money2(v + (b.monthly[i] || 0)));
  const sum = (x, y) => money2(monthly.slice(x, y).reduce((t, v) => t + v, 0));
  const byYear = { 1: sum(0, 12), 2: sum(12, 24), 3: sum(24, 36) };
  return {
    ...a,
    monthly,
    by_year: byYear,
    later_categories: b.categories,
    later_start_month: b.start_month,
    depreciable_cost_usd: money2(a.depreciable_cost_usd + b.depreciable_cost_usd),
    non_depreciable_cost_usd: money2(a.non_depreciable_cost_usd + b.non_depreciable_cost_usd),
    accumulated_by_year_end: { 1: byYear[1], 2: money2(byYear[1] + byYear[2]), 3: money2(byYear[1] + byYear[2] + byYear[3]) },
  };
}

/** The first month from which net cash flow stays at or above zero through month 36, or null. */
function cashFlowPositiveFrom(net36) {
  let from = null;
  for (let i = net36.length - 1; i >= 0; i--) {
    if (net36[i] >= 0) from = i + 1;
    else break;
  }
  return from;
}

/**
 * Splits the operating money a plan spends before it turns cash-positive into the categories a
 * use-of-proceeds table uses. Each category gets its share of gross spending over the funded
 * months. Revenue collected in those months offsets every category in proportion, so the
 * categories add up to the net amount funded.
 */
function allocateOperatingUses(amountUsd, months, spendByMonth) {
  const totals = {};
  for (let m = 1; m <= months; m++) {
    for (const [k, v] of Object.entries(spendByMonth(m))) totals[k] = (totals[k] || 0) + v;
  }
  const gross = Object.values(totals).reduce((a, v) => a + v, 0);
  const keys = Object.keys(totals).filter((k) => totals[k] > 0);
  const out = {};
  let allocated = 0;
  keys.forEach((k, i) => {
    const v = i === keys.length - 1 ? money2(amountUsd - allocated) : money2(gross > 0 ? (amountUsd * totals[k]) / gross : 0);
    out[k] = v;
    allocated = money2(allocated + v);
  });
  return out;
}

/** One-word names for the use-of-proceeds chart, where the full labels would overlap. */
const USE_OF_PROCEEDS_SHORT = Object.freeze({
  equipment: 'Equipment',
  hiring: 'Hiring',
  product: 'Product',
  marketing: 'Marketing',
  operations: 'Operations',
  debt_service: 'Loan payments',
  working_capital: 'Working capital',
  contingency: 'Contingency',
});

const USE_OF_PROCEEDS_LABELS = Object.freeze({
  equipment: 'Equipment, buildout and setup',
  hiring: 'Hiring plan: payroll and payroll taxes',
  product: 'Product and development',
  marketing: 'Marketing',
  operations: 'Rent, inventory and other operating costs',
  debt_service: 'Loan payments during the ramp',
  working_capital: 'Working capital',
  contingency: 'Contingency reserve',
});

/**
 * The launch model. Costs come from the cost model and revenue from the ramp, and the capital
 * structure funds both.
 *
 * Capital is sized one of two ways:
 *   - The founder stated an amount to raise or borrow. That amount is used, because the founder's
 *     number wins. The model reports how long it lasts (runway), what it pays for (use of
 *     proceeds), and whether it falls short.
 *   - No amount was stated. The need is setup, plus opening working capital, plus every dollar
 *     the business burns before it turns cash-positive (including loan payments when a loan is
 *     sought), plus a contingency. A loan is sized to that need less owner capital. The loan's
 *     own payments are part of the burn, so its size is iterated until it settles.
 */
/**
 * The founder's own equipment and build-out list (plan_detail.financials.cost_overrides.setup_items,
 * from the Guided Interview): [{ label, amount_usd, quoted }]. Null when absent or unusable, in which
 * case the benchmark setup figure stands. Only positive amounts count.
 */
function founderSetupItems(overrides) {
  const raw = overrides && Array.isArray(overrides.setup_items) ? overrides.setup_items : null;
  if (!raw) return null;
  const items = raw
    .map((i) => ({ label: String((i && i.label) || '').trim().slice(0, 120), amount_usd: Number(i && i.amount_usd), quoted: Boolean(i && i.quoted) }))
    .filter((i) => i.label && Number.isFinite(i.amount_usd) && i.amount_usd > 0);
  return items.length ? items : null;
}

/**
 * The founder's setup lines as a category split, each placed in the asset class its label names
 * (build-out, furniture, technology, else equipment) so it depreciates over the matching life.
 */
function founderSetupSplit(items) {
  const total = items.reduce((a, i) => a + i.amount_usd, 0);
  const classOf = (label) =>
    /build.?out|renovat|construct|leasehold|plumb|electric|hvac|flooring|remodel/i.test(label)
      ? 'buildout'
      : /furnit|seating|table|chair|decor/i.test(label)
        ? 'furniture'
        : /computer|laptop|software|point.of.sale|\bpos\b|tablet|website|technology/i.test(label)
          ? 'technology'
          : /permit|licen[sc]e|legal|deposit|opening inventory|inventory|grand opening/i.test(label)
            ? 'startup'
            : 'equipment';
  return items.map((i) => ({
    label: i.quoted ? `${i.label} (quoted)` : i.label,
    asset_class: classOf(i.label),
    share: total > 0 ? i.amount_usd / total : 0,
    basis: i.quoted ? 'quoted' : 'founder',
    source: i.quoted ? 'Vendor quote (founder)' : 'Founder estimate',
  }));
}

/**
 * The start-up cost check: founder quotes first, then the industry pack's must-have equipment at the
 * midpoint of its priced range, then the benchmark. Reports the figure used for equipment, the pack
 * range and the difference from the figure it replaced (or, with founder quotes, from the range).
 */
function setupCostCheck(lm) {
  const range = lm.packRange || null;
  const equipment = (lm.setupCategories || []).filter((c) => c.asset_class === 'equipment').reduce((a, c) => a + c.amount_usd, 0);
  if (!range) return { basis: lm.founderSetup ? 'founder' : 'benchmark', pack: null, equipment_usd: money2(equipment) };
  // A stated amount smaller than the start-up budget scales every setup line down in the statements.
  const funded = (lm.setupCategories || []).reduce((a, c) => a + c.amount_usd, 0);
  const cappedByFunding = lm.setup > 0 && funded < lm.setup - 1;
  const out = {
    capped_by_funding: cappedByFunding,
    pack: { id: range.id, title: range.title, version: range.version, naics: range.naics, low_usd: range.low_usd, high_usd: range.high_usd, mid_usd: range.mid_usd, items: range.items, retrieved: range.retrieved },
    equipment_usd: money2(equipment),
  };
  if (lm.founderSetup) {
    out.basis = 'founder';
    out.within_range = equipment >= range.low_usd && equipment <= range.high_usd;
    out.difference_usd = money2(equipment < range.low_usd ? equipment - range.low_usd : equipment > range.high_usd ? equipment - range.high_usd : 0);
  } else if (lm.packSetup) {
    out.basis = 'industry_pack';
    out.benchmark_equipment_usd = lm.packSetup.benchmark_equipment_usd;
    out.difference_usd = money2(range.mid_usd - lm.packSetup.benchmark_equipment_usd);
    out.within_range = true;
  } else {
    out.basis = 'benchmark';
    out.within_range = equipment >= range.low_usd && equipment <= range.high_usd;
  }
  return out;
}

/** A runway in months from a number or text such as "18 months" or "18-24 months" (the short end). */
function parseRunwayMonths(v) {
  if (v == null || v === '') return null;
  if (typeof v === 'number') return v > 0 ? v : null;
  const m = String(v).match(/(\d{1,2})\s*(?:(?:-|to|–)\s*\d{1,2}\s*)?months?/i);
  return m ? Number(m[1]) : null;
}

function buildLaunchModel(input) {
  const { costModel, stage, capital, kinds, outsideIntent, statedAmount, founderTermsText, revenueBuildup = null, runwayMonths = null, existingAnnualDebtServiceUsd = 0, adjust = null, termYearsOverride = null, phasing = null } = input;
  const profile = costModel.industry.profile;
  const base = PROFILE_BASE[profile];
  const stageFactor = stage === 'existing' || stage === 'launched' ? 0.55 : stage === 'pre_launch' ? 0.85 : 1;
  // Equipment and build-out lines the founder listed (with quotes where they have them) replace
  // the start-up budget outright. Otherwise the one-time budget is the cost model's cited benchmark
  // (or labeled allowance) for this industry and place; the profile figure only when no cost model
  // is present.
  const founderSetup = founderSetupItems(costModel.cost_overrides);
  const setupPlan = !founderSetup && costModel.startup ? { ...costModel.startup, total_usd: Math.round(costModel.startup.total_usd * stageFactor), stage_factor: stageFactor } : null;
  let setup = founderSetup
    ? Math.round(founderSetup.reduce((a, i) => a + i.amount_usd, 0))
    : setupPlan ? setupPlan.total_usd : Math.round(base.fixed_setup * stageFactor);
  // Founder quotes first (above); then the industry pack's must-have equipment at the midpoint of
  // its priced range for the equipment line; then the benchmark split for everything else.
  const packRange = costModel.startup && costModel.startup.industry_pack ? costModel.startup.industry_pack : null;
  const packSetup = !founderSetup && setupPlan && packRange ? icPackFedSetup(setupPlan.total_usd, setupPlan.categories_split || PROFILE_FIXED_SETUP_SPLIT[profile], packRange) : null;
  if (packSetup) setup = packSetup.total;
  const buffer = Math.round(base.variable_buffer * stageFactor);
  const growthRate = ANNUAL_GROWTH_RATE;
  const stageRamp = revenueRamp(STAGE_RAMP[stage] ? stage : 'idea', costModel.first_revenue_month, costModel.ramp);
  const ssr = costModel.stabilized_monthly_revenue_usd;
  // Revenue: the founder's price-times-volume build-up when there is one, starting in the same
  // month the cost-derived ramp would; otherwise the cost-derived ramp toward the sizing target.
  const firstRevenueMonth = Math.max(1, stageRamp.findIndex((f) => f > 0) + 1);
  // Each product starts when the business opens, or later when it needs a license of its own
  // (wine and beer wait for the alcohol license); the founder's ramp moves with the start.
  const schedule = costModel.schedule || null;
  const revenueModel = revenueBuildup
    ? buildRevenueModel(revenueBuildup, {
        firstMonth: firstRevenueMonth,
        plannedFirstMonth: schedule ? Math.min(schedule.intended_month, firstRevenueMonth) : firstRevenueMonth,
        // A split line's unlicensed share starts at opening (a what-if in Founder's Notes).
        tierStartMonth: (t) => (t.start_at_opening ? (schedule ? schedule.opening_month : firstRevenueMonth) : productStartMonth(schedule, t.name)),
      })
    : null;
  let cogsRatio = costModel.cogs_ratio;
  let ramp = stageRamp;
  let revenueSeries;
  let revenueByYear;
  let cogsSeries = null;
  let cogsByYear = null;
  if (revenueModel) {
    revenueSeries = revenueModel.revenue_by_month.slice(0, 12);
    cogsSeries = revenueModel.cogs_by_month.slice(0, 12);
    revenueByYear = { 2: revenueModel.annual[1].revenue_usd, 3: revenueModel.annual[2].revenue_usd };
    cogsByYear = { 2: revenueModel.annual[1].cogs_usd, 3: revenueModel.annual[2].cogs_usd };
    // The blended ratio at maturity (Year 2 mix), for break-even and the prose. The statements use
    // each month's own cost of goods.
    const basisYear = revenueModel.annual.find((y) => y.year === 2 && y.revenue_usd > 0) || revenueModel.annual.find((y) => y.revenue_usd > 0);
    cogsRatio = basisYear ? Math.round((basisYear.cogs_usd / basisYear.revenue_usd) * 10000) / 10000 : cogsRatio;
    const peak = revenueModel.monthly_revenue_month36_usd || Math.max(...revenueModel.revenue_by_month);
    ramp = revenueSeries.map((r) => (peak > 0 ? Math.round((r / peak) * 10000) / 10000 : 0));
  } else {
    revenueSeries = stageRamp.map((f) => ssr * f);
    revenueByYear = costModel.ramp === 'software' ? softwareLaterYearRevenue(stageRamp, ssr) : stageLaterYearRevenue(STAGE_RAMP[stage] ? stage : 'idea', costModel.first_revenue_month, ssr, growthRate);
  }
  let opexSeries = costModel.opex_by_month;
  // A what-if on the same model (the levers in Founder's Notes): prices or volumes scaled, or a
  // monthly cost removed. Never set for the plan itself.
  if (adjust) {
    const pf = adjust.price_factor ?? 1;
    const vf = adjust.volume_factor ?? 1;
    if (pf !== 1 || vf !== 1) {
      const y2 = revenueByYear?.[2] ?? revenueSeries[11] * 12 * (1 + growthRate);
      const y3 = revenueByYear?.[3] ?? y2 * (1 + growthRate);
      const baseCogs = cogsSeries || revenueSeries.map((r) => r * cogsRatio);
      const baseCogsByYear = cogsByYear || { 2: y2 * cogsRatio, 3: y3 * cogsRatio };
      // A price rise lifts revenue with the unit costs unchanged; a volume rise moves both.
      revenueSeries = revenueSeries.map((r) => r * pf * vf);
      revenueByYear = { 2: y2 * pf * vf, 3: y3 * pf * vf };
      cogsSeries = baseCogs.map((c) => c * vf);
      cogsByYear = { 2: baseCogsByYear[2] * vf, 3: baseCogsByYear[3] * vf };
    }
    if (Array.isArray(adjust.opex_reduction_by_month)) {
      opexSeries = opexSeries.map((v, i) => money2(Math.max(0, v - (adjust.opex_reduction_by_month[i] || 0))));
    }
  }
  const owner = capital.available_usd;
  const ownerForModel = owner ?? 0;
  const contingencyShare = MODEL_ASSUMPTIONS.contingency_share.value;

  const stated = outsideIntent === 'yes' && statedAmount > 0 ? statedAmount : null;
  const outsideType = kinds.equity && !kinds.debt ? 'equity' : kinds.debt && !kinds.equity ? 'debt' : kinds.equity ? 'equity' : 'unspecified';
  // A loan is modeled only when one is being sought.
  const loanSought = outsideIntent === 'yes' && outsideType === 'debt';
  const equityRaise = outsideIntent === 'yes' && outsideType === 'equity';

  // The funding horizon. A professional plan does not borrow to fund years of losses: the need
  // reaches monthly cash break-even, capped at a set number of months after opening. An equity
  // raise is sized to its runway instead (the founder's, or the convention), counted from the raise.
  const openingMonth = schedule?.opening_month || firstRevenueMonth;
  const afterOpening = MODEL_ASSUMPTIONS.runway_horizon_months_after_opening.value;
  const runwayStated = Number(runwayMonths) > 0 ? Math.round(Number(runwayMonths)) : null;
  const horizon = equityRaise
    ? {
        basis: 'equity_runway',
        months: Math.min(36, Math.max(6, runwayStated ?? MODEL_ASSUMPTIONS.equity_runway_months_default.value)),
        source: runwayStated ? 'founder' : 'convention',
        opening_month: openingMonth,
        months_after_opening: null,
      }
    : {
        basis: 'break_even',
        months: Math.min(36, openingMonth - 1 + afterOpening),
        source: 'convention',
        opening_month: openingMonth,
        months_after_opening: afterOpening,
      };
  const deficitWithin = (path, months) => money2(Math.max(0, -Math.min(0, ...path.slice(0, months))));

  const setupSplit = founderSetup ? founderSetupSplit(founderSetup) : packSetup ? packSetup.split : setupPlan?.categories_split || PROFILE_FIXED_SETUP_SPLIT[profile];

  // A phased launch (plan_detail.phasing): the business opens with its core lines, and the part of
  // the equipment, build-out and staff that serves the license-dependent lines comes when the
  // license does. That part is the deferred lines' share of month-36 sales, a proportional
  // allocation the plan states as such. The second-phase equipment is bought from the business's
  // cash in the license month; the deferred staff start then.
  const setupFull = setup;
  let phase2 = null;
  let opexAddByYear = {};
  const capexByMonth = Array.from({ length: 36 }, () => 0);
  const phaseShare = Number(phasing?.deferred_share);
  const phaseMonth = Math.round(Number(phasing?.phase2_month));
  if (phaseShare > 0 && phaseShare < 1 && phaseMonth > openingMonthOf(schedule, firstRevenueMonth) && phaseMonth <= 36) {
    const founderAt = (m) => costModel.staffing.filter((r) => r.is_founder && m >= r.start_month).reduce((a, r) => a + r.monthly_employer_cost_usd * r.count, 0);
    const staffAt = (m) => Math.max(0, (costModel.payroll_by_month[Math.min(m, 12) - 1] || 0) - founderAt(Math.min(m, 12)));
    const deferredAt = (m) => (m < phaseMonth ? money2(staffAt(m) * phaseShare) : 0);
    opexSeries = opexSeries.map((v, i) => money2(Math.max(0, v - deferredAt(i + 1))));
    const d = staffAt(12) * phaseShare;
    const k = 1 + growthRate * OPEX_SCALE_WITH_REVENUE;
    if (phaseMonth >= 13 && phaseMonth <= 24) {
      const y2 = d * (25 - phaseMonth) * k;
      opexAddByYear = { 2: money2(y2), 3: money2(d * 12 * k * k - y2 * k) };
    } else if (phaseMonth >= 25) {
      opexAddByYear = { 3: money2(d * (37 - phaseMonth) * k * k) };
    }
    const later = money2(setupFull * phaseShare);
    setup = money2(setupFull - later);
    capexByMonth[phaseMonth - 1] = later;
    phase2 = {
      month: phaseMonth,
      share: phaseShare,
      deferred_lines: Array.isArray(phasing.deferred_lines) ? phasing.deferred_lines.slice(0, 10) : [],
      capex_usd: later,
      staff_deferred_monthly_usd: money2(d),
      opening_setup_usd: setup,
      full_setup_usd: setupFull,
      categories: splitSetupCategories(later, setupSplit),
    };
  }
  const laterDepreciation = phase2 ? buildDepreciationSchedule(phase2.categories, phase2.month) : null;
  const withLater = (dep) => (laterDepreciation ? mergeDepreciation(dep, laterDepreciation) : dep);
  const setupDepreciation = withLater(buildDepreciationSchedule(splitSetupCategories(setup, setupSplit), firstRevenueMonth));
  const run = (openingCash, loan, depreciation = setupDepreciation) =>
    runLaunchProjection({ revenueSeries, opexSeries, cogsRatio, growthRate, openingCash, loan, revenueByYear, cogsSeries, cogsByYear, depreciation, opexAddByYear, capexByMonth });
  const makeLoan = (p) => {
    if (!(p > 0)) return null;
    const resolved = resolveLoanTerms(p, founderTermsText);
    // A longer term tried as a lever (Founder's Notes); never set for the plan itself.
    const terms = termYearsOverride > 0 ? { ...resolved, term_years: termYearsOverride } : resolved;
    return { ...buildAmortizationSchedule(p, terms.annual_rate, terms.term_years), terms };
  };

  // Size the need from the burn. If the owner's capital is unknown, the loan size is unknowable,
  // and a payment on an unknowable principal would be an invented number, so no loan is sized.
  let loan = null;
  let deficit = 0;
  let need = 0;
  for (let i = 0; i < 25; i++) {
    const r = run(0, loan);
    // Pre-opening costs and operating losses (with the loan's own payments) until the business is
    // cash-positive, but never past the horizon: the trough of the cash path within it.
    deficit = deficitWithin(r.path36, horizon.months);
    need = money2((setup + buffer + deficit) * (1 + contingencyShare));
    const wanted = loanSought && owner != null && stated == null ? money2(Math.max(0, need - ownerForModel)) : 0;
    const current = loan ? loan.principal_usd : 0;
    if (Math.abs(wanted - current) < 1) break;
    loan = makeLoan(wanted);
  }
  const modelNeed = need;

  // Sources.
  let outside;
  if (stated != null) outside = stated;
  else if (owner == null) outside = modelNeed;
  else outside = money2(Math.max(0, modelNeed - owner));
  const ownerSource = owner == null ? 0 : stated != null ? owner : Math.min(owner, modelNeed);
  const totalSources = money2(ownerSource + outside);
  if (stated != null) loan = loanSought ? makeLoan(stated) : null;
  else if (!loanSought || owner == null || !(outside > 0)) loan = null;
  // The loan is exactly the financing requested: the sizing loop settles within a dollar, and the
  // documents print the request and the loan side by side.
  else if (loan && Math.abs(loan.principal_usd - outside) >= 0.005) loan = makeLoan(outside);

  const openingCash = money2(totalSources - Math.min(setup, totalSources));
  // The assets actually bought: the full setup unless the sources fall short of it.
  const setupCategories = splitSetupCategories(money2(Math.min(setup, totalSources)), setupSplit);
  const depreciation = withLater(buildDepreciationSchedule(setupCategories, firstRevenueMonth));
  const final = run(openingCash, loan, depreciation);

  // Uses: what the sources pay for, adding to the same total. A plan that is not cash-positive by
  // its horizon spends the capital by then, so the uses (and the contingency still in hand) are
  // read within the horizon; later losses are the shortfall the plan reports, not a use.
  const positiveAt = cashFlowPositiveFrom(final.net36Operating || final.net36);
  const usesWindow = horizon.basis === 'break_even' && stated == null && !(positiveAt != null && positiveAt <= horizon.months) ? horizon.months : 36;
  const windowPath = final.path36.slice(0, usesWindow);
  const windowMin = windowPath.length ? Math.min(money2(openingCash), ...windowPath) : final.min36;
  const windowMinMonth = windowMin === money2(openingCash) && !windowPath.some((c) => c < openingCash) ? 0 : windowPath.indexOf(windowMin) + 1;
  const floor = money2(Math.max(0, usesWindow === 36 ? final.min36 : windowMin));
  const operating = money2(Math.max(0, openingCash) - floor);
  const contingencyTarget = money2(stated != null ? totalSources * contingencyShare : modelNeed - money2(modelNeed / (1 + contingencyShare)));
  const contingency = money2(Math.min(contingencyTarget, floor));
  const workingCapital = money2(floor - contingency);
  const equipment = money2(Math.min(setup, totalSources));

  const monthly12 = final.year1Monthly;
  const payrollShare = (m) => {
    const opex = opexSeries[Math.min(m, 12) - 1];
    return opex > 0 ? costModel.payroll_by_month[Math.min(m, 12) - 1] / opex : 0;
  };
  const engineeringPayrollShare = (() => {
    const eng = costModel.staffing.filter((r) => /^15-/.test(r.soc)).reduce((a, r) => a + r.monthly_employer_cost_usd, 0);
    return costModel.payroll.steady_state_monthly_usd > 0 ? eng / costModel.payroll.steady_state_monthly_usd : 0;
  })();
  const marketingLines = costModel.lines.filter((l) => /advertising|marketing/.test(l.key)).reduce((a, l) => a + l.monthly_usd, 0);
  const lineScale = costModel.steady_state_monthly_opex_usd - costModel.payroll.steady_state_monthly_usd;
  const software = costModel.industry.id === 'software_saas';
  const spendByMonth = (m) => {
    const y = Math.ceil(m / 12);
    const opex = m <= 12 ? monthly12[m - 1].opex_usd : final.years[y - 1].opex_usd / 12;
    const cogs = m <= 12 ? monthly12[m - 1].cogs_usd : final.years[y - 1].cogs_usd / 12;
    const tax = m <= 12 ? Math.max(0, monthly12[m - 1].estimated_income_tax_usd) : final.years[y - 1].estimated_income_tax_usd / 12;
    const payroll = opex * payrollShare(m);
    const lines = opex - payroll;
    const mkt = lineScale > 0 ? lines * (marketingLines / lineScale) : 0;
    const debt = loan?.schedule[m - 1]?.payment_usd || 0;
    return {
      hiring: payroll * (1 - engineeringPayrollShare),
      product: payroll * engineeringPayrollShare + (software ? cogs : 0),
      marketing: mkt,
      operations: lines - mkt + (software ? 0 : cogs) + tax,
      debt_service: debt,
    };
  };
  const fundedMonths = usesWindow === 36 ? final.min36Month : windowMinMonth;
  const opAlloc = operating > 0 && fundedMonths > 0 ? allocateOperatingUses(operating, fundedMonths, spendByMonth) : {};
  const uses = [
    { id: 'equipment', amount_usd: equipment },
    ...['hiring', 'product', 'marketing', 'operations', 'debt_service'].map((id) => ({ id, amount_usd: money2(opAlloc[id] || 0) })),
    { id: 'working_capital', amount_usd: workingCapital },
    { id: 'contingency', amount_usd: contingency },
  ]
    .filter((u) => u.amount_usd > 0 || u.id === 'equipment')
    .map((u) => ({ ...u, label: USE_OF_PROCEEDS_LABELS[u.id], short_label: USE_OF_PROCEEDS_SHORT[u.id] }));
  // Rounding lands in working capital so the table foots to the cent.
  const drift = money2(totalSources - uses.reduce((a, u) => a + u.amount_usd, 0));
  if (drift !== 0) {
    let wc = uses.find((u) => u.id === 'working_capital');
    if (!wc) {
      wc = { id: 'working_capital', amount_usd: 0, label: USE_OF_PROCEEDS_LABELS.working_capital, short_label: USE_OF_PROCEEDS_SHORT.working_capital };
      uses.push(wc);
    }
    wc.amount_usd = money2(wc.amount_usd + drift);
  }

  // Runway: months until cash would fall into the contingency the plan means to keep (the full
  // target, not whatever happened to be left), and months until cash runs out altogether.
  const positiveFrom = cashFlowPositiveFrom(final.net36Operating || final.net36);
  const holdBack = Math.max(contingency, contingencyTarget);
  const monthsAbove = (threshold) => {
    const idx = final.path36.findIndex((c) => c < threshold - 0.005);
    if (idx !== -1) return { months: idx, within_horizon: true };
    const last = final.net36[35];
    const remaining = final.path36[35] - threshold;
    return { months: last < 0 ? 36 + Math.floor(remaining / -last) : null, within_horizon: false };
  };
  const y1Net = final.net36.slice(0, 12).reduce((a, n) => a + n, 0);
  const avgBurn = y1Net < 0 ? money2(-y1Net / 12) : 0;
  const keep = monthsAbove(holdBack);
  const all = monthsAbove(0);
  let runway;
  if (keep.within_horizon) {
    runway = { basis: 'cash_out', months: keep.months, months_including_contingency: all.months };
  } else if (positiveFrom != null && final.net36[35] >= 0) {
    runway = { basis: 'self_sustaining', months: null, months_including_contingency: null, cash_flow_positive_month: positiveFrom };
  } else {
    runway = { basis: 'beyond_horizon', months: keep.months, months_including_contingency: all.months };
  }
  // How much more would carry the plan to cash-positive (or month 36) with the contingency intact.
  const shortfall = stated != null ? money2(Math.max(0, contingencyTarget - final.min36)) : 0;

  // Whether the plan works as structured: cash break-even inside the horizon and, with a loan,
  // Year 2 coverage at the lender's line. When it does not, the need stays at the horizon and the
  // further losses are reported as a shortfall, not borrowed.
  const bareFull = run(0, loan, depreciation);
  // Operating losses only: a phased launch's second-phase purchase is not a loss. Whether the
  // business's cash can pay for it is reported on its own (phase2_cash_shortfall_usd).
  let acc = 0;
  const operatingPath = (bareFull.net36Operating || bareFull.net36).map((n) => (acc = money2(acc + n)));
  const lossesFull = money2(Math.max(0, -Math.min(0, ...operatingPath)));
  const lossesWithin = deficitWithin(operatingPath, horizon.months);
  const y2 = final.years[1];
  const y2Ebitda = y2 ? y2.ebitda_usd ?? y2.operating_income_usd : null;
  const annualDebtService = loan ? money2(loan.monthly_payment_usd * 12 + (existingAnnualDebtServiceUsd || 0)) : 0;
  const dscrYear2 = loan && annualDebtService > 0 ? (y2Ebitda > 0 ? Math.round((y2Ebitda / annualDebtService) * 100) / 100 : 0) : null;
  const breakEvenWithin = positiveFrom != null && positiveFrom <= horizon.months;
  const coverageOk = dscrYear2 == null || dscrYear2 >= DSCR_REFERENCE_MINIMUM;
  const reasons = [];
  if (!equityRaise && !breakEvenWithin) reasons.push('break_even_beyond_horizon');
  if (!equityRaise && !coverageOk) reasons.push('coverage_below_minimum_year2');
  if (equityRaise && final.path36.slice(0, horizon.months).some((c) => c < 0)) reasons.push('runway_short_of_stated');
  // A phased launch buys its second phase from the business's cash; if cash cannot carry it, the
  // phasing does not work as planned.
  // The purchase must leave the contingency reserve in hand, as the opening does.
  const phase2Shortfall = phase2 ? money2(Math.max(0, Math.max(contingency, contingencyTarget) - Math.min(...final.path36.slice(phase2.month - 1)))) : 0;
  if (!equityRaise && phase2Shortfall > 0 && !reasons.includes('break_even_beyond_horizon')) reasons.push('phase2_not_funded_from_cash');
  const lowestIdx = final.path36.reduce((best, c, i) => (c < final.path36[best] ? i : best), 0);
  const fundingNeed = {
    rule: horizon.basis,
    horizon_months: horizon.months,
    horizon_months_after_opening: horizon.months_after_opening,
    horizon_source: horizon.source,
    opening_month: openingMonth,
    break_even_month: positiveFrom,
    break_even_within_horizon: breakEvenWithin,
    components: {
      setup_usd: money2(setup),
      opening_working_capital_usd: money2(buffer),
      pre_opening_and_ramp_losses_usd: money2(deficit),
      contingency_usd: money2(modelNeed - money2(modelNeed / (1 + contingencyShare))),
    },
    need_usd: money2(modelNeed),
    stated_by_founder: stated != null,
    // Losses after the horizon (before break-even, or through month 36) that this plan does not fund.
    unfunded_losses_after_horizon_usd: equityRaise ? 0 : money2(Math.max(0, lossesFull - lossesWithin)),
    phase2: phase2 ? { month: phase2.month, share: phase2.share, capex_usd: phase2.capex_usd, staff_deferred_monthly_usd: phase2.staff_deferred_monthly_usd, deferred_lines: phase2.deferred_lines, opening_setup_usd: phase2.opening_setup_usd, full_setup_usd: phase2.full_setup_usd } : null,
    phase2_cash_shortfall_usd: phase2Shortfall,
    lowest_cash_usd: final.min36,
    lowest_cash_month: final.min36 < 0 ? lowestIdx + 1 : final.min36Month,
    cash_goes_negative: final.min36 < 0,
    dscr_year2: dscrYear2,
    dscr_target: DSCR_REFERENCE_MINIMUM,
    works: reasons.length === 0,
    reasons,
  };

  const outsideLabel =
    outsideType === 'debt' && outsideIntent === 'yes'
      ? stated != null ? 'Loan financing (amount stated by the founder)' : 'Loan financing requested'
      : outsideType === 'equity' && outsideIntent === 'yes'
        ? stated != null ? 'Equity financing (raise stated by the founder)' : 'Equity financing needed'
        : 'Financing needed (loan / outside capital)';

  const debtOutstanding = loan ? loan.principal_usd : 0;
  const equityRaised = outsideType === 'equity' && outsideIntent === 'yes' ? outside : 0;
  const otherFinancing = money2(outside - debtOutstanding - equityRaised);

  return {
    setup,
    setupPlan,
    founderSetup,
    packRange,
    packSetup,
    setupCategories,
    depreciation,
    buffer,
    cogsRatio,
    growthRate,
    ramp,
    revenueSeries,
    revenueByYear,
    cogsSeries,
    cogsByYear,
    revenueModel,
    firstRevenueMonth,
    opexSeries,
    run,
    final,
    loan,
    loanSought,
    outsideType,
    stated,
    modelNeed,
    deficit,
    owner: ownerSource,
    outside,
    totalSources,
    openingCash,
    uses,
    contingency,
    contingencyTarget,
    workingCapital,
    runway,
    positiveFrom,
    avgBurn,
    shortfall,
    fundingNeed,
    horizon,
    phase2,
    opexAddByYear,
    capexByMonth,
    outsideLabel,
    debtOutstanding,
    equityRaised,
    otherFinancing,
  };
}

/** Percent for prose: 0.324 -> "32.4%". */
function pctText(x, digits = 1) {
  const v = Math.round(Number(x) * 100 * 10 ** digits) / 10 ** digits;
  return `${v}%`;
}

/**
 * Year-end balance sheets and the annual cash summary for a launch model with a real capital
 * structure: a loan that amortizes, outside equity, or financing whose type is still undecided.
 * Year 1 cash is the month-12 cash of the monthly cash flow. Years 2 and 3 add net income and
 * subtract the principal repaid that year, because this model is cash-basis with no receivables,
 * payables, inventory build, or depreciation. Assets equal liabilities plus equity every year.
 */
function buildLaunchPosition(bs, years, year1CashFlow, loan, depreciation = null, laterCapex = null) {
  const openingFixedCost = bs.assets.fixed_assets_cost_usd ?? bs.assets.fixed_assets_usd;
  const capexInYear = (y) => (laterCapex && Math.ceil(laterCapex.month / 12) === y ? laterCapex.capex_usd : 0);
  const otherFinancing = money2(bs.liabilities.financing_payable_usd - (bs.liabilities.loan_payable_usd || 0));
  const ownerCapital = bs.equity.owner_capital_usd;
  const outsideEquity = bs.equity.outside_equity_usd || 0;
  const annual_cash_summary = [];
  const projected_balance_sheets = [];
  let cash = bs.assets.cash_usd;
  let retained = 0;
  for (const y of years) {
    const beginning = cash;
    const netIncome = money2(y.net_income_usd);
    const dep = money2(y.depreciation_usd || 0);
    const principal = loan ? loan.annual[y.year - 1].principal_usd : 0;
    // Operating cash is net income with the non-cash depreciation charge added back.
    const operatingCash = money2(netIncome + dep);
    const capitalSpent = money2(capexInYear(y.year));
    const fixedCost = money2(openingFixedCost + (laterCapex && Math.ceil(laterCapex.month / 12) <= y.year ? laterCapex.capex_usd : 0));
    const ending =
      y.year === 1 ? money2(year1CashFlow[year1CashFlow.length - 1].ending_cash_usd) : money2(beginning + operatingCash - principal - capitalSpent);
    annual_cash_summary.push({
      year: y.year,
      beginning_cash_usd: money2(beginning),
      net_income_usd: netIncome,
      depreciation_usd: dep,
      net_cash_from_operations_usd: operatingCash,
      loan_principal_repaid_usd: money2(principal),
      capital_spending_usd: capitalSpent,
      ending_cash_usd: ending,
    });
    cash = ending;
    retained = money2(retained + netIncome);
    const loanBalance = loan ? loan.annual[y.year - 1].ending_balance_usd : 0;
    const liabilities = money2(otherFinancing + loanBalance);
    const totalEquity = money2(ownerCapital + outsideEquity + retained);
    const accumulated = depreciation ? depreciation.accumulated_by_year_end[y.year] : 0;
    const fixedNet = money2(fixedCost - accumulated);
    projected_balance_sheets.push({
      year: y.year,
      cash_usd: ending,
      fixed_assets_cost_usd: money2(fixedCost),
      accumulated_depreciation_usd: money2(accumulated),
      fixed_assets_usd: fixedNet,
      total_assets_usd: money2(ending + fixedNet),
      financing_payable_usd: liabilities,
      loan_payable_usd: money2(loanBalance),
      total_liabilities_usd: liabilities,
      owner_capital_usd: money2(ownerCapital),
      outside_equity_usd: money2(outsideEquity),
      retained_earnings_usd: retained,
      total_equity_usd: totalEquity,
      total_liabilities_and_equity_usd: money2(liabilities + totalEquity),
    });
  }
  return { annual_cash_summary, projected_balance_sheets };
}

/** Debt-service coverage for the modeled loan, plus a rate-shock row. */
function buildLaunchDebtService(lm, years, existingDebts) {
  if (!lm.loan) return null;
  const t = lm.loan.terms;
  const scenarios = [
    { label: t.basis === 'founder' ? 'Founder-stated terms' : 'Assumed SBA 7(a) terms', annual_rate: t.annual_rate, term_years: t.term_years },
    { label: 'Rate 2 points higher', annual_rate: Math.round((t.annual_rate + 0.02) * 10000) / 10000, term_years: t.term_years },
  ];
  const ds = buildDebtServiceAnalysis({ loan_amount_usd: lm.loan.principal_usd, years, existing_debts: existingDebts, scenarios });
  ds.scenarios[0].primary = true;
  ds.terms = t;
  ds.amortization = {
    principal_usd: lm.loan.principal_usd,
    monthly_payment_usd: lm.loan.monthly_payment_usd,
    term_months: lm.loan.schedule.length,
    total_interest_usd: lm.loan.total_interest_usd,
    annual: lm.loan.annual,
  };
  const primary = ds.scenarios[0];
  ds.years_below_threshold = primary.coverage.filter((c) => !c.meets_reference_minimum).map((c) => c.year);
  ds.flag_below_threshold = ds.years_below_threshold.length > 0;
  ds.note = 'Coverage is EBITDA (operating income before depreciation and amortization) over annual principal and interest. The loan payments are in the cash flow.';
  return ds;
}

/**
 * When the business opens, what holds it there, and what the pre-opening months cost; with the
 * model re-run (a) for a permit that takes the screen's full planning allowance and (b) for the
 * opening the founder asked for, so the owner's notes can say what each would change.
 */
function buildOpeningAnalysis(costModel, lm, costInput, launchInput) {
  const sch = costModel.schedule;
  if (!sch) return null;
  const scenario = (month) => {
    const cm = buildCostModel({ ...costInput, force_opening_month: month });
    const m = buildLaunchModel({ costModel: cm, ...launchInput });
    return {
      opening_month: cm.schedule.opening_month,
      total_capital_usd: m.totalSources,
      loan_usd: m.loan ? m.loan.principal_usd : null,
      year1_revenue_usd: m.final.years[0].revenue_usd,
    };
  };
  const opening = sch.opening_month;
  const pre = costModel.opex_by_month.slice(0, Math.max(0, opening - 1));
  const founderMonthly = costModel.staffing.filter((r) => r.is_founder).reduce((a, r) => a + r.monthly_employer_cost_usd * r.count, 0);
  const preOpening = {
    months: opening - 1,
    total_usd: money2(pre.reduce((a, x) => a + x, 0)),
    owner_pay_usd: money2(founderMonthly * (opening - 1)),
    lease_start_month: sch.lease_start_month,
    premises_usd: money2(costModel.lines_by_month.slice(0, Math.max(0, opening - 1)).reduce((a, x) => a + x, 0)),
    last_month_usd: pre.length ? money2(pre[pre.length - 1]) : 0,
  };
  const base = { opening_month: opening, total_capital_usd: lm.totalSources, loan_usd: lm.loan ? lm.loan.principal_usd : null, year1_revenue_usd: lm.final.years[0].revenue_usd };
  const allowanceMonth = Math.min(12, Math.max(0, ...sch.required_permits.map((p) => p.allowance_approval_month || 0)));
  const delay = allowanceMonth > opening ? scenario(allowanceMonth) : null;
  const target = sch.requested_month != null ? Math.max(sch.requested_month, sch.stage_floor_month) : null;
  let sooner = null;
  if (target != null && target < opening) {
    sooner = {
      ...scenario(target),
      permits_needed: sch.required_permits
        .filter((p) => p.approval_month > target)
        .map((p) => ({ id: p.id, label: p.label, lead_months: p.lead_months, needed_within_months: target - 1 })),
    };
  }
  return { schedule: sch, base, pre_opening: preOpening, permit_delay: delay, founder_requested: sooner };
}

/**
 * The ways to bring debt coverage to the lender's line (and owner's equity above zero), each
 * computed from the same loan and the same earnings: more owner equity in place of debt (or a
 * smaller project), a longer term, an interest-only start, and deferring the owner's pay until
 * opening. Nothing here changes the plan; it is the arithmetic for the owner's conversation.
 */
function buildFinancingOptions(lm, proj, ds, costModel) {
  if (!lm.loan || !ds?.applicable) return null;
  const target = DSCR_REFERENCE_MINIMUM;
  const t = lm.loan.terms;
  const P = lm.loan.principal_usd;
  const existing = ds.existing_annual_debt_service_usd || 0;
  const ebitdaOf = (y) => {
    const yr = proj.years.find((x) => x.year === y);
    return yr ? yr.ebitda_usd ?? yr.operating_income_usd : null;
  };
  const annualDs = (principal, rate, years) => money2(monthlyLoanPayment(principal, rate, years) * 12 + existing);
  const dscr = (ebitda, annual) => (annual > 0 && ebitda > 0 ? Math.round((ebitda / annual) * 100) / 100 : null);
  const r = t.annual_rate / 12;
  const n = Math.round(t.term_years * 12);
  const pvOfPayment = (payment) => (payment <= 0 ? 0 : r > 0 ? money2((payment * (1 - Math.pow(1 + r, -n))) / r) : money2(payment * n));

  const years = [1, 2, 3].map((y) => {
    const ebitda = ebitdaOf(y);
    const current = dscr(ebitda, annualDs(P, t.annual_rate, t.term_years));
    // The largest loan this year's earnings carry at the target coverage, same rate and term.
    const maxLoan = ebitda > 0 ? Math.min(P, pvOfPayment((ebitda / target - existing) / 12)) : 0;
    return {
      year: y,
      ebitda_usd: ebitda,
      dscr: current,
      meets_target: current != null && current >= target,
      max_loan_at_target_usd: money2(maxLoan),
      equity_to_reach_target_usd: current != null && current >= target ? 0 : ebitda > 0 ? money2(P - maxLoan) : null,
    };
  });
  // The year a lender reads first after the ramp: Year 2 when it falls short, else Year 3.
  const focus = years.find((y) => y.year >= 2 && !y.meets_target) || null;

  const longer = [15, 25].map((yrs) => ({
    term_years: yrs,
    monthly_payment_usd: monthlyLoanPayment(P, t.annual_rate, yrs),
    dscr_by_year: years.map((y) => ({ year: y.year, dscr: dscr(y.ebitda_usd, annualDs(P, t.annual_rate, yrs)) })),
  }));

  // Interest-only for the first twelve months, then level payments over the rest of the term.
  const ioMonths = 12;
  const ioInterestY1 = money2(P * t.annual_rate);
  const amortAfter = monthlyLoanPayment(P, t.annual_rate, (n - ioMonths) / 12);
  const interestOnly = {
    months: ioMonths,
    year1_payments_usd: ioInterestY1,
    year1_cash_saved_usd: money2(lm.loan.annual[0].principal_usd),
    monthly_payment_after_usd: amortAfter,
    dscr_by_year: years.map((y) => ({ year: y.year, dscr: y.year === 1 ? dscr(y.ebitda_usd, ioInterestY1 + existing) : dscr(y.ebitda_usd, amortAfter * 12 + existing) })),
  };

  const founderMonthly = costModel.staffing.filter((x) => x.is_founder).reduce((a, x) => a + x.monthly_employer_cost_usd * x.count, 0);
  const preMonths = Math.max(0, (costModel.schedule?.opening_month || 1) - 1);
  const deferOwnerPay = founderMonthly > 0 && preMonths > 0 ? { months: preMonths, saving_usd: money2(founderMonthly * preMonths) } : null;

  const equities = (proj.projected_balance_sheets || []).map((b) => ({ year: b.year, equity_usd: b.total_equity_usd }));
  const lowest = equities.reduce((m, e) => (m == null || e.equity_usd < m.equity_usd ? e : m), null);
  const equityPositive = lowest && lowest.equity_usd < 0 ? { lowest_year: lowest.year, lowest_equity_usd: lowest.equity_usd, injection_usd: money2(-lowest.equity_usd) } : null;

  return {
    target_dscr: target,
    loan_usd: P,
    annual_rate: t.annual_rate,
    term_years: t.term_years,
    years,
    focus_year: focus ? focus.year : null,
    longer_terms: longer,
    interest_only: interestOnly,
    defer_owner_pay: deferOwnerPay,
    equity_positive: equityPositive,
  };
}

/**
 * What it would take for a plan that does not work as structured to work. Each lever is tried on
 * its own: the smallest change that brings monthly cash break-even inside the funding horizon and,
 * with a loan, Year 2 debt coverage to the lender's line. Every figure is the same model re-run with
 * that one change (the loan re-sized to the new need), so the levers and the statements agree.
 * A lever that cannot get there within a plausible range says so, with where the range ends.
 */
function buildFundingLevers(costModel, lm, launchInput) {
  const evaluate = (patch) => buildLaunchModel({ costModel, ...launchInput, ...patch }).fundingNeed;
  const solve = (make, max) => {
    const top = evaluate(make(max));
    if (!top.works) return { reached: false, x: max, result: top };
    let lo = 0;
    let hi = max;
    let best = top;
    for (let i = 0; i < 14; i++) {
      const mid = (lo + hi) / 2;
      const r = evaluate(make(mid));
      if (r.works) {
        hi = mid;
        best = r;
      } else lo = mid;
    }
    return { reached: true, x: hi, result: best };
  };
  const pctUp = (x) => Math.ceil(x * 1000) / 10;
  const summary = (r) => ({ break_even_month: r.break_even_month, dscr_year2: r.dscr_year2, need_usd: r.need_usd, unfunded_losses_after_horizon_usd: r.unfunded_losses_after_horizon_usd });
  const levers = [];
  const add = (id, label, max, make, fields, extra = {}) => {
    const s = solve(make, max);
    levers.push({ id, label, ...extra, reached: s.reached, change: fields(s.x), limit: fields(max), result: summary(s.result) });
  };
  const months = Array.from({ length: 12 }, (_, i) => i + 1);
  const opening = lm.horizon.opening_month;
  const founderAt = (m) => costModel.staffing.filter((r) => r.is_founder && m >= r.start_month).reduce((a, r) => a + r.monthly_employer_cost_usd * r.count, 0);
  const cut = (fn, x) => ({ adjust: { opex_reduction_by_month: months.map((m) => money2(fn(m) * x)) } });

  add('price', 'Raise prices', 0.5, (x) => ({ adjust: { price_factor: 1 + x } }), (x) => ({ change_pct: pctUp(x) }));
  add('volume', 'Sell more', 1, (x) => ({ adjust: { volume_factor: 1 + x } }), (x) => ({ change_pct: pctUp(x) }));

  const rentLine = (costModel.lines || []).find((l) => l.key === 'occupancy' && l.monthly_usd > 0);
  if (rentLine) {
    const leaseStart = costModel.schedule?.lease_start_month ?? null;
    const rentAt = (m) => (m >= opening || (leaseStart != null && m >= leaseStart) ? rentLine.monthly_usd : 0);
    add('rent', 'Lower rent', 0.6, (x) => cut(rentAt, x), (x) => ({ change_pct: pctUp(x), from_usd: money2(rentLine.monthly_usd), to_usd: Math.floor(rentLine.monthly_usd * (1 - x) / 50) * 50 }));
  }

  const staffAt = (m) => Math.max(0, (costModel.payroll_by_month[m - 1] || 0) - founderAt(m));
  const staffSteady = staffAt(12);
  if (staffSteady > 0) {
    add('staffing', 'Leaner staffing', 0.5, (x) => cut(staffAt, x), (x) => ({ change_pct: pctUp(x), from_usd: money2(staffSteady), to_usd: Math.floor(staffSteady * (1 - x) / 50) * 50 }));
  }

  const ownerSteady = founderAt(12);
  if (ownerSteady > 0) {
    add('owner_pay', "Lower owner's pay", 1, (x) => cut(founderAt, x), (x) => ({ change_pct: pctUp(x), from_usd: money2(ownerSteady), to_usd: Math.floor(ownerSteady * (1 - x) / 50) * 50 }));
  }

  if (lm.loan && lm.stated == null) {
    const owner = launchInput.capital?.available_usd ?? 0;
    add(
      'equity',
      'More owner equity in place of debt',
      // Up to the whole loan (a little over, since less debt also means a smaller need).
      money2(lm.loan.principal_usd * 1.05),
      (x) => ({ capital: { ...launchInput.capital, available_usd: owner + x } }),
      (x) => {
        const more = Math.ceil(x / 1000) * 1000;
        return { amount_usd: more, owner_total_usd: money2(owner + more) };
      },
    );
  }

  // A longer loan term: the same loan re-run over 15 and 25 years. SBA 7(a) allows 25 years only for
  // real estate; equipment and working capital top out at 10.
  if (lm.loan) {
    const terms = [15, 25].map((years) => {
      const r = evaluate({ termYearsOverride: years });
      return { term_years: years, works: r.works, ...summary(r) };
    });
    levers.push({ id: 'loan_term', label: 'A longer loan term', reached: terms.some((t) => t.works), terms, real_estate_only_years: SBA_7A.max_term_years_real_estate.value, standard_max_years: SBA_7A.max_term_years_non_real_estate.value });
  }

  // A line held back for a license it only partly needs (wine with small plates): the share that
  // would have to be sold from opening, without the license, for the plan to work.
  const rb = launchInput.revenueBuildup;
  const sch = costModel.schedule;
  if (rb && sch) {
    const scaleVol = (v, f) => (v.mode === 'growth' ? { ...v, start: v.start * f } : { ...v, start: v.start * f, month12: v.month12 * f, month36: v.month36 * f });
    for (const t of rb.tiers) {
      const start = productStartMonth(sch, t.name);
      if (!(start > sch.opening_month)) continue;
      const lic = productLicense(sch, t.name);
      const make = (s) => ({
        revenueBuildup: {
          ...rb,
          tiers: rb.tiers.flatMap((x) =>
            x.id !== t.id
              ? [x]
              : [
                  ...(1 - s > 1e-6 ? [{ ...x, volume: scaleVol(x.volume, 1 - s) }] : []),
                  ...(s > 1e-6 ? [{ ...x, id: `${x.id}_at_opening`, name: `${x.name} (no license needed)`, start_at_opening: true, volume: scaleVol(x.volume, s) }] : []),
                ],
          ),
        },
      });
      add('split_line', 'Split a license-dependent line', 1, make, (x) => ({ share_pct: pctUp(x) }), {
        tier_name: t.name,
        license: lic ? lic.label : null,
        license_start_month: start,
      });
    }
  }
  return levers;
}

/** Revenue sensitivity for the launch model: the same run, revenue scaled, costs and loan held. */
function buildLaunchSensitivity(lm, proj, debtService) {
  const primary = debtService?.applicable ? debtService.scenarios.find((s) => s.primary) || debtService.scenarios[0] : null;
  const rows = SENSITIVITY_REVENUE_FACTORS.map((factor) => {
    const r = runLaunchProjection({
      revenueSeries: lm.revenueSeries.map((v) => v * factor),
      opexSeries: lm.opexSeries,
      cogsRatio: lm.cogsRatio,
      growthRate: lm.growthRate,
      openingCash: lm.openingCash,
      loan: lm.loan,
      revenueByYear: lm.revenueByYear ? { 2: lm.revenueByYear[2] * factor, 3: lm.revenueByYear[3] * factor } : null,
      // With a build-up, a volume change moves each tier's variable cost with its revenue.
      cogsSeries: lm.cogsSeries ? lm.cogsSeries.map((v) => v * factor) : null,
      cogsByYear: lm.cogsByYear ? { 2: lm.cogsByYear[2] * factor, 3: lm.cogsByYear[3] * factor } : null,
      depreciation: lm.depreciation,
      opexAddByYear: lm.opexAddByYear,
      capexByMonth: lm.capexByMonth,
    });
    const beRevenue = proj.break_even.break_even_monthly_revenue_usd;
    const beIdx = r.year1Monthly.findIndex((m) => m.revenue_usd >= beRevenue);
    const y2 = r.years[1];
    const y2Ebitda = y2.ebitda_usd ?? y2.operating_income_usd;
    const y2Dscr =
      primary && y2Ebitda > 0 && primary.annual_debt_service_usd > 0
        ? Math.round((y2Ebitda / primary.annual_debt_service_usd) * 100) / 100
        : null;
    return {
      revenue_change_pct: Math.round((factor - 1) * 100),
      year1_revenue_usd: r.year1Totals.revenue_usd,
      year1_operating_income_usd: r.year1Totals.operating_income_usd,
      year1_low_cash_usd: r.cashFlow.cash_flow_trough_usd,
      break_even_month: beIdx === -1 ? null : beIdx + 1,
      year2_revenue_usd: y2.revenue_usd,
      year2_operating_income_usd: y2.operating_income_usd,
      year2_dscr_mid: y2Dscr,
      low_cash_36_months_usd: r.min36,
    };
  });
  return {
    basis: lm.revenueModel
      ? 'Volume scaled by the stated percentage in every month, so revenue and each product\'s variable cost move together; operating costs, capital and loan payments held at the base case.'
      : 'Revenue scaled by the stated percentage in every month; costs, capital and loan payments held at the base case.',
    dscr_terms: primary ? { label: primary.label, annual_rate: primary.annual_rate, term_years: primary.term_years } : null,
    rows,
  };
}

/**
 * The launch projection set, assembled from the cost model and the launch model. The shape is
 * the one the documents already read, plus the cost build-up, the loan schedule, and the use of
 * proceeds.
 */
function buildLaunchProjections(lm, costModel, stage) {
  const f = lm.final;
  const profile = costModel.industry.profile;
  const staffing = costModel.staffing;
  const b = costModel.payroll.annual_burden_usd;
  const employeeWages = staffing.filter((r) => !r.contractor).reduce((a, r) => a + r.annual_wages_usd, 0);
  const contractorWages = staffing.filter((r) => r.contractor).reduce((a, r) => a + r.annual_wages_usd, 0);
  const opexCategories = [
    { label: 'Wages and salaries', monthly_usd: money2(employeeWages / 12), basis: 'BLS OEWS May 2025 median wages', source: 'bls_oews_may2025' },
    contractorWages > 0 ? { label: 'Contractors', monthly_usd: money2(contractorWages / 12), basis: 'BLS OEWS May 2025 median wage for the occupation', source: 'bls_oews_may2025' } : null,
    {
      label: 'Payroll taxes (Social Security, Medicare, federal and state unemployment)',
      monthly_usd: money2((b.social_security_usd + b.medicare_usd + b.futa_usd + b.suta_usd) / 12),
      basis: 'IRS employer rates; state new-employer unemployment rate',
      source: 'irs_topic_751',
    },
    { label: "Workers' compensation insurance", monthly_usd: money2(b.workers_comp_usd / 12), basis: 'State premium index per $100 of payroll', source: costModel.payroll.workers_comp.source },
    b.health_usd > 0 ? { label: 'Employee health benefits', monthly_usd: money2(b.health_usd / 12), basis: 'Employer share of single coverage', source: 'kff_ehbs_2025' } : null,
    ...costModel.lines.map((l) => ({
      label: l.label,
      monthly_usd: l.monthly_usd,
      basis: l.basis === 'founder' ? 'Founder figure' : `${pctText(l.ratio, 2)} of steady-state revenue`,
      source: l.basis === 'founder' ? null : l.source,
    })),
  ].filter(Boolean);
  // The categories are the steady-state month; pennies of rounding go to the last line so the
  // list foots to the modeled monthly cost.
  const opexSteady = money2(costModel.steady_state_monthly_opex_usd);
  const catSum = money2(opexCategories.reduce((a, c) => a + c.monthly_usd, 0));
  if (catSum !== opexSteady) opexCategories[opexCategories.length - 1].monthly_usd = money2(opexCategories[opexCategories.length - 1].monthly_usd + opexSteady - catSum);

  const equipment = lm.uses.find((u) => u.id === 'equipment').amount_usd;
  const fixedSetupCategories = lm.depreciation.categories.map((c) => ({ ...c }));

  const balance_sheet = {
    assets: {
      cash_usd: money2(lm.openingCash),
      // Equipment, buildout and start-up assets at cost; opening inventory and deposits are
      // carried inside this line and never depreciated.
      fixed_assets_cost_usd: money2(equipment),
      accumulated_depreciation_usd: 0,
      fixed_assets_usd: money2(equipment),
      total_assets_usd: money2(lm.openingCash + equipment),
    },
    liabilities: {
      financing_payable_usd: money2(lm.debtOutstanding + lm.otherFinancing),
      loan_payable_usd: money2(lm.debtOutstanding),
      total_liabilities_usd: money2(lm.debtOutstanding + lm.otherFinancing),
    },
    equity: {
      owner_capital_usd: money2(lm.owner),
      outside_equity_usd: money2(lm.equityRaised),
      total_equity_usd: money2(lm.owner + lm.equityRaised),
    },
  };

  const sources_and_uses = {
    sources: [
      { label: 'Owner capital', amount_usd: money2(lm.owner) },
      { label: lm.outsideLabel, amount_usd: money2(lm.outside), type: lm.outsideType },
    ],
    uses: lm.uses.map((u) => ({ id: u.id, label: u.label, short_label: u.short_label, amount_usd: u.amount_usd })),
    total_sources_usd: money2(lm.totalSources),
    total_uses_usd: money2(lm.uses.reduce((a, u) => a + u.amount_usd, 0)),
  };

  const opex12 = f.year1Monthly[11].opex_usd;
  const contribution = 1 - lm.cogsRatio;
  const breakEvenRevenue = money2(opex12 / contribution);
  const beIdx = f.year1Monthly.findIndex((m) => m.revenue_usd >= breakEvenRevenue);
  const break_even = {
    fixed_costs_monthly_usd: money2(opex12),
    contribution_margin_ratio: Math.round(contribution * 1000) / 1000,
    break_even_monthly_revenue_usd: breakEvenRevenue,
    break_even_month: beIdx === -1 ? null : beIdx + 1,
  };

  const position = buildLaunchPosition(balance_sheet, f.years, f.cashFlow.year1_cash_flow, lm.loan, lm.depreciation, lm.phase2);

  const sizing = costModel.revenue_sizing;
  const place = costModel.place.status === 'not_decided' ? 'national medians (no location chosen yet)' : `medians for ${costModel.place.label}`;
  const growthText = `${pctText(ANNUAL_GROWTH_RATE, 0)}, a conservative planning rate`;
  const y2 = f.years[1];
  const y3 = f.years[2];
  const impliedY3Growth = y2.revenue_usd > 0 ? y3.revenue_usd / y2.revenue_usd - 1 : null;
  const gc = costModel.growth_check;
  const rm = lm.revenueModel;
  const sp = lm.setupPlan;
  const rent = costModel.rent;
  const lives = ['equipment', 'furniture', 'technology', 'buildout', 'startup'].map((k) => MODEL_ASSUMPTIONS[`depreciation_life_${k}_years`].value);
  const assumptions = [
    rm
      ? `Revenue is built product by product from expected prices, billing terms and monthly volumes for ${rm.tiers.length} product${rm.tiers.length === 1 ? '' : 's'} and service${rm.tiers.length === 1 ? '' : 's'} (see Sales Forecast).`
      : sizing.method === 'labor_share'
      ? `Revenue is implied by costs — not a sales forecast. It is derived from the cost base rather than from a price-times-volume sales forecast: steady-state revenue is the sales this payroll supports at the industry's median labor cost of ${pctText(sizing.labor_share)} of sales (National Restaurant Association). The margin is what remains after cost of goods and benchmark overheads, which is thin, as it is in practice. Monthly revenue will be replaced by a product-by-product forecast as prices and volumes are confirmed.`
      : `Revenue is implied by costs — not a sales forecast. It is derived from the cost base rather than from a price-times-volume sales forecast: steady-state revenue is set so the modeled costs are covered with a ${pctText(sizing.target_operating_margin, 0)} operating margin. Monthly revenue will be replaced by a product-by-product forecast as prices and volumes are confirmed.`,
    `Payroll is built role by role from the ${costModel.team_basis === 'founder' ? 'planned team' : 'standard team for a business of this kind and stage'}, at Bureau of Labor Statistics May 2025 median wages (${place}), plus employer Social Security and Medicare (7.65%), federal unemployment tax, state unemployment insurance at the new-employer rate, and a workers' compensation estimate${costModel.payroll.health_benefit_offered ? ', and the employer share of single health coverage for full-time roles' : ''}. The owner's role is paid at the market median for the occupation.`,
    rm
      ? `Cost of goods sold is each product's direct cost per unit times its volume: ${pctText(lm.cogsRatio)} of revenue across the Year 2 mix, against an industry benchmark of ${pctText(costModel.cogs_ratio)}.`
      : `Cost of goods sold is ${pctText(lm.cogsRatio)} of revenue (${costModel.cogs_components.map((c) => c.label).join('; ')}).`,
    rent?.basis === 'benchmark'
      ? `Rent is ${proseMoney(rent.monthly_usd)} a month: about ${rent.square_feet.toLocaleString('en-US')} square feet at $${rent.annual_per_sq_ft_usd.toFixed(2)} per square foot a year, the ${rent.basis_text} (Cushman & Wakefield, Q2 2026). Shopping-center asking rents are used; street-front space can lease higher, and the signed lease will replace this figure.`
      : rent?.basis === 'allowance'
        ? `Rent is an allowance of ${proseMoney(rent.monthly_usd)} a month: about ${rent.square_feet.toLocaleString('en-US')} square feet of street-front space at $${rent.annual_per_sq_ft_usd.toFixed(2)} per square foot a year, within a planning range of ${proseMoney(rent.monthly_low_usd)} to ${proseMoney(rent.monthly_high_usd)}. The only published rate for ${rent.published_area}, $${rent.published_per_sq_ft_usd.toFixed(2)} (Cushman & Wakefield, Q2 2026), covers shopping centers, which lease below street-front space in the city center; the allowance is ${rent.factor} times that rate until a lease quote replaces it.`
        : rent?.basis === 'founder'
          ? `Rent is ${proseMoney(rent.monthly_usd)} a month, as quoted.`
          : 'No premises are rented.',
    'Utilities, insurance, repairs, marketing and the other operating lines are published ratios of revenue for this industry (sources in the cost build-up), set as fixed monthly amounts at the full-operation run rate. A quoted figure, where available, replaces the benchmark.',
    ...(costModel.schedule && costModel.schedule.opening_month > 1
      ? [
          `The business opens in month ${costModel.schedule.opening_month}, after the permits it needs to open${costModel.schedule.binding === 'permit' ? ' (the longest sets the date)' : ''}. Before then it carries only pre-opening costs: the owner's pay${costModel.schedule.lease_start_month && costModel.schedule.lease_start_month < costModel.schedule.opening_month ? `, and from the lease start in month ${costModel.schedule.lease_start_month}, rent and insurance, with utilities at ${pctText(MODEL_ASSUMPTIONS.pre_opening_utilities_share.value, 0)} of the running level during the buildout` : ''}. Staff, marketing and the other running costs start at opening.${(rm?.tiers || []).some((t) => t.start_month > costModel.schedule.opening_month) ? ` Products that need their own license start when it is expected: ${rm.tiers.filter((t) => t.start_month > costModel.schedule.opening_month).map((t) => `${t.name.toLowerCase()} in month ${t.start_month}`).join('; ')}.` : ''}`,
        ]
      : []),
    lm.founderSetup
      ? `One-time start-up costs of ${proseMoney(lm.setup)} are the equipment and build-out lines management listed${lm.founderSetup.some((i) => i.quoted) ? `, ${lm.founderSetup.filter((i) => i.quoted).length} of them from vendor quotes` : ''}.`
      : sp
      ? sp.basis === 'benchmark'
        ? `One-time start-up costs of ${proseMoney(lm.setup)} are based on ${sp.method === 'per_sq_ft' ? `published start-up costs of ${proseMoney(sp.per_sq_ft_usd)} per square foot for ${sp.square_feet_basis === 'quoted' ? 'the' : 'about'} ${sp.square_feet.toLocaleString('en-US')} square feet${sp.square_feet_basis === 'quoted' ? ' quoted' : ''}` : `a published start-up cost of ${proseMoney(STARTUP_COST_BENCHMARKS[costModel.industry.id]?.total_usd)}`}${sp.location_factor !== 1 ? `, adjusted by the regional price parity for the area (${sp.location_factor.toFixed(3)})` : ''}${sp.space_factor !== 1 ? ` and by ${sp.space_factor > 1 ? 'the higher cost of a full buildout' : 'the lower cost of taking over a fitted space'} (${sp.space_factor.toFixed(3)})` : ''}. They are split across categories by typical share and will be replaced by vendor quotes.`
        : `One-time start-up costs of ${proseMoney(lm.setup)} are a planning allowance for a business of this kind; no published benchmark was found, and vendor quotes will replace it.`
      : `One-time start-up costs are ${proseMoney(lm.setup)}.`,
    rm
      ? `Volumes start in month ${lm.firstRevenueMonth} and follow management's ramp for each product: straight lines from the opening volume to the month-12 and month-36 figures, or a monthly growth rate. Years 2 and 3 are the sums of those months, not a growth assumption. Operating costs grow ${pctText(ANNUAL_GROWTH_RATE * OPEX_SCALE_WITH_REVENUE, 1)} a year after Year 1.`
      : costModel.ramp === 'software'
      ? `Revenue starts in month ${costModel.first_revenue_month}, reaches ${pctText(MODEL_ASSUMPTIONS.software_month12_fraction_of_steady_state.value, 0)} of the cost-covering run rate by month 12, and builds in a straight line to the full run rate at month 36. Subscription revenue accumulates customer by customer, so this is an assumption, not a forecast. The implied Year 3 growth is ${impliedY3Growth == null ? 'not defined' : pctText(impliedY3Growth, 0)}${gc ? `; SaaS Capital reports a ${pctText(gc.benchmark_rate, 0)} median for equity-backed private software companies of all sizes` : ''}. Operating costs grow ${pctText(ANNUAL_GROWTH_RATE * OPEX_SCALE_WITH_REVENUE, 1)} a year after Year 1.`
      : `Year 1 is a ramp from zero toward the steady-state rate${costModel.first_revenue_month > 1 ? `, with first revenue in month ${costModel.first_revenue_month}` : ''}. Year 2 is that rate annualized and grown ${growthText}; Year 3 grows at the same rate. The step from Year 1 to Year 2 is the ramp completing rather than a growth assumption. Operating costs grow at ${Math.round(OPEX_SCALE_WITH_REVENUE * 100)}% of the revenue growth rate.`,
    ...(lm.phase2
      ? [
          `The launch is phased. The business opens with its core lines; ${lm.phase2.deferred_lines.map((n) => n.toLowerCase()).join(', ') || 'the license-dependent lines'} start in month ${lm.phase2.month}, when the license is expected. Their share of the equipment, build-out and staff, taken as their ${pctText(lm.phase2.share, 1)} share of month-36 sales until vendors quote each phase, waits for them: ${proseMoney(lm.phase2.capex_usd)} of equipment and build-out is bought in month ${lm.phase2.month} from the business's cash, and ${proseMoney(lm.phase2.staff_deferred_monthly_usd)} a month of staff payroll starts then.`,
        ]
      : []),
    lm.loan
      ? `The loan of ${proseMoney(lm.loan.principal_usd)} is modeled at ${pctText(lm.loan.annual_rate, 2)} over ${lm.loan.term_years} years (${lm.loan.terms.basis === 'founder' ? 'terms quoted to management' : `assumed: the SBA 7(a) maximum rate for this loan size, prime of ${pctText(lm.loan.terms.prime_rate, 2)} as of ${lm.loan.terms.rate_as_of} plus ${pctText(lm.loan.terms.spread, 1)}, over the 7(a) maximum term for working capital and equipment`}), a level monthly payment of ${proseMoney(lm.loan.monthly_payment_usd)}. Interest is an expense in the profit and loss statement, and principal and interest are paid in the cash flow.`
      : 'No loan is modeled, so there is no interest expense and no debt service in the cash flow.',
    `A contingency reserve of ${pctText(MODEL_ASSUMPTIONS.contingency_share.value, 0)} is held back from the capital raised and is not counted as runway.`,
    `Equipment is depreciated straight-line over ${lives[0]} years, furniture and fixtures over ${lives[1]}, computers and point-of-sale hardware over ${lives[2]}, and leasehold improvements over ${lives[3]}; start-up costs are amortized over ${lives[4]} years. Depreciation starts at opening. Opening inventory and deposits are not depreciated. Depreciation is a non-cash charge: it lowers net income and tax, not cash.`,
    `Net income assumes a flat ${Math.round(INCOME_TAX_RATE * 100)}% estimated income tax on positive pre-tax income (0% on a loss). This is a planning estimate; actual tax depends on the entity type and will be confirmed with the company's accountant.`,
    'Monthly estimated income tax accrues against cumulative year-to-date pre-tax income, so an early loss month shows no tax and a later month can show a catch-up once the year turns cumulatively profitable.',
    'Cash flow assumes cash-basis collection with no accounts-receivable lag. Estimated income tax is subtracted in the month it accrues, so the cash statement reconciles with the profit and loss statement. In practice estimated tax is paid quarterly, so cash within the year will differ from the model even where the annual totals agree.',
  ];


  return {
    profile,
    mode: 'launch',
    industry: costModel.industry,
    ...position,
    cogs_ratio: lm.cogsRatio,
    opex_categories: opexCategories,
    fixed_setup_categories: fixedSetupCategories,
    depreciation: {
      start_month: lm.depreciation.start_month,
      by_year: lm.depreciation.by_year,
      monthly: lm.depreciation.monthly,
      depreciable_cost_usd: lm.depreciation.depreciable_cost_usd,
      non_depreciable_cost_usd: lm.depreciation.non_depreciable_cost_usd,
      accumulated_by_year_end: lm.depreciation.accumulated_by_year_end,
    },
    startup_costs: lm.setupPlan || null,
    // 'founder' when the founder listed their own equipment and build-out (see founderSetupItems);
    // 'benchmark' for the indicative split by typical share for this kind of business.
    fixed_setup_basis: lm.founderSetup ? 'founder' : 'benchmark',
    fixed_setup_quoted: lm.founderSetup ? lm.founderSetup.filter((i) => i.quoted).length : 0,
    // The start-up cost check against the industry pack (Research Packs): which figure the equipment
    // line uses (founder quote, pack midpoint or benchmark) and how it compares with the others.
    setup_cost_check: setupCostCheck(lm),
    // With a build-up this is the month-36 run rate of the founder's volumes; otherwise the
    // cost-derived sizing target.
    stabilized_monthly_revenue_usd: money2(rm ? rm.monthly_revenue_month36_usd : costModel.stabilized_monthly_revenue_usd),
    cost_implied_monthly_revenue_usd: money2(costModel.stabilized_monthly_revenue_usd),
    revenue_basis: rm ? 'buildup' : 'cost_implied',
    revenue_basis_label: rm ? "Founder's price × volume build-up" : 'Implied by costs — not a sales forecast',
    revenue_ramp: lm.ramp,
    annual_growth_rate: lm.growthRate,
    year1_monthly: f.year1Monthly,
    year1_totals: f.year1Totals,
    years: f.years,
    balance_sheet,
    sources_and_uses,
    break_even,
    ...f.cashFlow,
    cash_path_36_months: f.path36,
    lowest_cash_36_months_usd: f.min36,
    lowest_cash_36_months_month: f.min36Month,
    income_tax_rate: INCOME_TAX_RATE,
    loan: lm.loan ? { terms: lm.loan.terms, principal_usd: lm.loan.principal_usd, annual_rate: lm.loan.annual_rate, term_years: lm.loan.term_years, monthly_payment_usd: lm.loan.monthly_payment_usd, total_interest_usd: lm.loan.total_interest_usd, annual: lm.loan.annual, schedule: lm.loan.schedule } : null,
    assumptions,
  };
}

/**
 * The revenue model as the documents read it. With a build-up: the per-tier table and totals, the
 * sanity flags, and the checks against the market and the cost base. Without one: the cost-derived
 * figures and the label that says they are not a sales forecast.
 */
function summarizeRevenueModel(lm, costModel, proj) {
  const rm = lm.revenueModel;
  const costImplied = money2(costModel.stabilized_monthly_revenue_usd);
  if (!rm) {
    return {
      basis: 'cost_implied',
      label: 'Implied by costs — not a sales forecast',
      cost_implied_monthly_revenue_usd: costImplied,
      years: proj.years.map((y) => ({ year: y.year, revenue_usd: y.revenue_usd, cogs_usd: y.cogs_usd, gross_profit_usd: y.gross_profit_usd })),
      break_even_monthly_revenue_usd: proj.break_even.break_even_monthly_revenue_usd,
      flags: [],
    };
  }
  const checks = revenueModelFlags(rm, {
    costImpliedMonthlyRevenueUsd: costImplied,
    breakEvenMonthlyRevenueUsd: proj.break_even.break_even_monthly_revenue_usd,
  });
  return {
    basis: 'buildup',
    label: "Founder's price × volume build-up",
    first_revenue_month: rm.first_revenue_month,
    planned_first_month: rm.planned_first_month,
    tiers: rm.tiers.map((t) => ({
      id: t.id,
      name: t.name,
      start_month: t.start_month,
      // The license this product waits on, when it starts after opening (e.g. the alcohol license).
      license: (() => {
        const lic = productLicense(costModel.schedule, t.name);
        return lic ? { id: lic.id, label: lic.label, lead_months: lic.lead_months, approval_month: lic.approval_month } : null;
      })(),
      price_usd: t.price_usd,
      billing: t.billing,
      billing_label: t.billing_label,
      volume_label: t.volume_label,
      volume: t.volume,
      volume_month_first: t.volume_month1,
      volume_month12: t.volume_month12,
      volume_month36: t.volume_month36,
      unit_cost_usd: t.unit_cost_usd,
      unit_margin_usd: t.unit_margin_usd,
      gross_margin_pct: t.gross_margin_pct,
      purchases_per_customer_month: t.purchases_per_customer_month,
      monthly_revenue_month12_usd: t.monthly_revenue_month12_usd,
      monthly_revenue_month36_usd: t.monthly_revenue_month36_usd,
      annual: t.annual,
      implied_customers_month36: t.implied_customers_month36,
    })),
    totals: {
      monthly_revenue_month12_usd: rm.monthly_revenue_month12_usd,
      monthly_revenue_month36_usd: rm.monthly_revenue_month36_usd,
      annual: rm.annual,
    },
    revenue_by_month: rm.revenue_by_month,
    cogs_by_month: rm.cogs_by_month,
    serviceable_customers: rm.serviceable_customers,
    market_basis: rm.market_basis,
    cost_implied_monthly_revenue_usd: costImplied,
    break_even_monthly_revenue_usd: proj.break_even.break_even_monthly_revenue_usd,
    market_check: checks.market_check,
    cost_check: checks.cost_check,
    flags: checks.flags,
    checks_policy: {
      serviceable_share_flag: REVENUE_CHECKS.serviceable_share_flag,
      above_cost_implied_ratio: REVENUE_CHECKS.above_cost_implied_ratio,
      below_cost_implied_ratio: REVENUE_CHECKS.below_cost_implied_ratio,
    },
  };
}

/** The use-of-proceeds statement: what the capital buys and how long it lasts. */
function buildUseOfProceeds(lm, costModel) {
  return {
    total_sources_usd: money2(lm.totalSources),
    owner_capital_usd: money2(lm.owner),
    outside_capital_usd: money2(lm.outside),
    outside_type: lm.outsideType,
    stated_by_founder: lm.stated != null,
    model_need_usd: money2(lm.modelNeed),
    lines: lm.uses.map((u) => ({ ...u })),
    total_uses_usd: money2(lm.uses.reduce((a, u) => a + u.amount_usd, 0)),
    contingency_usd: lm.uses.find((u) => u.id === 'contingency')?.amount_usd || 0,
    runway: lm.runway,
    runway_months_at_year1_average_burn:
      lm.avgBurn > 0 ? Math.floor((lm.totalSources - lm.setup - lm.contingency) / lm.avgBurn) : null,
    year1_average_monthly_net_burn_usd: lm.avgBurn,
    cash_flow_positive_month: lm.positiveFrom,
    shortfall_usd: lm.shortfall,
    month36_net_burn_usd: lm.final.net36[35] < 0 ? money2(-lm.final.net36[35]) : 0,
    basis:
      lm.stated != null
        ? 'Management set the amount; the model shows what it pays for and how long it lasts.'
        : lm.horizon.basis === 'equity_runway'
          ? `The amount is sized from the model: setup, opening working capital, the operating losses over a ${lm.horizon.months}-month runway from the raise, and a contingency.`
          : `The amount is sized from the model: setup, opening working capital, pre-opening costs and the operating losses until monthly cash break-even (capped at ${lm.horizon.months_after_opening} months after opening), and a contingency.`,
    funding_need: lm.fundingNeed,
    steady_state_monthly_opex_usd: costModel.steady_state_monthly_opex_usd,
  };
}

/**
 * Builds a full Year-1-monthly / Years-2-3-annual financial projection: P&L, opening balance
 * sheet, sources & uses, break-even, and Year-1 cash flow. Every input traces back to
 * estimateLaunchFinance's own line items — nothing here invents traction or sales beyond what
 * the modeled cost structure implies.
 *
 * @param {{ profile: string, stage: string, estimated_launch_cost_usd: number, line_items: {fixed_setup_usd: number, variable_buffer_usd: number, monthly_burn_usd: number, reserve_usd: number}, personal_capital: {available_usd: number|null}, funding_gap_usd: number|null }} input
 */
function buildFinancialProjections(input) {
  const profile = PROFILE_COGS_RATIO[input.profile] != null ? input.profile : 'lean_service';
  const stage = STAGE_RAMP[input.stage] ? input.stage : 'idea';
  const cogsRatio = PROFILE_COGS_RATIO[profile];
  const opexSplit = PROFILE_OPEX_SPLIT[profile];
  const fixedSetupSplit = PROFILE_FIXED_SETUP_SPLIT[profile];
  const monthlyBurn = input.line_items.monthly_burn_usd;
  const fixedSetup = input.line_items.fixed_setup_usd;
  const variableBuffer = input.line_items.variable_buffer_usd;
  const reserve = input.line_items.reserve_usd;
  const launchCost = input.estimated_launch_cost_usd;

  const stabilizedRevenue = stabilizedMonthlyRevenue(monthlyBurn, cogsRatio);
  const ramp = STAGE_RAMP[stage];

  const year1Monthly = buildYear1Monthly(
    ramp.map((frac) => stabilizedRevenue * frac),
    ramp.map(() => monthlyBurn),
    cogsRatio,
  );
  const year1Totals = buildYear1Totals(year1Monthly);
  const years = buildYears2And3(year1Monthly, year1Totals, cogsRatio);

  const ownerCapital = Math.min(input.personal_capital.available_usd ?? 0, launchCost);
  const financingNeeded = input.funding_gap_usd ?? Math.max(0, launchCost - ownerCapital);

  const balance_sheet = {
    assets: {
      cash_usd: money2(variableBuffer + reserve),
      fixed_assets_usd: money2(fixedSetup),
      total_assets_usd: money2(variableBuffer + reserve + fixedSetup),
    },
    liabilities: {
      financing_payable_usd: money2(financingNeeded),
      total_liabilities_usd: money2(financingNeeded),
    },
    equity: {
      owner_capital_usd: money2(ownerCapital),
      total_equity_usd: money2(ownerCapital),
    },
  };

  const sources_and_uses = {
    sources: [
      { label: 'Owner capital', amount_usd: money2(ownerCapital) },
      { label: 'Financing needed (loan / outside capital)', amount_usd: money2(financingNeeded) },
    ],
    uses: [
      { label: 'Equipment and buildout', amount_usd: money2(fixedSetup) },
      { label: 'Working capital / opening variable costs', amount_usd: money2(variableBuffer) },
      { label: 'Operating reserve', amount_usd: money2(reserve) },
    ],
    total_sources_usd: money2(ownerCapital + financingNeeded),
    total_uses_usd: money2(fixedSetup + variableBuffer + reserve),
  };

  const contributionMarginRatio = 1 - cogsRatio;
  const breakEvenMonthlyRevenue = money2(monthlyBurn / contributionMarginRatio);
  const breakEvenMonthIndex = year1Monthly.findIndex((m) => m.revenue_usd >= breakEvenMonthlyRevenue);
  const break_even = {
    fixed_costs_monthly_usd: money2(monthlyBurn),
    contribution_margin_ratio: Math.round(contributionMarginRatio * 1000) / 1000,
    break_even_monthly_revenue_usd: breakEvenMonthlyRevenue,
    break_even_month: breakEvenMonthIndex === -1 ? null : breakEvenMonthIndex + 1,
  };

  const cashFlow = buildYear1CashFlow(year1Monthly, variableBuffer + reserve);
  const position = buildProjectedPosition({ balance_sheet, years, ...cashFlow });

  return {
    profile,
    mode: 'launch',
    ...(position || {}),
    cogs_ratio: cogsRatio,
    opex_categories: opexSplit.map((c) => ({ label: c.label, monthly_usd: money2(monthlyBurn * c.share) })),
    fixed_setup_categories: fixedSetupSplit.map((c) => ({ label: c.label, amount_usd: money2(fixedSetup * c.share) })),
    stabilized_monthly_revenue_usd: money2(stabilizedRevenue),
    year1_monthly: year1Monthly,
    year1_totals: year1Totals,
    years,
    balance_sheet,
    sources_and_uses,
    break_even,
    ...cashFlow,
    income_tax_rate: INCOME_TAX_RATE,
    assumptions: [
      `Revenue is modeled from the business's own cost structure (a ${Math.round(TARGET_OPERATING_MARGIN * 100)}% target operating margin over modeled costs at steady state), rather than from a price-times-volume sales forecast. Treat monthly revenue as a sizing target, not a market forecast.`,
      `Cost of goods sold is assumed at ${Math.round(cogsRatio * 100)}% of revenue, typical for a business of this kind.`,
      // Says which baseline the growth applies to, because the two are very different numbers
      // and the reader can see both. Year 1 is a ramp from zero, so Year 2 is grown from the
      // annualized steady-state rate rather than from Year 1's part-year actual: on the sample
      // cafe that makes the Year 1 to Year 2 step +174% while the growth assumption is 18%. A
      // lender comparing those two figures against a flat claim of "18% annual growth" has found
      // an inconsistency, and it was the sentence that was wrong, not the model.
      `Monthly operating expenses hold flat at the modeled rate through Year 1. Year 1 is a ramp — revenue builds from zero toward the modeled steady-state rate — so Year 2 is that steady-state rate annualized and grown ${Math.round(ANNUAL_GROWTH_RATE * 100)}%, and Year 3 grows ${Math.round(ANNUAL_GROWTH_RATE * 100)}% again on Year 2. The step from Year 1 to Year 2 is therefore the ramp completing rather than a growth assumption. Operating expenses scale at ${Math.round(OPEX_SCALE_WITH_REVENUE * 100)}% of the revenue growth rate.`,
      `Operating expense and launch-cost categories (rent, payroll taxes, utilities, supplies, insurance, equipment, and the rest) are an indicative split of the modeled totals by typical share for this kind of business, not itemized receipts — replace with real quotes and vendor estimates as they come in.`,
      `Net income assumes a flat ${Math.round(INCOME_TAX_RATE * 100)}% estimated income tax on positive operating income (0% on a loss) — a rough planning placeholder, not a real tax calculation. Actual liability depends on entity structure (sole proprietorship, LLC, S-corp, C-corp), state, deductions, and credits; confirm with an accountant. Figures still exclude interest expense, which depends on actual loan terms.`,
      'Monthly estimated income tax accrues against cumulative year-to-date operating income rather than each month in isolation, so an early loss month shows no tax and a later month can show a catch-up once the year turns cumulatively profitable — the Year 1 total is the actual tax on the full year, not a sum of twelve separately-taxed months.',
      'Cash flow assumes cash-basis collection with no accounts-receivable lag. Estimated income tax is subtracted in the month it accrues, so the cash statement reconciles with the profit-and-loss statement above rather than overstating the cash left at year end. A real business pays estimated tax quarterly and may invoice on terms, so cash within the year will sit differently than modeled even where the annual totals agree.',
    ],
  };
}

/**
 * Builds a revision projection for an EXISTING business updating its plan — anchored to the
 * founder's disclosed current numbers rather than a cost-derived launch model. Reuses the same
 * P&L/tax/cash-flow math as buildFinancialProjections; only the revenue/opex trajectory differs.
 *
 * @param {{
 *   profile: string,
 *   current_financial_position: { monthly_revenue_usd: number, monthly_costs_usd: number, cash_on_hand_usd?: number|null, target_monthly_revenue_usd?: number|null, target_monthly_costs_usd?: number|null },
 *   update_goal?: string,
 * }} input
 */
function buildRevisionProjections(input) {
  const profile = PROFILE_COGS_RATIO[input.profile] != null ? input.profile : 'lean_service';
  const cogsRatio = PROFILE_COGS_RATIO[profile];
  const opexSplit = PROFILE_OPEX_SPLIT[profile];
  const pos = input.current_financial_position;
  const goal = ['grow', 'stabilize', 'shrink', 'survive'].includes(input.update_goal)
    ? input.update_goal
    : 'stabilize';
  const currentRevenue = pos.monthly_revenue_usd;
  const currentOpex = pos.monthly_costs_usd;
  const cashOnHand = pos.cash_on_hand_usd != null ? pos.cash_on_hand_usd : null;
  const hasTarget = pos.target_monthly_revenue_usd != null || pos.target_monthly_costs_usd != null;

  // Revenue/opex trajectory across the 12 modeled months:
  //  - A founder-given target ramps linearly from the current number to that target by month 12.
  //  - Absent a target, 'grow' compounds at the same conservative annual growth rate used for
  //    Years 2-3 elsewhere in this file, scaling opex at the same fraction of that rate.
  //  - Absent a target, 'stabilize', 'survive', and 'shrink' hold flat at the current numbers.
  //    The point of 'survive' is to show whether *today's* numbers, continued, run out of cash —
  //    not to guess a contraction or rebound magnitude the founder never stated.
  const monthlyGrowthRate = Math.pow(1 + ANNUAL_GROWTH_RATE, 1 / 12) - 1;
  const monthlyOpexGrowthRate = monthlyGrowthRate * OPEX_SCALE_WITH_REVENUE;
  const revenueSeries = [];
  const opexSeries = [];
  for (let i = 0; i < 12; i++) {
    const t = i / 11;
    if (pos.target_monthly_revenue_usd != null) {
      revenueSeries.push(currentRevenue + (pos.target_monthly_revenue_usd - currentRevenue) * t);
    } else if (goal === 'grow') {
      revenueSeries.push(currentRevenue * Math.pow(1 + monthlyGrowthRate, i));
    } else {
      revenueSeries.push(currentRevenue);
    }
    if (pos.target_monthly_costs_usd != null) {
      opexSeries.push(currentOpex + (pos.target_monthly_costs_usd - currentOpex) * t);
    } else if (goal === 'grow') {
      opexSeries.push(currentOpex * Math.pow(1 + monthlyOpexGrowthRate, i));
    } else {
      opexSeries.push(currentOpex);
    }
  }

  const year1Monthly = buildYear1Monthly(revenueSeries, opexSeries, cogsRatio);
  const year1Totals = buildYear1Totals(year1Monthly);
  const years = buildYears2And3(year1Monthly, year1Totals, cogsRatio);
  const cashFlow = buildYear1CashFlow(year1Monthly, cashOnHand ?? 0);

  const contributionMarginRatio = 1 - cogsRatio;
  const breakEvenMonthlyRevenue = money2(currentOpex / contributionMarginRatio);
  const breakEvenMonthIndex = year1Monthly.findIndex((m) => m.revenue_usd >= breakEvenMonthlyRevenue);
  const break_even = {
    fixed_costs_monthly_usd: money2(currentOpex),
    contribution_margin_ratio: Math.round(contributionMarginRatio * 1000) / 1000,
    break_even_monthly_revenue_usd: breakEvenMonthlyRevenue,
    break_even_month: breakEvenMonthIndex === -1 ? null : breakEvenMonthIndex + 1,
  };

  const current_position = {
    cash_on_hand_usd: cashOnHand,
    monthly_revenue_usd: money2(currentRevenue),
    monthly_costs_usd: money2(currentOpex),
    goal,
  };

  return {
    profile,
    mode: 'revision',
    update_goal: goal,
    cogs_ratio: cogsRatio,
    opex_categories: opexSplit.map((c) => ({ label: c.label, monthly_usd: money2(currentOpex * c.share) })),
    fixed_setup_categories: [],
    stabilized_monthly_revenue_usd: money2(currentRevenue),
    year1_monthly: year1Monthly,
    year1_totals: year1Totals,
    years,
    current_position,
    break_even,
    ...cashFlow,
    income_tax_rate: INCOME_TAX_RATE,
    assumptions: [
      `This plan updates a ${profile.replace(/_/g, ' ')} business from its disclosed current position — about ${proseMoney(currentRevenue)}/month in revenue and ${proseMoney(currentOpex)}/month in operating costs — not a from-scratch model.`,
      hasTarget
        ? 'Monthly revenue and/or costs ramp in a straight line from the current disclosed figure toward the target in this plan, reaching it by month 12.'
        : goal === 'grow'
          ? `No specific growth target was given, so revenue is modeled at the same conservative ${Math.round(ANNUAL_GROWTH_RATE * 100)}% annual growth rate used throughout these projections, with operating costs scaling at ${Math.round(OPEX_SCALE_WITH_REVENUE * 100)}% of that rate; it is a planning rate rather than a specific growth target.`
          : 'Current revenue and operating costs are held flat across the modeled year; no contraction or rebound is assumed.',
      `Cost of goods sold is assumed at ${Math.round(cogsRatio * 100)}% of revenue, typical for a ${profile.replace(/_/g, ' ')} business, applied to the business's reported revenue.`,
      'Operating-cost categories are an indicative split of the disclosed monthly total by typical share for this kind of business, not itemized receipts.',
      `Net income assumes a flat ${Math.round(INCOME_TAX_RATE * 100)}% estimated income tax on positive operating income (0% on a loss) — a rough planning placeholder; confirm with an accountant. Monthly tax accrues against cumulative year-to-date income, the same as the from-scratch model.`,
      cashOnHand == null
        ? 'Cash on hand was not disclosed, so the cash-flow projection below starts from $0 — treat the modeled cash position as understated until real cash on hand is added.'
        : 'Cash flow starts from the disclosed cash on hand.',
      // Unconditional on purpose. This used to sit in the disclosed-cash branch above, so a
      // founder who left cash on hand blank lost the disclosure entirely.
      'Cash flow assumes cash-basis collection with no accounts-receivable lag. Estimated income tax is subtracted in the month it accrues, so the cash statement reconciles with the profit-and-loss statement above; a real business pays estimated tax quarterly, so cash within the year will sit differently than modeled even where the annual totals agree.',
      'This is a revision, not a launch plan: no one-time setup or equipment cost is modeled here, and there is no opening balance sheet or sources-and-uses statement — see Current Financial Position instead.',
    ],
  };
}

/**
 * Which wage figures the cost model will use for a place: the metro's own rows, the state's, or
 * the national medians. The same order lookupMedianWage follows, read from the table's coverage,
 * so the Instant Build location line tells the founder the truth before the plan is built.
 */
function wageAreaForPlace(place = {}) {
  if (place.cbsa_code && WAGE_AREAS[`CBSA:${place.cbsa_code}`]) {
    return { level: 'metro', area_name: WAGE_AREAS[`CBSA:${place.cbsa_code}`].name };
  }
  if (place.state_code && WAGE_AREAS[`ST:${place.state_code}`]) {
    return { level: 'state', area_name: WAGE_AREAS[`ST:${place.state_code}`].name };
  }
  return { level: 'national', area_name: WAGE_AREAS.US.name };
}


const FinanceEngine = { normalizeRevenueBuildup, buildRevenueModel, proseMoney, wageAreaForPlace, BAND_TO_USD, DSCR_REFERENCE_MINIMUM, DEBT_SERVICE_SCENARIOS, monthlyLoanPayment, buildDebtServiceAnalysis, REALISM_POSTURE, PROFILE_COGS_RATIO, normalizePersonalCapital, profileBusiness, estimateLaunchFinance, assessFundingRealism, suggestGapOptions, suggestBusinessImprovements, buildFinancialProjections, buildRevisionProjections, buildProjectedPosition, buildRevenueSensitivity, SENSITIVITY_REVENUE_FACTORS, STAGE_RAMP, buildAmortizationSchedule, resolveLoanTerms, parseFounderLoanTerms };
const LenderPackage = { PERSONAL_FINANCIAL_STATEMENT, COLLATERAL_COLUMNS, buildLenderPackage };
/**
 * Company Build Instant intake + optional document import.
 *
 * Nine Instant prompts: the eight required responses plus "When do you want to open?", which is
 * preselected ("In about 3 months") and falls back to three months after the plan date when
 * skipped, so it never blocks a build. Document upload is optional for Instant and Guided — not an
 * Instant question.
 */

const FORBIDDEN_ASSUMPTION_PATHS = Object.freeze([
  'revenue_actuals',
  'customer_counts',
  'traction',
  'patents',
  'licenses',
  'legal_registration_status',
  'certifications',
  'grant_awards',
  'investor_interest',
  'regulatory_approval',
  'protected_eligibility_traits',
]);

const ALLOWED_ASSUMPTION_PATHS = Object.freeze([
  'audience_positioning_hypothesis',
  'indicative_pricing_range',
  'startup_expense_model',
  'entity_type_recommendation_options',
  'brand_voice_and_pillars',
  'competitive_alternatives_framing',
  'gtm_channel_hypotheses',
  'naics_candidate',
]);

const REQUIRED_INSTANT_FIELDS = Object.freeze([
  'business_description',
  'stage',
  'location',
  'customer',
  'revenue_model',
  'personal_capital',
  'outside_money',
  'brand_preference',
]);

const HIGH_IMPACT_GRAPH_PREFIXES = Object.freeze([
  'company_identity.legal',
  'company_identity.formation',
  'ownership.',
  'finance.actuals',
  'revenue_sales.actuals',
  'licenses.',
  'contracts.',
  'capital.awarded',
  'capital.raised',
]);

/** The ninth Instant question's choices. "In about 3 months" is preselected. */
const OPENING_CHOICES = Object.freeze(['about_3_months', 'asap', 'date']);
const DEFAULT_OPENING_MONTHS = 3;

/** 'YYYY-MM-DD' → [y, m, d], or null. Calendar arithmetic stays on the date the founder sees. */
function ymd(text) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(text || '').trim());
  if (!m) return null;
  const [y, mo, d] = [Number(m[1]), Number(m[2]), Number(m[3])];
  if (mo < 1 || mo > 12 || d < 1 || d > 31) return null;
  const probe = new Date(Date.UTC(y, mo - 1, d));
  if (probe.getUTCMonth() !== mo - 1) return null;
  return [y, mo, d];
}

const pad2 = (n) => String(n).padStart(2, '0');
const isoOf = ([y, m, d]) => `${y}-${pad2(m)}-${pad2(d)}`;

function addMonths([y, m, d], months) {
  const total = y * 12 + (m - 1) + months;
  const ny = Math.floor(total / 12);
  const nm = (total % 12) + 1;
  const last = new Date(Date.UTC(ny, nm, 0)).getUTCDate();
  return [ny, nm, Math.min(d, last)];
}

/**
 * The opening date, from the ninth Instant question (or the Guided Interview's).
 *
 *   about_3_months (preselected) → three months after the plan date
 *   asap                         → the plan date
 *   date                         → the date picked (never before the plan date)
 *   skipped / anything else      → three months after the plan date, marked as the default
 *
 * `model_month` is the month of the financial model the opening falls in, counting the plan
 * date's month as month 1, so the projections and the timeline carry real calendar dates.
 *
 * @param {{ choice?: string|null, date?: string|null }} answer
 * @param {string|Date} [planDate] defaults to today
 */
function resolveOpening(answer = {}, planDate) {
  const planIso = planDate instanceof Date ? planDate.toISOString().slice(0, 10) : String(planDate || new Date().toISOString().slice(0, 10)).slice(0, 10);
  const plan = ymd(planIso) || ymd(new Date().toISOString().slice(0, 10));
  const requested = OPENING_CHOICES.includes(answer && answer.choice) ? answer.choice : null;
  let choice = requested;
  let target;
  let note = null;
  if (requested === 'asap') target = plan;
  else if (requested === 'date') {
    const picked = ymd(answer.date);
    if (!picked) {
      choice = 'about_3_months';
      target = addMonths(plan, DEFAULT_OPENING_MONTHS);
      note = 'no_date_picked';
    } else if (isoOf(picked) < isoOf(plan)) {
      target = plan;
      note = 'date_before_plan_date';
    } else target = picked;
  } else {
    choice = 'about_3_months';
    target = addMonths(plan, DEFAULT_OPENING_MONTHS);
  }
  const modelMonth = (target[0] - plan[0]) * 12 + (target[1] - plan[1]) + 1;
  return {
    choice,
    date: isoOf(target),
    plan_date: isoOf(plan),
    model_month: Math.max(1, modelMonth),
    source: requested && !note ? 'founder' : 'default',
    ...(note ? { note } : {}),
  };
}

const DOCUMENT_IMPORT_PROMPT =
  'Do you already have documents, files, notes, or other information about this business? Upload anything you want Company Build to use so you don’t have to enter the same information again.';

function asTrimmedString(value) {
  return typeof value === 'string' ? value.trim() : '';
}

function isExistingOrLaunched(stage) {
  return stage === 'launched' || stage === 'existing';
}

/**
 * Optional import step for Instant or Guided.
 * @param {{ stage?: string, workspace_kind?: string }} [ctx]
 */
function documentImportStep(ctx = {}) {
  const prominent =
    isExistingOrLaunched(ctx.stage) || ctx.workspace_kind === 'existing_company';
  return {
    id: 'upload_what_you_already_have',
    required: false,
    is_instant_core_question: false,
    available_in: ['instant_build', 'guided_build'],
    prompt_variant: prominent ? 'prominent_existing_company' : 'standard',
    prompt_copy: DOCUMENT_IMPORT_PROMPT,
    prominence: prominent ? 'high' : 'normal',
  };
}

/**
 * @param {Record<string, unknown>} input
 */
function validateInstantIntake(input) {
  const errors = [];
  const warnings = [];

  if (!input || typeof input !== 'object' || Array.isArray(input)) {
    return { ok: false, errors: ['intake must be an object'], warnings };
  }

  for (const field of REQUIRED_INSTANT_FIELDS) {
    if (!(field in input) || input[field] == null || input[field] === '') {
      errors.push(`Missing required Instant response: ${field}`);
    }
  }

  const business = asTrimmedString(input.business_description);
  if (business && business.length < 8) {
    errors.push('business_description must be at least 8 characters');
  }

  const customer = asTrimmedString(input.customer);
  if (customer && customer.length < 3) {
    errors.push('customer must be at least 3 characters');
  }

  const stages = new Set(['idea', 'pre_launch', 'launched', 'existing']);
  if (input.stage != null && !stages.has(input.stage)) {
    errors.push(`Invalid stage: ${String(input.stage)}`);
  }

  const location = input.location;
  if (location && typeof location === 'object') {
    if (!['provided', 'not_decided'].includes(location.status)) {
      errors.push('location.status must be provided or not_decided');
    }
    if (location.status === 'provided') {
      if (location.mode === 'us_zip') {
        if (!/^[0-9]{5}$/.test(asTrimmedString(location.zip))) {
          errors.push('US location requires a 5-digit ZIP');
        }
      } else if (location.mode === 'us_place') {
        if (!/^[A-Z]{2}$/.test(asTrimmedString(location.state_code))) {
          errors.push('US place requires a 2-letter state code');
        }
      } else if (location.mode === 'non_us') {
        if (asTrimmedString(location.country_code).length !== 2) {
          errors.push('non_us location requires country_code');
        }
        if (!asTrimmedString(location.locality)) {
          errors.push('non_us location requires locality');
        }
      } else {
        errors.push('location.mode must be us_zip, us_place or non_us when status=provided');
      }
    }
    if (location.status === 'not_decided') {
      warnings.push(
        'Jurisdiction-final legal drafts blocked until location is decided',
      );
    }
  }

  const revenue = input.revenue_model;
  if (revenue && typeof revenue === 'object') {
    if (!['known', 'unknown'].includes(revenue.status)) {
      errors.push('revenue_model.status must be known or unknown');
    }
    if (
      revenue.status === 'known' &&
      !(Array.isArray(revenue.channels) && revenue.channels.length)
    ) {
      errors.push('revenue_model.channels required when status=known');
    }
  }

  const capital = input.personal_capital;
  if (capital && typeof capital === 'object') {
    const allowed = new Set(['amount', 'band', 'zero', 'unknown', 'prefer_not']);
    if (!allowed.has(capital.disclosure)) {
      errors.push('personal_capital.disclosure is invalid');
    }
    if (
      capital.disclosure === 'amount' &&
      !(typeof capital.amount_usd === 'number' && capital.amount_usd >= 0)
    ) {
      errors.push('personal_capital.amount_usd required when disclosure=amount');
    }
    if (capital.disclosure === 'band' && !capital.band) {
      errors.push('personal_capital.band required when disclosure=band');
    }
  }

  const outside = input.outside_money;
  if (outside && typeof outside === 'object') {
    if (!['none', 'yes', 'unsure'].includes(outside.intent)) {
      errors.push('outside_money.intent must be none, yes, or unsure');
    }
    if (
      outside.intent === 'yes' &&
      !(Array.isArray(outside.types) && outside.types.length)
    ) {
      errors.push('outside_money.types required when intent=yes');
    }
  }

  const brands = new Set(['new', 'import', 'defer']);
  if (input.brand_preference != null && !brands.has(input.brand_preference)) {
    errors.push('brand_preference must be new, import, or defer');
  }

  if (isExistingOrLaunched(input.stage)) {
    const deepen = input.existing_company_deepen;
    if (!deepen || typeof deepen !== 'object') {
      errors.push(
        'launched/existing Instant requires existing_company_deepen (name + already_formed); do not force Guided',
      );
    } else {
      if (!asTrimmedString(deepen.legal_or_public_name)) {
        errors.push('existing_company_deepen.legal_or_public_name is required');
      }
      if (!['yes', 'no', 'unknown'].includes(deepen.already_formed)) {
        errors.push('already_formed must be yes, no, or unknown — never assumed');
      }
      if (deepen.already_formed === 'yes') {
        if (!deepen.entity_type) {
          errors.push('entity_type required when already_formed=yes before legal outputs');
        }
        if (!asTrimmedString(deepen.formation_jurisdiction)) {
          errors.push(
            'formation_jurisdiction required when already_formed=yes before jurisdiction-specific outputs',
          );
        }
      }
      if (deepen.already_formed === 'unknown') {
        warnings.push(
          'Formation status unknown — legal registration finals blocked until confirmed',
        );
      }
      if (deepen.current_financial_position != null) {
        const pos = /** @type {Record<string, unknown>} */ (deepen.current_financial_position);
        if (typeof pos !== 'object') {
          errors.push('current_financial_position must be an object');
        } else {
          for (const key of ['monthly_revenue_usd', 'monthly_costs_usd']) {
            if (typeof pos[key] !== 'number' || !Number.isFinite(pos[key]) || pos[key] < 0) {
              errors.push(`current_financial_position.${key} is required and must be a non-negative number`);
            }
          }
          for (const key of ['cash_on_hand_usd', 'target_monthly_revenue_usd', 'target_monthly_costs_usd']) {
            if (pos[key] != null && (typeof pos[key] !== 'number' || !Number.isFinite(pos[key]) || pos[key] < 0)) {
              errors.push(`current_financial_position.${key} must be a non-negative number when provided`);
            }
          }
        }
      }
      if (
        deepen.update_goal != null &&
        !['grow', 'stabilize', 'shrink', 'survive'].includes(deepen.update_goal)
      ) {
        errors.push('update_goal must be grow, stabilize, shrink, or survive');
      }
    }
  }

  // Optional micro interview — validate shape only when present; never required.
  if (input.interview_deepen != null) {
    const deepen = input.interview_deepen;
    if (typeof deepen !== 'object' || Array.isArray(deepen)) {
      errors.push('interview_deepen must be an object when provided');
    } else {
      const fundingAllowed = new Set([
        'grants',
        'loans',
        'incubators',
        'equity',
        'skip_for_now',
      ]);
      if (deepen.funding_path_interest != null) {
        if (!Array.isArray(deepen.funding_path_interest)) {
          errors.push('interview_deepen.funding_path_interest must be an array');
        } else {
          for (const p of deepen.funding_path_interest) {
            if (!fundingAllowed.has(p)) {
              errors.push(`Unknown funding_path_interest: ${String(p)}`);
            }
          }
        }
      }
      const docAllowed = new Set([
        'pitch_one_pager',
        'grant_readiness',
        'incubator_notes',
        'lender_checklist',
        'operations_playbook',
        'competitive_snapshot',
      ]);
      if (deepen.document_extras != null) {
        if (!Array.isArray(deepen.document_extras)) {
          errors.push('interview_deepen.document_extras must be an array');
        } else {
          for (const d of deepen.document_extras) {
            if (!docAllowed.has(d)) {
              errors.push(`Unknown document_extras id: ${String(d)}`);
            }
          }
        }
      }
    }
  }

  return { ok: errors.length === 0, errors, warnings };
}

function isForbiddenAssumption(pathName) {
  return FORBIDDEN_ASSUMPTION_PATHS.includes(pathName);
}

function isAllowedAssumption(pathName) {
  return ALLOWED_ASSUMPTION_PATHS.includes(pathName);
}

/**
 * @param {{ path: string, proposed_value: unknown, rationale_summary: string, source_ids?: string[] }} proposal
 */
function proposeAssumption(proposal) {
  if (!proposal || typeof proposal.path !== 'string') {
    return { ok: false, error: 'assumption path required' };
  }
  if (isForbiddenAssumption(proposal.path)) {
    return { ok: false, error: `Forbidden Instant assumption: ${proposal.path}` };
  }
  if (!isAllowedAssumption(proposal.path)) {
    return { ok: false, error: `Assumption path not on allow-list: ${proposal.path}` };
  }
  return {
    ok: true,
    assumption: {
      path: proposal.path,
      proposed_value: proposal.proposed_value,
      rationale_summary: proposal.rationale_summary,
      source_ids: proposal.source_ids || [],
      status: 'PROPOSED',
      created_at: new Date().toISOString(),
    },
  };
}

/**
 * @param {Array<Record<string, unknown>>} files
 */
function validateUploadedFiles(files) {
  const errors = [];
  if (!Array.isArray(files)) {
    return { ok: false, errors: ['files must be an array'] };
  }
  files.forEach((file, i) => {
    if (!file || typeof file !== 'object') {
      errors.push(`files[${i}] must be an object`);
      return;
    }
    for (const key of ['file_id', 'original_filename', 'mime_type', 'local_uri', 'sha256']) {
      if (!asTrimmedString(file[key])) errors.push(`files[${i}].${key} required`);
    }
    if (file.preserved_original !== true) {
      errors.push(`files[${i}].preserved_original must be true — originals stay untouched`);
    }
    if (typeof file.byte_size !== 'number' || file.byte_size < 0) {
      errors.push(`files[${i}].byte_size must be >= 0`);
    }
  });
  return { ok: errors.length === 0, errors };
}

/**
 * Classify import candidates. Never marks founder_confirmed.
 * @param {Array<Record<string, unknown>>} candidates
 */
function analyzeDocumentImport(candidates) {
  if (!Array.isArray(candidates)) {
    return { ok: false, error: 'candidates must be an array' };
  }

  let canPrefill = 0;
  let needsConfirmation = 0;
  let conflicts = 0;
  /** @type {Array<Record<string, unknown>>} */
  const normalized = [];

  for (let index = 0; index < candidates.length; index += 1) {
    const raw = candidates[index];
    const graphPath = asTrimmedString(raw.graph_path);
    const provenance =
      raw.provenance && typeof raw.provenance === 'object' ? raw.provenance : null;
    if (
      !provenance ||
      !asTrimmedString(provenance.file_id) ||
      !asTrimmedString(provenance.location_label)
    ) {
      return {
        ok: false,
        error: `candidate[${index}] missing provenance.file_id/location_label`,
      };
    }

    const highImpact =
      raw.impact === 'high' ||
      HIGH_IMPACT_GRAPH_PREFIXES.some((prefix) => graphPath.startsWith(prefix));

    let status = raw.status;
    if (Array.isArray(raw.conflict_with_candidate_ids) && raw.conflict_with_candidate_ids.length) {
      status = 'CONFLICT';
    } else if (highImpact) {
      status = 'NEEDS_CONFIRMATION';
    } else if (!status) {
      status = 'PREFILL';
    }

    if (status === 'CONFLICT') conflicts += 1;
    else if (status === 'NEEDS_CONFIRMATION') needsConfirmation += 1;
    else if (status === 'PREFILL') canPrefill += 1;

    normalized.push({
      candidate_id: raw.candidate_id || `cand_${index + 1}`,
      graph_path: graphPath,
      proposed_value: raw.proposed_value,
      status,
      impact: highImpact ? 'high' : 'low',
      provenance: {
        file_id: String(provenance.file_id),
        location_label: String(provenance.location_label),
        excerpt: provenance.excerpt ? String(provenance.excerpt) : undefined,
      },
      conflict_with_candidate_ids: raw.conflict_with_candidate_ids || [],
      founder_confirmed: false,
    });
  }

  const total = normalized.length;
  return {
    ok: true,
    summary: {
      total_candidates: total,
      can_prefill: canPrefill,
      needs_confirmation: needsConfirmation,
      conflicts,
      message: `We found ${total} possible facts in your files. ${canPrefill} can prefill your build, ${needsConfirmation} need your confirmation, and ${conflicts} conflict with another source.`,
    },
    candidates: normalized,
  };
}

/**
 * @param {Record<string, unknown>} input
 * @param {{ confirmed_import_facts?: Array<{ graph_path: string, value: unknown, provenance: object }> }} [opts]
 */
function seedCompanyGraphFromIntake(input, opts = {}) {
  const validation = validateInstantIntake(input);
  if (!validation.ok) {
    return { ok: false, errors: validation.errors, warnings: validation.warnings };
  }

  /** @type {Array<{ path: string, value: unknown, origin_type: string, founder_confirmed: boolean, provenance?: object }>} */
  const facts = [];

  facts.push({
    path: 'offer_catalog.description',
    value: asTrimmedString(input.business_description),
    origin_type: 'FOUNDER',
    founder_confirmed: true,
  });
  facts.push({
    path: 'company_identity.stage',
    value: input.stage,
    origin_type: 'FOUNDER',
    founder_confirmed: true,
  });
  facts.push({
    path: 'company_identity.operating_locations',
    value: input.location,
    origin_type: 'FOUNDER',
    founder_confirmed: true,
  });
  facts.push({
    path: 'customers_market.customer',
    value: asTrimmedString(input.customer),
    origin_type: 'FOUNDER',
    founder_confirmed: true,
  });
  facts.push({
    path: 'revenue_sales.revenue_streams',
    value: input.revenue_model,
    origin_type: 'FOUNDER',
    founder_confirmed: true,
  });
  facts.push({
    path: 'finance.founder_investment',
    value: input.personal_capital,
    origin_type: 'FOUNDER',
    founder_confirmed: true,
  });
  facts.push({
    path: 'capital.outside_money',
    value: input.outside_money,
    origin_type: 'FOUNDER',
    founder_confirmed: true,
  });
  facts.push({
    path: 'brand.preference',
    value: input.brand_preference,
    origin_type: 'FOUNDER',
    founder_confirmed: true,
  });

  if (input.existing_company_deepen) {
    const deepen = /** @type {Record<string, unknown>} */ (input.existing_company_deepen);
    facts.push({
      path: 'company_identity.legal_or_public_name',
      value: deepen.legal_or_public_name,
      origin_type: 'FOUNDER',
      founder_confirmed: true,
    });
    facts.push({
      path: 'company_identity.formation.already_formed',
      value: deepen.already_formed,
      origin_type: 'FOUNDER',
      founder_confirmed: true,
    });
    if (deepen.already_formed === 'yes') {
      facts.push({
        path: 'company_identity.formation.entity_type',
        value: deepen.entity_type,
        origin_type: 'FOUNDER',
        founder_confirmed: true,
      });
      facts.push({
        path: 'company_identity.formation.jurisdiction',
        value: deepen.formation_jurisdiction,
        origin_type: 'FOUNDER',
        founder_confirmed: true,
      });
    }
    if (deepen.current_financial_position && typeof deepen.current_financial_position === 'object') {
      facts.push({
        path: 'finance.actuals.current_financial_position',
        value: deepen.current_financial_position,
        origin_type: 'FOUNDER',
        founder_confirmed: true,
      });
    }
    if (deepen.update_goal) {
      facts.push({
        path: 'finance.actuals.update_goal',
        value: deepen.update_goal,
        origin_type: 'FOUNDER',
        founder_confirmed: true,
      });
    }
  }

  if (input.interview_deepen && typeof input.interview_deepen === 'object') {
    const micro = /** @type {Record<string, unknown>} */ (input.interview_deepen);
    if (Array.isArray(micro.funding_path_interest) && micro.funding_path_interest.length) {
      facts.push({
        path: 'capital.funding_path_prefs',
        value: micro.funding_path_interest,
        origin_type: 'FOUNDER',
        founder_confirmed: true,
      });
    }
    if (Array.isArray(micro.document_extras) && micro.document_extras.length) {
      facts.push({
        path: 'documents.optional_picks',
        value: micro.document_extras,
        origin_type: 'FOUNDER',
        founder_confirmed: true,
      });
    }
    if (micro.financial && typeof micro.financial === 'object') {
      facts.push({
        path: 'finance.interview_micro',
        value: micro.financial,
        origin_type: 'FOUNDER',
        founder_confirmed: true,
      });
    }
    if (micro.operational && typeof micro.operational === 'object') {
      facts.push({
        path: 'operations.interview_micro',
        value: micro.operational,
        origin_type: 'FOUNDER',
        founder_confirmed: true,
      });
    }
    if (micro.strategic && typeof micro.strategic === 'object') {
      facts.push({
        path: 'strategy.interview_micro',
        value: micro.strategic,
        origin_type: 'FOUNDER',
        founder_confirmed: true,
      });
    }
  }

  for (const imported of opts.confirmed_import_facts || []) {
    facts.push({
      path: imported.graph_path,
      value: imported.value,
      origin_type: 'IMPORT_CONFIRMED',
      founder_confirmed: true,
      provenance: imported.provenance,
    });
  }

  const blockedOutputs = [];
  if (input.location && /** @type {any} */ (input.location).status === 'not_decided') {
    blockedOutputs.push({
      output: 'jurisdiction_final_legal_drafts',
      reason: 'formation/operating location not decided',
    });
  }
  if (
    isExistingOrLaunched(/** @type {string} */ (input.stage)) &&
    input.existing_company_deepen &&
    /** @type {any} */ (input.existing_company_deepen).already_formed !== 'yes'
  ) {
    blockedOutputs.push({
      output: 'legal_registration_finals',
      reason: 'legal registration status not confirmed as formed',
    });
  }

  return {
    ok: true,
    errors: [],
    warnings: validation.warnings,
    facts,
    blockedOutputs,
    assumptionReviewRequired: true,
    financeNote:
      'personal_capital is founder investment only; launch cost / funding gap computed by finance engine separately',
  };
}


