/** City/state overlays for known hard windows (illustrative, conservative). */
const JURISDICTION_OVERLAYS = Object.freeze({
  'US-MA-Boston': {
    label: 'Boston, MA overlay',
    notes: [
      'Boston local licenses and inspections can involve neighborhood / board calendars.',
      'Some regulated licenses (including alcohol) historically use limited application windows — missing one can mean waiting for the next posted cycle.',
      'Plan as if inspection and hearing slots are scarce; build calendar buffer before lease commencement.',
    ],
    amplifies: ['local_business_license', 'food_service_permit', 'alcohol_license'],
    timing_multiplier: 1.25,
  },
  'US-MA': {
    label: 'Massachusetts overlay',
    notes: [
      'State professional boards and ABC processes may add hearing calendars on top of municipal steps.',
    ],
    amplifies: ['alcohol_license', 'professional_license_screen'],
    timing_multiplier: 1.1,
  },
  'US-NY-New York': {
    label: 'New York City overlay',
    notes: [
      'Agency queues and appointment systems create de-facto cycles even when filings are “rolling.”',
    ],
    amplifies: ['local_business_license', 'food_service_permit'],
    timing_multiplier: 1.3,
  },
  'US-CA': {
    label: 'California overlay',
    notes: [
      'Seller’s permit / local business tax registration are usually rolling; industry licenses still dominate timeline.',
    ],
    amplifies: [],
    timing_multiplier: 1.05,
  },
});

/**
 * @param {string} businessDescription
 * @param {string[]} [extraTriggers]
 */
function detectTriggers(businessDescription, extraTriggers = []) {
  const text = String(businessDescription || '').toLowerCase();
  const triggers = new Set(['any_business', ...extraTriggers]);
  // A software product that serves an industry is not in that industry. "Subscription software
  // that automates reconciliation for independent restaurant groups" was screened for a food
  // service permit, a certificate of occupancy and — had it said "wine bars" — an alcohol
  // license, and the Business Plan listed all of them under Operations. The customer's industry
  // is named in the description; the business's own premises are not. A software business that
  // also runs a physical site says so ("our kitchen", "a storefront"), and keeps those screens.
  const softwareOnly =
    /\b(software|saas|platform|app|api)\b/.test(text) &&
    !/\b(our|we run|we operate|operates an?|runs an?)\s+(own\s+)?(kitchen|cafe|restaurant|bar|storefront|shop|studio|clinic|warehouse)\b/.test(text);
  if (softwareOnly) {
    triggers.add('needs_formation');
    return [...triggers];
  }
  for (const track of LICENSE_TRACKS) {
    for (const t of track.triggers) {
      if (t === 'any_business' || t === 'needs_formation') continue;
      // A short trigger must be a whole word: "bar" inside "barbecue" or "barber" put an alcohol
      // license (and a closed filing window) into a barbecue food truck's Business Plan.
      if (t.length <= 3 ? new RegExp(`\\b${t}s?\\b`).test(text) : text.includes(t)) triggers.add(t);
    }
  }
  if (/(storefront|studio|shop|clinic|restaurant|cafe|warehouse|office lease)/.test(text)) {
    triggers.add('physical_presence');
    triggers.add('storefront');
  }
  if (/(restaurant|cafe|bakery|food truck|kitchen)/.test(text)) {
    triggers.add('food');
    triggers.add('restaurant');
  }
  triggers.add('needs_formation');
  return [...triggers];
}

/**
 * @param {{ state_code?: string, primary_city?: string } | null | undefined} location
 */
function resolveOverlays(location) {
  /** @type {Array<typeof JURISDICTION_OVERLAYS[string] & { key: string }>} */
  const hits = [];
  if (!location || !location.state_code) return hits;
  const stateKey = `US-${location.state_code}`;
  if (JURISDICTION_OVERLAYS[stateKey]) {
    hits.push({ key: stateKey, ...JURISDICTION_OVERLAYS[stateKey] });
  }
  if (location.primary_city) {
    const cityKey = `US-${location.state_code}-${location.primary_city}`;
    // try exact and loose contains for Boston
    for (const [key, overlay] of Object.entries(JURISDICTION_OVERLAYS)) {
      if (key === cityKey) hits.push({ key, ...overlay });
      else if (
        key.startsWith(stateKey + '-') &&
        location.primary_city.toLowerCase().includes(key.split('-').slice(2).join('-').toLowerCase())
      ) {
        hits.push({ key, ...overlay });
      }
    }
  }
  // dedupe by key
  const seen = new Set();
  return hits.filter((h) => (seen.has(h.key) ? false : (seen.add(h.key), true)));
}

/**
 * @param {LicenseTrack} track
 * @param {ReturnType<typeof resolveOverlays>} overlays
 */
function applyOverlays(track, overlays) {
  let mult = 1;
  const notes = [...track.caveats];
  let cycle = { ...track.cycle };
  for (const overlay of overlays) {
    if (overlay.amplifies.includes(track.id)) {
      mult *= overlay.timing_multiplier || 1;
      notes.push(...overlay.notes);
      if (track.difficulty === 'very_high' || track.difficulty === 'high') {
        // Conservative: treat scarce regulated windows as closed-until-confirmed
        if (cycle.status === 'unknown' || cycle.status === 'open' || track.id === 'alcohol_license') {
          const isAlcohol = track.id === 'alcohol_license';
          cycle = {
            ...cycle,
            status: isAlcohol ? 'closed' : cycle.status === 'closed' ? 'closed' : 'closing_soon',
            next_open_hint: isAlcohol
              ? `Treat the current ${overlay.label} window as closed until the city/state posts the next application/hearing cycle — missing it can mean waiting until the following year.`
              : cycle.next_open_hint,
            cutoff_note:
              cycle.cutoff_note ||
              'Confirm whether the current application/hearing cycle is still open before locking an open date.',
          };
        }
      }
    } else if (overlay.timing_multiplier) {
      mult *= Math.min(overlay.timing_multiplier, 1.1);
    }
  }
  const typical = Math.round(track.timing.typical_days * mult);
  const buffer = Math.round(track.timing.buffer_days * Math.max(mult, 1));
  return {
    ...track,
    timing: {
      min_days: track.timing.min_days,
      typical_days: typical,
      buffer_days: buffer,
      planning_days: buffer, // err toward buffer for plans
    },
    cycle,
    caveats: notes,
    overlay_keys: overlays.map((o) => o.key),
  };
}

/**
 * Assess applicable license tracks for a company context.
 * @param {{
 *   business_description?: string,
 *   stage?: string,
 *   location?: { state_code?: string, primary_city?: string, status?: string, micro_place?: boolean } | null,
 *   as_of?: string | Date,
 * }} input
 */
function assessComplianceCalendar(input = {}) {
  const triggers = detectTriggers(input.business_description);
  const overlays = resolveOverlays(input.location);
  const asOf = input.as_of ? new Date(input.as_of) : new Date();

  const applicable = LICENSE_TRACKS.filter((track) =>
    track.triggers.some((t) => triggers.includes(t)),
  ).map((track) => applyOverlays(track, overlays));

  const critical = applicable.filter(
    (t) => t.difficulty === 'high' || t.difficulty === 'very_high' || t.cycle.status === 'closed',
  );

  const longest = applicable.reduce(
    (max, t) => Math.max(max, t.timing.planning_days),
    0,
  );

  const closedCycles = applicable.filter((t) => t.cycle.status === 'closed');
  const closingSoon = applicable.filter((t) => t.cycle.status === 'closing_soon');

  /** @type {Array<{ path: string, value: unknown, origin_type: string, founder_confirmed: boolean }>} */
  const facts = [
    {
      path: 'compliance.calendar.as_of',
      value: asOf.toISOString().slice(0, 10),
      origin_type: 'DERIVED',
      founder_confirmed: false,
    },
    {
      path: 'compliance.calendar.applicable_track_ids',
      value: applicable.map((t) => t.id),
      origin_type: 'ASSUMED',
      founder_confirmed: false,
    },
    {
      path: 'compliance.calendar.planning_horizon_days',
      value: longest,
      origin_type: 'ASSUMED',
      founder_confirmed: false,
    },
  ];

  const blocked_outputs = [];
  if (closedCycles.length) {
    blocked_outputs.push({
      output: 'launch_date_commitment',
      reason: `One or more regulated filing cycles look closed or quota-bound (${closedCycles
        .map((t) => t.label)
        .join('; ')}). The next window must be confirmed before an opening date can be committed.`,
    });
  }
  if (!input.location || !input.location.state_code) {
    blocked_outputs.push({
      output: 'jurisdiction_specific_license_packets',
      reason: 'State/city unknown — license packets stay generic screens only',
    });
  }

  return {
    ok: true,
    status: 'screen_only',
    as_of: asOf.toISOString().slice(0, 10),
    triggers,
    overlays: overlays.map((o) => ({ key: o.key, label: o.label })),
    tracks: applicable.map((t) => ({
      id: t.id,
      label: t.label,
      level: t.level,
      difficulty: t.difficulty,
      timing_days: t.timing,
      cycle: t.cycle,
      prerequisites: t.prerequisites,
      caveats: t.caveats,
    })),
    critical_path: critical.map((t) => t.id),
    planning_horizon_days: longest,
    closed_cycle_count: closedCycles.length,
    closing_soon_count: closingSoon.length,
    summary: summarizeCalendar(applicable, overlays, longest),
    labels: {
      timing: 'ASSUMED — conservative screen, not an agency SLA',
      cycle: 'CONFIRM — cycle open/closed must be verified with the authority',
      difficulty: 'ASSUMED — relative difficulty for planning, not a legal opinion',
    },
    facts,
    blocked_outputs,
    notes: [
      'Screens estimate difficulty and calendars; they do not replace clerks or inspectors.',
      'Err toward buffer_days when writing plans, loan packages, or launch commitments.',
      'If a cycle is closed, model the next window — do not invent a workaround.',
    ],
  };
}

/**
 * @param {ReturnType<typeof applyOverlays>[]} tracks
 * @param {ReturnType<typeof resolveOverlays>} overlays
 * @param {number} horizon
 */
function summarizeCalendar(tracks, overlays, horizon) {
  if (!tracks.length) {
    return 'No special license tracks detected beyond baseline formation screens.';
  }
  const hardest = [...tracks].sort(
    (a, b) => difficultyRank(b.difficulty) - difficultyRank(a.difficulty),
  )[0];
  const closed = tracks.filter((t) => t.cycle.status === 'closed');
  const overlayBit = overlays.length
    ? ` Jurisdiction overlay: ${overlays.map((o) => o.label).join('; ')}.`
    : '';
  const cycleBit = closed.length
    ? ` ${closed.length} ${closed.length === 1 ? 'track' : 'tracks'} may be past a filing window — confirm next cycle before locking dates.`
    : ' No closed cycles detected in the curated screen — still verify with the live authority.';
  return `Hardest screen: ${hardest.label} (${hardest.difficulty}; plan ~${hardest.timing.planning_days} days). Overall planning horizon ~${horizon} days.${cycleBit}${overlayBit}`;
}

/** @param {Difficulty} d */
function difficultyRank(d) {
  return { low: 1, moderate: 2, high: 3, very_high: 4 }[d] || 0;
}


const ComplianceCalendar = { LICENSE_TRACKS, JURISDICTION_OVERLAYS, detectTriggers, resolveOverlays, assessComplianceCalendar };
