/**
 * Shared helpers for the Operating Plan: HTML building blocks in the same plain Word-document
 * style as the Business Plan (headings, paragraphs, bullets, tables only for numbers and
 * checklists), money and date formatting, and the To-Do and citation registers every section
 * writes into.
 *
 * Every top-level name is prefixed op/OP_ because the browser bundle inlines every module into
 * one scope, where a repeated name silently replaces another.
 */

const OP_MONTH_FULL = Object.freeze(['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']);
const OP_MONTH_ABBR = Object.freeze(['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']);
const OP_DAY_ABBR = Object.freeze(['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']);
const OP_DAY_MS = 86400000;

function opEsc(s) {
  return String(s ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

/** Whole dollars, rounded by magnitude so a figure and its negation print the same digits. */
function opMoney(n) {
  if (n == null || !Number.isFinite(Number(n))) return '';
  const v = Number(n);
  const r = Math.round(Math.abs(v));
  if (r === 0) return '$0';
  return `${v < 0 ? '-' : ''}$${r.toLocaleString('en-US')}`;
}

/** Dollars and cents for small unit prices ($4.39), whole dollars above $100. */
function opPrice(n) {
  if (n == null || !Number.isFinite(Number(n))) return '';
  const v = Number(n);
  if (Math.abs(v) >= 100 || Number.isInteger(v)) return opMoney(v);
  return `$${v.toFixed(2)}`;
}

function opMoneyRange(lo, hi) {
  if (lo == null && hi == null) return '';
  if (lo === hi || hi == null) return opPrice(lo);
  if (lo == null) return `up to ${opPrice(hi)}`;
  return `${opPrice(lo)}-${opPrice(hi)}`;
}

function opPct(r, digits = 1) {
  if (r == null || !Number.isFinite(Number(r))) return '';
  const v = Number(r) * 100;
  const s = v.toFixed(digits).replace(/(\.\d*?)0+$/, '$1').replace(/\.$/, '');
  return `${s}%`;
}

// ----- Dates (all UTC, ISO yyyy-mm-dd) -----------------------------------------------------------

function opParse(iso) {
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(iso || ''));
  if (!m) return null;
  return new Date(Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3]), 12));
}

function opIso(d) {
  return d.toISOString().slice(0, 10);
}

function opAddDays(iso, n) {
  const d = opParse(iso);
  return opIso(new Date(d.getTime() + Math.round(n) * OP_DAY_MS));
}

function opAddMonths(iso, n) {
  const d = opParse(iso);
  const y = d.getUTCFullYear();
  const m = d.getUTCMonth() + n;
  const target = new Date(Date.UTC(y + Math.floor(m / 12), ((m % 12) + 12) % 12, 1, 12));
  const last = new Date(Date.UTC(target.getUTCFullYear(), target.getUTCMonth() + 1, 0, 12)).getUTCDate();
  target.setUTCDate(Math.min(d.getUTCDate(), last));
  return opIso(target);
}

function opDaysBetween(a, b) {
  return Math.round((opParse(b).getTime() - opParse(a).getTime()) / OP_DAY_MS);
}

/** Monday of the week holding `iso`. */
function opMonday(iso) {
  const d = opParse(iso);
  const dow = d.getUTCDay();
  return opAddDays(iso, dow === 0 ? -6 : 1 - dow);
}

/** "October 5, 2026" */
function opDateLong(iso) {
  const d = opParse(iso);
  return `${OP_MONTH_FULL[d.getUTCMonth()]} ${d.getUTCDate()}, ${d.getUTCFullYear()}`;
}

/** "Mon Oct 5" (year added when it differs from `refYear`). */
function opDateShort(iso, refYear) {
  const d = opParse(iso);
  const yr = refYear != null && d.getUTCFullYear() !== refYear ? `, ${d.getUTCFullYear()}` : '';
  // A no-break space keeps "Sep 26" on one line in narrow table columns.
  return `${OP_MONTH_ABBR[d.getUTCMonth()]} ${d.getUTCDate()}${yr}`;
}

function opWeekday(iso) {
  return OP_DAY_ABBR[opParse(iso).getUTCDay()];
}

/** "Oct 5-11, 2026" or "Dec 28, 2026-Jan 3, 2027" for the seven days from `mondayIso`. */
function opWeekLabel(mondayIso) {
  const a = opParse(mondayIso);
  const b = opParse(opAddDays(mondayIso, 6));
  if (a.getUTCFullYear() !== b.getUTCFullYear()) return `${opDateShort(mondayIso)}, ${a.getUTCFullYear()}-${opDateShort(opIso(b))}, ${b.getUTCFullYear()}`;
  if (a.getUTCMonth() !== b.getUTCMonth()) return `${opDateShort(mondayIso)}-${opDateShort(opIso(b))}, ${b.getUTCFullYear()}`;
  return `${opDateShort(mondayIso)}-${b.getUTCDate()}, ${b.getUTCFullYear()}`;
}

function opMonthLabel(iso) {
  const d = opParse(iso);
  return `${OP_MONTH_FULL[d.getUTCMonth()]} ${d.getUTCFullYear()}`;
}

// ----- HTML blocks -------------------------------------------------------------------------------

function opH3(text) {
  return `<h3>${opEsc(text)}</h3>`;
}

/** A paragraph from plain text (escaped). */
function opP(text) {
  return text ? `<p>${opEsc(text)}</p>` : '';
}

/** A paragraph from trusted inline HTML. */
function opPh(html) {
  return html ? `<p>${html}</p>` : '';
}

function opNote(text) {
  return text ? `<p class="table-note">${opEsc(text)}</p>` : '';
}

/** Bullets from plain-text items (escaped); an item may be { html } for trusted markup. */
function opUl(items) {
  const li = (items || []).filter(Boolean).map((i) => `<li>${typeof i === 'object' ? i.html : opEsc(i)}</li>`);
  return li.length ? `<ul>${li.join('')}</ul>` : '';
}

/**
 * Numbered steps as numbered paragraphs rather than a list element: the Word export numbers every
 * list from one shared sequence, so explicit numbers keep each set of steps starting at 1 in both
 * the PDF and the .docx.
 */
function opOl(items) {
  return (items || [])
    .filter(Boolean)
    .map((i, n) => `<p class="op-step">${n + 1}. ${typeof i === 'object' ? i.html : opEsc(i)}</p>`)
    .join('');
}

/**
 * A table. Cells are plain text (escaped) or { html } for trusted markup. opts.num lists the
 * right-aligned (figure) columns; a row may be { cells, cls } for subtotal / grand-total rules.
 */
function opTable(headers, rows, opts = {}) {
  const num = opts.num || [];
  const cell = (c, i, tag) => {
    const cls = num.includes(i) ? ' class="num"' : '';
    const body = c && typeof c === 'object' ? c.html : opEsc(c);
    // An empty cell gets a no-break space so blank worksheet rows keep their height for writing in.
    return `<${tag}${cls}>${body == null || body === '' ? '&nbsp;' : body}</${tag}>`;
  };
  const head = `<tr>${headers.map((h, i) => cell(h, i, 'th')).join('')}</tr>`;
  const body = rows
    .map((r) => {
      const cells = Array.isArray(r) ? r : r.cells;
      const cls = !Array.isArray(r) && r.cls ? ` class="${r.cls}"` : '';
      return `<tr${cls}>${cells.map((c, i) => cell(c, i, 'td')).join('')}</tr>`;
    })
    .join('');
  return `<table class="doc-table${opts.cls ? ` ${opts.cls}` : ''}">${head}${body}</table>`;
}

// ----- Registers ---------------------------------------------------------------------------------

/**
 * Collects every To-Do raised while the plan is written, so the plan can print each one where it
 * belongs and list them all at the end. A To-Do is raised whenever a fact is missing from the
 * research (a null row, a missing pack, an expired pack) or a decision is still yours to make.
 * It never carries an invented figure.
 */
function opTodoRegister() {
  const items = [];
  return {
    items,
    /** @returns {string} inline HTML to print where the To-Do belongs */
    add(section, text, origin = 'decision') {
      const clean = String(text || '').trim().replace(/\.?$/, '.');
      if (!items.some((t) => t.section === section && t.text === clean)) items.push({ section, text: clean, origin });
      return `<strong>To-Do:</strong> ${opEsc(clean)}`;
    },
  };
}

/**
 * Numbered source list. Each fact printed from a pack or from the model's cited benchmark table
 * registers its source once and gets a number, printed as [n] beside the fact and in full under
 * Resources and Sources.
 */
function opCitationRegister() {
  const byKey = new Map();
  return {
    list: () => [...byKey.values()],
    /** @returns {number|null} the citation number */
    add(origin, src) {
      if (!src || !src.url) return null;
      // One number per URL, however many packs cite the same page.
      const key = String(src.url).replace(/\/+$/, '').toLowerCase();
      const period = /^current/i.test(src.reference_period || '') ? '' : src.reference_period || '';
      if (!byKey.has(key)) byKey.set(key, { n: byKey.size + 1, key, publisher: src.publisher || '', title: src.title || '', url: src.url, retrieved: src.retrieved || '', reference_period: period, origin: src.origin || origin || '' });
      return byKey.get(key).n;
    },
  };
}


/**
 * The research the Operating Plan is written from: the national, state and (when one exists)
 * industry Research Pack for this business, read from the verified digest
 * (research-digest.js, generated from the signed packs at build time).
 *
 * Inputs are codes only: the state from the location screen and a NAICS code. The NAICS code is
 * taken from the intake when the owner confirmed one, otherwise matched on this device from the
 * industry packs' own aliases (restricted to the model's industry sector), otherwise the model's
 * sector code. A business with no curated industry pack gets the generic fallback: national and
 * state facts, and marked To-Dos in place of industry specifics. Nothing here is ever invented:
 * a fact whose pack value is null, or whose pack has expired, is returned as missing so the
 * section prints a To-Do instead.
 */

/** A pack is expired a year after its oldest retrieval; its facts become "verify" To-Dos. */
const OP_PACK_FAIL_DAYS = 365;

function opPackStatus(pack, asOf) {
  if (!pack) return 'missing';
  const oldest = pack.retrieved_min || pack.built_at;
  if (!oldest) return 'ok';
  const age = opDaysBetween(String(oldest).slice(0, 10), asOf);
  if (age > OP_PACK_FAIL_DAYS) return 'expired';
  if (age > 120) return 'stale';
  return 'ok';
}

function opTableRows(pack, key) {
  const t = pack && pack.data && pack.data[key];
  if (!t) return [];
  return t.rows.map((r) => Object.fromEntries(t.columns.map((c, i) => [c, r[i]])));
}

/** The NAICS code and how it was chosen. */
function opResolveNaics(pipeline, digest) {
  const intake = pipeline.intake || {};
  const confirmed = [intake.naics, intake.industry?.naics, intake.industry_confirmation?.naics, intake.plan_detail?.company?.naics]
    .map((c) => String(c || '').replace(/\D/g, ''))
    .find((c) => c.length === 6);
  const rawModel = String(pipeline.finance?.cost_model?.industry?.naics || pipeline.finance?.projections?.industry?.naics || '').trim();
  // A sector range such as 44-45 (retail) stays a range: stripping the hyphen would make it another code.
  const modelNaics = /^\d{2}-\d{2}$/.test(rawModel) ? rawModel : rawModel.replace(/\D/g, '');
  if (confirmed) return { code: confirmed, basis: 'intake' };
  const industries = Object.values(digest.packs).filter((p) => p.tier === 'industry');
  const text = [intake.business_description, ...(intake.revenue_model?.channels || [])].filter(Boolean).join(' ').toLowerCase();
  let best = null;
  for (const p of industries) {
    const ind = p.data.industry;
    // The model's sector breaks ties; it no longer excludes a pack the description names outright
    // (a "bakery-cafe" is a bakery even when the cost model files it under food service).
    const within = !modelNaics || opNaicsWithin(String(ind.naics), modelNaics) || (ind.related_naics || []).some((n) => opNaicsWithin(String(n), modelNaics));
    // The pack's own name counts as an alias ("nail salon", "bakery"), besides its listed aliases.
    const own = String(p.id.split('/').pop() || '').replace(/-/g, ' ');
    for (const alias of [...(ind.aliases || []), own]) {
      // Outside the model's sector only the pack's own name counts ("boutique" alone is not a shop).
      if (!alias || (!within && alias !== own)) continue;
      const a = String(alias).toLowerCase().replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      const at = text.search(new RegExp(`(^|[^a-z])${a}([^a-z]|$)`));
      if (at < 0) continue;
      const better = !best || at < best.at || (at === best.at && (within && !best.within || (within === best.within && alias.length > best.alias.length)));
      if (better) best = { at, alias, code: ind.naics, within };
    }
  }
  if (best) return { code: best.code, basis: 'alias', alias: best.alias };
  return { code: modelNaics || '', basis: modelNaics ? 'model' : 'none' };
}

/** Whether a 6-digit code falls within a model sector code (a prefix, or a 2-digit range like 44-45). */
function opNaicsWithin(code, sector) {
  const m = /^(\d{2})-(\d{2})$/.exec(sector);
  if (m) return Number(code.slice(0, 2)) >= Number(m[1]) && Number(code.slice(0, 2)) <= Number(m[2]);
  return code.startsWith(sector.slice(0, Math.min(3, sector.length)));
}

/** The nearest industry pack for a code: exact 6-digit, else a 4- or 5-digit prefix match. */
function opFindIndustryPack(digest, code) {
  if (!code || !/^\d+$/.test(code)) return null;
  const packs = Object.values(digest.packs).filter((p) => p.tier === 'industry');
  for (let len = Math.min(code.length, 6); len >= 4; len -= 1) {
    const prefix = code.slice(0, len);
    const hit = packs.find((p) => [p.data.industry.naics, ...(p.data.industry.related_naics || [])].some((n) => (len === 6 ? n === prefix : String(n).startsWith(prefix))));
    if (hit) return hit;
  }
  return null;
}

function opNaicsTitle(naicsPack, code) {
  if (!code) return null;
  const rows = opTableRows(naicsPack, 'naics_2022');
  const exact = rows.find((x) => String(x.code) === code);
  if (exact) return { code: String(exact.code), title: exact.title, exact: true };
  if (!/^\d+$/.test(code)) return null;
  for (let len = code.length; len >= 2; len -= 1) {
    const r = rows.find((x) => String(x.code) === code.slice(0, len));
    if (r) return { code: String(r.code), title: r.title, exact: len === code.length };
  }
  return null;
}

/**
 * @param {object} pipeline
 * @param {string} asOf
 * @param {{ todos: ReturnType<import('./op-common').opTodoRegister>, cites: ReturnType<import('./op-common').opCitationRegister> }} regs
 */
function opResearch(pipeline, asOf, regs, digest = OP_RESEARCH_DIGEST) {
  const packs = digest.packs;
  const stateCode = String(pipeline.location?.state_code || pipeline.finance?.cost_model?.place?.state_code || '').toUpperCase();
  const core = packs['national/core'] || null;
  const labor = packs['national/labor'] || null;
  const naicsPack = packs['national/naics'] || null;
  const state = stateCode ? packs[`state/${stateCode}`] || null : null;
  const naics = opResolveNaics(pipeline, digest);
  const industry = opFindIndustryPack(digest, naics.code);
  const naicsInfo = opNaicsTitle(naicsPack, industry ? industry.data.industry.naics : naics.code);
  const used = [core, labor, naicsPack, state, industry].filter(Boolean);
  const status = Object.fromEntries(used.map((p) => [p.id, opPackStatus(p, asOf)]));

  /** Registers a pack source; returns its citation number or null. */
  function cite(pack, sourceId) {
    if (!pack || !sourceId) return null;
    const src = pack.sources[sourceId];
    return src ? regs.cites.add(`${pack.id}#${sourceId}`, { ...src, origin: pack.id }) : null;
  }

  /** Registers one of the model's cited benchmark sources (finance data_sources). */
  function citeModel(sourceId) {
    const fin = pipeline.finance || {};
    const src = [...(fin.data_sources || []), ...(fin.market_context?.sources || [])].find((s) => s && s.id === sourceId);
    return src ? regs.cites.add(`model#${sourceId}`, { ...src, origin: 'model' }) : null;
  }

  /** A usable row (non-null value in a non-expired pack), with its citation, or null. */
  function row(pack, r) {
    if (!pack || !r || r.value === null || r.value === undefined) return null;
    if (status[pack.id] === 'expired') return null;
    return { value: r.value, note: r.note || null, url: r.url || null, n: cite(pack, r.source_id), row: r };
  }

  const stateFact = (field) => (state ? row(state, state.data.facts[field]) : null);
  const federal = (field) => (core ? row(core, core.data.federal[field]) : null);
  const sbaLoan = (field) => (core ? row(core, core.data.sba_loans[field]) : null);

  const stateName = state ? state.data.name : pipeline.location?.state_name || '';
  const officeRow = stateFact('formation_office');
  const formationOffice = officeRow ? officeRow.value.name : stateName ? `the ${stateName} business filing office` : 'your state business filing office';

  /** OEWS national wage row for a SOC code. */
  let wageMap = null;
  function wage(soc) {
    if (!labor) return null;
    if (!wageMap) wageMap = new Map(opTableRows(labor, 'oews_national').map((x) => [x.soc, x]));
    const r = wageMap.get(soc);
    if (!r || r.hourly_median_usd == null || status[labor.id] === 'expired') return null;
    return { ...r, n: cite(labor, labor.data.oews_national.source_id) };
  }

  /** Industry rows of one kind, usable ones first, each { value, n, id } or { id, missing, reason }. */
  function industryRows(key) {
    if (!industry || !Array.isArray(industry.data[key])) return [];
    return industry.data[key].map((r) => {
      const ok = row(industry, r);
      return ok ? { id: r.id, ...ok } : { id: r.id, missing: true, reason: r.null_reason || (status[industry.id] === 'expired' ? 'pack expired' : null) };
    });
  }

  // Every number any pack in use holds as a value. A dollar figure the plan prints from a pack's
  // free-text note must be one of these, or that part of the note is left out: a fee is only ever
  // printed from a sourced, structured row.
  const allowed = new Set();
  const visit = (v) => {
    if (typeof v === 'number') allowed.add(Math.round(v * 100) / 100);
    else if (Array.isArray(v)) v.forEach(visit);
    else if (v && typeof v === 'object') Object.values(v).forEach(visit);
  };
  for (const p of used) visit(p.data);
  const perPack = new Map();
  /** Numbers held by one pack only (a state note may only repeat that state's own figures). */
  function packNumbers(pack) {
    if (!perPack.has(pack.id)) {
      const set = new Set();
      const walk = (v) => {
        if (typeof v === 'number') set.add(Math.round(v * 100) / 100);
        else if (Array.isArray(v)) v.forEach(walk);
        else if (v && typeof v === 'object') Object.values(v).forEach(walk);
      };
      walk(pack.data);
      perPack.set(pack.id, set);
    }
    return perPack.get(pack.id);
  }
  /** A pack note with every clause dropped that names a dollar figure the pack does not hold. */
  function safeNote(note, pack) {
    if (!note) return '';
    const ok = pack ? packNumbers(pack) : allowed;
    return String(note)
      .split(/(?<=[.;])\s+/)
      .filter((part) => [...part.matchAll(/\$\s?([\d,]+(?:\.\d+)?)/g)].every((m) => ok.has(Number(m[1].replace(/,/g, '')))))
      .join(' ')
      .trim();
  }

  const taxCalendar = core && status[core.id] !== 'expired'
    ? core.data.tax_calendar.filter((r) => r.value && r.value.due_date).map((r) => ({ id: r.id, ...r.value, note: r.note || null, n: cite(core, r.source_id) }))
    : [];

  return {
    digest,
    asOf,
    stateCode,
    stateName,
    core,
    labor,
    naicsPack,
    state,
    industry,
    naics,
    naicsInfo,
    family: industry ? industry.data.industry.family : null,
    businessModel: industry ? industry.data.industry.business_model : null,
    fallback: !industry,
    status,
    used,
    formationOffice,
    cite,
    citeModel,
    stateFact,
    federal,
    sbaLoan,
    wage,
    industryRows,
    taxCalendar,
    safeNote,
    allowedNumbers: allowed,
    /** Latest due date the national tax calendar covers. */
    taxCoverageEnd: taxCalendar.reduce((m, r) => (r.due_date > m ? r.due_date : m), ''),
  };
}


/**
 * One shared context for every Operating Plan section: the research (packs), the model's outputs
 * (read through the finance engine's existing result, never recomputed), the licensing research, the
 * opening date and the To-Do and citation registers.
 *
 * The opening date comes from the model: the first day of the month the model opens for business
 * (cost_model.opening_month on the plan calendar), or the exact date the owner gave when it falls
 * in that month. That keeps every date in this plan on the same calendar as the Business Plan and
 * Financial Statements.
 */

const OP_ALREADY_TRADING = Object.freeze(['launched', 'existing']);

/** Planning allowance for the build-out, by the space the owner described (days before opening). */
const OP_BUILDOUT_DAYS = Object.freeze({ turnkey: 30, light_buildout: 90, full_buildout: 150 });

function opOpening(pipeline, asOf, cal, cm, proj) {
  const intake = pipeline.intake || {};
  if (OP_ALREADY_TRADING.includes(intake.stage) || proj?.mode === 'revision') {
    return { date: asOf, month: 1, basis: 'trading', trading: true };
  }
  const ramp = Array.isArray(proj?.revenue_ramp) ? proj.revenue_ramp : [];
  const firstSales = ramp.findIndex((r) => Number(r) > 0) + 1;
  const month = Math.max(1, Number(cm?.opening_month) || Number(cm?.first_revenue_month) || firstSales || 1);
  const monthStart = opAddMonths(cal.start_iso, month - 1);
  const asked = intake.opening && /^\d{4}-\d{2}-\d{2}$/.test(String(intake.opening.date || '')) ? intake.opening.date : null;
  let date = monthStart;
  let basis = cal.basis === 'founder' ? 'founder' : 'model';
  if (asked && asked.slice(0, 7) === monthStart.slice(0, 7)) {
    date = asked;
    basis = intake.opening.source === 'founder' ? 'founder' : 'default';
  }
  if (date < asOf) date = asOf;
  return { date, month, basis, trading: false, asked };
}

/** Months of the model that fall before opening, and what they cost in cash. */
function opPreOpening(proj, openMonth) {
  const cf = Array.isArray(proj?.year1_cash_flow) ? proj.year1_cash_flow : [];
  const months = cf.filter((m) => m.month < openMonth);
  const total = months.reduce((a, m) => a + (Number(m.total_cash_paid_out_usd) || 0), 0);
  const last = months.length ? Number(months[months.length - 1].total_cash_paid_out_usd) || 0 : 0;
  return { months: months.length, total_usd: total, monthly_usd: last };
}

function opTraits(pipeline, R) {
  const intake = pipeline.intake || {};
  const text = [intake.business_description, ...(intake.revenue_model?.channels || []), intake.customer].filter(Boolean).join(' ').toLowerCase();
  const industryId = pipeline.finance?.cost_model?.industry?.id || '';
  // A matched industry pack decides; words in the description only count without one (software
  // sold to restaurants is not a food business).
  const food = R.family === 'food-service' || industryId === 'food_service' || (!R.industry && industryId !== 'software_saas') && /\b(cafe|café|coffee|restaurant|bakery|food truck|catering)\b/.test(text);
  const model = R.businessModel || (industryId === 'software_saas' ? 'online' : industryId === 'cleaning_services' ? 'service_at_customer_site' : industryId === 'professional_services' ? 'professional' : pipeline.finance?.profile === 'physical_ops' ? 'storefront' : 'professional');
  return {
    text,
    food,
    alcohol: /\b(wine|beer|bar|cocktails?|spirits|liquor|taproom|brewery)\b/.test(text),
    catering: /\b(catering|private events?|events|workshops?|wholesale|corporate)\b/.test(text),
    storefront: ['storefront', 'facility'].includes(model),
    model,
    b2b: ['service_at_customer_site', 'professional'].includes(model) || /\b(catering|private events?|wholesale|b2b|clients?|contracts?|corporate)\b/.test(text),
    saas: industryId === 'software_saas' || /\b(saas|subscription software|platform)\b/.test(text),
    retail: industryId === 'retail' || R.family === 'retail',
  };
}

/**
 * @param {object} pipeline
 * @param {string} asOf  plan date, yyyy-mm-dd
 * @param {{ companyTitle: Function, hasBusinessName: Function, planCalendar: Function, locationLine: Function }} host
 */
function opContext(pipeline, asOf, host) {
  const todos = opTodoRegister();
  const cites = opCitationRegister();
  // host.digest lets a test hand in altered research (a null fee, an expired pack); the app never sets it.
  const R = opResearch(pipeline, asOf, { todos, cites }, host.digest || undefined);
  const intake = pipeline.intake || {};
  const fin = pipeline.finance || {};
  const proj = fin.projections || {};
  const cm = fin.cost_model || {};
  const cal = host.planCalendar(pipeline, asOf);
  const opening = opOpening(pipeline, asOf, cal, cm, proj);
  const loc = pipeline.location || {};
  const screen = assessComplianceCalendar({
    business_description: intake.business_description,
    stage: intake.stage,
    location: { state_code: loc.state_code, primary_city: loc.primary_city, status: loc.status, micro_place: Boolean(loc.micro_place) },
    as_of: asOf,
  });
  const company = intake.plan_detail?.company || {};
  const staffing = Array.isArray(cm.staffing) ? cm.staffing : [];
  const setupCats = Array.isArray(proj.fixed_setup_categories) ? proj.fixed_setup_categories : [];
  const traits = opTraits(pipeline, R);
  const named = host.hasBusinessName(pipeline);
  const locLine = host.locationLine(pipeline);
  const placeDecided = !/not decided|pending/i.test(locLine);
  const entity = intake.existing_company_deepen?.entity_type || company.entity_type || null;

  /** Plan month n as the first day of its calendar month. */
  const monthIso = (n) => opAddMonths(cal.start_iso, n - 1);
  /** The plan month a date falls in (1-based; can be < 1 before the plan starts). */
  const monthOf = (iso) => {
    const a = opParse(cal.start_iso);
    const b = opParse(iso);
    return (b.getUTCFullYear() - a.getUTCFullYear()) * 12 + (b.getUTCMonth() - a.getUTCMonth()) + 1;
  };

  return {
    pipeline,
    asOf,
    host,
    todos,
    cites,
    R,
    intake,
    fin,
    proj,
    cm,
    cal,
    opening,
    daysToOpen: opDaysBetween(asOf, opening.date),
    preOpening: opPreOpening(proj, opening.month),
    screen,
    tracks: screen.tracks || [],
    company,
    ownerName: String(company.owner_name || '').trim(),
    name: named ? host.companyTitle(pipeline) : 'Your business',
    // The name mid-sentence: "opening your business" when there is no name yet.
    nameMid: named ? host.companyTitle(pipeline) : 'your business',
    named,
    place: placeDecided ? locLine : '',
    placeDecided,
    city: loc.primary_city || '',
    county: loc.county?.name || '',
    staffing,
    founderRole: staffing.find((s) => s.is_founder) || null,
    hires: staffing.filter((s) => !s.is_founder),
    setupCats,
    traits,
    entity,
    formed: intake.existing_company_deepen?.already_formed === 'yes',
    buildoutDays: OP_BUILDOUT_DAYS[intake.interview_deepen?.operational?.space_type] || null,
    spaceType: intake.interview_deepen?.operational?.space_type || null,
    monthIso,
    monthOf,
    todayIso: opIso(opParse(asOf)),
  };
}

/**
 * The cash-low trigger: two months of the model's fixed costs, or one month when the plan itself
 * dips below two months (a trigger the plan is expected to cross would fire while you are on plan).
 */
function opCashTrigger(oc) {
  const fixed = Number(oc.proj.break_even?.fixed_costs_monthly_usd) || 0;
  if (!fixed) return null;
  const low = Number(oc.proj.lowest_cash_36_months_usd);
  const months = Number.isFinite(low) && low < fixed * 2 ? 1 : 2;
  return { amount: fixed * months, months, fixed, planLow: Number.isFinite(low) ? low : null };
}


/**
 * Free local business help for the Operating Plan (SBDC centers, SCORE chapters, Women's Business
 * Centers, VBOCs, SBA district offices, state business offices, microloan and community lenders).
 *
 * Read through planLocalHelp (../local-help.js), the same lookup Founder's Notes, the To-Do List
 * and Help use: getLocalResources over the signed resources pack in the verified digest. The plan
 * names an office only when the pack lists it; otherwise it points to the national locators. Codes
 * only go in: state, county, ZIP and the ZIP's centroid, all resolved on this device.
 */

/** National locators, used when the pack lists no office of a kind for the founder's state. */
const OP_NATIONAL_LOCATORS = Object.freeze([
  { kind: 'sbdc', name: "America's SBDC: find your Small Business Development Center", website: 'https://americassbdc.org/find-your-sbdc/', what: 'Free one-to-one advising on plans, financing and licensing' },
  { kind: 'score', name: 'SCORE: find a mentor', website: 'https://www.score.org/find-mentor', what: 'Free mentoring from experienced business owners' },
  { kind: 'sba', name: 'U.S. Small Business Administration: local assistance', website: 'https://www.sba.gov/local-assistance', what: "Finder for SBDCs, Women's Business Centers, veterans centers and district offices" },
]);

/**
 * @returns {{ local: boolean, help: object, sbdc: object|null, entries: object[] }}
 *   sbdc: the office to book first (the nearest SBDC, else SCORE, else a Women's Business Center)
 */
function opLocalHelp(oc) {
  const host = oc.host || {};
  const help = planLocalHelp(oc.pipeline, { digest: host.digest || undefined, getLocalResources: typeof host.getLocalResources === 'function' ? host.getLocalResources : undefined });
  const entries = [help.sbdc, help.score, help.wbc, help.vboc, help.district, help.state_office].filter(Boolean);
  if (help.local) return { local: true, help, sbdc: help.nearest, entries };
  return { local: false, help, sbdc: null, entries: OP_NATIONAL_LOCATORS.map((e) => ({ ...e, label: '', phone: '', address: '' })) };
}

/** One line naming the adviser to book: "Name, phone, website (about 7 miles away)", or the locators. */
function opAdviserLine(h) {
  if (h && h.sbdc) return lhOfficeLine(h.sbdc);
  return 'find your nearest center at americassbdc.org/find-your-sbdc or a SCORE mentor at score.org/find-mentor';
}


/**
 * The launch schedule: every pre-opening task with a real date, owner, dependency, cost and
 * source, and the critical path to opening.
 *
 * Permits are scheduled on the licensing research's typical processing time and checked against its
 * longer planning allowance (the same rule the model uses): a permit that must be in hand before
 * opening is filed no later than its typical lead time before the opening date, and the plan says
 * plainly when that date has already passed. Tasks that do not depend on a permit are scheduled
 * forward from today in dependency order. Every fee comes from a research pack; a fee the pack does
 * not hold prints as "Confirm fee" with a To-Do, never as a number.
 */

/** Days before opening a permit needed to open should be in hand (time to post it and fix a last-minute item). */
const OP_ISSUE_BEFORE_OPEN = 7;

/** The one To-Do per permit: its fee and current processing time, from the issuing office. */
function opPermitTodo(track) {
  return `Confirm the ${opShortTrack(track).toLowerCase()} fee and current processing time with the issuing office`;
}

/** Licensing research tracks that must be approved before the doors open. */
function opRequiredToOpen(trackId, traits) {
  if (trackId === 'childcare_or_education_license') return true;
  if (trackId === 'food_service_permit') return traits.food;
  if (trackId === 'local_business_license') return traits.storefront;
  if (trackId === 'professional_license_screen') return true;
  if (trackId === 'alcohol_license') return !traits.food;
  return false;
}

function opTrackTiming(track) {
  const t = track.timing_days || {};
  const typical = Number(t.typical_days) || Number(t.planning_days) || 0;
  const buffer = Number(t.planning_days) || Number(t.buffer_days) || typical;
  return { typical, buffer };
}

/** Industry-pack license row that describes a licensing research track, when one exists. */
function opLicenseRowFor(oc, trackId) {
  const map = {
    food_service_permit: ['food-establishment-permit', 'food-service-permit', 'food-permit', 'health-permit'],
    local_business_license: ['business-license', 'certificate-of-occupancy'],
    alcohol_license: ['liquor-license', 'alcohol-license'],
    professional_license_screen: ['professional-license', 'contractor-license', 'occupational-license'],
  };
  const ids = map[trackId] || [];
  return oc.R.industryRows('licenses').find((r) => !r.missing && ids.includes(r.id)) || null;
}

function opFormationFee(oc) {
  const st = oc.R.stateFact;
  const kind = /corp/i.test(oc.entity || '') ? 'corp' : 'llc';
  const fee = st(kind === 'corp' ? 'corp_filing_fee_usd' : 'llc_filing_fee_usd');
  const form = st(kind === 'corp' ? 'corp_formation_form' : 'llc_formation_form');
  return { kind, fee, form };
}

/**
 * @returns {{ tasks: object[], critical: object[], windowStart: string, permits: object[], conflicts: object[] }}
 */
function opBuildSchedule(oc) {
  const T = oc.asOf;
  const O = oc.opening.date;
  const tasks = [];
  const byId = new Map();
  const R = oc.R;
  const traits = oc.traits;

  const add = (t) => {
    const task = { owner: 'You', deps: [], cost: '', source: 'Common practice', late: false, critical: false, ...t };
    tasks.push(task);
    byId.set(task.id, task);
    return task;
  };
  const after = (depId, lag = 0) => {
    const dep = depId ? byId.get(depId) : null;
    const base = dep && dep.date > T ? dep.date : T;
    return opAddDays(base, lag);
  };
  const before = (days) => opAddDays(O, -days);
  /** Schedule back from opening, but never before today or before its dependencies. */
  const back = (days, deps = []) => {
    const want = before(days);
    let floor = T;
    for (const d of deps) {
      const dep = byId.get(d);
      if (dep && dep.date > floor) floor = dep.date;
    }
    return { date: want < floor ? floor : want, late: want < T };
  };
  const cite = (n) => (n ? ` [${n}]` : '');

  // Free advice first: the local resources pack names the office when it is available.
  if (oc.localHelp) {
    const h = oc.localHelp;
    add({ id: 'adviser', label: 'Adviser booked', title: `Book a free session with ${h.sbdc ? `your local ${h.sbdc.label || 'business advisor'}` : 'a Small Business Development Center advisor or SCORE mentor'}: ${opAdviserLine(h)}`, date: after(null, 1), cost: 'Free', source: h.local ? 'Local help directory' : 'National locator', phase: 'setup' });
  }
  if (oc.opening.trading) {
    opTradingSchedule(oc, add, after);
    tasks.sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
    return { tasks, byId, critical: tasks.filter((t) => t.critical), permits: [], conflicts: [], trading: true };
  }

  // ----- Formation and registrations ----------------------------------------------------------
  const formationTrack = oc.tracks.find((t) => t.id === 'entity_sos_formation');
  const formTiming = formationTrack ? opTrackTiming(formationTrack) : { typical: 7, buffer: 21 };
  if (!oc.formed) {
    add({ id: 'entity_choice', label: 'Entity chosen', title: 'Choose your entity type and a name; check the name is available with the state', owner: 'You, with your accountant', date: after(null, 2), phase: 'setup' });
    const { kind, fee, form } = opFormationFee(oc);
    const formName = form ? form.value : kind === 'corp' ? 'articles of incorporation' : 'LLC formation document';
    const feeText = fee ? `${opMoney(fee.value)}${cite(fee.n)}` : 'Confirm fee';
    if (!fee) oc.todos.add('Formation and registrations', `Confirm the ${kind === 'corp' ? 'corporation' : 'LLC'} filing fee with ${R.formationOffice}`, 'null_fact');
    add({ id: 'formation', label: 'Formation filed', title: `File your ${formName} with ${R.formationOffice}`, owner: 'You (an attorney is optional)', deps: ['entity_choice'], date: after('entity_choice', 3), cost: feeText, source: R.state ? 'State research' : 'Confirm with the state', phase: 'setup', critical: true });
    add({ id: 'formation_approved', label: 'Formation approved', title: `Formation approved (typically ${formTiming.typical} days; allow up to ${formTiming.buffer})`, deps: ['formation'], date: after('formation', formTiming.typical), source: 'Licensing research', phase: 'setup' });
  }
  const einFee = R.federal('ein_fee_usd');
  add({ id: 'ein', label: 'EIN', title: 'Apply online for your Employer Identification Number (Form SS-4)', deps: oc.formed ? [] : ['formation_approved'], date: after(oc.formed ? null : 'formation_approved', 0), cost: einFee ? `${opMoney(einFee.value)}${cite(einFee.n)}` : 'Confirm fee', source: 'Federal research', phase: 'setup' });
  add({ id: 'bank', label: 'Bank account', title: 'Open business checking and a separate savings account for taxes', deps: ['ein'], date: after('ein', 2), phase: 'setup' });
  add({ id: 'books', label: 'Bookkeeping', title: 'Set up bookkeeping software and the chart of accounts in this plan', owner: 'You, with your accountant', deps: ['bank'], date: after('bank', 3), phase: 'setup' });
  const salesReg = R.stateFact('sales_tax_registration');
  const whReg = R.stateFact('withholding_registration');
  const agency = salesReg ? salesReg.value.agency : `the ${R.stateName || 'state'} revenue department`;
  add({ id: 'state_tax', label: 'State tax accounts', title: `Register for sales tax and payroll withholding with ${agency}`, deps: ['ein'], date: after('ein', 3), cost: '', source: salesReg || whReg ? `State research${cite((salesReg || whReg).n)}` : 'Confirm with the state', phase: 'setup' });
  const ui = R.stateFact('unemployment_registration');
  add({ id: 'ui_reg', label: 'Unemployment account', title: ui ? `Register for state unemployment insurance with ${ui.value.agency || ui.value.name}` : 'Register for state unemployment insurance before the first payroll', deps: ['ein'], date: after('ein', 3), source: ui ? `State research${cite(ui.n)}` : 'Confirm with the state', phase: 'setup' });

  // ----- Site, permits and build-out (premises businesses) -------------------------------------
  const permits = [];
  const conflicts = [];
  if (traits.storefront) {
    add({ id: 'zoning', label: 'Zoning checked', title: 'Confirm with the city that zoning allows your use at each address you are considering', deps: [], date: after(null, 7), phase: 'site' });
    const required = oc.tracks.filter((t) => opRequiredToOpen(t.id, traits));
    const fileBys = required.map((t) => before(opTrackTiming(t).typical + OP_ISSUE_BEFORE_OPEN));
    const permitFileBy = fileBys.length ? fileBys.reduce((a, b) => (a < b ? a : b)) : before(60);
    const buildoutBy = oc.buildoutDays ? before(oc.buildoutDays + 14) : null;
    const leaseWant = opAddDays([permitFileBy, buildoutBy].filter(Boolean).reduce((a, b) => (a < b ? a : b)), -7);
    const zoneDone = byId.get('zoning').date;
    add({ id: 'lease', label: 'Lease signed', title: 'Sign the lease, with a permit contingency (terms to negotiate are in the location section)', owner: 'You, with your attorney', deps: ['zoning'], date: leaseWant < zoneDone ? zoneDone : leaseWant, late: leaseWant < T, cost: oc.setupCats.find((c) => c.asset_class === 'deposit') ? `${opMoney(oc.setupCats.find((c) => c.asset_class === 'deposit').amount_usd)} deposits (model)` : '', source: 'Your model', phase: 'site', critical: true });
    add({ id: 'insurance', label: 'Insurance bound', title: 'Bind general liability and property insurance; send the certificate to your landlord', owner: 'You, with an insurance agent', deps: ['lease'], date: after('lease', 0), cost: opInsuranceCost(oc), source: 'Your model', phase: 'site' });
    for (const t of oc.tracks) {
      const timing = opTrackTiming(t);
      const req = opRequiredToOpen(t.id, traits);
      if (['entity_sos_formation', 'ein_federal'].includes(t.id)) continue;
      const want = req ? before(timing.typical + OP_ISSUE_BEFORE_OPEN) : T;
      const lease = byId.get('lease');
      const floor = lease.date > T ? lease.date : T;
      const date = want < floor ? floor : want;
      const approval = opAddDays(date, timing.typical);
      const approvalBuffer = opAddDays(date, timing.buffer);
      const row = opLicenseRowFor(oc, t.id);
      const lateBy = req ? opDaysBetween(O, approval) : 0;
      const p = { track: t, required: req, fileBy: want, date, approval, approvalBuffer, timing, row, late: req && want < floor, lateBy };
      // The licensing research reads words in the description; a health permit flagged for a business
      // that does not sell food or drink is something to confirm, not a filing to schedule.
      if (t.id === 'food_service_permit' && !traits.food) {
        permits.push({ ...p, confirm: true });
        oc.todos.add('Formation and registrations', 'The licensing research flagged a health permit from words in your description; if you will not sell food or drink, confirm with the city that you do not need one', 'decision');
        continue;
      }
      permits.push(p);
      if (req && lateBy > 0) conflicts.push(p);
      add({
        id: `permit_${t.id}`,
        label: `${opShortTrack(t)} filed`,
        title: t.id === 'food_service_permit' ? 'Submit the health department plan review and food permit application' : t.id === 'alcohol_license' ? 'File the alcohol license application (needs the signed lease)' : `File for the ${opShortTrack(t).toLowerCase()}`,
        deps: ['lease'],
        date,
        late: p.late,
        cost: 'Confirm fee',
        source: `Licensing research${row ? `; industry research${cite(row.n)}` : ''}`,
        phase: 'permits',
        critical: req,
      });
      oc.todos.add('Formation and registrations', opPermitTodo(t), 'null_fact');
    }
    const bp = R.industryRows('licenses').find((r) => r.id === 'building-permit' && !r.missing);
    if (oc.buildoutDays && oc.spaceType !== 'turnkey') add({ id: 'building_permit', label: 'Building permit', title: 'Apply for the building / tenant improvement permit with your contractor\'s drawings', owner: 'You and your contractor', deps: ['lease'], date: after('lease', 7), cost: 'Confirm fee', source: bp ? `Industry research${cite(bp.n)}` : 'Common practice', phase: 'buildout' });
    const sign = R.industryRows('licenses').find((r) => r.id === 'sign-permit' && !r.missing);
    add({ id: 'sign_permit', label: 'Sign permit', title: 'Apply for the permanent exterior sign permit', deps: ['lease'], date: after('lease', 14), cost: 'Confirm fee', source: sign ? `Industry research${cite(sign.n)}` : 'Common practice', phase: 'permits' });
    if (oc.buildoutDays && oc.spaceType !== 'turnkey') {
      const b = back(oc.buildoutDays, ['building_permit']);
      const buildCat = oc.setupCats.find((c) => c.asset_class === 'buildout');
      add({ id: 'buildout_start', label: 'Build-out started', title: 'Start build-out once the building permit is issued', owner: 'Your contractor', deps: ['building_permit'], ...b, cost: buildCat ? `${opMoney(buildCat.amount_usd)} (model)` : '', source: 'Your model', phase: 'buildout', critical: true });
      add({ id: 'buildout_done', label: 'Build-out complete', title: 'Build-out complete; punch list walked with the contractor', owner: 'Your contractor', deps: ['buildout_start'], ...back(21, ['buildout_start']), phase: 'buildout', critical: true });
    }
    const eq = opEquipmentTotals(oc);
    add({ id: 'equipment_order', label: 'Equipment ordered', title: 'Order must-have equipment after two quotes per item; confirm delivery lead times', deps: ['lease'], ...back(56, ['lease']), cost: eq ? `${opMoneyRange(eq.low, eq.high)} (industry research)` : opEquipmentModelCost(oc), source: eq ? 'Industry research' : 'Your model', phase: 'buildout' });
    add({ id: 'equipment_install', label: 'Equipment installed', title: 'Equipment delivered, installed and hooked up (plumbing, electrical, water filtration)', owner: 'You and your contractor', deps: ['equipment_order', oc.buildoutDays ? 'buildout_done' : 'lease'], ...back(17, ['equipment_order']), phase: 'buildout' });
    add({ id: 'inspections', label: 'Final inspections', title: `Final inspections: building, fire${traits.food ? ' and health' : ''}`, deps: ['equipment_install'], ...back(12, ['equipment_install']), phase: 'permits', critical: true });
    // Each permit needed to open is issued after the final inspections and its processing time.
    for (const p of permits.filter((x) => x.required)) {
      const insp = byId.get('inspections').date;
      const date = p.approval > insp ? p.approval : opAddDays(insp, 2);
      const t = p.track;
      const title = t.id === 'food_service_permit' ? 'Health permit issued; post it where the public can see it' : t.id === 'local_business_license' ? 'Business license and certificate of occupancy issued' : `${opShortTrack(t)} issued`;
      add({ id: `approved_${t.id}`, label: `${opShortTrack(t)} issued`, title: `${title} (typically ${p.timing.typical} days from filing; allow ${p.timing.buffer})`, deps: [`permit_${t.id}`, 'inspections'], date, late: p.lateBy > 0, source: 'Licensing research', phase: 'permits', critical: true });
    }
  } else {
    for (const t of oc.tracks) {
      if (['entity_sos_formation', 'ein_federal'].includes(t.id)) continue;
      const timing = opTrackTiming(t);
      const req = opRequiredToOpen(t.id, traits);
      const want = req ? before(timing.typical) : T;
      const date = want < T ? T : want;
      const approval = opAddDays(date, timing.typical);
      const p = { track: t, required: req, fileBy: want, date, approval, approvalBuffer: opAddDays(date, timing.buffer), timing, row: opLicenseRowFor(oc, t.id), late: req && want < T, lateBy: req ? opDaysBetween(O, approval) : 0 };
      permits.push(p);
      if (req && p.lateBy > 0) conflicts.push(p);
      add({ id: `permit_${t.id}`, label: `${opShortTrack(t)} filed`, title: `Apply for the ${opShortTrack(t).toLowerCase()}`, deps: ['ein'], date, late: p.late, cost: 'Confirm fee', source: 'Licensing research', phase: 'permits', critical: req });
      oc.todos.add('Formation and registrations', opPermitTodo(t), 'null_fact');
    }
    add({ id: 'insurance', label: 'Insurance bound', title: oc.traits.model === 'professional' ? 'Bind general and professional liability insurance before the first client' : 'Bind general liability insurance before the first job', owner: 'You, with an insurance agent', deps: ['formation_approved'].filter((d) => byId.has(d)), ...back(21), cost: opInsuranceCost(oc), source: 'Your model', phase: 'site' });
    add({ id: 'equipment_order', label: 'Tools and equipment', title: 'Buy the tools, equipment and software you need to deliver the first job', ...back(28), cost: opEquipmentModelCost(oc), source: 'Your model', phase: 'buildout' });
  }

  // ----- Team -----------------------------------------------------------------------------------
  const hires = oc.hires;
  if (hires.length) {
    const wc = R.stateFact('workers_comp_threshold');
    add({ id: 'job_posts', label: 'Jobs posted', title: `Write job descriptions and post openings: ${hires.map((h) => opRoleName(h)).join(', ')}`, deps: [], ...back(42), phase: 'team' });
    add({ id: 'interviews', label: 'Interviews', title: 'Interview and check references', deps: ['job_posts'], ...back(35, ['job_posts']), phase: 'team' });
    add({ id: 'offers', label: 'Offers made', title: 'Make written offers with pay, hours and start date', deps: ['interviews'], ...back(28, ['interviews']), phase: 'team' });
    add({ id: 'workers_comp', label: "Workers' comp", title: "Bind workers' compensation insurance before anyone starts work", owner: 'You, with an insurance agent', deps: ['ein'], ...back(21, ['ein']), cost: opWorkersCompCost(oc), source: wc ? `State research${cite(wc.n)}` : 'Confirm with the state', phase: 'team' });
    add({ id: 'payroll_setup', label: 'Payroll set up', title: 'Set up payroll (withholding, unemployment, direct deposit) and collect Form W-4 from each hire', deps: ['state_tax', 'ui_reg'], ...back(14, ['state_tax', 'ui_reg']), phase: 'team' });
    add({ id: 'staff_start', label: 'Staff start', title: 'Staff start: complete Form I-9 within three business days and report each new hire to the state', deps: ['offers', 'workers_comp', 'payroll_setup'], ...back(10, ['offers', 'workers_comp', 'payroll_setup']), phase: 'team' });
    add({ id: 'posters', label: 'Posters', title: 'Put up the required federal and state workplace posters', deps: ['staff_start'], ...back(10, ['staff_start']), phase: 'team' });
    add({ id: 'training', label: 'Training', title: 'Train staff on the opening, shift and closing procedures and practice service', deps: ['staff_start'], ...back(7, ['staff_start']), phase: 'team' });
  }
  if (traits.food) {
    const cert = R.industryRows('startup_costs').find((r) => r.id === 'food-protection-manager-cert' && !r.missing);
    add({ id: 'food_manager', label: 'Food manager certified', title: 'Pass the certified food protection manager exam (you and each shift lead)', deps: [], ...back(30), cost: cert ? `${opMoneyRange(cert.value.low_usd, cert.value.high_usd)} per person${cite(cert.n)}` : 'Confirm cost', source: cert ? 'Industry research' : 'Common practice', phase: 'team' });
  }

  // ----- Suppliers, systems, marketing, opening -------------------------------------------------
  add({ id: 'suppliers', label: 'Supplier accounts', title: 'Open accounts with your main suppliers and a backup for each; agree terms', deps: [], ...back(28), phase: 'suppliers' });
  add({ id: 'pos', label: 'POS ready', title: traits.storefront ? 'Set up the point-of-sale system and card payments; load items and prices' : 'Set up invoicing and card payments', deps: ['bank'], ...back(21, ['bank']), source: 'Common practice', phase: 'suppliers' });
  if (traits.storefront) add({ id: 'first_order', label: 'Opening order', title: 'Set par levels, place opening orders and check deliveries in', deps: ['suppliers'], ...back(7, ['suppliers']), phase: 'suppliers' });
  add({ id: 'mkt_list', label: 'Email list', title: 'Start the pre-opening email list and social accounts', deps: [], ...back(56), phase: 'marketing' });
  add({ id: 'mkt_site', label: 'Website live', title: 'Publish the website and Google Business Profile with hours and opening date', deps: traits.storefront ? ['lease'] : [], ...back(42, traits.storefront ? ['lease'] : []), phase: 'marketing' });
  add({ id: 'mkt_event', label: 'Opening event planned', title: 'Plan the opening event; invite neighbors, nearby businesses and local press', deps: ['mkt_list'], ...back(28, ['mkt_list']), phase: 'marketing' });
  if (traits.storefront) add({ id: 'soft_open', label: 'Soft opening', title: 'Soft opening for friends, neighbors and staff practice', deps: ['training', 'first_order'].filter((d) => byId.has(d)), ...back(3, ['training', 'first_order'].filter((d) => byId.has(d))), phase: 'marketing' });
  const openDeps = tasks.filter((t) => t.id.startsWith('approved_')).map((t) => t.id);
  add({ id: 'open', label: 'Opening', title: traits.storefront ? 'Open for business' : 'Start serving your first customers', deps: openDeps.length ? openDeps : tasks.filter((t) => t.critical).slice(-1).map((t) => t.id), date: O, phase: 'open', critical: true });

  tasks.sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : (b.critical ? 1 : 0) - (a.critical ? 1 : 0)));
  const critical = tasks.filter((t) => t.critical);
  return { tasks, byId, critical, permits, conflicts, trading: false };
}

function opTradingSchedule(oc, add, after) {
  add({ id: 'books', label: 'Books current', title: 'Bring bookkeeping current and reconcile every account', owner: 'You, with your accountant', date: after(null, 7), phase: 'setup' });
  add({ id: 'registrations', label: 'Registrations checked', title: 'Check every state and local registration and license is current', date: after(null, 14), phase: 'setup' });
  add({ id: 'kpis', label: 'Scorecard', title: 'Start the weekly scorecard in this plan', date: after(null, 7), phase: 'setup' });
  add({ id: 'cash', label: 'Cash plan', title: 'Build a 13-week cash plan and set the cash-low trigger', date: after(null, 10), phase: 'setup', critical: true });
  add({ id: 'costs', label: 'Cost review', title: 'Review every cost line against the targets in this plan; renegotiate or cut', date: after(null, 21), phase: 'setup', critical: true });
  add({ id: 'marketing', label: 'Marketing push', title: 'Run the first 30-day marketing push from the channel playbooks', date: after(null, 30), phase: 'marketing' });
}

function opShortTrack(t) {
  return String(t.label || '')
    .replace(/\s*\(if applicable\)/i, '')
    .replace(/\s*\(SOS[^)]*\)/i, '')
    .replace(/\s*posture$/i, '')
    .replace(/\s*screen$/i, '')
    .replace(/Municipal business license \/ certificate of occupancy/i, 'Business license and certificate of occupancy')
    .replace(/Food service \/ health permit/i, 'Health permit')
    .trim();
}

function opRoleName(r) {
  const t = String(r.title || r.occupation || 'Staff').trim();
  return t.charAt(0).toUpperCase() + t.slice(1);
}

function opEquipmentTotals(oc) {
  const rows = oc.R.industryRows('equipment').filter((r) => !r.missing && r.value.must_have);
  if (!rows.length) return null;
  return rows.reduce((a, r) => ({ low: a.low + r.value.low_usd, high: a.high + r.value.high_usd }), { low: 0, high: 0 });
}

function opEquipmentModelCost(oc) {
  const eq = oc.setupCats.filter((c) => ['equipment', 'technology'].includes(c.asset_class));
  const total = eq.reduce((a, c) => a + (Number(c.amount_usd) || 0), 0);
  return total ? `${opMoney(total)} (model)` : '';
}

function opInsuranceCost(oc) {
  const line = (oc.cm.lines || []).find((l) => l.key === 'insurance');
  return line ? `${opMoney(line.monthly_usd)}/month (model)` : '';
}

function opWorkersCompCost(oc) {
  const wc = oc.cm.payroll?.workers_comp;
  const annual = oc.cm.payroll?.annual_burden_usd?.workers_comp_usd;
  return annual ? `about ${opMoney(annual)}/year (model)` : wc?.per_100_usd ? `${opPrice(wc.per_100_usd)} per $100 of payroll (model)` : '';
}

/** A sentence stating the opening date and whether the permits fit it. */
function opOpeningVerdict(oc, sched) {
  if (oc.opening.trading) return '';
  const worst = sched.conflicts.slice().sort((a, b) => b.lateBy - a.lateBy)[0];
  if (!worst) return `Every permit needed to open fits before ${opDateLong(oc.opening.date)} at its typical processing time, if you file on the dates below.`;
  return `At its typical processing time the ${opShortTrack(worst.track).toLowerCase()} would arrive around ${opDateLong(worst.approval)}, ${worst.lateBy} days after your opening date.`;
}


/**
 * Tax and filing dates for the Operating Plan, from the national pack's federal tax calendar and
 * the state pack's report rules. Only dates the packs hold are printed; a date the packs do not
 * cover becomes a To-Do.
 */

/** Who a federal calendar row applies to, as a short, plain label. */
function opTaxAudience(appliesTo) {
  const a = String(appliesTo || '').toLowerCase();
  if (/employer/.test(a)) return 'employers';
  if (/nonemployee/.test(a)) return 'if you pay contractors';
  if (/reportable payments|rents|substitute/.test(a)) return 'if you pay rent or other reportable amounts';
  if (/s corporation|electing s/.test(a)) return 'S corporations';
  if (/c corporation/.test(a)) return 'C corporations';
  if (/partnership/.test(a)) return 'partnerships and multi-member LLCs';
  if (/sole proprietor|individual|single-member/.test(a)) return 'sole proprietors and single-member LLCs';
  return a;
}

/**
 * Federal calendar rows that matter for this business between `from` and `to`, oldest first.
 * A business that is not yet trading has no prior-year return, so rows for the tax year before it
 * started are left out.
 */
function opFederalDates(oc, from, to) {
  const firstYear = Number(oc.asOf.slice(0, 4));
  const hasStaff = oc.hires.length > 0;
  const ent = String(oc.entity || '').toLowerCase();
  return oc.R.taxCalendar
    .filter((r) => r.due_date >= from && r.due_date <= to)
    .filter((r) => {
      const yr = (String(r.description).match(/\b(20\d\d)\b/) || [])[1];
      if (!oc.opening.trading && yr && Number(yr) < firstYear) return false;
      const who = opTaxAudience(r.applies_to);
      if (who === 'employers') {
        if (!hasStaff && !oc.founderRole) return false;
        // Nothing is owed for a period that ends before the first payroll.
        const firstPay = opFirstPayroll(oc);
        const q = /Q([1-4])\s+(20\d\d)/.exec(r.description);
        const through = /through (March|June|September)/i.exec(r.description);
        let periodEnd = null;
        if (q) periodEnd = `${q[2]}-${['03-31', '06-30', '09-30', '12-31'][Number(q[1]) - 1]}`;
        else if (through && yr) periodEnd = `${yr}-${{ march: '03-31', june: '06-30', september: '09-30' }[through[1].toLowerCase()]}`;
        else if (yr) periodEnd = `${yr}-12-31`;
        if (periodEnd && firstPay && periodEnd < firstPay) return false;
      }
      if (ent) {
        if (who === 'S corporations' && !/s.?corp/.test(ent)) return false;
        if (who === 'C corporations' && !/c.?corp|corporation/.test(ent)) return false;
        if (who === 'partnerships and multi-member LLCs' && !/partner|multi/.test(ent)) return false;
      }
      return true;
    })
    .sort((a, b) => (a.due_date < b.due_date ? -1 : a.due_date > b.due_date ? 1 : 0));
}

/** First day of the first month anyone is on payroll in the model. */
function opFirstPayroll(oc) {
  const starts = (oc.hires.length ? oc.hires : oc.staffing).map((s) => Number(s.start_month) || 1);
  if (!starts.length) return null;
  return oc.monthIso(Math.max(1, Math.min(...starts)));
}

/** The state's periodic report for the planned entity, dated from the formation date when the rule allows. */
function opStateReport(oc, formationIso) {
  const st = oc.R.stateFact;
  const corp = /corp/i.test(oc.entity || '');
  const due = st(corp ? 'corp_annual_report_due' : 'llc_annual_report_due');
  const fee = st(corp ? 'corp_annual_report_fee_usd' : 'llc_annual_report_fee_usd');
  const freq = st('report_frequency');
  let date = null;
  if (due && /anniversary/i.test(String(due.value)) && formationIso) {
    const years = freq && /bienn/i.test(String(freq.value)) ? 2 : 1;
    date = opAddMonths(formationIso, 12 * years);
  }
  return { due, fee, freq, date, corp };
}

function opDueText(r) {
  return opDateLong(r.due_date);
}


