const DOCUMENT_CATALOG = Object.freeze([...RECOMMENDED_DOCUMENTS, ...OPTIONAL_DOCUMENTS]);

/**
 * The standard notice every document carries: a short form on its first page and in full at the
 * end. Written the way a professional adviser's work product states its limits.
 */
/** Bump when the notice text changes; the app asks for a fresh acknowledgment on a new version. */
const DISCLAIMER_VERSION = '2026-09-25';

/** The full notice printed on page 2 of every document, after the cover. */
const IMPORTANT_NOTICE_PARAGRAPHS = Object.freeze([
  'This document is for planning purposes only. It is not financial, legal, tax, or investment advice, and it is not an offer of credit or of securities.',
  'The projections in it are estimates built on assumptions that may not prove correct. Actual results will differ, and the differences may be material; no projection is a guarantee of future performance.',
  'Figures drawn from published sources and industry benchmarks should be verified, and estimates replaced with quotes, bids or actual results, before anyone relies on them.',
  'Consult a qualified financial advisor, accountant, and attorney before relying on this document or submitting it to a lender or investor.',
]);

const PLANNING_DISCLAIMER =
  'This document is for planning purposes only and is not financial, legal, tax, or investment advice. Consult a qualified financial advisor, accountant, and attorney before making decisions or submitting it to a lender or investor.';

/**
 * Rounds to whole dollars by magnitude rather than by signed value.
 *
 * Math.round sends .5 toward +Infinity, so -14337.5 becomes -14337 while 14337.5 becomes 14338.
 * Those two are the same quantity in this workspace — the cash-flow trough and the reserve
 * needed to cover it are defined as each other's negation — and they were printing a dollar
 * apart in consecutive sentences. Rounding the magnitude keeps a figure and its negation
 * showing the same digits. compactMoney already did this; these did not.
 */
function roundMagnitude(n) {
  const value = Number(n);
  const rounded = value < 0 ? -Math.round(-value) : Math.round(value);
  // -0 prints as "$-0"; a zero is a zero.
  return rounded === 0 ? 0 : rounded;
}

function money(n) {
  if (n == null || Number.isNaN(Number(n))) return 'Not yet quantified';
  const rounded = roundMagnitude(n);
  if (rounded < 0) return `($${Math.abs(rounded).toLocaleString('en-US')})`;
  return `$${rounded.toLocaleString('en-US')}`;
}

function pct(n, digits = 0) {
  if (n == null || Number.isNaN(Number(n))) return 'n/a';
  return `${(Number(n) * 100).toFixed(digits)}%`;
}

function article(word) {
  // An initialism is read letter by letter: "an LLC", "an S-corp", "a C-corp".
  if (/^[A-Z]{2,}\b|^[A-Z]-/.test(String(word))) return /^[AEFHILMNORSX]/.test(String(word)) ? 'an' : 'a';
  return /^[aeiou]/i.test(word) ? 'an' : 'a';
}

function money2Sum(...nums) {
  return Math.round(nums.reduce((sum, n) => sum + Number(n || 0), 0) * 100) / 100;
}

/** Whole-dollar rounding, matching what money() displays. Used to derive a total row (like Net
 * income) from other rows' own displayed whole-dollar figures, so a reader doing the subtraction
 * by hand on the printed numbers gets the same answer shown — independently rounding both the
 * total and its parts to the nearest dollar can otherwise disagree by a dollar. */
/**
 * Plural nouns without the "(s)" that marks a document as machine-filled. These documents go in
 * front of lenders; "1 closed cycle(s)" reads like a form letter, which is the one thing the
 * whole pack is trying not to be.
 */
function plural(count, singular, pluralForm = `${singular}s`) {
  return Number(count) === 1 ? singular : pluralForm;
}

function wholeDollar(n) {
  if (n == null || Number.isNaN(Number(n))) return 0;
  return roundMagnitude(n);
}

function esc(s) {
  return String(s ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

// Shared chart palette. Kept restrained (one accent, one warning tone) to read as a
// bank/investor document rather than a dashboard.
const ACCENT = '#2b2b2b';
const ACCENT_LIGHT = '#9a9a9a';
const WARN = '#5e5e5e';
const CHART_GRID = '#d8dee3';
const CHART_AXIS_TEXT = '#555555';

function fmtAxisMoney(n) {
  const abs = Math.abs(n);
  const sign = n < 0 ? '-' : '';
  if (abs >= 1000) {
    // Rounding to whole thousands here is what made evenly spaced gridlines read as uneven:
    // ticks 6,250 apart printed as -9k, -3k, 4k, 10k, 16k. A half-thousand step keeps its half.
    const k = abs / 1000;
    const text = Number.isInteger(k) ? String(k) : String(Math.round(k * 10) / 10);
    return `${sign}$${text}k`;
  }
  return `${sign}$${Math.round(abs)}`;
}

/**
 * Gridline values a reader recognises: 1, 2, 2.5 or 5 times a power of ten, with the axis ends
 * pushed out to whole multiples of that step.
 *
 * Splitting the raw data range into four equal parts puts gridlines at whatever arbitrary
 * numbers fall out — $16,000 down to -$9,000 gives ticks 6,250 apart. Nobody reads a financial
 * chart that way, and rounding those labels for display makes even spacing look uneven.
 */
function niceAxis(minValue, maxValue, targetTicks = 4) {
  let min = Number(minValue);
  let max = Number(maxValue);
  if (!Number.isFinite(min) || !Number.isFinite(max)) return { min: 0, max: 1, step: 1, values: [0, 1] };
  if (max === min) { max = min + 1; }
  const rough = (max - min) / Math.max(1, targetTicks);
  const magnitude = Math.pow(10, Math.floor(Math.log10(rough)));
  const normalized = rough / magnitude;
  // Round to the nearest nice number rather than always up. Always rounding up jumps a
  // $24k range straight to a $10k step and leaves four gridlines on the whole chart; nearest
  // picks $5k and gives seven, which is what a reader expects to see.
  const step = (normalized < 1.5 ? 1 : normalized < 3 ? 2 : normalized < 7 ? 5 : 10) * magnitude;
  const niceMin = Math.floor(min / step) * step;
  const niceMax = Math.ceil(max / step) * step;
  const values = [];
  // Multiply rather than accumulate: repeated addition of a fractional step drifts.
  const count = Math.round((niceMax - niceMin) / step);
  for (let i = 0; i <= count; i++) values.push(niceMin + i * step);
  return { min: niceMin, max: niceMax, step, values };
}

function shortenLabel(s, max = 16) {
  const str = String(s);
  return str.length > max ? `${str.slice(0, max - 1)}…` : str;
}

/**
 * Minimal inline-SVG line chart. No external libraries; every coordinate is computed
 * directly from the series values passed in, so the chart can never show a number the
 * table beside it doesn't already show.
 */
function svgLineChart({ series, xLabels, width = 640, height = 220, zeroLine = false }) {
  const padL = 56;
  const padR = 16;
  const padT = 16;
  const padB = 26;
  const plotW = width - padL - padR;
  const plotH = height - padT - padB;
  const allValues = series.flatMap((s) => s.values);
  let maxV = Math.max(...allValues, 0);
  let minV = zeroLine ? Math.min(...allValues, 0) : Math.min(...allValues);
  if (maxV === minV) {
    maxV += 1;
    minV -= 1;
  }
  const axis = niceAxis(minV, maxV);
  minV = axis.min;
  maxV = axis.max;
  const n = xLabels.length;
  const xAt = (i) => padL + (n === 1 ? 0 : (plotW * i) / (n - 1));
  const yAt = (v) => padT + plotH * (1 - (v - minV) / (maxV - minV));

  const gridLines = [];
  for (const v of axis.values) {
    const y = yAt(v);
    gridLines.push(
      `<line x1="${padL}" y1="${y.toFixed(1)}" x2="${width - padR}" y2="${y.toFixed(1)}" stroke="${CHART_GRID}" stroke-width="1" />` +
        `<text x="${padL - 8}" y="${(y + 3).toFixed(1)}" text-anchor="end" font-size="10" fill="${CHART_AXIS_TEXT}" font-family='"EB Garamond", Georgia, Gelasio, "DejaVu Serif", serif'>${esc(fmtAxisMoney(v))}</text>`,
    );
  }

  const zeroY = zeroLine && minV < 0 ? yAt(0) : null;
  const zeroLineSvg =
    zeroY != null
      ? `<line x1="${padL}" y1="${zeroY.toFixed(1)}" x2="${width - padR}" y2="${zeroY.toFixed(1)}" stroke="${CHART_AXIS_TEXT}" stroke-width="1" stroke-dasharray="3,2" />`
      : '';

  const xLabelsSvg = xLabels
    .map((l, i) => `<text x="${xAt(i).toFixed(1)}" y="${height - 8}" text-anchor="middle" font-size="9" fill="${CHART_AXIS_TEXT}" font-family='"EB Garamond", Georgia, Gelasio, "DejaVu Serif", serif'>${esc(l)}</text>`)
    .join('');

  const seriesSvg = series
    .map((s) => {
      const color = s.color || ACCENT;
      const points = s.values.map((v, i) => `${xAt(i).toFixed(1)},${yAt(v).toFixed(1)}`).join(' ');
      let areaFill = '';
      if (s.fillNegative && zeroY != null) {
        const belowPts = s.values.map((v, i) => `${xAt(i).toFixed(1)},${yAt(Math.min(v, 0)).toFixed(1)}`).join(' ');
        areaFill = `<polygon points="${xAt(0).toFixed(1)},${zeroY.toFixed(1)} ${belowPts} ${xAt(n - 1).toFixed(1)},${zeroY.toFixed(1)}" fill="${WARN}" fill-opacity="0.15" />`;
      }
      const dots = s.values
        .map((v, i) => `<circle cx="${xAt(i).toFixed(1)}" cy="${yAt(v).toFixed(1)}" r="2.25" fill="${color}" />`)
        .join('');
      return `${areaFill}<polyline points="${points}" fill="none" stroke="${color}" stroke-width="2.5" />${dots}`;
    })
    .join('');

  return `<svg viewBox="0 0 ${width} ${height}" role="img" class="doc-chart">${gridLines.join('')}${zeroLineSvg}${seriesSvg}${xLabelsSvg}</svg>`;
}

/**
 * Minimal inline-SVG grouped bar chart, same no-library / no-invented-numbers approach as svgLineChart.
 *
 * Negative values draw below a zero line. They used to be clamped to zero, which is harmless for
 * a use-of-funds chart and a lie on a profit chart: a Year 1 operating loss drew as a year that
 * broke even.
 */
function svgBarChart({ groups, width = 640, height = 220 }) {
  const padL = 56;
  const padR = 16;
  const padT = 16;
  const padB = 30;
  const plotW = width - padL - padR;
  const plotH = height - padT - padB;
  const allValues = groups.flatMap((g) => g.bars.map((b) => b.value));
  const axis = niceAxis(Math.min(...allValues, 0), Math.max(...allValues, 0) || 1);
  const maxV = axis.max;
  const minV = axis.min;
  const yAt = (v) => padT + plotH * (1 - (v - minV) / (maxV - minV));
  const zeroY = yAt(0);
  const groupW = plotW / groups.length;

  const gridLines = [];
  for (const v of axis.values) {
    const y = yAt(v);
    gridLines.push(
      `<line x1="${padL}" y1="${y.toFixed(1)}" x2="${width - padR}" y2="${y.toFixed(1)}" stroke="${CHART_GRID}" stroke-width="1" />` +
        `<text x="${padL - 8}" y="${(y + 3).toFixed(1)}" text-anchor="end" font-size="10" fill="${CHART_AXIS_TEXT}" font-family='"EB Garamond", Georgia, Gelasio, "DejaVu Serif", serif'>${esc(fmtAxisMoney(v))}</text>`,
    );
  }

  const bars = groups
    .map((g, gi) => {
      const bw = Math.min(40, (groupW * 0.6) / g.bars.length);
      const gx = padL + gi * groupW + groupW / 2;
      const totalBarsW = bw * g.bars.length + (g.bars.length - 1) * 4;
      let x = gx - totalBarsW / 2;
      const rects = g.bars
        .map((b) => {
          const yv = yAt(b.value);
          const y = Math.min(yv, zeroY);
          const h = Math.abs(zeroY - yv);
          const rect = `<rect x="${x.toFixed(1)}" y="${y.toFixed(1)}" width="${bw.toFixed(1)}" height="${h.toFixed(1)}" fill="${b.color || ACCENT}" />`;
          x += bw + 4;
          return rect;
        })
        .join('');
      const label = `<text x="${gx.toFixed(1)}" y="${height - 10}" text-anchor="middle" font-size="10" fill="${CHART_AXIS_TEXT}" font-family='"EB Garamond", Georgia, Gelasio, "DejaVu Serif", serif'>${esc(g.label)}</text>`;
      return rects + label;
    })
    .join('');

  const zeroLineSvg =
    minV < 0
      ? `<line x1="${padL}" y1="${zeroY.toFixed(1)}" x2="${width - padR}" y2="${zeroY.toFixed(1)}" stroke="${CHART_AXIS_TEXT}" stroke-width="1" />`
      : '';
  return `<svg viewBox="0 0 ${width} ${height}" role="img" class="doc-chart">${gridLines.join('')}${zeroLineSvg}${bars}</svg>`;
}

function chartLegend(items) {
  return `<p class="chart-legend">${items
    .map((it) => `<span class="swatch" style="background:${it.color}"></span>${esc(it.label)}`)
    .join(' &nbsp; ')}</p>`;
}

/**
 * The audience banner printed on a document's cover.
 *
 * On the document rather than in a manual, because a founder assembling a loan package at
 * eleven at night reads filenames and first pages, not documentation.
 */
/**
 * The distribution table on page one, built from the same catalog that labels each document —
 * so the summary and the covers cannot disagree with each other.
 */
function documentAudienceRowsHtml(pipeline) {
  const picked = new Set(selectedDocumentExtras(pipeline));
  const inPack = [
    FRONT_MATTER_DOCUMENT,
    DRAFT_NOTES_DOCUMENT,
    ...RECOMMENDED_DOCUMENTS,
    ...OPTIONAL_DOCUMENTS.filter((d) => picked.has(d.id)),
  ];
  return inPack
    .map((d) => {
      const label = audienceLabel(d.audience);
      return `<tr><td>${esc(d.name)}</td><td><strong>${esc(label.short)}</strong> — ${esc(label.who)}</td></tr>`;
    })
    .join('');
}

function audienceNoticeHtml(audience) {
  const label = audienceLabel(audience);
  return `<p class="audience-notice"><strong>${esc(label.heading)}.</strong> ${esc(label.line)}</p>`;
}

function companyTitle(pipeline) {
  // An existing business that told us its legal or public name gets that name on its documents.
  // A plan a lender reads should say who the borrower is, and "Neighborhood cafe with beer and
  // wine in Boston" is a description, not a company. The description stays as the fallback for a
  // business that genuinely has no name yet — it is never a substitute for one the founder gave.
  const disclosed = pipeline?.intake?.existing_company_deepen?.legal_or_public_name;
  const planned = pipeline?.intake?.plan_detail?.company?.name;
  const name =
    (typeof disclosed === 'string' && disclosed.trim()) ||
    (typeof planned === 'string' && planned.trim()) ||
    nameFromDescription(pipeline?.intake?.business_description) ||
    pipeline?.intake?.business_description ||
    'Untitled Company';
  return name.length > 72 ? `${name.slice(0, 69)}…` : name;
}

/**
 * The business's own name, when the founder opened their description with it.
 *
 * "Ellery Coffee & Wine is a founder-owned neighborhood cafe…" names the business in its first
 * words, and the pack printed the whole sentence — cut off at 72 characters — as the company
 * name on every cover and page header. A lender read "Ellery Coffee & Wine is a founder-owned
 * neighborhood cafe and wine ba…" where a borrower's name belongs.
 *
 * Only a run of capitalised words followed directly by a verb counts ("X is", "X will", "X
 * offers"), so a description that opens with a category ("Neighborhood cafe with beer and wine")
 * is left alone and no name is guessed. Nothing is invented: the name is the founder's own words.
 */
function nameFromDescription(description) {
  const text = String(description || '').trim();
  const m = text.match(
    /^((?:[A-Z0-9][\w'’.&-]*)(?:\s+(?:&|and|of|the|de|la|[A-Z0-9][\w'’.&-]*))*)\s+(?:is|are|will|provides|offers|sells|makes|builds|helps|runs|operates)\b/,
  );
  if (!m) return null;
  const name = m[1].trim();
  if (/^(we|i|it|this|our|my|they|he|she|a|an|the)$/i.test(name)) return null;
  if (name.length < 2 || name.length > 60) return null;
  return name;
}

/** Whether the company title is a real name rather than the description standing in for one. */
function hasBusinessName(pipeline) {
  const intake = pipeline?.intake || {};
  return Boolean(
    String(intake.existing_company_deepen?.legal_or_public_name || '').trim() ||
      String(intake.plan_detail?.company?.name || '').trim() ||
      nameFromDescription(intake.business_description),
  );
}

/**
 * How running prose refers to the business.
 *
 * With no name, the title falls back to the description cut at 72 characters, which is tolerable
 * on a cover but not mid-sentence: "Residential and small-office cleaning service run by the
 * founder, sta… is an idea-stage business" is what the executive summary printed. Prose says
 * "The business" instead, and the cover carries the description in full.
 */
function planSubject(pipeline, { lower = false } = {}) {
  if (hasBusinessName(pipeline)) return companyTitle(pipeline);
  return lower ? 'this business' : 'This';
}

/** A founder's phrase with its closing punctuation removed, for use mid-sentence. */
function clause(text) {
  return String(text ?? '').trim().replace(/[.!?;:,\s]+$/, '');
}

/**
 * A founder's answer spliced into the middle of a sentence. Answers are typed as sentences, so
 * they start with a capital: "…business serving Office workers at lunch through Food sales,
 * catering." Only a first word that is a common word is lowered — "Texas farms", "Google
 * Workspace users" and "SBA loan" keep their capitals, because a proper noun cannot be told from
 * a common one by its shape.
 */
const COMMON_OPENERS = new Set(
  (
    'a an the small smaller large larger mid midsize medium local busy young older new existing independent ' +
    'office owners owner families family parents homeowners renters residents neighborhood nearby people ' +
    'customers clients businesses companies firms startups restaurants farms farmers retailers shoppers ' +
    'students teachers schools seniors adults kids children women men pet pets dog dogs event events tourists ' +
    'visitors travelers commuters professionals workers employees managers teams food hardware software ' +
    'product products services service consulting subscription subscriptions sales online direct wholesale ' +
    'retail monthly annual recurring catering coffee drinks meals health healthcare hospitals clinics ' +
    'nonprofits churches contractors builders landlords property drivers fleet manufacturers suppliers ' +
    'distributors government agencies universities colleges gyms athletes musicians artists creators couples ' +
    'patients members subscribers users developers engineers designers marketing advertising advisory coaching ' +
    'training tuition fees commissions licensing rentals memberships tickets donations grants ads venue hotels ' +
    'working budget premium luxury value vegetable organic mostly primarily mainly both hourly project ' +
    'weekend weekly daily individual individuals regional national'
  ).split(' '),
);

function asMidSentence(text) {
  const t = clause(text);
  const m = /^([A-Z][a-z]+)(?=$|[\s,;:'’-])/.exec(t);
  if (!m || !COMMON_OPENERS.has(m[1].toLowerCase())) return t;
  return m[1].toLowerCase() + t.slice(m[1].length);
}

/**
 * The founder's outside-money answer as the object of "structured as …". "Raising $750k seed
 * equity from angel investors" printed "structured as Raising $750k seed equity…"; the verb and a
 * leading "yes," are the founder answering the question, not describing the financing.
 */
function fundingStructurePhrase(raw) {
  let t = clause(raw)
    .replace(/^(yes|yeah|yep)\b[\s,:;.-]*/i, '')
    .replace(/^(we are|we're|we will be|i am|i'm|i will be)\s+/i, '')
    .replace(/^(raising|seeking|looking for|looking to raise|planning to raise|plan to raise|hoping to raise|want to raise|would like|need|asking for|applying for|getting)\s+/i, '');
  t = asMidSentence(t);
  return t || clause(raw);
}

function locationLine(pipeline) {
  const summary = pipeline?.render_model?.location_summary;
  // The render model's label for this case is "Not decided — jurisdiction finals blocked", which
  // is the pipeline describing its own gating to itself. A reader of the plan needs to know the
  // location is undecided, not which internal outputs that holds back.
  if (summary?.status === 'not_decided' || pipeline?.location?.status === 'not_decided') return 'Location not decided';
  if (summary?.label) return summary.label;
  const loc = pipeline?.location;
  if (!loc || loc.status === 'not_decided') return 'Location not decided';
  return [loc.primary_city, loc.state_code].filter(Boolean).join(', ') || 'Location pending';
}

/**
 * The location as a sentence says it: "Atlanta, Georgia", "Boston, Massachusetts (Suffolk
 * County)", "Texas". locationLine() is the label form ("Boston, MA · Suffolk County") used on
 * covers and in tables; spliced into prose it printed "operating in Atlanta · GA".
 * Anything not resolved to a place falls back to that label.
 */
function locationProse(pipeline) {
  const line = locationLine(pipeline);
  const loc = pipeline?.location;
  if (!loc || loc.ok === false || loc.status === 'not_decided' || /not decided|pending/i.test(line)) return line;
  const state = loc.state_name || loc.state_code;
  const place = loc.primary_city ? [loc.primary_city, state].filter(Boolean).join(', ') : state;
  if (!place) return line;
  if (!loc.county?.name) return place;
  // The Census crosswalk names carry their own kind ("Suffolk County", "Orleans Parish").
  const county = / (County|Parish|Borough|Census Area|Municipality|city|City and Borough)$/.test(loc.county.name) ? loc.county.name : `${loc.county.name} County`;
  return `${place} (${county})`;
}

function stageLabel(pipeline) {
  const stage = pipeline?.intake?.stage;
  return STAGE_NAMES[stage] || stage || 'Idea';
}

function revenueLine(pipeline) {
  const rm = pipeline?.intake?.revenue_model;
  if (!rm || rm.status === 'unknown') return 'Revenue model not yet decided';
  if (Array.isArray(rm.channels) && rm.channels.length) return rm.channels.join(', ');
  return 'Revenue model noted';
}

function personalCapitalUsd(pipeline) {
  const pc = pipeline?.finance?.personal_capital;
  if (pc && pc.available_usd != null) return pc.available_usd;
  return null;
}

function complianceSummary(pipeline) {
  return pipeline?.render_model?.compliance_summary || {};
}

function complianceTracks(pipeline) {
  return complianceSummary(pipeline).tracks || [];
}

function blockedList(pipeline) {
  return pipeline?.review?.blocked_outputs || [];
}

function plainLicenseName(label) {
  if (!label) return 'License';
  return String(label)
    .replace(/\s*\(if applicable\)/i, '')
    .replace(/\s*\/\s*Companies House equivalent/i, '')
    .replace(/\s*posture$/i, '')
    .replace(/\s*screen$/i, '')
    .trim();
}

/**
 * The licensing timeline as the model schedules it: each license's expected lead time (the
 * typical processing time, or the planning allowance when its window is closed and it waits for
 * the next cycle), what it holds back (the opening, or a product that needs it), and the month it
 * is expected. Every document reads the opening and product start months from here, so the text,
 * the milestones and the statements agree.
 */
function openingFacts(pipeline) {
  const fin = pipeline?.finance || {};
  const sch = fin.cost_model?.schedule;
  if (!sch) return null;
  const tiers = fin.revenue_model?.tiers || fin.projections?.revenue_model?.tiers || [];
  const gatedTiers = tiers.filter((t) => t.license && t.start_month > sch.opening_month);
  const rows = complianceTracks(pipeline).map((t) => {
    const used = scheduledDays(t);
    const known = used.days != null && Number.isFinite(Number(used.days));
    const required = sch.required_permits.find((p) => p.id === t.id);
    const products = gatedTiers.filter((x) => x.license.id === t.id);
    return {
      track: t,
      name: plainLicenseName(t.label),
      lead_months: known ? leadMonths(used.days) : null,
      basis: used.basis,
      allowance_months: t.planning_days != null ? leadMonths(t.planning_days) : null,
      approval_month: known ? approvalMonth(used.days) : null,
      gates: required ? 'opening' : products.length ? 'product' : null,
      products,
      start_month: products.length ? products[0].start_month : null,
    };
  });
  const binding = rows.filter((r) => r.gates === 'opening').sort((a, b) => b.approval_month - a.approval_month)[0] || null;
  return { sch, rows, binding, gatedTiers };
}

function monthsText(n) {
  return `${n} ${n === 1 ? 'month' : 'months'}`;
}

/** "Evening wine and small plates" / "A and B", for the products a license holds back. */
function productList(tiers) {
  return joinClauses(tiers.map((t) => t.name));
}

function risksHtml(pipeline) {
  const blocked = blockedList(pipeline);
  const items = blocked.slice(0, 8).map((b) => {
    const code = typeof b === 'string' ? b : b.output;
    const reason =
      typeof b === 'string'
        ? 'Held until required facts are confirmed.'
        : b.reason || 'Held until required facts are confirmed.';
    return `<li><strong>${esc(blockedOutputName(code))}</strong>: ${esc(reason)}</li>`;
  });
  if (!items.length) {
    return '<p>No hard blocks on the current screen. Continue confirming assumptions before publish.</p>';
  }
  return `<ul>${items.join('')}</ul>`;
}

function selectedDocumentExtras(pipeline) {
  const extras = pipeline?.intake?.interview_deepen?.document_extras;
  return Array.isArray(extras) ? extras.map(String) : [];
}

/** The finance engine's spend buckets, as a reader says them (the ids printed raw before). */
const SPEND_BUCKET_NAMES = Object.freeze({
  needed: 'Needed to open',
  wanted: 'Wanted for polish',
  can_do_without: 'Can do without for 90 days',
});

function gapOptionsHtml(pipeline) {
  const gap = pipeline?.finance?.gap_options;
  if (!gap) return '<p>Funding gap notes are not available on this draft.</p>';
  if (!gap.has_gap) {
    return `<p>${esc(gap.headline || 'There is no funding gap on these figures.')}</p>`;
  }
  // A plan whose loan covers the gap (and works) is not short of money: these options lower what
  // it borrows. Said as "still to find", the same figures read as a hole the loan already fills.
  const loan = pipeline.finance?.projections?.loan;
  const loanCovers = Boolean(loan && loan.principal_usd >= gap.gap_usd - 1 && pipeline.finance?.funding_need?.works !== false);
  const recommendedKind = gap.ranking?.recommended_id;
  const opts = (gap.options || [])
    .map((o) => {
      const isRecommended = recommendedKind != null && o.kind === recommendedKind;
      const relief = o.estimated_relief_usd != null ? ` (about ${esc(money(o.estimated_relief_usd))} less)` : '';
      return `<li${isRecommended ? ' class="recommended"' : ''}><strong>${esc(o.title)}</strong>${
        isRecommended ? ' <span class="doc-muted">(recommended first)</span>' : ''
      }: ${esc(o.detail)}${relief}</li>`;
    })
    .join('');
  const buckets = (gap.needed_vs_wanted || [])
    .map((b) => `<li><strong>${esc(SPEND_BUCKET_NAMES[b.bucket] || b.bucket)}</strong>: ${esc(clause(b.examples))}</li>`)
    .join('');
  const free = (gap.free_money_paths || [])
    .map((p) => `<li><strong>${esc(p.title)}</strong>: ${esc(p.detail)}</li>`)
    .join('');
  const recommendation =
    recommendedKind != null
      ? `<p>Of the options below, the one to try first is <strong>${esc(
          (gap.options || []).find((o) => o.kind === recommendedKind)?.title || '',
        )}</strong>: weighed for the best real result (cost, time and risk together), not just the cheapest or the fastest on its own. You can pick a different order; these are starting points, not requirements.</p>`
      : '';
  // What the list is worth once the founder has done all of it.
  //
  // The heading says "ways to close the gap", the options are individually plausible, and nothing
  // added them up: on the sample cafe they come to $24,025 against a $37,500 gap, so someone who
  // does every one of them is still $13,475 short. A founder could reasonably read this section
  // as a route out and skip the financing conversation on the strength of it.
  const combined = gap.combined_relief_usd;
  const remaining = gap.remaining_after_options_usd;
  const share = Math.round((combined / gap.gap_usd) * 100);
  const arithmetic =
    combined > 0
      ? loanCovers
        ? `<p>Done together, the options with a figure come to about <strong>${esc(money(combined))}</strong>, roughly ${esc(Math.min(100, share))}% less to borrow. Confirm each figure against real quotes before relying on it.</p>`
        : gap.options_close_the_gap
          ? `<p>Done together, the options with a figure come to about <strong>${esc(money(combined))}</strong>, which covers the gap. Confirm each figure against real quotes before relying on it.</p>`
          : `<p>Done together, the options with a figure come to about <strong>${esc(money(combined))}</strong>, roughly ${esc(share)}% of the gap, leaving about <strong>${esc(money(remaining))}</strong> still to find. Trimming helps here; on these figures it does not finish the job.</p>`
      : '';
  const headline = loanCovers ? `${gap.headline} The loan in your funding request covers it; the options below lower what you borrow.` : gap.headline;

  return `<p><strong>${esc(headline)}</strong></p>
<p>Sort what you spend into three groups:</p>
<ul>${buckets || '<li>Add what you must spend and what can wait in the interview, and they are sorted here.</li>'}</ul>
<p>${loanCovers ? 'Ways to borrow less:' : 'Ways to need less outside money:'}</p>
${recommendation}
<ul>${opts}</ul>
${arithmetic}
${free ? `<p>Kinds of funding you said you are considering:</p><ul>${free}</ul>` : ''}`;
}

function improvementsHtml(pipeline, domain) {
  const pack = pipeline?.finance?.business_improvements;
  const items = (pack?.items || []).filter((i) => !domain || i.domain === domain);
  if (!items.length) {
    return domain
      ? `<p class="doc-muted">No ${esc(domain)} improvement notes on this draft yet.</p>`
      : '<p class="doc-muted">No additional improvement notes on this draft yet.</p>';
  }
  return `<ul>${items
    .map((i) => `<li><strong>${esc(i.title)}</strong>: ${esc(i.detail)}</li>`)
    .join('')}</ul>`;
}

function joinClauses(bits) {
  if (!bits.length) return '';
  if (bits.length === 1) return bits[0];
  if (bits.length === 2) return `${bits[0]} and ${bits[1]}`;
  return `${bits.slice(0, -1).join(', ')}, and ${bits[bits.length - 1]}`;
}

/** Founder's own additional detail, written as narrative rather than a label:value dump. */
function founderDetailProse(pipeline) {
  const d = pipeline?.intake?.interview_deepen || {};
  const fin = d.financial || {};
  const ops = d.operational || {};
  const strat = d.strategic || {};
  const paragraphs = [];

  const finBits = [];
  if (fin.must_have_spend) finBits.push(`treat <strong>${esc(fin.must_have_spend)}</strong> as must-have spend`);
  if (fin.can_defer_spend) finBits.push(`can defer <strong>${esc(fin.can_defer_spend)}</strong> if needed`);
  if (fin.monthly_burn_comfort_usd != null)
    finBits.push(`are comfortable with monthly spending up to <strong>${esc(money(fin.monthly_burn_comfort_usd))}</strong>`);
  const timing = codeLabel(FIRST_REVENUE_TIMING_NAMES, fin.first_revenue_timing);
  if (timing) finBits.push(fin.first_revenue_timing === 'already' ? `are <strong>${esc(timing)}</strong>` : `expect first revenue <strong>${esc(timing)}</strong>`);
  if (finBits.length) paragraphs.push(`<p>On spending, you ${joinClauses(finBits)}.</p>`);

  const opsBits = [];
  const space = codeLabel(SPACE_TYPE_NAMES, ops.space_type);
  const team = codeLabel(TEAM_SIZE_NAMES, ops.team_now);
  const hours = codeLabel(WEEKLY_HOURS_NAMES, ops.weekly_hours);
  if (space) opsBits.push(`plan to operate from <strong>${esc(space)}</strong>`);
  if (team) opsBits.push(`are starting with <strong>${esc(team)}</strong>`);
  if (hours) opsBits.push(`expect to commit <strong>${esc(hours)}</strong> a week`);
  // Deliberately not repeated here: first_customer_path is a plan requirement now and Marketing
  // and Sales Strategy carries it. Saying it twice in one document reads as padding, and it was
  // appearing in both once the completion questions started collecting it.
  if (opsBits.length) paragraphs.push(`<p>On operations, you ${joinClauses(opsBits)}.</p>`);

  const stratBits = [];
  if (strat.ninety_day_goal) stratBits.push(`are targeting “${esc(strat.ninety_day_goal)}” as the 90-day goal`);
  if (strat.edge_one_liner) stratBits.push(`describe your edge as “${esc(strat.edge_one_liner)}”`);
  if (strat.biggest_risk) stratBits.push(`name “${esc(strat.biggest_risk)}” as the biggest risk`);
  if (stratBits.length) paragraphs.push(`<p>Strategically, you ${joinClauses(stratBits)}.</p>`);

  if (!paragraphs.length) {
    // Empty rather than a sentence reporting emptiness: the caller omits the heading entirely.
    return '';
  }
  return paragraphs.join('\n');
}

/** The privacy statement for the owner's own documents. Never printed on lender documents. */
const PRIVACY_STATEMENT =
  "Your business plan information stays on your device. Foundry doesn't send it to MaterialLogix or anyone else, and it's never used to train anything.";

function buildReadThisFirst(pipeline, asOf) {
  const loc = locationLine(pipeline);
  const picked = new Set(selectedDocumentExtras(pipeline));
  const extras = OPTIONAL_DOCUMENTS.filter((d) => picked.has(d.id)).map((d) => d.name);
  return {
    id: FRONT_MATTER_DOCUMENT.id,
    name: FRONT_MATTER_DOCUMENT.name,
    filename: FRONT_MATTER_DOCUMENT.filename,
    purpose: FRONT_MATTER_DOCUMENT.purpose,
    tier: 'front_matter',
    status: 'notice',
    snippet: `Jurisdiction notices for ${companyTitle(pipeline)} · ${loc}. Read before the rest of this pack.`,
    sections: [
      {
        id: 'front_cover',
        heading: 'Read This First',
        body_html: `<p><strong>${esc(companyTitle(pipeline))}</strong></p>
<p>Document pack prepared ${esc(asOf)}${loc && !/not decided/i.test(loc) ? ` · ${esc(loc)}` : ''}</p>
<p>This memo explains what is in the pack, who each document is for, and what to confirm before you rely on it. The pack is a planning document. It is not an award, a loan offer, an agency approval or a professional sign-off.</p>`,
      },
      {
        id: 'privacy',
        heading: 'Your Information',
        body_html: `<p>${esc(PRIVACY_STATEMENT)}</p>`,
      },
      {
        id: 'pack_contents',
        heading: 'What Is in This Pack',
        body_html: `<table class="doc-table">
<tr><th>Document</th><th>What it is</th></tr>
<tr><td>Business Plan</td><td>The lender and investor plan, written in the company's voice: company, market, competition, management, operations, marketing, funding request and financial plan.</td></tr>
<tr><td>Financial Statements</td><td>Start-up costs and capital required, sources and uses, sales forecast, cost build-up, monthly Year 1 and annual Years 1-3 statements, balance sheets, break-even, sensitivity and debt service.</td></tr>
<tr><td>Founder's Notes</td><td>Your adviser's memo: the checks behind the numbers, what to confirm, how to prepare for the lender, and where every figure comes from.</td></tr>
<tr><td>Local Licenses</td><td>The permit and license schedule for your location, with lead times and filing windows.</td></tr>
<tr><td>To-Do List</td><td>Your action plan, in priority order.</td></tr>
<tr><td>Operating Plan</td><td>Your step-by-step manual to open and run the business: a dated launch timeline, registrations and licenses, start-up costs, suppliers, pricing, hiring, daily procedures, marketing, money management, weekly numbers and what to do when things go wrong.</td></tr>
<tr><td>Draft Notes</td><td>Your interview answers as the pack recorded them, to check.</td></tr>
${extras.map((n) => `<tr><td>${esc(n)}</td><td>${esc(OPTIONAL_DOCUMENTS.find((d) => d.name === n)?.purpose || '')}</td></tr>`).join('')}
</table>`,
      },
      {
        id: 'who_gets_what',
        heading: 'Who Gets Which Document',
        body_html: `<p>Not every document here is meant to leave your hands. Check this table before you attach anything to an email.</p>
<table class="doc-table">
<tr><th>Document</th><th>Who may see it</th></tr>
${documentAudienceRowsHtml(pipeline)}
</table>
<p><strong>In short:</strong> the Business Plan goes to anyone you are asking for money or a lease. Financial Statements go to a lender or investor underwriting you. Everything else is yours: it contains your negotiating position, your fallback options and the items still open.</p>`,
      },
      {
        id: 'how_to_use',
        heading: 'Before You Submit',
        body_html: `<ol>
<li>Work through the To-Do List, starting with priority 1.</li>
<li>Read Founder's Notes, especially the checks on the forecast and the items to confirm.</li>
<li>Replace benchmark figures with quotes: the lease, equipment and buildout bids, insurance.</li>
<li>Have your accountant review the Financial Statements before a lender sees them.</li>
<li>Regenerate the pack after each change so every document agrees.</li>
</ol>`,
      },
      { id: 'juris_short', heading: 'Jurisdiction Coverage', body_html: `<p>${esc(JURISDICTION_SCREEN_NOTICE.short)}</p>` },
      { id: 'juris_licenses', heading: 'Licenses and Permits', body_html: `<p>${esc(JURISDICTION_SCREEN_NOTICE.licenses)}</p>` },
      { id: 'juris_funding', heading: 'Grants, Loans, Incubators and Equity', body_html: `<p>${esc(JURISDICTION_SCREEN_NOTICE.funding)}</p>` },
      { id: 'juris_legal', heading: 'Formation and Commercial Matters', body_html: `<p>${esc(JURISDICTION_SCREEN_NOTICE.legal)}</p>` },
      { id: 'front_disclaimer', heading: 'Notice', body_html: `<p>${esc(PLANNING_DISCLAIMER)}</p>` },
    ],
  };
}

/** Plan start date, as the founder's documents explain it. */
function planStartHtml(pipeline, asOf) {
  const cal = planCalendar(pipeline, asOf);
  const opening = pipeline.intake?.opening;
  const lead =
    cal.basis === 'founder'
      ? `The plan starts in ${cal.long(1)}, the start date you gave.`
      : cal.basis === 'opening' || cal.basis === 'opening_default'
        ? `The plan starts in ${cal.long(1)}, the month of the plan date, and counts every month from there.${cal.basis === 'opening' ? ` You asked to open ${opening.choice === 'asap' ? 'as soon as possible' : `in ${cal.long(opening.model_month)}`}.` : ' You did not pick an opening date, so the plan asked for one three months out.'}`
        : cal.basis === 'immediate'
        ? `You said the business can start right away, so the plan starts in ${cal.long(1)}, the month after the plan date.`
        : `You did not give a start date, so the plan assumes a start three months after the plan date: month 1 is ${cal.long(1)}.`;
  const proj = pipeline.finance?.projections;
  const firstRevenue = proj ? proj.year1_monthly.findIndex((m) => m.revenue_usd > 0) + 1 : 0;
  return `<p>${esc(lead)}${firstRevenue > 0 ? ` ${esc(`The forecast opens for business in month ${firstRevenue} (${cal.long(firstRevenue)}).`)}` : ''} Every date in the Business Plan and Financial Statements counts from it. Give a start date in the interview to move the whole calendar.</p>`;
}

/**
 * Why the plan opens when it does, what the months before opening cost, and (from the model re-run)
 * what opening on the founder's date, or a slower permit, would change.
 */
function openingNotesHtml(pipeline, asOf) {
  const fin = pipeline.finance || {};
  const oa = fin.opening_analysis;
  const facts = openingFacts(pipeline);
  if (!oa || !facts) return '';
  const cal = planCalendar(pipeline, asOf);
  const sch = oa.schedule;
  const when = (m) => `${cal.long(m)} (month ${m})`;
  const intake = pipeline.intake || {};
  const timing = intake.interview_deepen?.financial?.first_revenue_timing;
  const asked =
    sch.request_source === 'asap'
      ? 'You asked to open as soon as possible'
      : sch.request_source === 'date'
        ? `You asked to open in ${cal.long(sch.requested_month)}`
        : sch.request_source === 'timing'
          ? `You expected first sales ${FIRST_REVENUE_TIMING_NAMES[timing] || 'soon'} (month ${sch.requested_month})`
          : sch.request_source === 'default'
            ? `No opening date was picked, so the plan asked for ${cal.long(sch.requested_month)}`
            : 'You did not give an opening date';
  const parts = [];
  const b = facts.binding;
  if (sch.binding === 'permit' && b) {
    parts.push(`${asked}. The plan opens in ${when(sch.opening_month)} instead, because a ${lowerFirst(b.name.replace(/ screen$/i, ''))} is needed before the doors open and it typically takes about ${monthsText(b.lead_months)} from filing. Filed in month 1, it is expected in ${cal.long(b.approval_month)}.`);
  } else if (sch.binding === 'stage') {
    parts.push(`${asked}. A business at this stage needs time for formation, financing and fit-out, so the plan opens in ${when(sch.opening_month)}.${b ? ` The approvals needed to open (the longest, the ${lowerFirst(b.name)}) are expected by ${cal.long(b.approval_month)}.` : ''}`);
  } else {
    parts.push(`${asked}, and the plan opens then, in ${when(sch.opening_month)}.${b ? ` The approvals needed to open are expected before it (the longest, the ${lowerFirst(b.name)}, by ${cal.long(b.approval_month)}).` : ' No permit has to be in hand before the business can trade.'}`);
  }
  const pre = oa.pre_opening;
  if (pre.months > 0) {
    const lease = pre.lease_start_month && pre.lease_start_month <= pre.months ? pre.lease_start_month : null;
    parts.push(`The ${monthsText(pre.months)} before opening cost ${money(pre.total_usd)}: your pay (${money(pre.owner_pay_usd)})${lease ? ` and, from the lease start in ${cal.long(lease)}, rent and insurance, with utilities at a quarter of the running level during the buildout (${money(pre.premises_usd)})` : ''}. Staff, marketing and the other running costs start at opening. The last month before opening costs ${money(pre.last_month_usd)}, so each month the opening slips adds about that much, plus loan payments, to the capital needed.`);
  }
  const fr = oa.founder_requested;
  if (fr) {
    const need = fr.permits_needed.map((p) => `the ${lowerFirst(plainLicenseName(p.label))} approved within ${monthsText(p.needed_within_months)} of filing (typical: about ${p.lead_months})`);
    parts.push(`To open in ${cal.long(fr.opening_month)}${sch.requested_month != null && fr.opening_month > sch.requested_month ? ` (month ${fr.opening_month}, the earliest a new business can open after formation, financing and fit-out)` : ' as you asked'}, you would need ${joinClauses(need)}. That happens where a space was already permitted for the same use and the office's queue is short, so ask the issuing office for its current turnaround before you sign a lease. Opening then would need ${money(fr.total_capital_usd)} in total, ${money(oa.base.total_capital_usd - fr.total_capital_usd)} less than this plan, with Year 1 sales of ${money(fr.year1_revenue_usd)} instead of ${money(oa.base.year1_revenue_usd)}.`);
  }
  const d = oa.permit_delay;
  if (d && b) {
    parts.push(`The other way: if the ${lowerFirst(b.name)} takes the full ${monthsText(b.allowance_months)} the licensing research allows for, opening moves to ${when(d.opening_month)} and the project needs ${money(d.total_capital_usd)}, ${money(d.total_capital_usd - oa.base.total_capital_usd)} more than this plan. The contingency does not cover all of that; know where the rest would come from.`);
  }
  for (const r of facts.rows.filter((x) => x.gates === 'product')) {
    const small = r.products.some((t) => /\band\b/i.test(t.name));
    parts.push(`${productList(r.products)} ${r.products.length === 1 ? 'waits' : 'wait'} for the ${lowerFirst(r.name)}. ${r.basis === 'next_cycle' ? `Its application window is treated as closed, so the plan schedules the license for the next cycle, about ${monthsText(r.lead_months)} from now` : `It typically takes about ${monthsText(r.lead_months)}`}, and those sales start in ${when(r.start_month)}.${small ? ' If part of that line can be sold without the license (food in the evening, for example), enter it as its own product in the interview so it starts at opening.' : ''} An earlier license brings that revenue forward; ask the licensing board for its next window.`);
  }
  return parts.map((x) => `<p>${esc(x)}</p>`).join('\n');
}

/**
 * The ways to bring debt coverage to the lender's line and keep owner's equity positive, each
 * computed by the model from the same forecast (finance.financing_options).
 */
function financingOptionsHtml(pipeline) {
  const fin = pipeline.finance || {};
  const fo = fin.financing_options;
  const proj = fin.projections;
  if (!fo) return '<p>No loan is modeled, so there is no coverage to work on.</p>';
  const x = (v) => (v == null ? 'not covered' : `${v.toFixed(2)}×`);
  const coverage = fo.years.map((y) => `Year ${y.year} ${x(y.dscr)}`).join(', ');
  const parts = [];
  const short = fo.years.filter((y) => y.year >= 2 && !y.meets_target);
  parts.push(`Debt service coverage on the ${money(fo.loan_usd)} loan (${(fo.annual_rate * 100).toFixed(2)}%, ${fo.term_years} years) is ${coverage}, against the ${fo.target_dscr.toFixed(2)}× most lenders look for.${fo.equity_positive ? ` Owner's equity falls to ${money(fo.equity_positive.lowest_equity_usd)} at the end of Year ${fo.equity_positive.lowest_year}.` : ''} The lender documents show these figures as they are. ${short.length ? 'These are the ways to close the gap, each computed from the same forecast:' : 'Coverage clears the line after Year 1; these options ease the ramp:'}`);
  const rows = [];
  for (const y of short) {
    if (y.equity_to_reach_target_usd == null) {
      rows.push([`More owner equity (Year ${y.year})`, `No loan size reaches ${fo.target_dscr.toFixed(2)}× in Year ${y.year}: earnings before interest that year are ${money(y.ebitda_usd)}.`, 'Only higher sales or lower costs in that year change this.']);
    } else {
      rows.push([`More owner equity, or a smaller project (Year ${y.year})`, `${money(y.equity_to_reach_target_usd)} more from you (or that much less spent), borrowing ${money(y.max_loan_at_target_usd)}`, `Year ${y.year} coverage reaches ${fo.target_dscr.toFixed(2)}×.`]);
    }
  }
  for (const lt of fo.longer_terms) {
    rows.push([`A ${lt.term_years}-year term`, `Payment of ${money(lt.monthly_payment_usd)} a month`, `${lt.dscr_by_year.filter((d) => d.year >= 2).map((d) => `Year ${d.year} ${x(d.dscr)}`).join(', ')}. SBA 7(a) allows more than 10 years only for real estate, so this needs a property component or another program.`]);
  }
  const io = fo.interest_only;
  rows.push([
    `Interest only for the first ${io.months} months`,
    `Year 1 payments of ${money(io.year1_payments_usd)}, then ${money(io.monthly_payment_after_usd)} a month`,
    `Year 1 cash improves by ${money(io.year1_cash_saved_usd)}; ${io.dscr_by_year.filter((d) => d.year >= 2).map((d) => `Year ${d.year} ${x(d.dscr)}`).join(', ')} because the loan then repays over fewer months.`,
  ]);
  if (fo.defer_owner_pay) {
    rows.push(['Take no pay until opening', `${money(fo.defer_owner_pay.saving_usd)} over the ${monthsText(fo.defer_owner_pay.months)} before opening`, 'Lowers the capital needed by about that much (plus the contingency on it); coverage is unchanged.']);
  }
  if (fo.equity_positive) {
    rows.push(["Keep owner's equity above zero", `${money(fo.equity_positive.injection_usd)} more equity at the start`, `Covers the losses to the end of Year ${fo.equity_positive.lowest_year}; lenders read negative equity as the owner's cushion being gone.`]);
  }
  return `<p>${esc(parts[0])}</p>
<table class="doc-table"><tr><th>Option</th><th>What it takes</th><th>Effect</th></tr>${rows.map((r) => `<tr>${r.map((c) => `<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</table>
<p>${esc('The options combine: a smaller loan with an interest-only start is a common first offer to a new business. Take the figures to the lender as the basis for the conversation, not as terms.')}</p>`;
}

/** Why a plan does not work as structured, in plain words with the model's own figures. */
function fundingProblemSentences(pipeline, asOf) {
  const fn = pipeline.finance?.funding_need;
  if (!fn || fn.works) return [];
  const ctx = { ...bpContext(pipeline), cal: planCalendar(pipeline, asOf) };
  const out = [];
  if (fn.reasons.includes('break_even_beyond_horizon')) {
    out.push(
      `On the forecast the business does not reach monthly cash break-even ${fn.break_even_month ? `until ${bpWhen(ctx, fn.break_even_month)}` : 'within the 36 months projected'}, past the funding horizon of ${bpWhen(ctx, fn.horizon_months)}, ${monthsText(fn.horizon_months_after_opening)} after opening.`,
    );
  }
  if (fn.reasons.includes('coverage_below_minimum_year2')) {
    out.push(fn.dscr_year2 > 0 ? `Year 2 earnings cover the loan payments ${fn.dscr_year2.toFixed(2)} times, under the ${fn.dscr_target.toFixed(2)} times lenders underwrite to.` : `Year 2 earnings before interest, tax and depreciation are negative, so they cover none of the loan payments; lenders underwrite to ${fn.dscr_target.toFixed(2)} times.`);
  }
  if (fn.reasons.includes('phase2_not_funded_from_cash') && fn.phase2) {
    out.push(`The second phase (${money(fn.phase2.capex_usd)} of equipment and build-out in ${bpWhen(ctx, fn.phase2.month)}) would leave less than the contingency reserve in hand; the business's cash cannot yet pay for it.`);
  }
  out.push(
    `The plan does not borrow to fund the gap. The lender documents show the capital needed to ${bpWhen(ctx, fn.horizon_months)} (${money(fn.need_usd)})${fn.unfunded_losses_after_horizon_usd > 0 ? ` and state the further ${money(fn.unfunded_losses_after_horizon_usd)} of losses after it as unfunded` : ''}.`,
  );
  return out;
}

/** "This plan does not work as structured yet": the model-computed levers, one change at a time. */
function fundingFixHtml(pipeline, asOf) {
  const fin = pipeline.finance || {};
  const fn = fin.funding_need;
  if (!fn || fn.works || fn.rule !== 'break_even') return '';
  const ctx = { ...bpContext(pipeline), cal: planCalendar(pipeline, asOf) };
  const cov = (v) => (v == null ? 'No loan' : v > 0 ? `${v.toFixed(2)}×` : 'Not covered');
  const be = (m) => (m ? `Month ${m}` : 'After month 36');
  const total = fin.projections?.sources_and_uses?.total_sources_usd || 0;
  const rows = [];
  for (const l of fn.levers || []) {
    const r = l.result || {};
    if (l.id === 'loan_term') {
      for (const t of l.terms) {
        rows.push([`A ${t.term_years}-year loan term`, `${t.term_years} years instead of ${l.standard_max_years}${t.term_years > l.standard_max_years ? ` (SBA 7(a) allows more than ${l.standard_max_years} years only with real estate)` : ''}`, t.works ? 'Works on its own' : 'Not enough on its own', be(t.break_even_month), cov(t.dscr_year2)]);
      }
      continue;
    }
    const c = l.reached ? l.change : l.limit;
    let what;
    if (l.id === 'price') what = `Prices ${c.change_pct}% higher across the board`;
    else if (l.id === 'volume') what = `Sales volume ${c.change_pct}% higher in every month`;
    else if (l.id === 'rent') what = `Rent of ${money(c.to_usd)} a month instead of ${money(c.from_usd)} (${c.change_pct}% lower)`;
    else if (l.id === 'staffing') what = `Staff payroll ${c.change_pct}% lower, about ${money(c.to_usd)} a month instead of ${money(c.from_usd)} (fewer hours or roles)`;
    else if (l.id === 'owner_pay') what = c.to_usd > 0 ? `Owner's pay of ${money(c.to_usd)} a month instead of ${money(c.from_usd)}` : `No owner's pay from the business (instead of ${money(c.from_usd)} a month)`;
    else if (l.id === 'equity') what = l.reached ? `${money(c.amount_usd)} more owner equity in place of debt (${money(c.owner_total_usd)} in all)` : 'Owner equity in place of the whole loan';
    else if (l.id === 'split_line') what = l.reached ? `Split "${l.tier_name}" so at least ${c.share_pct}% of its sales (the part that needs no license) start at opening instead of ${bpWhen(ctx, l.license_start_month)}` : `Split "${l.tier_name}" and start all of it at opening instead of ${bpWhen(ctx, l.license_start_month)}`;
    else what = l.label;
    rows.push([l.label, what, l.reached ? 'Works on its own' : 'Not enough on its own, even at this', be(r.break_even_month), cov(r.dscr_year2)]);
  }
  const eqShare = total > 0 ? (fin.projections?.sources_and_uses?.sources?.[0]?.amount_usd || 0) / total : null;
  const equityLine = eqShare != null && fin.projections?.loan ? `Your equity is ${pct(eqShare)} of the project today; SBA 7(a) loans to a start-up need at least 10% (SBA SOP 50 10 8), and lenders often ask for 15% to 20%. ` : '';
  return `<p><strong>This plan does not work as structured yet.</strong> ${esc(fundingProblemSentences(pipeline, asOf).join(' '))}</p>
<p>${esc(`Each change below is tried on its own and re-run through the same model, with the loan re-sized to the new need. "Works" means cash break-even by ${bpWhen(ctx, fn.horizon_months)} and, with a loan, Year 2 coverage of at least ${fn.dscr_target.toFixed(2)}×.`)}</p>
<table class="doc-table"><tr><th>Lever</th><th>Change needed</th><th>On its own</th><th>Break-even</th><th>Year 2 coverage</th></tr>${rows.map((r) => `<tr>${r.map((x) => `<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</table>
<p>${esc(`Changes combine: two smaller changes can do what one large one does. ${equityLine}Paths That Could Work, next, sets out complete alternatives with their figures.`)}</p>`;
}

/**
 * Funding Realism, read from the plan's own outcome: whether the model works as structured, its
 * break-even month, its loan coverage and the owner's share of the project. It used to print the
 * finance engine's opening screen instead ("bank loan odds screen low ... Fix the calendar before
 * implying loan readiness"), which is computed before the model runs and said the same thing about
 * a plan that clears every line (Ellery: 1.58x coverage in Year 2) as about one that fails.
 */
function fundingRealismHtml(pipeline, asOf) {
  const fin = pipeline.finance || {};
  const intake = pipeline.intake || {};
  const kinds = fundingKinds(intake);
  const ctx = { ...bpContext(pipeline), cal: planCalendar(pipeline, asOf) };
  const fn = fin.funding_need;
  const su = fin.projections?.sources_and_uses;
  const capital = personalCapitalUsd(pipeline);
  const project = su?.total_uses_usd || 0;
  const share = capital != null && project > 0 ? capital / project : null;
  const primary = primaryDebtScenario(fin.debt_service);
  const loan = fin.projections?.loan;
  const target = fn?.dscr_target || fin.debt_service?.reference_minimum || 1.25;
  const cov = (y) => primary?.coverage?.find((c) => c.year === y)?.dscr ?? null;
  const x = (v) => `${Number(v).toFixed(2)}×`;
  const gap = Number(fin.funding_gap_usd) || 0;
  const out = [];
  const items = [];

  if (gap <= 0 && !loan) {
    out.push(capital > 0 && project > 0 ? `The plan needs no outside money: your ${money(capital)} covers the ${money(project)} it requires.` : 'The plan needs no outside money on these figures.');
  } else if (fn && fn.works === false) {
    out.push(`On its own figures, this plan does not work as structured yet. ${fundingProblemSentences(pipeline, asOf)[0] || ''} A lender is unlikely to approve it until that changes; This Plan Does Not Work as Structured Yet and Paths That Could Work set out what would change it.`);
    if (loan || kinds.debt) items.push('Bank or SBA loan: not yet. Rework the plan first, then take it to a lender.');
  } else if (fn?.rule === 'equity_runway') {
    out.push(`The plan raises ${money(gap)} from investors, sized to carry the business through ${bpWhen(ctx, fn.horizon_months)}${fn.break_even_month ? `, and it reaches monthly cash break-even in ${bpWhen(ctx, fn.break_even_month)}` : '. It does not reach monthly cash break-even within the 36 months projected, so a further raise, or a change to the plan, will be needed before the money runs out'}.`);
  } else {
    const be = fn?.break_even_month || fin.projections?.break_even?.break_even_month || null;
    const bits = [];
    if (be) bits.push(`the business reaches monthly cash break-even in ${bpWhen(ctx, be)}`);
    const y2 = cov(2);
    const y3 = cov(3);
    if (loan && y2 != null) bits.push(`its earnings cover the loan payments ${x(y2)} in Year 2${y3 != null ? ` and ${x(y3)} in Year 3` : ''}, against the ${x(target)} lenders commonly look for`);
    out.push(`On its own figures, this plan works as structured${bits.length ? `: ${joinClauses(bits)}` : ''}.`);
    if (loan && cov(1) != null && cov(1) < target) out.push('Year 1 does not cover the payments while sales build; the plan funds them from the loan, and an interest-only start is worth asking the lender for.');
    if (loan) {
      if (share == null) items.push('Bank or SBA loan: set your own cash contribution first; a lender will ask for one before anything else.');
      else if (share < 0.1) items.push(`Bank or SBA loan: your ${money(capital)} is ${pct(share)} of the project, under the 10% SBA 7(a) minimum for a start-up (SBA SOP 50 10 8). Add equity or reduce the project before you apply.`);
      else if (share < 0.15) items.push(`Bank or SBA loan: workable. Your ${money(capital)} is ${pct(share)} of the project, above the 10% SBA minimum but under the 15% to 20% many lenders ask for, so expect questions about equity and collateral.`);
      else items.push(`Bank or SBA loan: a workable case. Coverage clears the usual line and your ${money(capital)} is ${pct(share)} of the project, ${share >= 0.2 ? 'above' : 'within'} the 15% to 20% most lenders ask a start-up owner for.`);
    }
  }
  if (kinds.debt && gap > 0 && gap <= 50000) items.push(`Smaller lenders: the ${money(gap)} to raise is within the SBA Microloan limit of $50,000, so microlenders and community lenders (CDFIs) are an option alongside a bank.`);
  if (kinds.equity) items.push('Investors: an equity raise is priced by negotiation, not by these figures. Investors weigh the team and how revenue grows past Year 3 more than loan coverage.');
  if (kinds.grant) items.push('Grants: competitive and slow; none is counted in this plan. Apply in parallel, not instead of the financing above.');
  return `<p>${esc(out.join(' ').replace(/\s+/g, ' ').trim())}</p>
${items.length ? `<ul>${items.map((i) => `<li>${esc(i)}</li>`).join('')}</ul>` : ''}
<p>${esc('This reads the plan’s own figures the way a lender first looks at them. It is not a prediction of any lender’s decision: approval also depends on your credit, collateral, experience and the lender’s own review.')}</p>`;
}

/** "Paths that could work": alternative tracks, each re-run through the finance model. */
function planPathsHtml(pipeline) {
  const pt = pipeline.plan_tracks;
  if (!pt?.applicable) return '';
  const cov = (v) => (v == null ? 'No loan' : v > 0 ? `${v.toFixed(2)}×` : 'Not covered');
  const parts = [
    `<p>${esc('These are options to evaluate with an adviser (an SBDC counselor, a SCORE mentor or your accountant), not a promise of funding or of eligibility for any program. Each is your plan with one set of changes, re-run through the same finance model; nothing here is estimated separately. Tracks that work on the model come first, then the rest by how well they fit what you told us you want.')}</p>`,
  ];
  const microloan = pt.funding_sources.find((s) => s.id === 'sba_microloan');
  pt.tracks.forEach((t, i) => {
    const f = t.figures;
    const status = f.works ? 'works on the model' : t.better_than_current ? 'closer, not there yet' : 'does not help on its own';
    parts.push(`<h3>${esc(`${i + 1}. ${t.title} (${status})`)}</h3>`);
    parts.push(`<ul>${t.changes.map((c) => `<li>${esc(c)}</li>`).join('')}</ul>`);
    parts.push(
      `<table class="doc-table"><tr><th class="num">Capital needed</th><th class="num">From you</th><th class="num">Outside</th><th>Break-even</th><th>Year 2 coverage</th><th class="num">Left unfunded</th></tr><tr><td class="num">${esc(money(f.total_capital_usd))}</td><td class="num">${esc(money(f.owner_usd))}</td><td class="num">${esc(money(f.outside_usd))}</td><td>${esc(f.break_even_month ? `Month ${f.break_even_month}` : 'After month 36')}</td><td>${esc(cov(f.dscr_year2))}</td><td class="num">${esc(money(f.unfunded_losses_after_horizon_usd))}</td></tr></table>`,
    );
    parts.push(`<p>${esc(`What you give up: ${t.gives_up}`)}</p>`);
    if (t.fit_reasons.length) parts.push(`<p>${esc(`Fit with your answers: ${t.fit_reasons.join(' ')}`)}</p>`);
    if (microloan && (t.funding_notes || []).includes('sba_microloan')) parts.push(`<p>${esc(`The outside money this track needs (${money(f.outside_usd)}) is within the SBA Microloan limit of ${money(microloan.max_usd)}.`)}</p>`);
  });
  if (pt.not_modeled?.length) {
    parts.push(`<h3>${esc('Not modeled yet')}</h3>`);
    parts.push(`<ul>${pt.not_modeled.map((n) => `<li>${esc(`${n.title}: ${n.reason}`)}</li>`).join('')}</ul>`);
  }
  parts.push(`<h3>${esc('Smaller-dollar funding sources')}</h3>`);
  parts.push(`<ul>${pt.funding_sources.map((s) => `<li>${esc(`${s.title}: ${s.summary}`)}${s.url ? ` (${esc(s.url)})` : ''}</li>`).join('')}</ul>`);
  parts.push(`<p>${esc(`To rebuild every document on one of these tracks, open Paths that could work on the Documents page and choose Build my plan on this track. Your current plan is kept, and you can go back to it.`)}</p>`);
  return parts.join('\n');
}

/** For a plan rebuilt on a track: which one, what changed, and that the original is kept. */
function planTrackNoteHtml(pipeline) {
  const t = pipeline.intake?.plan_track;
  if (!t) return '';
  const when = String(t.chosen_at || '').slice(0, 10);
  return `<p>${esc(`This plan is built on the track "${t.title}", chosen ${when ? `on ${bpLongDate(when)}` : 'in the app'}. It is your plan with these changes:`)}</p>
<ul>${(t.changes || []).map((c) => `<li>${esc(c)}</li>`).join('')}</ul>
<p>${esc('Your original plan is kept on this device; Paths that could work, on the Documents page, takes you back to it.')}</p>`;
}

/** The checks behind the numbers: what the lender documents state as conclusions, tested. */
function forecastChecksHtml(pipeline, asOf) {
  const fin = pipeline.finance || {};
  const proj = fin.projections;
  const rm = revenueModelOf(pipeline);
  const cm = fin.cost_model;
  const items = [];
  if (rm?.basis === 'buildup') {
    const mc = rm.market_check || {};
    const cc = rm.cost_check || {};
    if (mc.serviceable_customers && mc.implied_customers_month36 != null) {
      items.push(`Market share: by month 36 your volumes imply at least ${Math.round(mc.implied_customers_month36).toLocaleString('en-US')} regular customers (the largest single product, since customers overlap), ${pct(mc.share, 1)} of the ${mc.serviceable_customers.toLocaleString('en-US')} you count as reachable. Above ${pct(rm.checks_policy?.serviceable_share_flag ?? 0.1)} would be a warning sign; this is ${mc.share > (rm.checks_policy?.serviceable_share_flag ?? 0.1) ? 'above it' : 'well inside it'}.`);
    }
    if (cc.cost_implied_monthly_revenue_usd) {
      items.push(`Price times volume against the cost base: Year 2 revenue averages ${money(cc.year2_average_monthly_revenue_usd)} a month, ${cc.ratio}× the ${money(cc.cost_implied_monthly_revenue_usd)} your costs would need at industry labor ratios. Below 0.5× or above 2× would suggest the volumes or the team are out of proportion.`);
    }
    for (const f of (rm.flags || []).filter((x) => x.severity === 'warning')) items.push(`Warning: ${f.message}`);
    for (const f of (rm.flags || []).filter((x) => x.severity !== 'warning')) items.push(f.message);
  } else if (proj && proj.mode !== 'revision') {
    items.push(`Revenue is sized from your cost base (${money(proj.stabilized_monthly_revenue_usd)} a month at full operation), not from prices and volumes. Add a price-and-volume build-up in the interview; lenders test forecasts built that way.`);
  }
  if (cm?.labor_check?.modeled_share != null) items.push(`Payroll is ${pct(cm.labor_check.modeled_share, 1)} of revenue at full operation against an industry median of ${pct(cm.labor_check.benchmark_share, 1)}.`);
  const rent = cm?.rent;
  const occ = (cm?.lines || []).find((l) => l.key === 'occupancy');
  if (rent?.basis === 'allowance') {
    items.push(`Rent (${money(rent.monthly_usd)} a month) is an allowance, not a quote: ${rent.square_feet.toLocaleString('en-US')} square feet at $${rent.annual_per_sq_ft_usd.toFixed(2)} per square foot a year, twice the only published figure for ${rent.published_area} ($${rent.published_per_sq_ft_usd.toFixed(2)}, shopping centers, Cushman & Wakefield). Street-front space in the city center leases well above shopping centers, and the plan's range is ${money(rent.monthly_low_usd)} to ${money(rent.monthly_high_usd)} a month. A lease quote replaces it; every $500 a month is $6,000 a year off earnings and coverage.${rent.floor_area_basis === 'assumption' ? ' The floor area is a planning assumption; enter your real square footage.' : ''}`);
  }
  if (rent?.basis === 'benchmark') {
    items.push(`Rent (${money(rent.monthly_usd)} a month) is ${rent.square_feet.toLocaleString('en-US')} square feet at the ${rent.basis_text}, $${rent.annual_per_sq_ft_usd.toFixed(2)} per square foot a year (Cushman & Wakefield, shopping centers). Street-front space in a dense neighborhood usually leases higher; get a broker's quote.${occ?.ratio_monthly_usd ? ` The industry occupancy ratio would have given ${money(occ.ratio_monthly_usd)} a month.` : ''}${rent.floor_area_basis === 'assumption' ? ' The floor area is a planning assumption; enter your real square footage.' : ''}`);
  }
  const sc = proj?.setup_cost_check;
  if (sc?.pack) {
    const range = `${money(sc.pack.low_usd)} to ${money(sc.pack.high_usd)}`;
    const what = `the ${sc.pack.items} must-have items priced in the industry research for ${sc.pack.title.replace(/ \(NAICS \d+\)$/, '').toLowerCase()} (commercial listings, retrieved ${sc.pack.retrieved})`;
    if (sc.basis === 'industry_pack') {
      const d = sc.difference_usd;
      items.push(`Equipment: the model uses ${money(sc.pack.mid_usd)}, the midpoint of ${what}, which run ${range} in all${sc.capped_by_funding ? ` (scaled with the rest of the start-up budget to the amount you stated, it shows as ${money(sc.equipment_usd)} in the statements)` : ''}. The published start-up benchmark's equipment share would have been ${money(sc.benchmark_equipment_usd)}${d ? `, ${money(Math.abs(d))} ${d < 0 ? 'more' : 'less'} than the model now uses` : ''}. Replace it with your own quotes: two per item, then rebuild the plan.`);
    } else if (sc.basis === 'founder') {
      items.push(sc.within_range
        ? `Equipment: your figure of ${money(sc.equipment_usd)} sits inside the ${range} range for ${what}.`
        : `Equipment: your figure of ${money(sc.equipment_usd)} is ${money(Math.abs(sc.difference_usd))} ${sc.difference_usd < 0 ? 'below' : 'above'} the ${range} range for ${what}. Your figure is used; check nothing is missing${sc.difference_usd > 0 ? ' or over-specified' : ''}.`);
    } else if (!sc.within_range) {
      items.push(`Equipment: the start-up budget carries ${sc.equipment_usd ? money(sc.equipment_usd) : 'no separate line'} for equipment; ${what} run ${range}. Add your equipment list in the interview so the budget covers it.`);
    }
  }
  const sp = proj?.startup_costs;
  if (sp) {
    items.push(
      sp.basis === 'benchmark'
        ? `Start-up costs ${proj.setup_cost_check?.basis === 'industry_pack' ? `(${money(proj.fixed_setup_categories.reduce((t, c) => t + c.amount_usd, 0))}, with equipment at list prices; the benchmark alone gives ${money(sp.total_usd)})` : `(${money(sp.total_usd)})`} come from a published benchmark${sp.method === 'per_sq_ft' ? ` of ${sp.per_sq_ft_usd} per square foot, from a 2018 survey that has not been adjusted for inflation, so it likely runs low` : ''}. The split by category is an allocation. Get written quotes for buildout and equipment before the lender meeting.`
        : `Start-up costs (${money(sp.total_usd)}) are a planning allowance; no published benchmark was found for this kind of business. Replace them with quotes.`,
    );
  }
  for (const f of (cm?.flags || []).filter((x) => x.code !== 'costs_exceed_founder_ceiling')) items.push(f.message);
  // Opening date against permit lead times: the model schedules it (see Your Opening Date).
  const oa = fin.opening_analysis;
  if (oa?.founder_requested) {
    const cal = planCalendar(pipeline, asOf);
    items.push(`Opening date: you asked for ${cal.long(oa.founder_requested.opening_month)}; the permits needed to open put it at ${cal.long(oa.base.opening_month)}. See Your Opening Date for what would have to be true to open sooner.`);
  }
  const burn = pipeline.intake?.interview_deepen?.financial?.monthly_burn_comfort_usd;
  if (cm?.ceiling?.status === 'above_ceiling') {
    items.push(`Your spending ceiling: you said up to ${money(burn)} a month; the costed plan runs ${money(cm.steady_state_monthly_opex_usd)}. The plan shows the costed figure. Staying under your ceiling means fewer roles or hours, lower owner pay, or a cheaper site, and each changes the revenue the team can support.`);
  }
  if (!items.length) return '<p>No checks to report on this draft.</p>';
  return `<p>The Business Plan and Financial Statements state conclusions. These are the tests behind them, and what each result means for you.</p>
<ul>${items.map((i) => `<li>${esc(i)}</li>`).join('')}</ul>`;
}

/** Preparing for the lender: what the lender documents leave to the owner. */
function lenderPrepHtml(pipeline) {
  const fin = pipeline.finance || {};
  const intake = pipeline.intake || {};
  const ds = fin.debt_service;
  const pkg = fin.lender_package || {};
  const kinds = fundingKinds(intake);
  const capital = personalCapitalUsd(pipeline);
  const items = [];
  const su = fin.projections?.sources_and_uses;
  if (su) {
    items.push(
      capital == null
        ? `You have not set how much of your own money goes in. The plan therefore shows the full ${money(su.total_uses_usd)} as financing required. Decide your contribution; most lenders expect one.`
        : capital === 0
          ? `You are not putting in cash. The full ${money(su.total_uses_usd)} would have to be borrowed or raised. SBA 7(a) lenders commonly expect an owner contribution on a start-up; be ready to explain yours, or add one.`
          : `Your ${money(capital)} is ${pct(capital / su.total_uses_usd)} of the ${money(su.total_uses_usd)} project.${capital / su.total_uses_usd < 0.1 ? ' That is thin for a start-up loan; expect the lender to ask for more equity or collateral.' : ''}`,
    );
  }
  if (kinds.debt && ds?.applicable) {
    const primary = primaryDebtScenario(ds);
    items.push(`Coverage: ${primary.coverage.map((c) => `Year ${c.year} ${c.dscr == null ? 'not covered' : `${c.dscr}×`}`).join(', ')}. The plan compares against ${ds.reference_minimum}×, a conservative line many lenders use; program minimums can be lower. Ask your lender which figure they underwrite to.`);
    if ((ds.years_below_threshold || []).includes(1)) items.push('Year 1 does not cover the payments while sales build. Ask the lender for an interest-only period or a deferred first payment; the plan already funds the Year 1 payments from the loan.');
    if ((ds.years_below_threshold || []).some((y) => y > 1)) items.push('Coverage is below the planning line after Year 1, which usually stops an approval. Consider a smaller loan, more equity, a longer term, or lower costs before you apply.');
    if (!ds.existing_debts_disclosed) items.push('No existing debt was entered. A lender counts every payment you owe (vehicle, equipment, credit lines, personal debt). Enter them so the coverage figure is the one the lender will compute.');
    items.push(pkg.collateral?.completed ? `Collateral entered: ${money(pkg.collateral.available_equity_usd)} of available equity.` : 'No collateral has been identified. List what you could pledge (equipment, real estate, savings) and any liens against it.');
  }
  items.push(pkg.personal_financial_statement?.completed ? 'Your personal financial statement is complete and appears in the Financial Statements.' : 'Complete a personal financial statement (SBA Form 413) for each owner of 20% or more. The lines are below.');
  const pfs = pkg.personal_financial_statement;
  const worksheet =
    pfs && !pfs.completed
      ? `<h3>Personal Financial Statement Worksheet</h3>
<table class="doc-table"><tr><th>Assets</th><th class="num">Amount</th></tr>${pfs.assets.map((l) => `<tr><td>${esc(l.label)}</td><td class="num"></td></tr>`).join('')}</table>
<table class="doc-table"><tr><th>Liabilities</th><th class="num">Amount</th></tr>${pfs.liabilities.map((l) => `<tr><td>${esc(l.label)}</td><td class="num"></td></tr>`).join('')}</table>`
      : '';
  return `<ul>${items.map((i) => `<li>${esc(i)}</li>`).join('')}</ul>${worksheet}`;
}

/** A competitor worksheet to fill in; kept here until it has real entries. */
function competitorWorksheetHtml(pipeline) {
  const cats = competitorNames(founderText(pipeline, 'named_competitors'));
  const rows = (cats.length ? cats : ['Competitor 1', 'Competitor 2', 'Competitor 3']).map((c) => `<tr><td>${esc(bpSentenceCase(c))}</td><td></td><td></td><td></td><td></td><td></td></tr>`).join('');
  return `<p>Name three to five direct competitors near your location and fill in the table. Once it has real entries, add them to the interview and the Business Plan's competitive analysis will carry them.</p>
<table class="doc-table"><tr><th>Competitor (or type)</th><th>Name and location</th><th>Price point</th><th>What they offer</th><th>Strengths</th><th>Weaknesses</th></tr>${rows}</table>`;
}

/** What the plan is built from, figure by figure: published, assumed, or yours. */
function provenanceHtml(pipeline) {
  const fin = pipeline.finance || {};
  const cm = fin.cost_model;
  const rows = [];
  const sp = fin.projections?.startup_costs;
  if (sp) rows.push(['Start-up costs', sp.basis === 'benchmark' ? 'Published benchmark, scaled for location' : 'Planning allowance', 'Vendor quotes']);
  if (cm?.rent) rows.push(['Rent', cm.rent.basis === 'founder' ? 'Your figure' : cm.rent.basis === 'allowance' ? `Allowance for street-front space (${cm.rent.factor}× the published shopping-center rent) × ${cm.rent.square_feet.toLocaleString('en-US')} sq ft` : `Published asking rent × ${cm.rent.square_feet.toLocaleString('en-US')} sq ft (${cm.rent.floor_area_basis === 'assumption' ? 'assumed size' : 'size from a trade reference'})`, 'Lease quote']);
  if (cm) rows.push(['Wages', 'BLS median wages for the area', 'Your pay plan']);
  if (cm) rows.push(['Other operating costs', 'Published industry ratios', 'Quotes and first months of actuals']);
  if (revenueModelOf(pipeline)?.basis === 'buildup') rows.push(['Prices and volumes', 'Your figures', 'Pre-sales, bookings, early trading']);
  if (fin.market_context) rows.push(['Industry and market figures', 'Published statistics (Census, BLS, BEA, NRA)', 'Check at the URLs below']);
  const table = rows.length ? `<table class="doc-table"><tr><th>Figure</th><th>Basis</th><th>Replace with</th></tr>${rows.map((r) => `<tr>${r.map((c) => `<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</table>` : '';
  return `${table}\n${fullSourcesHtml(fin)}`;
}

function buildFinancialWorkingNotes(pipeline, asOf) {
  const fin = pipeline.finance || {};
  const isRevision = fin.projections?.mode === 'revision';
  const meta = RECOMMENDED_DOCUMENTS.find((d) => d.id === 'financial_working_notes');
  const draft = draftStatusLine(planGapsFor(pipeline));
  return {
    id: meta.id,
    name: meta.name,
    filename: meta.filename,
    purpose: meta.purpose,
    audience: meta.audience,
    tier: 'recommended',
    status: 'draft',
    snippet: `How the funding looks, ways to need less money, and notes for ${companyTitle(pipeline)}. Yours only.`,
    sections: [
      {
        id: 'notes_cover',
        heading: "Founder's Notes",
        body_html: `<p><strong>${esc(companyTitle(pipeline))}</strong> · as of ${esc(asOf)}</p>
${audienceNoticeHtml(meta.audience)}
<p>${esc(PRIVACY_STATEMENT)}</p>
<p>This memo is written to you, not about the business. The Business Plan and Financial Statements state the business case for a lender; this is the thinking behind them: the checks on the numbers, what is still open, how to prepare for the lender, and where each figure comes from.</p>`,
      },
      { id: 'plan_start', heading: 'Plan Start Date', body_html: planStartHtml(pipeline, asOf) },
      {
        id: 'plan_readiness',
        heading: 'How Close This Plan Is',
        body_html: `${draft ? `<p><strong>${esc(draft.replace(/^DRAFT — /, 'Draft: '))}.</strong> The Business Plan shows "Draft" in its page header until these are answered.</p>` : ''}${planReadinessHtml(pipeline)}${
          planGapsFor(pipeline).filter((g) => g.marker).length
            ? `<p>Left out of the lender documents until you answer:</p><ul>${planGapsFor(pipeline)
                .filter((g) => g.marker)
                .map((g) => `<li>${esc(g.section)}: ${esc(g.marker)}</li>`)
                .join('')}</ul>`
            : ''
        }`,
      },
      isRevision ? null : { id: 'opening_date', heading: 'Your Opening Date', body_html: openingNotesHtml(pipeline, asOf) },
      { id: 'forecast_checks', heading: 'Checks on the Numbers', body_html: forecastChecksHtml(pipeline, asOf) },
      isRevision || !pipeline.intake?.plan_track ? null : { id: 'plan_track', heading: 'Built on a Track', body_html: planTrackNoteHtml(pipeline) },
      isRevision || !fundingFixHtml(pipeline, asOf) ? null : { id: 'funding_fix', heading: 'This Plan Does Not Work as Structured Yet', body_html: fundingFixHtml(pipeline, asOf) },
      isRevision || !pipeline.plan_tracks?.applicable ? null : { id: 'plan_paths', heading: 'Paths That Could Work', body_html: planPathsHtml(pipeline) },
      isRevision ? null : { id: 'coverage_options', heading: 'Options on the Loan', body_html: financingOptionsHtml(pipeline) },
      { id: 'lender_prep', heading: 'Preparing for the Lender', body_html: lenderPrepHtml(pipeline) },
      { id: 'competitor_worksheet', heading: 'Competitor Worksheet', body_html: competitorWorksheetHtml(pipeline) },
      { id: 'free_help', heading: 'Free Help Near You', body_html: freeHelpNotesHtml(pipeline) },
      renderProgramsSection(pipeline.intake?.eligibility_programs),
      {
        id: 'funding_realism',
        heading: 'Funding Realism',
        body_html: fundingRealismHtml(pipeline, asOf),
      },
      { id: 'gap_options', heading: isRevision ? 'Closing the Gap' : 'Closing the Funding Gap', body_html: gapOptionsHtml(pipeline) },
      { id: 'improvement_notes', heading: 'Financial Notes', body_html: improvementsHtml(pipeline, 'financial') },
      { id: 'operational_notes', heading: 'Operational Notes', body_html: improvementsHtml(pipeline, 'operational') },
      { id: 'strategic_notes', heading: 'Strategic Notes', body_html: improvementsHtml(pipeline, 'strategic') },
      isRevision ? null : { id: 'sources_provenance', heading: 'Where the Figures Come From', body_html: provenanceHtml(pipeline) },
      {
        id: 'how_to_use',
        heading: 'Using These Figures',
        body_html: `<ul>
<li>Keep expected sales and customer counts modest: present the likely case, not the best case.</li>
<li>Tie any opening date to the permit and license timing in this plan, not to a hoped-for date.</li>
<li>Present the projections as projections, not audited statements; a lender will treat them as such.</li>
<li>Replace benchmark figures with quotes and bids before a formal package goes out.</li>
</ul>`,
      },
      {
        id: 'notes_disclaimer',
        heading: 'Notice',
        body_html: `<p>These notes are planning aids, not an offer of credit or investment, and not a prediction of any lender's decision. ${esc(PLANNING_DISCLAIMER)}</p>
<p>See <strong>Read This First</strong> for jurisdiction notices on funding paths and local rules.</p>`,
      },
    ].filter(Boolean),
  };
}


/**
 * Tasks created by what the lender documents leave out. The Business Plan omits a sub-point or
 * states a neutral plan where information is missing; each omission becomes a task here, so
 * nothing silently disappears.
 */
function lenderDocTodos(pipeline, asOf) {
  const intake = pipeline.intake || {};
  const fin = pipeline.finance || {};
  const company = intake.plan_detail?.company || {};
  const ops = intake.interview_deepen?.operational || {};
  const pkg = fin.lender_package || {};
  const kinds = fundingKinds(intake);
  const remote = ['online_only', 'home'].includes(ops.space_type);
  const out = [];
  const add = (priority, title, detail, document = 'Business Plan') => out.push({ priority, title, detail, document });
  if (!hasBusinessName(pipeline)) add(1, 'Choose a business name', 'The plan cover and every page header use your business description until the business has a name. Lenders expect the legal or trading name on the plan.');
  if (!String(company.owner_name || '').trim()) add(2, 'Add your name and title for the cover', 'The plan cover and management section refer to "the owner" until you give your name and title.');
  if (![company.address, company.phone, company.email].some((x) => String(x || '').trim())) add(2, 'Add contact details for the cover', 'A lender expects an address, phone number and email on the cover of the plan.');
  if (!founderText(pipeline, 'advisors')) add(2, 'Name your accountant, attorney and insurance agent', 'The plan says the business will retain them before opening. Naming them strengthens the management section, and your accountant should review the projections before a lender sees them.');
  if (!founderText(pipeline, 'suppliers')) add(3, 'Name your main suppliers and their terms', 'The operations section describes standard purchasing for your industry. Named suppliers with terms read as a plan rather than an intention.');
  if (!founderText(pipeline, 'insurance')) add(2, 'Get insurance quotes', `The plan budgets insurance from an industry ratio. Replace it with a quote for the coverages listed in the Operations Plan.`, 'Financial Statements');
  if (!remote && !founderText(pipeline, 'facility')) add(1, 'Find a site and get a letter of intent', 'Rent and start-up costs are benchmarks until you have a site. A letter of intent or lease quote replaces both and lets the permit clock start.', 'Financial Statements');
  if (fin.projections?.startup_costs) add(1, 'Get written quotes for buildout and equipment', 'Start-up costs are a published benchmark split by typical share. A lender will ask for vendor quotes behind each line.', 'Financial Statements');
  if (fin.cost_model?.rent?.basis === 'allowance') add(1, 'Get a lease quote', `Rent is an allowance of ${money(fin.cost_model.rent.monthly_usd)} a month for street-front space (range ${money(fin.cost_model.rent.monthly_low_usd)} to ${money(fin.cost_model.rent.monthly_high_usd)}), not a quote. A lender will ask for the lease or a letter of intent; a quote replaces the allowance throughout the plan.`, 'Financial Statements');
  if (fin.cost_model?.rent?.basis === 'benchmark') add(2, 'Confirm rent with a broker', 'Rent is the published shopping-center asking rate for your area times an assumed floor area. Street-front space often costs more.', 'Financial Statements');
  if (competitorNames(founderText(pipeline, 'named_competitors')).length < 3 || !/[A-Z][a-z]+ [A-Z]/.test(answerPart(founderText(pipeline, 'named_competitors'), 'Competitors', { orWhole: true }))) add(2, 'Name three to five direct competitors', "Fill in the competitor worksheet in Founder's Notes with names, locations and price points. Lenders read a competitive analysis with real names as evidence you know the market.", "Founder's Notes");
  if (!founderText(pipeline, 'marketing_budget') || !founderText(pipeline, 'retention')) add(3, 'Estimate what a customer costs to win and is worth', 'Customer acquisition cost and repeat-customer value are not yet quantified. Even a rough figure from your first month of trading will strengthen the marketing section.');
  if (kinds.debt && !pkg.personal_financial_statement?.completed) add(1, 'Complete a personal financial statement (SBA Form 413)', "Each owner of 20% or more completes one. The worksheet is in Founder's Notes.", "Founder's Notes");
  if (kinds.debt && !pkg.collateral?.completed) add(2, 'List collateral you can offer', 'The plan says collateral will be pledged as the lender requires. List what you could pledge and any liens against it.');
  add(2, 'Prepare your résumé', 'The appendix lists an owner résumé among the supporting documents.');
  const capital = personalCapitalUsd(pipeline);
  if (capital == null || capital === 0) add(1, 'Decide your own cash contribution', `The plan shows the full ${money(fin.projections?.sources_and_uses?.total_uses_usd ?? fin.estimated_launch_cost_usd)} as financing required. Most lenders expect an owner contribution.`, 'Financial Statements');
  const cal = planCalendar(pipeline, asOf);
  if (cal.basis === 'default') add(3, 'Set a start date', `The plan assumes month 1 is ${cal.long(1)}, three months after the plan date. Give a date in the interview to move every timeline.`, "Founder's Notes");
  else if (cal.basis === 'opening_default') add(3, 'Choose an opening date', 'No opening date was picked, so the plan asked for one three months after the plan date. Pick your own in the interview; permits may still set a later one.', "Founder's Notes");
  const facts = openingFacts(pipeline);
  if (facts?.binding) {
    add(1, 'Confirm permit timelines with the issuing offices', `The plan opens in month ${facts.sch.opening_month} because the ${lowerFirst(facts.binding.name)} typically takes about ${monthsText(facts.binding.lead_months)} from filing${facts.binding.allowance_months > facts.binding.lead_months ? ` (allow up to ${facts.binding.allowance_months})` : ''}. File in month 1. A confirmed faster timeline moves the opening earlier; a slower one moves it later and raises the capital needed (see Founder's Notes).`, 'Local Licenses');
  }
  for (const t of facts?.gatedTiers || []) {
    add(2, `Confirm when the ${lowerFirst(plainLicenseName(t.license.label))} can be issued`, `${t.name} is not in the forecast until month ${t.start_month}. Ask the licensing board for the next application window; an earlier license brings that revenue forward.`, 'Local Licenses');
    break;
  }
  if (fin.funding_need && !fin.funding_need.works && fin.funding_need.rule === 'break_even') add(1, 'Rework the plan so it works before you apply', `On the forecast the plan is not cash-positive within ${monthsText(fin.funding_need.horizon_months_after_opening)} of opening${fin.funding_need.reasons.includes('coverage_below_minimum_year2') ? ', or cannot carry its loan by Year 2' : ''}. Founder's Notes shows what each change would take and the paths that could work; the Documents page can rebuild the plan on one of them.`, "Founder's Notes");
  const help = planLocalHelp(pipeline);
  if (help.nearest) add(2, `Book a free session with ${help.nearest.name}`, `${help.nearest.label}: ${lhOfficeLine(help.nearest)}. Free one-to-one advice on this plan, the lease and the loan; bring the Business Plan and Financial Statements. Other free offices near you are in Founder's Notes.`, "Founder's Notes");
  if (fin.cost_model?.ceiling?.status === 'above_ceiling') add(2, 'Decide how to fit your spending ceiling', "The costed plan runs above the monthly spending you said you were comfortable with. See Founder's Notes for the options.", "Founder's Notes");
  return out;
}


/** Founder's Notes: the nearest free advisers and the lenders that make small loans, from the local help directory. */
function freeHelpNotesHtml(pipeline) {
  const h = planLocalHelp(pipeline);
  if (!h.ok) {
    return '<p>Find your nearest Small Business Development Center at americassbdc.org/find-your-sbdc and a SCORE mentor at score.org/find-mentor. Both are free.</p>';
  }
  const row = (o) => `<tr><td>${esc(o.label)}</td><td><strong>${esc(o.name)}</strong>${o.address ? `<br>${esc(o.address)}` : ''}${o.distance_miles != null ? ` (${esc(lhDistanceText(o.distance_miles, o))})` : ''}${o.phone || o.website ? `<br>${esc([o.phone, o.website].filter(Boolean).join(' · '))}` : ''}</td></tr>`;
  const offices = [h.sbdc, h.score, h.wbc, h.vboc, h.district, h.state_office].filter(Boolean);
  const parts = [`<p>Free, confidential advice from people who review plans like this one every week. Book a first session with ${esc(h.nearest ? h.nearest.name : 'the nearest center')} before you sign a lease or apply for the loan, and bring the Business Plan and Financial Statements.</p>`];
  if (offices.length) parts.push(`<table class="doc-table"><tr><th>Kind</th><th>Office, address, phone and website</th></tr>${offices.map(row).join('')}</table>`);
  for (const o of h.locators) parts.push(`<p>No ${esc(o.label)} is listed for your state yet; the official locator is ${esc(o.website)}.</p>`);
  if (h.lenders.length) parts.push(`<p>Lenders that make smaller loans, often with advice attached (lenders, not advisors): ${h.lenders.map((o) => `${esc(o.name)} (${esc(o.website)})`).join('; ')}.</p>`);
  parts.push('<p class="doc-note">From the local help directory that ships with the app (SBA, SBDC, SCORE and state listings; retrieval dates are in the Operating Plan). Call ahead: hours and locations change.</p>');
  return parts.join('\n');
}

function noteLine(label, value) {
  const v = String(value ?? '').trim();
  if (!v) return '';
  return `<tr><td>${esc(label)}</td><td>${esc(v)}</td></tr>`;
}

/** Every answered plan question, as table rows, in checklist order. */
function planAnswerRows(pipeline) {
  const intake = pipeline.intake || {};
  return Object.values(REQUIREMENT_BY_ID)
    .map((item) => {
      const raw = readPath(intake, item.path);
      const value = Array.isArray(raw) ? raw.join(', ') : typeof raw === 'string' ? raw.trim() : '';
      if (!value || typeof raw === 'object' && !Array.isArray(raw)) return '';
      const label = item.id === 'legal_entity_type' ? entityTypeLabel(value) : value;
      return `<tr><td>${esc(item.question || item.id)}</td><td>${esc(label)}</td></tr>`;
    })
    .join('');
}

function buildDraftNotes(pipeline, asOf) {
  const intake = pipeline.intake || {};
  const fin = pipeline.finance || {};
  const deepen = intake.interview_deepen || {};
  const finDeep = deepen.financial || {};
  const opsDeep = deepen.operational || {};
  const stratDeep = deepen.strategic || {};
  const loc = locationLine(pipeline);
  const capital = personalCapitalUsd(pipeline);
  const reviewNotes = pipeline.assumption_review?.notes;
  const extras = selectedDocumentExtras(pipeline);
  const FUNDING_PATH_NAMES = { grants: 'grants', loans: 'loans', incubators: 'incubators', equity: 'equity investment' };
  const fundingPaths = Array.isArray(deepen.funding_path_interest)
    ? deepen.funding_path_interest
        .filter((v) => v !== 'skip_for_now')
        .map((v) => FUNDING_PATH_NAMES[v] || String(v).replace(/_/g, ' '))
        .join(', ')
    : '';

  // Written as prose rather than label:value pairs. A reader-facing document that says
  // "Stage: Idea / Brand posture: new" is a form printout, and sections that exist only to
  // report "nothing recorded yet" are noise — those are dropped instead. Every value here comes
  // from what the founder answered; nothing is filled in on their behalf.
  const sentences = [];
  const isExisting = intake.stage === 'existing' || intake.stage === 'launched';
  if (intake.business_description) {
    const stage = String(stageLabel(pipeline)).toLowerCase();
    const brand =
      intake.brand_preference === 'import'
        ? 'under an existing brand'
        : intake.brand_preference === 'defer'
          ? 'with the brand still to be decided'
          : 'under a new brand';
    // "You are building" is wrong for a business that already trades — it is already built.
    const verb = isExisting ? 'You are running' : 'You are building';
    // "You are building Ellery Coffee & Wine is a founder-owned cafe…" is what splicing a
    // description that opens with its own name produced. Name first, then the description.
    const named = nameFromDescription(intake.business_description);
    sentences.push(
      named
        ? `${verb} ${esc(named)} — ${esc(stage)} stage, ${brand}. ${esc(intake.business_description)}`
        : `${verb} ${esc(intake.business_description)} — ${esc(stage)} stage, ${brand}.`,
    );
  }
  const place = loc && !/not decided|pending/i.test(loc) ? `operating in ${esc(locationProse(pipeline))}` : null;
  const serves = intake.customer ? `serving ${esc(asMidSentence(intake.customer))}` : null;
  const via = revenueLine(pipeline);
  const viaText = via && !/not yet decided/i.test(via) ? `through ${esc(asMidSentence(via))}` : null;
  const secondSentence = [place, serves, viaText].filter(Boolean);
  if (secondSentence.length) {
    sentences.push(`${secondSentence.join(', ').replace(/^./, (c) => c.toUpperCase())}.`);
  }

  const moneySentences = [];
  if (capital != null) {
    moneySentences.push(`You are putting in ${esc(money(capital))} of your own capital.`);
  }
  const intent = intake.outside_money?.intent;
  if (intent === 'yes' || intake.outside_money?.raw) {
    const how = intake.outside_money?.raw ? ` (${esc(intake.outside_money.raw)})` : '';
    moneySentences.push(`You intend to seek outside money${how}.`);
  } else if (intent === 'no') {
    moneySentences.push('You are not seeking outside money at this stage.');
  }
  if (fin.estimated_launch_cost_usd != null) {
    const gap = fin.funding_gap_usd;
    // An existing business has no launch cost. In revision mode this figure is what the
    // cash-flow model says the plan still needs, which is a different claim entirely — calling
    // it a launch cost in a document the founder reads would simply be wrong.
    const revision = fin.projections?.mode === 'revision';
    const what = revision
      ? `The additional capital this plan needs is ${esc(money(fin.estimated_launch_cost_usd))}`
      : `The total capital the plan requires is ${esc(money(fin.estimated_launch_cost_usd))}`;
    moneySentences.push(
      gap != null && gap > 0
        ? `${what}, leaving ${esc(money(gap))} to finance from outside.`
        : `${what}, which your own capital covers.`,
    );
  }
  if (fundingPaths) {
    moneySentences.push(`Outside funding options you selected: ${esc(fundingPaths)}.`);
  }

  const extraDetail = (
    noteLine('Must-have spend', finDeep.must_have_spend) +
    noteLine('Can defer', finDeep.can_defer_spend) +
    (finDeep.monthly_burn_comfort_usd != null
      ? noteLine('Monthly burn comfort', money(finDeep.monthly_burn_comfort_usd))
      : '') +
    noteLine('First revenue timing', codeLabel(FIRST_REVENUE_TIMING_NAMES, finDeep.first_revenue_timing)) +
    noteLine('Space', codeLabel(SPACE_TYPE_NAMES, opsDeep.space_type)) +
    noteLine('Team now', codeLabel(TEAM_SIZE_NAMES, opsDeep.team_now)) +
    noteLine('Weekly hours', codeLabel(WEEKLY_HOURS_NAMES, opsDeep.weekly_hours)) +
    noteLine('First-customer path', opsDeep.first_customer_path) +
    noteLine('90-day goal', stratDeep.ninety_day_goal) +
    noteLine('Edge', stratDeep.edge_one_liner) +
    noteLine('Biggest risk', stratDeep.biggest_risk)
  ).trim();

  const sections = [
    {
      id: 'notes_cover',
      heading: 'Draft Notes',
      body_html: `<p><strong>${esc(companyTitle(pipeline))}</strong></p>
<p>Captured ${esc(asOf)} from your Instant answers, so you can check them before relying on the pack built from them. Correcting something here does not rebuild anything on its own.</p>`,
    },
    sentences.length
      ? { id: 'notes_summary', heading: 'Summary of Your Answers', body_html: sentences.map((x) => `<p>${x}</p>`).join('\n') }
      : null,
    moneySentences.length
      ? {
          id: 'notes_money',
          heading: 'Capital Position',
          body_html: `${moneySentences.map((x) => `<p>${x}</p>`).join('\n')}
<p class="doc-muted">Figures are estimates until replaced with quotes. See Read This First for jurisdiction notices.</p>`,
        }
      : null,
    extraDetail
      ? {
          id: 'notes_extra',
          heading: 'Additional Detail',
          // A table rather than eleven label-and-value paragraphs: the same content in about
          // two-thirds of the height, which keeps this short closing section on the page before.
          body_html: `<table class="doc-table compact"><tr><th>Question</th><th>Your answer</th></tr>${extraDetail}</table>`,
        }
      : null,
    planAnswerRows(pipeline)
      ? {
          id: 'notes_plan_answers',
          heading: 'Your Plan Answers',
          body_html: `<p>Recorded exactly as you gave them. The Business Plan restates them in the company's voice.</p><table class="doc-table compact"><tr><th>Question</th><th>Your answer</th></tr>${planAnswerRows(pipeline)}</table>`,
        }
      : null,
    extras.length
      ? {
          id: 'notes_extras_selected',
          heading: 'Optional documents you selected',
          body_html: `<p>${esc(extras.map((id) => OPTIONAL_DOCUMENTS.find((d) => d.id === id)?.name || id).join(', '))}.</p>`,
        }
      : null,
    reviewNotes ? { id: 'notes_review', heading: 'Review notes', body_html: `<p>${esc(reviewNotes)}</p>` } : null,
  ].filter(Boolean);

  return {
    id: DRAFT_NOTES_DOCUMENT.id,
    name: DRAFT_NOTES_DOCUMENT.name,
    filename: DRAFT_NOTES_DOCUMENT.filename,
    purpose: DRAFT_NOTES_DOCUMENT.purpose,
    tier: 'working_notes',
    status: 'draft',
    snippet: `Your answers as working notes for ${companyTitle(pipeline)} · ${stageLabel(pipeline)} stage · ${loc}.`,
    sections,
  };
}

/**
 * Which Business Plan gaps are still open for this run.
 *
 * Single source for both readers: the plan prints each gap's neutral marker, the founder's
 * To-Do List gets the same gap's instruction. Previously each section decided for itself and
 * wrote the founder's copy inline, which is how instructions addressed to the founder ended up
 * printed in the one document written to be handed to a lender.
 */
function planGapsFor(pipeline) {
  const intake = pipeline.intake || {};
  // A gap is open when any requirement it covers is unanswered, read from that requirement's own
  // `path` — the same path the interview writes to and the sections render from.
  //
  // This used to be a switch statement, and three of its branches were hardcoded `return false`
  // with a comment saying nothing collected that data yet. The moment anything did, the gap would
  // have stayed open forever and the plan would have printed "in preparation" over content the
  // founder had actually supplied.
  return openPlanGaps((gapId) =>
    GAP_BY_ID[gapId].covers.every((reqId) => isRequirementAnswered(intake, REQUIREMENT_BY_ID[reqId])),
  );
}

/**
 * How complete this plan is against the full lender checklist, not just the gaps with markers.
 *
 * The critical items are answered from the gaps rather than checked a second time here: a gap
 * names the requirement ids it covers, so an item is present exactly when no open gap covers it.
 * Checking them independently would be a third opinion on the same question, free to disagree
 * with the marker printed in the document and the task sitting in the To-Do List.
 *
 * The non-critical items are honest about a blunt fact: today's intake collects almost none of
 * them. Only prior-period financials can be satisfied, and only for a business already trading.
 * Reporting the rest as missing is the accurate answer, not a placeholder.
 */
function planCompletenessFor(pipeline) {
  const intake = pipeline.intake || {};
  return assessPlanForIntake(intake);
}

/**
 * A paragraph built from one collected answer, or nothing when it was never given.
 *
 * `lead` introduces the answer so the section reads as prose rather than a form. The founder's
 * own words are the sentence; the lead is only the hinge into them.
 */
function answerPara(pipeline, requirementId, lead) {
  const item = REQUIREMENT_BY_ID[requirementId];
  if (!item) return '';
  const raw = readPath(pipeline.intake || {}, item.path);
  const value = Array.isArray(raw) ? raw.join(', ') : typeof raw === 'string' ? raw.trim() : '';
  if (!value) return '';
  // The founder's answer often already ends in a full stop. Adding a second one reads as a typo
  // in a document going to a bank, which is how "the two office buildings.." got shipped.
  const body = /[.!?]$/.test(value) ? value : `${value}.`;
  return lead ? `<p>${esc(lead)} ${esc(body)}</p>` : `<p>${esc(body)}</p>`;
}

/** Joins section parts, dropping the ones that had no answer behind them. */
function proseSection(parts) {
  return parts.filter(Boolean).join('\n');
}

/** A founder's answer to a plan requirement, trimmed, or '' when never given. */
function founderText(pipeline, requirementId) {
  const item = REQUIREMENT_BY_ID[requirementId];
  if (!item) return '';
  const raw = readPath(pipeline.intake || {}, item.path);
  if (Array.isArray(raw)) return raw.join(', ');
  return typeof raw === 'string' ? raw.trim() : '';
}

/**
 * The Guided Interview writes several questions into one plan requirement as "Label: text."
 * pieces (answer-mapping.js): the competitors, their prices, their strengths and why customers
 * choose this business all land in named_competitors. Printed whole, the labels read like a form
 * pasted into the plan ("will compete ... as Competitors: Blue Bottle ... Their prices: ..."). These
 * are the labels it writes (answer-parts test holds the list to the question bank); the documents
 * take the pieces apart and give each its place.
 */
const ANSWER_PART_LABELS = Object.freeze([
  'Why now', 'What is changing', 'How it began', 'A normal day', 'Site status', 'Where', 'Size', 'Rent', 'Lease',
  'Foot traffic', 'Nearby', 'Who is around', 'Service area', 'Customers', 'What they need', 'How they buy', 'Buying process',
  'Competitors', 'Their prices', 'Their strengths', 'Where they fall short', 'Why customers choose us', 'Certifications held',
  'Prices nearby', 'Our pricing', 'Daily volume', 'Rate and hours', 'Jobs and ticket', 'Plans and customers', 'Chairs and services',
  'Markup', 'Hosting', 'Investor terms', 'Backup', 'Channels', 'How',
]);

/** How a label reads as a run-in heading in a lender document (third person, no form wording). */
const ANSWER_PART_HEADINGS = Object.freeze({
  Where: 'Location',
  Lease: 'Lease terms',
  Nearby: 'Nearby',
  'Who is around': 'Who lives and works nearby',
  Customers: 'Customer groups',
  'Their prices': 'Competitor prices',
  'Their strengths': 'Competitor strengths',
  'Where they fall short': 'Where competitors fall short',
  'Why customers choose us': 'Why customers will choose the business',
  'Our pricing': 'Pricing',
  Backup: 'Backup supplier',
  How: 'Approach',
});

const ANSWER_PART_RE = new RegExp(
  // Labels are plain words (no pattern characters); longest first, so "How they buy" beats "How".
  `(?:^|(?<=[.!?]\\s))(${[...ANSWER_PART_LABELS].sort((a, b) => b.length - a.length).join('|')}): `,
  'g',
);

/** "Competitors: A, B. Their prices: $5." -> [{ label: 'Competitors', text: 'A, B.' }, ...]; plain text is one unlabeled part. */
function answerParts(text) {
  const t = String(text || '').trim();
  if (!t) return [];
  const hits = [...t.matchAll(ANSWER_PART_RE)];
  if (!hits.length) return [{ label: null, text: t }];
  const parts = [];
  if (hits[0].index > 0) parts.push({ label: null, text: t.slice(0, hits[0].index).trim() });
  hits.forEach((h, i) => {
    const end = i + 1 < hits.length ? hits[i + 1].index : t.length;
    const body = t.slice(h.index + h[0].length, end).trim();
    if (body) parts.push({ label: h[1], text: body });
  });
  return parts.filter((x) => x.text);
}

/** The text of one labeled piece; for an unlabeled answer, the whole answer when `orWhole`. */
function answerPart(text, label, { orWhole = false } = {}) {
  const parts = answerParts(text);
  const hit = parts.find((x) => x.label === label);
  if (hit) return hit.text;
  return orWhole && parts.length === 1 && !parts[0].label ? parts[0].text : '';
}

/** The pieces' words without their labels, as one run of sentences. */
function answerProse(text) {
  return answerParts(text).map((x) => (/[.!?]$/.test(x.text) ? x.text : `${x.text}.`)).join(' ');
}

/**
 * An answer in the company's voice: one paragraph for a plain answer; a labeled one becomes a
 * paragraph per piece, each with a short run-in heading, the way a written plan sets them out.
 */
function bpVoiceParts(text, ctx, { skip = [] } = {}) {
  const parts = answerParts(text).filter((x) => !skip.includes(x.label));
  if (!parts.length) return '';
  if (parts.length === 1 && !parts[0].label) return bpP(esc(bpVoice(parts[0].text, ctx)));
  return parts
    .map((x) => (x.label ? `<p><strong>${esc(ANSWER_PART_HEADINGS[x.label] || x.label)}.</strong> ${esc(bpVoice(x.text, ctx))}</p>` : bpP(esc(bpVoice(x.text, ctx)))))
    .join('\n');
}

/** The competitor names from the founder's answer: the Competitors piece, or a plain answer. */
function competitorNames(text) {
  return bpSplitList(answerPart(text, 'Competitors', { orWhole: true }));
}

function isLaunchProjection(proj) {
  return Boolean(proj) && proj.mode !== 'revision';
}

/**
 * The capital the modeled Year 1 actually needs, not only the launch estimate.
 *
 * The launch estimate carries a fixed reserve. The monthly cash flow is computed separately and,
 * on a slow ramp, runs below zero anyway — on the sample cafe by $14,338 at month 9. The
 * Financial Statements said so; the Business Plan asked for the launch gap alone and never
 * mentioned it, so the two documents a lender reads side by side disagreed about what the
 * business needs. This is the one place that figure is assembled, so both say the same thing.
 */
function capitalRequirement(pipeline) {
  const fin = pipeline.finance || {};
  const proj = fin.projections;
  if (!isLaunchProjection(proj)) return null;
  const extra = proj.additional_reserve_needed_usd || 0;
  const launch = fin.estimated_launch_cost_usd;
  const total = money2Sum(launch, extra);
  const capital = personalCapitalUsd(pipeline);
  return {
    launch_usd: launch,
    extra_reserve_usd: extra,
    trough_month: proj.cash_flow_trough_month,
    total_usd: total,
    outside_implied_usd: capital == null ? null : Math.max(0, money2Sum(total, -capital)),
  };
}

/** Lower-cases a label's first letter for use mid-sentence, leaving acronyms like POS alone. */
function lowerFirst(label) {
  const t = String(label || '');
  return /^[A-Z][a-z]/.test(t) ? t[0].toLowerCase() + t.slice(1) : t;
}

function opexCategory(proj, pattern) {
  return (proj?.opex_categories || []).filter((c) => pattern.test(c.label));
}

function sumMonthly(cats) {
  return money2Sum(...cats.map((c) => c.monthly_usd));
}

function brandSentence(pref) {
  if (pref === 'import') return 'The business operates under an established brand of its own.';
  if (pref === 'defer') return 'Brand identity has not yet been set.';
  return 'A new brand is being developed for launch.';
}

/** The plan's headline numbers in one table, each carried from the same model as the statements. */
/** The revenue model the finance engine reports, or null for a revision or an older pipeline. */
function revenueModelOf(pipeline) {
  return pipeline?.finance?.revenue_model || pipeline?.finance?.projections?.revenue_model || null;
}

/** Whether revenue comes from the founder's price-times-volume build-up. */
function hasRevenueBuildup(pipeline) {
  return revenueModelOf(pipeline)?.basis === 'buildup';
}

/** "$5.50" for prices under $100, whole dollars above. */
function priceText(n) {
  const v = Number(n) || 0;
  return v < 100 && Math.round(v * 100) % 100 !== 0 ? `$${v.toFixed(2)}` : money(v);
}

/** A volume as printed: whole numbers above 10, one decimal below (2.5 events a month). */
function volumeText(n) {
  const v = Number(n) || 0;
  return v >= 10 || Number.isInteger(v) ? Math.round(v).toLocaleString('en-US') : v.toFixed(1);
}

const BILLING_PRICE_SUFFIX = Object.freeze({ one_time: 'per sale', monthly: 'a month', annual: 'a year', per_unit: 'per unit' });
const BILLING_VOLUME_NOUN = Object.freeze({ one_time: 'new customers', monthly: 'subscribers', annual: 'subscribers', per_unit: 'units' });

/** The loan scenario the cash flow actually carries: the modeled terms, not a sensitivity row. */
function primaryDebtScenario(ds) {
  if (!ds?.applicable || !ds.scenarios?.length) return null;
  return ds.scenarios.find((s) => s.primary) || ds.scenarios.find((s) => s.label === 'Mid') || ds.scenarios[0];
}

/** How long the capital lasts, in words. */
function runwayText(uop) {
  const r = uop?.runway;
  if (!r) return 'Not modeled';
  if (r.basis === 'self_sustaining') return `Carries the business to cash-positive, from about month ${r.cash_flow_positive_month}`;
  if (r.basis === 'cash_out') {
    return `About ${r.months} months with the contingency intact${r.months_including_contingency ? `, ${r.months_including_contingency} months if it is spent` : ''}`;
  }
  const more = r.months != null ? r.months - 36 : null;
  return more > 0 ? `Through month 36, then about ${monthsText(more)} more at the month-36 burn rate` : 'Through the 36 months modeled';
}

/** A source's publisher, for a table cell. */
function sourcePublisher(fin, id) {
  if (!id) return 'Quoted figure';
  const src = (fin.data_sources || []).find((x) => x.id === id);
  return src ? src.short || src.publisher : 'Published benchmark';
}

/** Hours a week, from a full-time-equivalent share. */
function hoursPerWeek(fte) {
  return `${Math.round(fte * 40)} hrs/wk`;
}

/**
 * Longest section, in characters of visible text, still treated as short enough to move whole
 * rather than break across a page.
 *
 * Roughly a quarter of a letter page at this body size. Sections above it break normally,
 * because forcing a long one to move whole opens a bigger hole than the break it prevents.
 */
/**
 * The serif these documents are set in.
 *
 * EB Garamond is bundled via FONT_FACE_CSS above -- vendored woff2 subsets served as data URIs
 * in every rendered document, so Windows, macOS, and Linux all typeset the same characters
 * with the same metrics. It is a professional garamond in the same family as the Cormorant
 * Garamond the app UI uses, but designed for body text rather than display, which is what a
 * bank-ready document set at 11-13pt actually needs.
 *
 * The tail of the stack (Georgia, Gelasio, DejaVu Serif, ...) is the earlier fallback, kept
 * verbatim in case a future rendering context ever fails to honour @font-face -- an unlikely
 * enough case that the bundled data URIs make it moot in practice, but a safe stack costs
 * nothing to keep. Verified that the layout does not depend on which face wins: rendering the
 * whole pack in DejaVu Serif, about 26% wider than Liberation Serif, adds pages but produces
 * no stranded pages, no orphaned tails and no margin overflow -- 0 findings across 77 pages.
 */
const DOC_SERIF = '"EB Garamond", Georgia, Gelasio, "DejaVu Serif", "Liberation Serif", "Times New Roman", serif';

const SHORT_SECTION_CHARS = 800;

/**
 * A catalog entry by id.
 *
 * The builders used to index DOCUMENT_CATALOG by position, which silently broke the moment a
 * document was inserted ahead of them: adding Founder's Notes at [2] pushed Local Licenses to [3]
 * and the To-Do List to [4], and both kept reading the old slots. Local Licenses then showed the
 * Founder's Notes purpose — owner-only material, advertised on a different document's header.
 */
function catalogEntry(id) {
  const entry = DOCUMENT_CATALOG.find((d) => d.id === id);
  if (!entry) throw new Error(`no catalog entry for ${id}`);
  return entry;
}

// ---------------------------------------------------------------------------------------------
// The lender edition of the Business Plan.
//
// Written the way a consultant-prepared SBA plan is written: in the company's voice ("Ellery
// Coffee & Wine will…"), plain title-case headings, prose where prose explains and tables only
// where numbers need them. Nothing addressed to the owner appears here — no gaps, checks, flags
// or placeholders. Where information is missing, a sub-point is left out or stated as a plan in
// neutral terms, and the owner's task goes to the To-Do List and Founder's Notes instead.
//
// Every section is a function of one shared context (bpContext), so the same facts can later be
// rendered at a different depth — a detailed operating edition for the owner — without the
// lender edition carrying operating filler.
// ---------------------------------------------------------------------------------------------

/** Stage, as a lender plan describes it. */
const BP_STAGE_PHRASE = Object.freeze({
  idea: 'a new business in the planning stage',
  pre_launch: 'a new business preparing to open',
  launched: 'a recently opened business',
  existing: 'an established, operating business',
});

/** Sentence case for a phrase that will open a sentence. */
function bpSentenceCase(text) {
  const t = String(text || '').trim();
  return t ? t[0].toUpperCase() + t.slice(1) : t;
}

/** A phrase with its closing punctuation, once. */
function bpSentence(text) {
  const t = bpSentenceCase(clause(text));
  return t ? `${t}.` : '';
}

/**
 * An answer rewritten in the company's voice: "The founder has…" becomes "The owner has…" (or the
 * owner's name), first person becomes third, and the result is a sentence with a capital and one
 * full stop. Only these substitutions are made; the owner's own words are otherwise kept.
 */
function bpVoice(text, ctx) {
  const t = bpPronouns(clause(text), ctx);
  return t ? bpSentence(t) : '';
}

/** The owner's words mid-sentence: first person made third person, case otherwise kept. */
function bpWords(text, ctx) {
  return bpPronouns(asMidSentence(clause(text)), ctx);
}

/** "run" -> "runs", "cover" -> "covers", "manage" -> "manages"; past tense and modals unchanged. */
function bpThirdPerson(verb) {
  const v = String(verb);
  if (/ed$/.test(v) || /^(spent|ran|built|led|made|took|grew|won|sold|had|did|was|went|began|brought|found|kept|left|met|paid|set|taught|wrote|can|could|would|should|may|might|must|also|still|now|then|already)$/.test(v)) return v;
  if (v === 'have') return 'has';
  if (v === 'do') return 'does';
  if (v === 'go') return 'goes';
  if (/(s|sh|ch|x|z|o)$/.test(v)) return `${v}es`;
  if (/[^aeiou]y$/.test(v)) return `${v.slice(0, -1)}ies`;
  return `${v}s`;
}

function bpPronouns(text, ctx) {
  let t = String(text || '');
  if (!t) return '';
  const owner = ctx.owner.ref;
  const subj = ctx.subject;
  t = t
    .replace(/\bthe founder's\b/gi, `${owner}'s`)
    .replace(/\bthe founders'\b/gi, "the owners'")
    .replace(/\bthe founders\b/gi, 'the owners')
    .replace(/\bthe founder\b/gi, owner)
    .replace(/\bfounder estimates?\b/gi, 'management estimate')
    .replace(/\bfounder's\b/gi, `${owner}'s`)
    .replace(/\bI am\b/g, `${owner} is`)
    .replace(/\bI'm\b/g, `${owner} is`)
    .replace(/\bI have\b/g, `${owner} has`)
    .replace(/\bI've\b/g, `${owner} has`)
    .replace(/\bI will\b/g, `${owner} will`)
    .replace(/\bI (?!am\b|have\b|will\b)([a-z]+)\b/g, (m, verb) => `${owner} ${bpThirdPerson(verb)}`)
    .replace(/\bI\b/g, owner)
    .replace(/\bmy\b/gi, `${owner}'s`)
    .replace(/\bwe are\b/gi, `${subj} is`)
    .replace(/\bwe're\b/gi, `${subj} is`)
    .replace(/\bwe will\b/gi, `${subj} will`)
    .replace(/\bwe have\b/gi, `${subj} has`)
    .replace(/\bwe were\b/gi, `${subj} was`)
    // "because we pour better coffee" -> "because Ellery Coffee & Wine pours better coffee".
    .replace(/\bwe ([a-z]+)\b/gi, (m, verb) => `${subj} ${bpThirdPerson(verb.toLowerCase())}`)
    .replace(/\bour\b/gi, `${subj}'s`)
    .replace(/\b(choose|chose|pick|picks|call|calls|find|finds|recommend|recommends|trust|trusts|love|loves|visit|visits) us\b/g, '$1 the business');
  // "I counted" became "the owner counted" mid-answer; a sentence still starts with a capital.
  return t.replace(/(^|[.!?]\s+)(the owner)\b/g, (m, lead) => `${lead}The owner`);
}

/** Words that open a verb phrase ("open softly…", "reach 750 customers…"). */
const BP_VERB_OPENERS = /^(open|reach|book|sign|launch|hire|sell|serve|build|grow|win|secure|get|land|hit|complete|finish|establish|achieve|break|close|raise|start|add|acquire|onboard|convert|retain|ship|release|expand|introduce|test|validate|generate|earn|attract|recruit|train|develop|create|finalize|obtain|increase|reduce|lower|make|deliver)\b/i;

/** The owner's positioning line as the company's positioning statement. */
function bpPositioning(edge, ctx) {
  const e = clause(edge);
  if (!e) return '';
  if (/^(a|an|the)\s/i.test(e)) return `${ctx.subject} is positioned as ${e.replace(/^(A|An|The)\s/, (m) => m.toLowerCase())}.`;
  if (BP_VERB_OPENERS.test(e) || /^(we|it|they)\b/i.test(e)) return bpVoice(e, ctx);
  return `${ctx.subject} is positioned as ${article(e)} ${e.replace(/^./, (c) => c.toLowerCase())}.`;
}

/** A list from the owner's own comma/"and" series, each item sentence-cased. */
function bpSplitList(text) {
  return String(text || '')
    .replace(/\.$/, '')
    .split(/,|;|\band\b|\bor\b/i)
    .map((s) => s.trim())
    .filter((s) => s.length > 1);
}

function bpCount(n) {
  const words = ['no', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten'];
  return n >= 0 && n <= 10 ? words[n] : String(n);
}

/** Headcount from the staffing table, the one place team size is stated. */
function bpTeam(fin) {
  const staffing = fin.cost_model?.staffing || [];
  const people = staffing.reduce((a, r) => a + (r.count || 1), 0);
  const fullTime = staffing.filter((r) => r.fte >= 0.75).reduce((a, r) => a + (r.count || 1), 0);
  const partTime = people - fullTime;
  const opening = fin.cost_model?.opening_month || 1;
  const atOpening = staffing.filter((r) => r.start_month <= opening).reduce((a, r) => a + (r.count || 1), 0);
  return { staffing, people, fullTime, partTime, opening, atOpening };
}

/** "two full-time and two part-time" — derived only from the staffing table. */
function bpTeamSplit(team) {
  if (team.fullTime && team.partTime) return `${bpCount(team.fullTime)} full-time and ${bpCount(team.partTime)} part-time`;
  return team.partTime ? 'all part-time' : 'all full-time';
}

/** "four people: two full-time and two part-time" — derived only from the staffing table. */
function bpTeamPhrase(team) {
  if (!team.people) return '';
  const split =
    team.fullTime && team.partTime
      ? `: ${bpCount(team.fullTime)} full-time and ${bpCount(team.partTime)} part-time`
      : team.partTime
        ? ', all part-time'
        : team.people > 1
          ? ', all full-time'
          : '';
  return `${bpCount(team.people)} ${team.people === 1 ? 'person' : 'people'}${split}`;
}

function bpContext(pipeline) {
  const intake = pipeline.intake || {};
  const fin = pipeline.finance || {};
  const proj = fin.projections || null;
  const company = intake.plan_detail?.company || {};
  const named = hasBusinessName(pipeline);
  const subject = named ? companyTitle(pipeline) : 'The company';
  const ownerName = String(company.owner_name || '').trim();
  const ownerTitle = String(company.owner_title || '').trim();
  const loc = pipeline?.location || {};
  const decided = !/not decided|pending/i.test(locationLine(pipeline));
  return {
    pipeline,
    intake,
    fin,
    proj,
    launch: isLaunchProjection(proj),
    revision: proj?.mode === 'revision',
    rm: hasRevenueBuildup(pipeline) ? revenueModelOf(pipeline) : null,
    cm: fin.cost_model || null,
    named,
    subject,
    subjectLower: named ? subject : 'the company',
    owner: {
      name: ownerName,
      title: ownerTitle || 'Owner',
      ref: ownerName || 'the owner',
      Ref: ownerName || 'The owner',
    },
    decided,
    place: decided ? locationProse(pipeline) : '',
    city: loc.primary_city || '',
    stagePhrase: BP_STAGE_PHRASE[intake.stage] || BP_STAGE_PHRASE.idea,
    kinds: fundingKinds(intake),
    team: bpTeam(fin),
    edge: clause(intake.interview_deepen?.strategic?.edge_one_liner || ''),
    goal90: clause(intake.interview_deepen?.strategic?.ninety_day_goal || ''),
    risk: clause(intake.interview_deepen?.strategic?.biggest_risk || ''),
    ops: intake.interview_deepen?.operational || {},
    spend: intake.interview_deepen?.financial || {},
    text: (id) => founderText(pipeline, id),
    industryId: fin.cost_model?.industry?.id || 'general',
    market: fin.market_context || null,
  };
}

/** 'YYYY-MM-DD' as "March 10, 2027". */
function bpLongDate(iso) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(iso || ''));
  return m ? `${MONTH_FULL[Number(m[2]) - 1]} ${Number(m[3])}, ${m[1]}` : String(iso || '');
}

/** "February 2027 (month 3)" once the calendar is known, else "month 3". */
function bpWhen(ctx, m) {
  return ctx.cal ? `${ctx.cal.long(m)} (month ${m})` : `Month ${m}`;
}

function bpH3(text) {
  return `<h3>${esc(text)}</h3>`;
}

function bpP(html) {
  return html ? `<p>${html}</p>` : '';
}

function bpTable(headers, rows, opts = {}) {
  const numCols = opts.num || [];
  const head = headers.map((h, i) => `<th${numCols.includes(i) ? ' class="num"' : ''}>${esc(h)}</th>`).join('');
  const body = rows
    .map((r) => {
      const cls = r.cls ? ` class="${r.cls}"` : '';
      const cells = (r.cells || r).map((c, i) => `<td${numCols.includes(i) ? ' class="num"' : ''}>${esc(c)}</td>`).join('');
      return `<tr${cls}>${cells}</tr>`;
    })
    .join('');
  return `<table class="doc-table${opts.cls ? ` ${opts.cls}` : ''}"><tr>${head}</tr>${body}</table>`;
}

function bpSourceNote(text) {
  return text ? `<p class="table-note">${esc(text)}</p>` : '';
}

// ----- Industry operating descriptions ---------------------------------------------------------
//
// Standard operating practice for each industry, written as what the business plans to do. They
// are not claims that anything is already in place. The detailed operating edition expands each
// into procedures; the lender edition carries one paragraph per topic.

function bpFoodTraits(ctx) {
  const text = [ctx.intake.business_description, ctx.intake.revenue_model?.channels?.join(' '), (ctx.rm?.tiers || []).map((t) => t.name).join(' ')]
    .filter(Boolean)
    .join(' ')
    .toLowerCase();
  return {
    coffee: /coffee|espresso|cafe|café/.test(text),
    alcohol: /wine|beer|bar\b|cocktail|spirits|brew/.test(text),
    bakery: /bakery|pastry|pastries|bread/.test(text),
    catering: /catering|private event/.test(text),
    events: /workshop|event|class/.test(text),
    morning: /coffee|breakfast|espresso|pastry/.test(text),
    evening: /wine|dinner|evening|bar\b|cocktail/.test(text),
  };
}

