const BP_ROLE_TITLE_BY_SOC = Object.freeze({
  '11-1021': 'General manager', '11-2021': 'Marketing manager', '11-9051': 'Operations manager', '13-1111': 'Consultant',
  '13-1121': 'Events manager', '13-1161': 'Marketing specialist', '13-2011': 'Bookkeeper', '15-1252': 'Engineering lead',
  '15-1253': 'Quality assurance lead', '35-1011': 'Kitchen lead', '35-3023': 'Counter staff', '37-1011': 'Cleaning supervisor',
  '37-2012': 'Cleaner', '39-5012': 'Stylist', '39-9031': 'Instructor', '41-1011': 'Store manager', '41-3091': 'Customer success lead',
  '41-4011': 'Sales lead', '43-4051': 'Customer support', '43-6014': 'Administrator',
});

function bpRoleTitle(r) {
  const sentence = /^(i|my|we|our)\b/i.test(r.title) || /\b(run|runs|cover|covers|handle|handles|do|does)\b/i.test(r.title);
  const base = sentence ? (r.is_founder || /^i\b/i.test(r.title) ? `Owner and ${(BP_ROLE_TITLE_BY_SOC[r.soc] || 'manager').toLowerCase()}` : BP_ROLE_TITLE_BY_SOC[r.soc] || r.occupation) : r.title;
  return `${base.replace(/^./, (c) => c.toUpperCase())}${r.count > 1 ? ` (${r.count})` : ''}${r.contractor ? ' (contract)' : ''}`;
}

function bpStartText(r, team) {
  if (r.start_month <= 1) return r.is_founder ? 'Month 1 (pre-opening)' : 'Month 1';
  return r.start_month === team.opening ? `Month ${r.start_month} (opening)` : `Month ${r.start_month}`;
}

// ----- Sections ---------------------------------------------------------------------------------

function bpFinancialHighlights(ctx) {
  const proj = ctx.proj;
  if (!proj) return '';
  const ds = ctx.fin.debt_service;
  const primary = ctx.kinds.debt && ds?.applicable ? primaryDebtScenario(ds) : null;
  const years = proj.years;
  const net = years.map((y) => wholeDollar(y.operating_income_usd) - wholeDollar(y.interest_expense_usd || 0) - wholeDollar(y.estimated_income_tax_usd));
  const rows = [
    ['Revenue', ...years.map((y) => money(y.revenue_usd))],
    ['Gross margin', ...years.map((y) => pct(y.revenue_usd > 0 ? y.gross_profit_usd / y.revenue_usd : null))],
    ['EBITDA', ...years.map((y) => money(y.ebitda_usd ?? y.operating_income_usd))],
    ['Net income', ...net.map(money)],
  ];
  if (primary) rows.push(['Debt service coverage', ...primary.coverage.map((c) => (c.dscr == null ? '—' : `${c.dscr}×`))]);
  return bpTable(['', ...years.map((y) => `Year ${y.year}`)], rows, { num: [1, 2, 3] });
}

function bpExecutiveSummary(ctx) {
  const { intake, fin, proj, rm } = ctx;
  const parts = [];
  const desc = intake.business_description ? bpVoice(intake.business_description, ctx) : '';

  // The business.
  const open = ctx.revision
    ? `${ctx.subject} is ${ctx.stagePhrase}${ctx.place ? ` in ${esc(ctx.place)}` : ''}. This plan sets out its next stage of growth.`
    : `${ctx.subject} is ${ctx.stagePhrase}${ctx.place ? ` in ${esc(ctx.place)}` : ''}.`;
  parts.push(bpH3('The Business'));
  parts.push(bpP(esc(desc ? `${desc} It is ${ctx.stagePhrase}${ctx.place ? ` in ${ctx.place}` : ''}.${ctx.revision ? ' This plan sets out its next stage of growth.' : ''}` : open)));
  // The mission is stated once, under Company Description.
  if (ctx.edge) parts.push(bpP(esc(bpPositioning(ctx.edge, ctx))));

  // The opportunity.
  // The summary states the opportunity in its own words; the founder's market description and the
  // industry paragraph are printed in full under Industry and Market Analysis, once.
  const opp = [];
  const mc = rm?.market_check || {};
  if (mc.serviceable_customers) {
    opp.push(`Management estimates about ${mc.serviceable_customers.toLocaleString('en-US')} potential customers within reach of the business.`);
  }
  const ind = ctx.market?.industry;
  const industryLine = bpIndustrySummary(ind);
  if (industryLine) opp.push(industryLine);
  if (!opp.length && ctx.text('market_size_source')) opp.push('The market and its size are set out under Industry and Market Analysis.');
  if (opp.length) {
    parts.push(bpH3('The Opportunity'));
    parts.push(bpP(esc(opp.join(' '))));
  }

  // The offer and the customer.
  if (rm) {
    const names = rm.tiers.map((t) => t.name.replace(/\s*\(.*?\)\s*/g, '').toLowerCase());
    parts.push(bpH3('The Offer'));
    parts.push(
      bpP(
        esc(
          `${ctx.subject} will earn revenue from ${bpCount(rm.tiers.length)} lines: ${joinClauses(names)}. Prices range from ${priceText(Math.min(...rm.tiers.map((t) => t.price_usd)))} to ${priceText(Math.max(...rm.tiers.map((t) => t.price_usd)))}, with a blended gross margin of about ${pct(rm.totals.annual[1]?.gross_margin_pct ?? rm.totals.annual[0].gross_margin_pct)}.`,
        ),
      ),
    );
  }
  if (intake.customer) {
    parts.push(bpH3('Target Market'));
    parts.push(bpP(esc(`The primary customers are ${asMidSentence(clause(intake.customer))}.`)));
  }

  // Advantage and management.
  const adv = [];
  if (ctx.text('founder_background')) adv.push(`${ctx.owner.name ? `${ctx.owner.name}, the owner,` : 'The owner'} brings direct operating experience in this kind of business, set out under Organization and Management.`);
  if (ctx.team.people) adv.push(`The business will open with a team of ${bpTeamPhrase(ctx.team)}, costed at local median wages.`);
  if (adv.length) {
    parts.push(bpH3('Management'));
    parts.push(bpP(esc(adv.join(' '))));
  }

  // The request.
  const gap = fin.funding_gap_usd;
  const capital = personalCapitalUsd(ctx.pipeline);
  if (proj && ctx.launch) {
    parts.push(bpH3('Financing Sought'));
    parts.push(bpP(esc(`${bpAskSummary(ctx)} It pays for the fit-out and equipment, the months before the business is cash-positive, and a contingency.`)));
  }
  // Financial highlights.
  if (proj) {
    parts.push(bpH3('Financial Highlights'));
    const be = proj.break_even;
    const y1 = proj.years[0];
    const y3 = proj.years[2];
    parts.push(
      bpP(
        esc(
          `${rm ? 'Built product by product from expected prices and volumes, the' : ctx.revision ? 'The' : 'Revenue is implied by costs, not a sales forecast: the'} forecast shows revenue of ${money(y1.revenue_usd)} in Year 1, rising to ${money(y3.revenue_usd)} in Year 3.${be.break_even_month ? ` Monthly sales pass the ${money(be.break_even_monthly_revenue_usd)} break-even point around month ${be.break_even_month}.` : ''}`,
        ),
      ),
    );
    parts.push(bpFinancialHighlights(ctx));
  }
  return parts.filter(Boolean).join('\n');
}

/**
 * The industry headline for the Executive Summary. When the same sentence opens the Industry
 * Overview, the summary restates it rather than repeating it word for word.
 */
function bpIndustrySummary(ind) {
  if (!ind?.headline) return '';
  const repeated = (ind.paragraphs || []).some((p) => p.includes(ind.headline));
  if (!repeated) return ind.headline;
  const nra = /^The National Restaurant Association projects (.+?) sales of (\$[\d.,]+ (?:trillion|billion|million)) in (\d{4}), with real growth of ([\d.]+%)\.$/.exec(ind.headline);
  if (nra) return `${nra[1].replace(/^U\.S\./, 'U.S.')} sales are expected to reach ${nra[2]} in ${nra[3]}, ${nra[4]} real growth (National Restaurant Association).`;
  return '';
}

/**
 * The request in the Executive Summary: the same figures as the Funding Request, said once in
 * summary form rather than repeated sentence for sentence.
 */
function bpAskSummary(ctx) {
  const { fin, proj, intake } = ctx;
  const su = proj?.sources_and_uses;
  if (!su) return '';
  const gap = fin.funding_gap_usd;
  const capital = personalCapitalUsd(ctx.pipeline);
  const total = su.total_uses_usd;
  const sba = /\bsba\b/i.test(intake.outside_money?.raw || '');
  if (gap > 0 && intake.outside_money?.intent === 'yes') {
    const what = ctx.kinds.debt ? `a ${money(gap)}${sba ? ' SBA 7(a)' : ''} term loan` : ctx.kinds.equity ? `${money(gap)} of equity investment` : `${money(gap)} of outside financing`;
    return capital > 0 ? `The owner seeks ${what} and is investing ${money(capital)} of their own cash (${money(total)} in all).` : `The owner seeks ${what}, the whole of the ${money(total)} project.`;
  }
  if (gap === 0) return `The owner funds the whole ${money(total)} project.`;
  if (gap > 0) return `Of the ${money(total)} the project needs, ${money(gap)} must come from outside financing${intake.outside_money?.intent === 'none' ? ' or a smaller launch' : ', in a form still to be chosen'}.`;
  return `The project needs ${money(total)}; owner capital has not yet been set.`;
}

function bpCompanyDescription(ctx) {
  const { intake } = ctx;
  const parts = [];
  const existing = intake.existing_company_deepen || {};
  parts.push(
    bpP(
      esc(
        `${ctx.place ? `${ctx.subject} ${ctx.revision || ['launched', 'existing'].includes(intake.stage) ? 'is' : 'will be'} based in ${ctx.place}.` : `${ctx.subject}'s operating location has not been decided; the site will be chosen for access to its customers.`}${!ctx.revision && ctx.launch && ctx.cm?.schedule ? ` It plans to open in ${bpWhen(ctx, ctx.cm.schedule.opening_month)}.` : ''} ${
          intake.brand_preference === 'import' ? 'It trades under its established brand.' : intake.brand_preference === 'defer' ? '' : 'It will launch under a new brand developed for the business.'
        }`.trim(),
      ),
    ),
  );
  // The business description itself opens the Executive Summary; it is not repeated here.
  // Where it stands today and why this place: facts from the intake and interview, no filler.
  const stageLine = { idea: `${ctx.subject} is at the planning stage and has not begun trading.`, pre_launch: `${ctx.subject} is preparing to open and has not begun trading.` }[intake.stage] || '';
  const customers = String(intake.customer || '').trim().replace(/[.\s]+$/, '');
  const whyHere = ctx.place && customers && !ctx.revision ? `The location puts it within reach of the customers it is built for: ${customers.charAt(0).toLowerCase()}${customers.slice(1)}.` : '';
  if (stageLine || whyHere) parts.push(bpP(esc([stageLine, whyHere].filter(Boolean).join(' '))));
  const mission = ctx.text('mission');
  if (mission) {
    parts.push(bpH3('Mission'));
    parts.push(bpP(esc(bpVoice(mission, ctx))));
  }
  const legal = existing.entity_type && existing.formation_jurisdiction;
  const ownership = ctx.text('ownership');
  if (legal || ownership) {
    parts.push(bpH3('Legal Structure and Ownership'));
    if (legal) parts.push(bpP(esc(`${ctx.subject} is ${article(entityTypeLabel(existing.entity_type))} ${entityTypeLabel(existing.entity_type)} formed in ${existing.formation_jurisdiction}.`)));
    if (ownership) parts.push(bpP(esc(bpVoice(ownership, ctx))));
  }
  // Milestones to date: what the founder said has happened, then the facts the intake holds that a
  // lender counts as progress (equity committed, a lease quote), each only if not already said.
  const history = ctx.text('business_history');
  const milestones = [];
  if (!ctx.revision && !['launched', 'existing'].includes(intake.stage)) {
    const capital = personalCapitalUsd(ctx.pipeline);
    if (existing.already_formed === 'yes' && !legal && !/\bformed\b/i.test(history || '')) milestones.push(`The company is formed${existing.formation_jurisdiction ? ` in ${existing.formation_jurisdiction}` : ''}.`);
    if (capital > 0) milestones.push(`The owner has committed ${money(capital)} of cash equity.`);
    if (/\b(quote|quoted|letter of intent|loi|lease)\b/i.test(ctx.text('facility') || '') && !/\b(quote|lease)\b/i.test(history || '')) milestones.push('A landlord has quoted the premises (see Operations Plan).');
  }
  if (history || milestones.length) {
    parts.push(bpH3(['launched', 'existing'].includes(intake.stage) || ctx.revision ? 'History' : 'Milestones to Date'));
    if (history) parts.push(bpVoiceParts(history, ctx));
    if (milestones.length) parts.push(`<ul>${milestones.map((m) => `<li>${esc(m)}</li>`).join('')}</ul>`);
  }
  if (ctx.goal90 || ctx.rm) {
    parts.push(bpH3('Objectives'));
    const items = [];
    if (ctx.goal90) items.push(`In the first 90 days of trading: ${ctx.goal90}.`);
    if (ctx.rm) items.push(`By ${bpWhen(ctx, 12)}: monthly sales of ${money(ctx.rm.totals.monthly_revenue_month12_usd)}.`);
    if (ctx.proj?.break_even?.break_even_month) items.push(`Monthly break-even by ${bpWhen(ctx, ctx.proj.break_even.break_even_month)}.`);
    if (ctx.rm) items.push(`By ${bpWhen(ctx, 36)}: monthly sales of ${money(ctx.rm.totals.monthly_revenue_month36_usd)}.`);
    parts.push(`<ul>${items.map((i) => `<li>${esc(bpSentenceCase(i))}</li>`).join('')}</ul>`);
  }
  return parts.filter(Boolean).join('\n');
}

function bpMarketAnalysis(ctx) {
  const { intake, rm } = ctx;
  const parts = [];
  const m = ctx.market;
  const ind = m?.industry;
  if (ind?.paragraphs?.length) {
    parts.push(bpH3('Industry Overview'));
    for (const p of ind.paragraphs) parts.push(bpP(esc(p)));
  }
  const trend = ctx.text('industry_trend');
  if (trend) {
    if (!ind?.paragraphs?.length) parts.push(bpH3('Industry Overview'));
    parts.push(bpVoiceParts(trend, ctx));
  }
  const local = m?.local;
  const size = ctx.text('market_size_source');
  if (local?.paragraph || size) {
    parts.push(bpH3('Local Market'));
    if (local?.paragraph) parts.push(bpP(esc(local.paragraph)));
    if (size) parts.push(bpP(esc(bpVoice(size, ctx))));
  }
  if (intake.customer || ctx.text('target_segment_detail')) {
    parts.push(bpH3('Target Customers'));
    if (intake.customer) parts.push(bpP(esc(`${ctx.subject} will serve ${asMidSentence(clause(intake.customer))}.`)));
    const seg = ctx.text('target_segment_detail');
    if (seg) parts.push(bpVoiceParts(seg, ctx));
    if (m?.consumer?.sentence) parts.push(bpP(esc(m.consumer.sentence)));
  }
  const sizing = m?.sizing;
  const mc = rm?.market_check || {};
  if (sizing?.rows?.length) {
    parts.push(bpH3('Market Size'));
    if (sizing.lead) parts.push(bpP(esc(sizing.lead)));
    parts.push(bpTable(['Measure', 'Basis', 'Annual value'], sizing.rows.map((r) => [r.label, r.basis, r.value]), { num: [2] }));
    if (sizing.note) parts.push(bpSourceNote(sizing.note));
  } else if (mc.serviceable_customers && mc.implied_customers_month36 != null) {
    parts.push(bpH3('Market Size'));
    parts.push(
      bpP(
        esc(
          `Management estimates about ${mc.serviceable_customers.toLocaleString('en-US')} potential customers within reach${rm.market_basis ? ` — ${bpVoice(rm.market_basis, ctx).replace(/\.$/, '').replace(/^./, (c) => c.toLowerCase())}` : ''}. At month-36 volumes the forecast implies roughly ${Math.round(mc.implied_customers_month36).toLocaleString('en-US')} regular customers, about ${pct(mc.share, 0)} of that market.`,
        ),
      ),
    );
  }
  return parts.filter(Boolean).join('\n') || bpP(esc(`${ctx.subject} will serve customers in ${ctx.place || 'its chosen market'}.`));
}

function bpCompetition(ctx) {
  const parts = [];
  const competitors = ctx.text('named_competitors');
  const cats = competitorNames(competitors);
  if (cats.length) {
    parts.push(
      bpP(
        esc(
          `${ctx.subject} will compete for the same customers and occasions as ${joinClauses(cats.map((c) => asMidSentence(c)))}. Each meets part of the need; the business is designed to meet more of it in one place.`,
        ),
      ),
    );
  }
  // What the founder said about those competitors (the Guided Interview's pieces), each set out
  // under its own run-in heading; why customers choose this business and certifications it holds
  // are advantages, below.
  const aboutRivals = bpVoiceParts(competitors, ctx, { skip: [null, 'Competitors', 'Why customers choose us', 'Certifications held'] });
  if (aboutRivals) parts.push(aboutRivals);
  const adv = [];
  // The positioning statement opens the Executive Summary; the advantages below are the reasons it holds.
  if (ctx.text('founder_background')) adv.push('An owner-operator with direct experience in this kind of business (see Organization and Management).');
  if (ctx.rm && ctx.rm.tiers.length > 2) adv.push('A broad mix of revenue lines that spreads demand across the day and the week rather than depending on one product.');
  const edge = answerPart(competitors, 'Why customers choose us');
  if (edge) adv.push(bpVoice(edge, ctx));
  const certs = answerPart(competitors, 'Certifications held');
  if (certs) adv.push(`The business holds these certifications: ${clause(certs)}.`);
  const pricing = ctx.text('pricing_basis');
  if (pricing) adv.push(bpVoice(answerPart(pricing, 'Our pricing', { orWhole: true }) || answerProse(pricing), ctx));
  if (adv.length) {
    parts.push(bpH3('Competitive Advantages'));
    parts.push(`<ul>${adv.map((a) => `<li>${esc(a)}</li>`).join('')}</ul>`);
  }
  if (!parts.length) parts.push(bpP(esc(`${ctx.subject} will compete on the quality and consistency of its offer and on service.`)));
  return parts.join('\n');
}

function bpManagement(ctx) {
  const parts = [];
  const background = ctx.text('founder_background');
  const hours = { '40_plus': 'full time', '20_40': 'between 20 and 40 hours a week', '10_20': 'part time, 10 to 20 hours a week', under_10: 'part time, under 10 hours a week' }[ctx.ops.weekly_hours];
  parts.push(bpH3('Management'));
  const bio = [];
  if (ctx.owner.name) bio.push(`${ctx.owner.name}, ${ctx.owner.title}, will lead the business.`);
  if (background) bio.push(bpVoice(background, ctx));
  if (hours) bio.push(`${ctx.owner.Ref} will work in the business ${hours}.`);
  if (!bio.length) bio.push(`${ctx.owner.Ref} will manage the business day to day.`);
  parts.push(bpP(esc(bio.join(' '))));
  const team = ctx.team;
  if (team.staffing.length) {
    parts.push(bpH3('Roles and Responsibilities'));
    parts.push(
      bpP(
        esc(
          `The business will open with a team of ${bpTeamPhrase(team)}. Each role, what it covers and when it starts:`,
        ),
      ),
    );
    parts.push(
      bpTable(
        ['Role', 'Responsibilities', 'Hours / week', 'Starts'],
        team.staffing.map((r) => [bpRoleTitle(r), BP_ROLE_DUTIES[r.soc] || 'Supports daily operations.', `${Math.round(r.fte * 40)}`, bpStartText(r, team)]),
        { num: [2] },
      ),
    );
    // The table is already built from the owner's roles answer; repeat it only when the table is a
    // default team and the answer adds something.
    const roles = ctx.cm?.team_basis === 'founder' ? '' : ctx.text('key_roles');
    if (roles) parts.push(bpP(esc(`Division of responsibilities, as planned: ${bpWords(roles, ctx)}.`)));
    const staffing = ctx.text('staffing_plan');
    if (staffing) parts.push(bpP(esc(`Hiring plan: ${bpWords(staffing, ctx)}.`)));
  }
  parts.push(bpH3('Professional Advisors'));
  const advisors = ctx.text('advisors');
  parts.push(
    bpP(
      esc(
        advisors
          ? bpVoice(advisors, ctx)
          : `${ctx.subject} will retain an accountant, an attorney and an insurance agent before opening, to handle tax and payroll filings, lease and contract review, and coverage.`,
      ),
    ),
  );
  return parts.join('\n');
}

function bpProducts(ctx) {
  const parts = [];
  const offering = ctx.text('offering_detail');
  if (offering) parts.push(bpP(esc(`The menu of products and services: ${bpWords(offering, ctx)}.`)));
  const rm = ctx.rm;
  if (rm) {
    if (!offering) parts.push(bpP(esc(`${ctx.subject} will sell ${bpCount(rm.tiers.length)} products and services, each priced to cover its direct cost with a healthy margin:`)));
    parts.push(
      bpTable(
        ['Product or service', 'Price', 'Direct cost', 'Gross margin'],
        rm.tiers.map((t) => [t.name, `${priceText(t.price_usd)} ${BILLING_PRICE_SUFFIX[t.billing] || ''}`.trim(), priceText(t.unit_cost_usd), pct(t.gross_margin_pct)]),
        { num: [1, 2, 3] },
      ),
    );
    parts.push(bpSourceNote('Direct cost is the ingredients, materials or delivery cost of one unit; labor and overhead are in operating expenses.'));
  } else if (!offering) {
    const via = revenueLine(ctx.pipeline);
    parts.push(bpP(esc(/not yet decided/i.test(via) ? 'The revenue model is still to be decided: what is sold, and how customers pay, will be set before launch.' : `Revenue is generated through ${asMidSentence(via)}.`)));
    if (ctx.proj && !/not yet decided/i.test(via)) parts.push(bpP(esc(`Each item will be priced to recover its direct cost at a target gross margin of about ${pct(1 - ctx.proj.cogs_ratio)}, with prices reviewed quarterly against costs and local competitors.`)));
  }
  const unit = ctx.text('unit_economics');
  if (unit) parts.push(bpP(esc(`Unit economics: ${bpWords(answerProse(unit), ctx)}.`)));
  const lifecycle = ctx.text('lifecycle');
  if (lifecycle) {
    parts.push(bpH3('Development of the Offer'));
    parts.push(bpP(esc(bpVoice(lifecycle, ctx))));
  }
  return parts.filter(Boolean).join('\n') || bpP(esc(`${ctx.subject} will define its offer and pricing before opening.`));
}

function bpMarketing(ctx) {
  const parts = [];
  const { rm, proj } = ctx;
  if (rm) {
    const margins = rm.tiers.map((t) => t.gross_margin_pct).filter((x) => x != null);
    const lo = Math.min(...margins);
    const hi = Math.max(...margins);
    const pricingAnswer = ctx.text('pricing_basis');
    const pricing = answerPart(pricingAnswer, 'Our pricing', { orWhole: true });
    const nearby = answerPart(pricingAnswer, 'Prices nearby');
    parts.push(bpH3('Pricing Strategy'));
    parts.push(
      bpP(
        esc(
          `Prices are set per item to recover direct cost with gross margins of ${pct(lo)} to ${pct(hi)}, ${pricing ? bpVoice(pricing, ctx).replace(/^./, (c) => c.toLowerCase()) : 'and will be reviewed quarterly against direct costs and local competitors'}${pricing ? '' : '.'}${nearby ? ` Prices nearby: ${bpWords(nearby, ctx)}.` : ''}`,
        ),
      ),
    );
  }
  const channels = ctx.text('acquisition_channels');
  const first = ctx.text('first_customers');
  if (channels || first) {
    parts.push(bpH3('Sales and Marketing Channels'));
    const channelList = answerPart(channels, 'Channels', { orWhole: true });
    const approach = answerPart(channels, 'How');
    if (channelList) parts.push(bpP(esc(`Customers will be reached through ${bpWords(channelList, ctx).replace(/^./, (c) => c.toLowerCase())}.`)));
    if (approach) parts.push(bpP(esc(bpVoice(approach, ctx))));
    if (first) parts.push(bpP(esc(`The first customers will come from ${bpWords(first, ctx).replace(/^./, (c) => c.toLowerCase())}.`)));
  }
  const budget = ctx.text('marketing_budget');
  if (budget) parts.push(bpP(esc(`Budgeted cost to acquire a customer: ${bpWords(budget, ctx)}.`)));
  const retention = ctx.text('retention');
  if (retention) parts.push(bpP(esc(`Customers are brought back through ${bpWords(retention, ctx)}.`)));
  // Launch plan: what the opening sequence does.
  const launchMarketing = (proj?.fixed_setup_categories || []).find((c) => /marketing launch|launch marketing|pre-opening marketing/i.test(c.label));
  if (ctx.launch) {
    parts.push(bpH3('Launch Plan'));
    parts.push(
      bpP(
        esc(
          `Marketing will begin four to six weeks before opening with signage, a website and listings on the main search and map services, and outreach to neighbors, nearby employers and local groups. ${first ? 'A soft opening will test service before the public launch, followed by an opening event.' : 'A soft opening will test service before the public launch.'}${launchMarketing ? ` The launch budget is ${money(launchMarketing.amount_usd)}.` : ''}`,
        ),
      ),
    );
  }
  const goals = [];
  if (ctx.goal90) goals.push(['First 90 days', bpSentenceCase(ctx.goal90)]);
  if (rm) {
    const top = [...rm.tiers].sort((a, b) => b.monthly_revenue_month12_usd - a.monthly_revenue_month12_usd)[0];
    goals.push(['Month 12', `Monthly sales of ${money(rm.totals.monthly_revenue_month12_usd)}, including about ${volumeText(top.volume_month12)} ${(BILLING_VOLUME_NOUN[top.billing] || 'units')} of ${top.name.toLowerCase()} a month`]);
  }
  if (goals.length) {
    parts.push(bpH3('Goals'));
    parts.push(bpTable(['Period', 'Goal'], goals));
  }
  const marketing = sumMonthly(opexCategory(proj, /marketing/i));
  if (marketing > 0 || launchMarketing) {
    parts.push(bpH3('Marketing Budget'));
    const rows = [];
    if (launchMarketing) rows.push(['Pre-opening launch (one time)', money(launchMarketing.amount_usd)]);
    if (marketing > 0) {
      rows.push(['Ongoing marketing and advertising, per month', money(marketing)]);
      rows.push({ cells: ['Year 1 total', money(money2Sum(launchMarketing?.amount_usd || 0, marketing * 12))], cls: 'subtotal' });
    }
    parts.push(bpTable(['Item', 'Amount'], rows, { num: [1] }));
  }
  return parts.filter(Boolean).join('\n');
}

function bpLicenseTable(ctx) {
  const facts = openingFacts(ctx.pipeline);
  const tracks = complianceTracks(ctx.pipeline);
  if (!tracks.length) return '';
  const base = facts
    ? facts.rows
    : tracks.map((t) => ({ track: t, name: plainLicenseName(t.label), lead_months: t.planning_days != null ? leadMonths(t.planning_days) : null, allowance_months: null, basis: 'typical', gates: null }));
  const rows = base.map((r) => {
    const lead =
      r.lead_months == null
        ? '—'
        : r.basis === 'next_cycle'
          ? `About ${monthsText(r.lead_months)} (next application window)`
          : `About ${monthsText(r.lead_months)}${r.allowance_months > r.lead_months ? ` (allow up to ${r.allowance_months})` : ''}`;
    const needed =
      r.gates === 'opening'
        ? `Opening, expected ${bpWhen(ctx, r.approval_month)}`
        : r.gates === 'product'
          ? `${productList(r.products)}, from ${bpWhen(ctx, r.start_month)}`
          : /entity|ein/i.test(r.track.id)
            ? 'Banking, hiring and the lease'
            : 'Before that activity starts';
    return [r.name, { local: 'City or county', state: 'State', federal: 'Federal' }[r.track.level] || r.track.level || '', lead, needed];
  });
  return bpTable(['License or permit', 'Issued by', 'Expected lead time', 'Needed for'], rows);
}

/** The paragraph above the license table: when the business opens, and why then. */
function bpLicenseLead(ctx) {
  const facts = openingFacts(ctx.pipeline);
  if (!facts || !ctx.launch) return `${ctx.subject} will obtain the following before opening. Applications will be filed in order of lead time.`;
  const { sch, binding, gatedTiers } = facts;
  const bits = [`${ctx.subject} will file for each license in month 1, in order of lead time.`];
  if (binding && sch.binding === 'permit') {
    bits.push(`It opens in ${bpWhen(ctx, sch.opening_month)}, when the ${lowerFirst(binding.name)}, the longest of the approvals needed to open, is expected.`);
  } else if (binding) {
    bits.push(`It opens in ${bpWhen(ctx, sch.opening_month)}, after the approvals needed to open (the longest, the ${lowerFirst(binding.name)}, is expected by ${bpWhen(ctx, binding.approval_month)}).`);
  } else {
    bits.push(`It opens in ${bpWhen(ctx, sch.opening_month)}; none of these approvals needs to be in hand before it can trade.`);
  }
  const byLicense = new Map();
  for (const t of gatedTiers) {
    if (!byLicense.has(t.license.id)) byLicense.set(t.license.id, { license: t.license, tiers: [] });
    byLicense.get(t.license.id).tiers.push(t);
  }
  for (const { license, tiers } of byLicense.values()) {
    bits.push(`${productList(tiers)} ${tiers.length === 1 ? 'is' : 'are'} not sold until the ${lowerFirst(plainLicenseName(license.label))} is expected, in ${bpWhen(ctx, tiers[0].start_month)}; the forecast carries no revenue from ${tiers.length === 1 ? 'it' : 'them'} before then.`);
  }
  if (facts.rows.some((r) => r.basis === 'typical' && r.allowance_months > r.lead_months && r.gates)) {
    bits.push('Lead times are typical processing times; the longer allowance is the time to plan for if an office is slow, and Risks and Mitigations sets out what that would change.');
  }
  if (facts.rows.some((r) => r.basis === 'next_cycle' && r.gates)) {
    bits.push('A license whose application window is closed is scheduled for the next window.');
  }
  return bits.join(' ');
}

function bpOperationsPlan(ctx) {
  const parts = [];
  const o = bpOperations(ctx);
  const facility = ctx.text('facility');
  const remote = ['online_only', 'home'].includes(ctx.ops.space_type);
  parts.push(bpH3('Location and Facilities'));
  const where = ctx.place ? `${ctx.subject} will operate in ${ctx.place}` : `${ctx.subject} will choose its location for access to its customers`;
  if (facility && answerParts(facility).some((x) => x.label)) {
    parts.push(bpP(esc(`${where}.`)));
    parts.push(bpVoiceParts(facility, ctx));
  } else if (facility) parts.push(bpP(esc(`${where}. ${bpVoice(facility, ctx)}`)));
  else if (remote) parts.push(bpP(esc(`${where}, working ${ctx.ops.space_type === 'home' ? 'from a home office' : 'online'} with no customer-facing premises.`)));
  else {
    const rentLine = ctx.cm?.rent;
    parts.push(
      bpP(
        esc(
          `${where}. The site will offer ${o.site}.${rentLine?.square_feet ? ` The plan budgets for about ${rentLine.square_feet.toLocaleString('en-US')} square feet at ${money(rentLine.monthly_usd)} a month.` : ''}`,
        ),
      ),
    );
  }
  parts.push(bpP(esc(o.hours)));

  const team = ctx.team;
  if (team.people) {
    parts.push(bpH3('Staffing'));
    const wages = ctx.cm ? sumMonthly(opexCategory(ctx.proj, /wage|contractor/i)) : 0;
    const tax = ctx.cm ? sumMonthly(opexCategory(ctx.proj, /payroll|workers|health benefits/i)) : 0;
    parts.push(
      bpP(
        esc(
          `The ${bpCount(team.people)}-person team (${bpTeamSplit(team)}) is set out under Organization and Management.${wages > 0 ? ` Payroll is budgeted at local median wages: ${money(wages)} a month in wages plus ${money(tax)} in payroll taxes and insurance once the full team is in place.` : ''}`,
        ),
      ),
    );
  }

  parts.push(bpH3('Suppliers'));
  const suppliers = ctx.text('suppliers');
  parts.push(suppliers ? bpVoiceParts(suppliers, ctx) : bpP(esc(o.suppliers)));

  const setup = (ctx.proj?.fixed_setup_categories || []).filter((c) => /equipment|furniture|fixtures|technology|pos|computer/i.test(c.label));
  parts.push(bpH3('Equipment and Technology'));
  if (setup.length) {
    parts.push(bpP(esc(`The opening budget includes ${joinClauses(setup.map((c) => `${lowerFirst(c.label)} (${money(c.amount_usd)})`))}; the full list is in the start-up costs in the Financial Statements. ${o.technology}`)));
  } else {
    parts.push(bpP(esc(o.technology)));
  }

  parts.push(bpH3('Quality Control'));
  parts.push(bpP(esc(o.quality)));
  parts.push(bpH3('Customer Service'));
  parts.push(bpP(esc(o.service)));

  const licenses = bpLicenseTable(ctx);
  if (licenses) {
    parts.push(bpH3('Licenses and Permits'));
    parts.push(bpP(esc(bpLicenseLead(ctx))));
    parts.push(licenses);
  }

  parts.push(bpH3('Insurance'));
  const insurance = ctx.text('insurance');
  const budget = sumMonthly(opexCategory(ctx.proj, /insurance/i));
  parts.push(
    bpP(
      esc(
        insurance
          ? bpVoice(insurance, ctx)
          : `${ctx.subject} will carry the following coverage${budget > 0 ? `, budgeted at ${money(budget)} a month` : ''}: ${joinClauses(o.insurance)}.`,
      ),
    ),
  );
  return parts.join('\n');
}

function bpMilestones(ctx) {
  const { fin, proj, intake } = ctx;
  // Each row carries the plan month it falls in, so the table reads in date order, with a step that
  // later ones depend on (formation, then financing, then the lease) first within a month.
  const rows = [];
  const tracks = complianceTracks(ctx.pipeline);
  const months = (days) => Math.max(1, Math.round((Number(days) || 0) / 30));
  const formation = tracks.filter((t) => /entity|ein/i.test(t.id));
  const formationMonth = months(formation.reduce((a, t) => a + (Number(t.planning_days) || 0), 0));
  if (formation.length) rows.push(['Form the business entity and obtain a federal EIN', bpWhen(ctx, formationMonth), formationMonth]);
  const facts = ctx.launch ? openingFacts(ctx.pipeline) : null;
  const leaseStart = facts?.sch?.lease_start_month;
  if (fin.funding_gap_usd > 0 && intake.outside_money?.intent === 'yes') rows.push(['Close financing', 'Before buildout and equipment orders', (leaseStart || 1) + 0.001]);
  if (!ctx.text('facility') && ctx.cm?.rent && ctx.launch) rows.push(['Sign lease and begin buildout', leaseStart ? bpWhen(ctx, leaseStart) : 'After financing closes', (leaseStart || 1) + 0.002]);
  if (facts) {
    for (const r of facts.rows.filter((x) => !/entity|ein/i.test(x.track.id) && x.approval_month)) {
      rows.push([`${r.name} approved`, `${bpWhen(ctx, r.approval_month)}, about ${monthsText(r.lead_months)} from filing`, r.approval_month + 0.01]);
    }
  } else {
    for (const t of tracks.filter((x) => !/entity|ein/i.test(x.id))) {
      rows.push([`${plainLicenseName(t.label)} approved`, t.planning_days != null ? `Lead time about ${monthsText(months(t.planning_days))}` : 'Before opening', t.planning_days != null ? months(t.planning_days) + 0.01 : 900]);
    }
  }
  const firstRevenueMonth = proj ? proj.year1_monthly.findIndex((m) => m.revenue_usd > 0) + 1 : 0;
  // A date the founder picked is printed as the date itself when the plan can open on it.
  const picked = intake.opening?.source === 'founder' && intake.opening.choice === 'date' && facts?.sch?.binding === 'founder' ? intake.opening.date : null;
  if (firstRevenueMonth > 0 && ctx.launch) rows.push(['Open for business', picked ? `${bpLongDate(picked)} (month ${firstRevenueMonth})` : bpWhen(ctx, firstRevenueMonth), firstRevenueMonth + 0.5]);
  for (const t of facts?.gatedTiers || []) rows.push([`Begin selling ${lowerFirst(t.name)}`, bpWhen(ctx, t.start_month), t.start_month + 0.6]);
  const ph2 = ctx.fin.funding_need?.phase2;
  if (ph2) rows.push([`Second phase: ${money(ph2.capex_usd)} of equipment and build-out and the added staff, paid from the business's cash`, bpWhen(ctx, ph2.month), ph2.month + 0.7]);
  if (ctx.goal90) rows.push([bpSentenceCase(ctx.goal90), firstRevenueMonth > 0 ? `By ${bpWhen(ctx, firstRevenueMonth + 2)}` : 'First 90 days of trading', firstRevenueMonth > 0 ? firstRevenueMonth + 2.1 : 3.1]);
  if (proj?.break_even?.break_even_month) rows.push(['Monthly break-even', bpWhen(ctx, proj.break_even.break_even_month), proj.break_even.break_even_month + 0.2]);
  if (ctx.rm) {
    rows.push([`Monthly sales of ${money(ctx.rm.totals.monthly_revenue_month12_usd)}`, bpWhen(ctx, 12), 12.3]);
    rows.push([`Monthly sales of ${money(ctx.rm.totals.monthly_revenue_month36_usd)}`, bpWhen(ctx, 36), 36.3]);
  }
  if (!rows.length) return bpP(esc(`${ctx.subject} will set dated milestones once its opening date is fixed.`));
  return `${bpP(esc(ctx.cal ? `The plan begins in ${ctx.cal.long(1)}. Dates depend on financing and permits and will move with them.` : 'Timings are counted from the start of the plan, since the opening date depends on financing and permits.'))}
${bpTable(['Milestone', 'Timing'], rows.map((r, i) => ({ r, i })).sort((a, b) => (a.r[2] ?? 900) - (b.r[2] ?? 900) || a.i - b.i).map(({ r }) => [r[0], r[1]]))}`;
}

function bpSwot(ctx) {
  const { fin, proj, intake } = ctx;
  const s = [];
  const w = [];
  const o = [];
  const t = [];
  const background = ctx.text('founder_background');
  if (background) s.push('Hands-on operating experience in the business the owner is opening.');
  if (ctx.edge) s.push('A distinctive concept aimed at a defined local customer base.');
  const ratio = fin.funding_realism?.owner_equity_ratio;
  if (ratio != null && ratio >= 0.1) s.push(`The owner is contributing ${Math.round(Math.min(ratio, 1) * 100)}% of the project cost in equity.`);
  if (ctx.rm && ctx.rm.tiers.length > 2) s.push('Several revenue lines that spread sales across the day and the week.');
  if (ctx.rm) {
    const gm = ctx.rm.totals.annual[1]?.gross_margin_pct;
    if (gm != null && gm >= 0.6) s.push(`High gross margins (about ${pct(gm)} across the mix).`);
  }

  if (ctx.launch) w.push('A new business with no trading history; the forecast rests on expected prices and volumes.');
  if (ctx.team.people <= 1) w.push('Depends on the owner alone at opening.');
  const below = ctx.kinds.debt && fin.debt_service?.applicable ? fin.debt_service.years_below_threshold || [] : [];
  if (below.some((y) => y > 1)) w.push(`Earnings do not cover loan payments at the lender's usual 1.25× in ${below.length === 3 ? 'any of the three years projected' : `Years ${below.join(' and ')}`}; the loan is sized to carry the losses until then.`);
  else if (below.includes(1)) w.push('Year 1 earnings do not cover loan payments while sales ramp up; payments in that year are funded from the loan’s working-capital reserve.');
  if (proj && proj.cash_flow_trough_usd < 0) w.push('Cash is tight during the first-year ramp.');
  if (!ctx.decided) w.push('The site has not been selected.');

  if (intake.customer) o.push(`A defined customer base: ${asMidSentence(clause(intake.customer))}.`);
  const trend = ctx.text('industry_trend');
  for (const x of answerParts(trend)) o.push(bpVoice(x.text, ctx));
  const lifecycle = ctx.text('lifecycle');
  if (lifecycle) o.push(bpVoice(lifecycle, ctx));
  if (ctx.rm?.tiers?.some((x) => /catering|event|subscription|wholesale/i.test(x.name))) o.push('Catering, events and subscriptions add revenue beyond walk-in trade.');
  if (ctx.kinds.grant) o.push('Local grant programs may reduce the cost of launch; none is assumed in this plan.');

  if (ctx.risk) t.push(bpSentence(ctx.risk));
  const competitors = competitorNames(ctx.text('named_competitors'));
  if (competitors.length) t.push(`Competition from ${joinClauses(competitors.map((c) => asMidSentence(c)))}.`);
  if (complianceTracks(ctx.pipeline).some((x) => x.cycle_status === 'closed' || x.cycle_status === 'closing_soon')) t.push('Permit and license timing can delay opening.');
  t.push('Rising food, labor and occupancy costs.'.replace('food, ', ctx.industryId === 'food_service' ? 'food, ' : ''));

  const cell = (items) => (items.length ? `<ul>${items.map((i) => `<li>${esc(i)}</li>`).join('')}</ul>` : '');
  return `<table class="doc-table swot-table">
<tr><th>Strengths</th><th>Weaknesses</th></tr>
<tr><td>${cell(s)}</td><td>${cell(w)}</td></tr>
<tr><th>Opportunities</th><th>Threats</th></tr>
<tr><td>${cell(o)}</td><td>${cell(t)}</td></tr>
</table>`;
}

function bpRisks(ctx) {
  const { fin, proj, intake } = ctx;
  const rows = [];
  if (ctx.risk) {
    const m = [];
    if (/licen|permit/i.test(ctx.risk)) m.push(openingFacts(ctx.pipeline)?.gatedTiers?.length ? 'Applications are filed in month 1, the opening is set after the approvals needed to open, and products that need their own license are not sold until it is expected.' : 'Applications are filed in month 1, and the opening is set after the approvals needed to open.');
    if (/cash|winter|season|slow/i.test(ctx.risk)) m.push(`The project budget carries ${money(fin.line_items?.reserve_usd)} of contingency and working capital to carry slow months.`);
    rows.push([bpSentenceCase(ctx.risk), m.join(' ') || 'Management will monitor this monthly against the plan.']);
  }
  const need = capitalRequirement(ctx.pipeline);
  if (need && need.extra_reserve_usd > 0) {
    rows.push([
      `Cash runs short during the first-year ramp: the forecast needs a further ${money(need.extra_reserve_usd)} around month ${need.trough_month}.`,
      `Carrying the ramp takes about ${money(need.total_usd)} in total; the gap will be closed with additional capital, lower monthly costs or a faster ramp before launch.`,
    ]);
  }
  const low = fin.sensitivity?.rows?.find((r) => r.revenue_change_pct === -20);
  rows.push([
    'Sales ramp more slowly than forecast.',
    `The forecast has been re-run at 20% lower volumes${low ? `: the lowest Year 1 cash balance would be ${money(low.year1_low_cash_usd)}` : ''}. Hours, staffing and purchasing will be adjusted monthly against actual sales.`,
  ]);
  // Forecast warnings, stated as business risks; the check itself is in Founder's Notes.
  const FORECAST_RISKS = {
    customers_implausible_vs_market: ['The forecast depends on winning a large share of nearby customers.', 'Volumes will be tested with pre-opening sales and early trading, and staffing and purchasing scaled to actual demand.'],
    far_above_cost_implied: ['Forecast sales are high for the size of the team and cost base.', 'Staffing will be added only as sales reach each level, and volumes will be tested against early trading.'],
    far_below_cost_implied: ['Forecast sales are low for the size of the team and cost base.', 'Hours and roles will be matched to sales, and prices and the offer reviewed monthly.'],
    below_break_even: ['Forecast sales stay below break-even.', 'Prices, the cost base and the offer will be revised before launch until the plan reaches break-even.'],
    unit_cost_at_or_above_price: ['One product is priced at or below its direct cost.', 'That product will be repriced or dropped before launch.'],
  };
  for (const f of (ctx.rm?.flags || []).filter((x) => x.severity === 'warning' && FORECAST_RISKS[x.code])) rows.push(FORECAST_RISKS[f.code]);
  rows.push([
    'Start-up costs exceed estimates.',
    'A contingency reserve is held back from the financing, and equipment and buildout will be priced from written quotes before orders are placed.',
  ]);
  if (ctx.kinds.debt && fin.debt_service?.applicable && fin.debt_service.terms && (fin.debt_service.years_below_threshold || []).length) {
    const later = fin.debt_service.years_below_threshold.filter((y) => y > 1);
    rows.push([
      later.length ? 'Earnings do not cover loan payments at the assumed rate in some years.' : 'Loan payments begin before sales reach their run rate.',
      later.length
        ? 'Management will size the loan, term and owner contribution with the lender so coverage clears the lender’s minimum.'
        : 'Year 1 payments are funded from the project budget, and management will ask the lender for an interest-only period during the ramp.',
    ]);
  }
  if (complianceTracks(ctx.pipeline).some((x) => x.cycle_status === 'closed' || x.cycle_status === 'closing_soon')) {
    rows.push(['A required license is issued on a fixed filing cycle.', 'The application will be prepared ahead of the next window, and revenue that depends on it is not scheduled before approval.']);
  }
  // A slower approval, re-run through the model: what the opening and the capital would become.
  const delay = fin.opening_analysis?.permit_delay;
  const bindingPermit = openingFacts(ctx.pipeline)?.binding;
  if (delay && bindingPermit && ctx.launch) {
    rows.push([
      `The ${lowerFirst(bindingPermit.name)} takes longer than its typical time.`,
      `If it took the full ${monthsText(bindingPermit.allowance_months)} allowed for, opening would move to ${bpWhen(ctx, delay.opening_month)} and the project would need about ${money(delay.total_capital_usd - fin.opening_analysis.base.total_capital_usd)} more. The plan review will be filed in month 1 and the office's current timeline confirmed before the lease is signed.`,
    ]);
  }
  if (!ctx.decided) rows.push(['The site has not been chosen.', 'Rent, licensing and local rules will be confirmed during site selection, before financing closes.']);
  if (intake.revenue_model?.status === 'unknown') rows.push(['The revenue model has not been set.', 'Prices and sales channels will be set, and the forecast rebuilt from them, before launch.']);
  if (ctx.industryId === 'food_service') rows.push(['Food and labor costs rise.', 'Menu prices will be reviewed quarterly against food cost, and schedules built against forecast sales.']);
  rows.push(['Key-person dependence on the owner.', 'Written procedures and a trained shift lead will let the business run in the owner’s absence; key-person insurance will be considered.']);
  return bpTable(['Risk', 'Mitigation'], rows);
}

/**
 * The capital position in one or two plain sentences: the total project, what the owner puts in,
 * and the financing required, for every case — a request made, a need with no request yet, owner
 * capital of zero, or owner capital not yet set.
 */
function bpAskSentences(ctx) {
  const { fin, proj, intake } = ctx;
  const su = proj?.sources_and_uses;
  if (!su) return [];
  const gap = fin.funding_gap_usd;
  const capital = personalCapitalUsd(ctx.pipeline);
  const total = su.total_uses_usd;
  const uop = fin.use_of_proceeds;
  const sba = /\bsba\b/i.test(intake.outside_money?.raw || '');
  const out = [];
  if (gap > 0 && intake.outside_money?.intent === 'yes') {
    const what = ctx.kinds.debt ? `a term loan of ${money(gap)}${sba ? ' under the SBA 7(a) program' : ''}` : ctx.kinds.equity ? `${money(gap)} of equity investment` : `${money(gap)} of outside financing`;
    out.push(`${ctx.subject} is requesting ${what}${uop?.stated_by_founder ? ', the amount management has set for this raise' : ''}.`);
    out.push(capital > 0 ? `The owner will contribute ${money(capital)} in cash equity, for a total project of ${money(total)}.` : capital === 0 ? `The owner is not contributing cash equity, so the full ${money(total)} project is financed from outside.` : `The total project is ${money(total)}.`);
  } else if (gap === 0) {
    out.push(`The owner will fund the full ${money(total)} project; no outside financing is requested.`);
    if (intake.outside_money?.approximate_amount_usd > 0) out.push(`The ${money(intake.outside_money.approximate_amount_usd)} the owner plans to raise would fund growth beyond this plan.`);
  } else if (gap > 0) {
    out.push(`The project requires ${money(total)} in total.`);
    out.push(capital > 0 ? `The owner will contribute ${money(capital)}, leaving ${money(gap)} of outside financing required.` : `The owner is not contributing cash equity, so the full ${money(gap)} is outside financing required.`);
    out.push(intake.outside_money?.intent === 'none' ? 'The owner does not plan to seek outside money, so the plan would be funded by additional owner capital, a smaller launch or lower costs.' : 'The form of that financing (loan, investment or grant) will be chosen before launch, so no specific request is made in this plan.');
  } else {
    out.push(`The project requires ${money(total)} in total. Owner capital has not been set, so the full amount is shown as financing required; owner equity reduces it dollar for dollar.`);
  }
  const need = capitalRequirement(ctx.pipeline);
  if (need && need.extra_reserve_usd > 0) {
    out.push(`At its lowest, around month ${need.trough_month}, the monthly cash flow runs a further ${money(need.extra_reserve_usd)} below zero, so carrying the first-year ramp takes about ${money(need.total_usd)} in total unless costs come down or sales build faster.`);
  }
  return out;
}

/**
 * What the amount covers, by the funding rule: to monthly cash break-even (capped at a set number of
 * months after opening), or over an equity runway. A plan that is not cash-positive by the cap says
 * so, with the losses after it that the request does not fund.
 */
function bpFundingNeedSentences(ctx) {
  const fn = ctx.fin.funding_need;
  const hasLoan = Boolean(ctx.fin.projections?.loan);
  const loanText = hasLoan ? ' and loan payments' : '';
  const lossesText = hasLoan ? 'pre-opening costs, operating losses and loan payments' : 'pre-opening costs and operating losses';
  if (!fn) return [`The amount covers equipment, buildout and start-up costs; opening working capital; operating costs${loanText} until the business is cash-positive; and a contingency reserve.`];
  if (fn.rule === 'equity_runway') {
    return [`The amount covers equipment and start-up costs, opening working capital, the operating losses over a ${fn.horizon_months}-month runway from the raise, and a contingency reserve.`];
  }
  if (fn.break_even_within_horizon) {
    return [`The amount covers equipment, buildout and start-up costs; opening working capital; ${lossesText} until the business reaches monthly cash break-even, which the forecast puts in ${bpWhen(ctx, fn.break_even_month)}; and a contingency reserve.`];
  }
  const out = [`The amount covers equipment, buildout and start-up costs; opening working capital; ${lossesText} through ${bpWhen(ctx, fn.horizon_months)}, ${monthsText(fn.horizon_months_after_opening)} after opening; and a contingency reserve.`];
  if (fn.unfunded_losses_after_horizon_usd > 0) {
    out.push(`On this forecast the business is not yet cash-positive by then: it would lose a further ${money(fn.unfunded_losses_after_horizon_usd)} ${fn.break_even_month ? `before it breaks even in ${bpWhen(ctx, fn.break_even_month)}` : 'through the 36 months projected'}. That shortfall is not part of this request, and no loan is sized to cover it; management will close it before financing is drawn.`);
  }
  return out;
}

function bpRunwaySentence(fin) {
  const r = fin.use_of_proceeds?.runway;
  if (!r) return '';
  if (r.basis === 'self_sustaining') return `On the forecast, the business is cash-positive from about month ${r.cash_flow_positive_month} with the contingency still in hand.`;
  if (r.basis === 'cash_out') return `At the forecast burn rate the capital lasts about ${r.months} months before the contingency reserve is touched${r.months_including_contingency ? `, and about ${r.months_including_contingency} months if the reserve is spent` : ''}.`;
  if (r.basis === 'beyond_horizon') {
    // months counts from month 1; what is left after the projection is the part past month 36.
    const more = r.months != null ? r.months - 36 : null;
    return more > 0
      ? `The capital lasts through the 36 months projected, and what remains then would last about ${monthsText(more)} more at the month-36 burn rate.`
      : 'The capital lasts through the 36 months projected, with the business still using cash at month 36.';
  }
  return '';
}

function bpFundingRequest(ctx) {
  const { fin, proj, intake } = ctx;
  const parts = [];
  const gap = fin.funding_gap_usd;
  const capital = personalCapitalUsd(ctx.pipeline);
  if (!proj) return bpP(esc(`${ctx.subject} will finalize its financing requirement with its lender.`));
  if (ctx.revision) {
    parts.push(bpP(esc(gap > 0 ? `${ctx.subject} is seeking ${money(gap)} to fund the plan’s working-capital need.` : `${ctx.subject} will fund this plan from operations; no outside financing is sought.`)));
    return parts.join('\n');
  }
  const su = proj.sources_and_uses;
  parts.push(bpP(esc(bpAskSentences(ctx).join(' '))));
  parts.push(bpH3('Sources and Uses of Funds'));
  parts.push(
    bpTable(
      ['Sources', 'Amount'],
      [...su.sources.filter((x) => x.amount_usd > 0 || su.sources.length === 1).map((x) => [bpSourceLabel(x, ctx), money(x.amount_usd)]), { cells: ['Total sources', money(su.total_sources_usd)], cls: 'grand-total' }],
      { num: [1] },
    ),
  );
  parts.push(bpTable(['Uses', 'Amount'], [...su.uses.map((u) => [u.label, money(u.amount_usd)]), { cells: ['Total uses', money(su.total_uses_usd)], cls: 'grand-total' }], { num: [1] }));
  const uop = fin.use_of_proceeds;
  const bits = [];
  bits.push(...bpFundingNeedSentences(ctx));
  const runway = bpRunwaySentence(fin);
  if (runway) bits.push(runway);
  if (uop?.stated_by_founder && uop.runway && uop.runway.basis !== 'self_sustaining' && uop.month36_net_burn_usd > 0) bits.push(`The business is still burning about ${money(uop.month36_net_burn_usd)} a month at month 36, so a further round, or revenue ahead of plan, is needed before this capital runs out.`);
  parts.push(bpH3('Use of Proceeds'));
  parts.push(bpP(esc(bits.join(' '))));
  if (ctx.spend.must_have_spend || ctx.spend.can_defer_spend) {
    const pri = [];
    if (ctx.spend.must_have_spend) pri.push(`Proceeds will be spent first on ${clause(ctx.spend.must_have_spend).replace(/^./, (c) => c.toLowerCase())}.`);
    if (ctx.spend.can_defer_spend) pri.push(`Items such as ${clause(ctx.spend.can_defer_spend).replace(/^./, (c) => c.toLowerCase())} will be deferred until revenue supports them.`);
    parts.push(bpP(esc(pri.join(' '))));
  }
  const termsSought = ctx.text('funding_terms');
  if (termsSought) {
    parts.push(bpH3('Terms Requested'));
    const loanTerms = answerParts(termsSought).filter((x) => !x.label).map((x) => x.text).join(' ');
    const investorTerms = answerPart(termsSought, 'Investor terms');
    if (loanTerms) parts.push(bpP(esc(`${ctx.subject} is requesting ${bpWords(loanTerms, ctx)}.`)));
    if (investorTerms) parts.push(bpP(esc(`From investors, ${ctx.subject} is seeking ${bpWords(investorTerms, ctx)}.`)));
  }
  if (ctx.kinds.debt && gap > 0 && fin.debt_service?.applicable && fin.debt_service.terms) {
    const ds = fin.debt_service;
    const sc = primaryDebtScenario(ds);
    const t = ds.terms;
    parts.push(bpH3('Proposed Terms'));
    parts.push(
      bpP(
        esc(
          `${t.basis === 'founder' ? `The request assumes ${pct(t.annual_rate, 2)} over ${t.term_years} years` : `The plan assumes a ${t.term_years}-year term at ${pct(t.annual_rate, 2)}, the SBA 7(a) maximum rate for a loan of this size (prime of ${pct(t.prime_rate, 2)} plus ${pct(t.spread, 1)}); a lower quoted rate improves every figure`}. The level payment is ${money(sc.monthly_payment_usd)} a month. Debt service coverage (EBITDA over annual principal and interest) is ${sc.coverage.map((c) => `${c.dscr == null ? 'not covered' : `${c.dscr}×`} in Year ${c.year}`).join(', ')}.`,
        ),
      ),
    );
    parts.push(bpP(esc(`Collateral will be pledged as the lender requires, including the business’s equipment and fixtures. ${/\bsba\b/i.test(intake.outside_money?.raw || '') ? 'As SBA rules require, each owner of 20% or more will personally guarantee the loan.' : 'The owner will provide a personal guarantee.'}`)));
  }
  if (ctx.kinds.equity) {
    const exit = ctx.text('exit_strategy');
    parts.push(bpH3('For Investors'));
    const ownership = ctx.text('ownership');
    parts.push(bpP(esc([ownership ? 'Current ownership is set out under Company Description.' : '', 'Valuation and terms will be agreed with investors in definitive documents.', exit ? bpVoice(exit, ctx) : ''].filter(Boolean).join(' '))));
  }
  if (ctx.kinds.grant) parts.push(bpP(esc(`${ctx.subject} will also apply for local grant programs for which it is eligible. No grant is included in the sources of funds above.`)));
  return parts.filter(Boolean).join('\n');
}

function bpSourceLabel(src, ctx) {
  if (/owner capital/i.test(src.label)) return 'Owner equity (cash)';
  if (/loan/i.test(src.label)) return /\bsba\b/i.test(ctx.intake.outside_money?.raw || '') ? 'SBA 7(a) term loan (requested)' : 'Term loan (requested)';
  if (/equity financing/i.test(src.label)) return 'Equity investment (sought)';
  return 'Outside financing';
}

function bpSalesForecast(ctx) {
  const rm = ctx.rm;
  const proj = ctx.proj;
  if (!proj) return '';
  if (!rm) {
    if (ctx.revision) return bpP(esc(`Revenue starts from current monthly sales of ${money(proj.current_position?.monthly_revenue_usd)} and follows the growth plan set out above.`));
    return bpP(esc(`Revenue is forecast from the sales this cost base is designed to support: ${money(proj.stabilized_monthly_revenue_usd)} a month at full operation. It will be replaced with a product-by-product forecast as prices and volumes are confirmed.`));
  }
  const yearHeaders = proj.years.map((y) => `Year ${y.year}`);
  const tierRows = rm.tiers.map((t) =>
    t.start_month > 12
      ? [t.name, `${priceText(t.price_usd)} ${BILLING_PRICE_SUFFIX[t.billing] || ''}`.trim(), `From ${ctx.cal ? ctx.cal.long(t.start_month) : `month ${t.start_month}`}`, money(0)]
      : [t.name, `${priceText(t.price_usd)} ${BILLING_PRICE_SUFFIX[t.billing] || ''}`.trim(), `${volumeText(t.volume_month12)} ${BILLING_VOLUME_NOUN[t.billing] || 'units'}`, money(t.monthly_revenue_month12_usd)],
  );
  const tierTable = bpTable(['Product or service', 'Price', 'Volume a month (month 12)', 'Sales a month (month 12)'], [...tierRows, { cells: ['Total', '', '', money(rm.totals.monthly_revenue_month12_usd)], cls: 'grand-total' }], { num: [1, 2, 3] });
  const annualRows = rm.tiers.map((t) => [t.name, ...t.annual.map((a) => money(a.revenue_usd))]);
  const annualTable = bpTable(
    ['Annual sales by product', ...yearHeaders],
    [
      ...annualRows,
      { cells: ['Total revenue', ...rm.totals.annual.map((a) => money(a.revenue_usd))], cls: 'subtotal' },
      { cells: ['Direct cost of sales', ...rm.totals.annual.map((a) => money(a.cogs_usd))] },
      { cells: ['Gross profit', ...rm.totals.annual.map((a) => `${money(a.gross_margin_usd)} (${pct(a.gross_margin_pct)})`)], cls: 'grand-total' },
    ],
    { num: [1, 2, 3] },
  );
  const mc = rm.market_check || {};
  const share =
    mc.serviceable_customers && mc.implied_customers_month36 != null
      ? ` At month-36 volumes the forecast implies about ${Math.round(mc.implied_customers_month36).toLocaleString('en-US')} regular customers, roughly ${pct(mc.share, 0)} of the ${mc.serviceable_customers.toLocaleString('en-US')} potential customers management estimates are within reach.`
      : '';
  const gated = rm.tiers.filter((t) => t.license && t.start_month > rm.first_revenue_month);
  const gatedText = gated.length
    ? ` ${productList(gated)} ${gated.length === 1 ? 'starts' : 'start'} in ${bpWhen(ctx, gated[0].start_month)}, once the ${lowerFirst(plainLicenseName(gated[0].license.label))} is expected, and ${gated.length === 1 ? 'builds' : 'build'} from there.`
    : '';
  return `${bpP(esc(`Sales are forecast product by product from expected prices and monthly volumes. Trading begins in ${bpWhen(ctx, rm.first_revenue_month)}; volumes build steadily from the opening through the month-12 figures below and continue to month 36.${gatedText}${share}`))}
${tierTable}
${annualTable}`;
}

function bpFinancialPlan(ctx) {
  const { fin, proj } = ctx;
  if (!proj) return bpP('Financial projections accompany this plan.');
  const parts = [];
  const y1 = proj.year1_totals;
  parts.push(
    bpP(
      esc(
        `The accompanying Financial Statements set out the monthly profit and loss and cash flow for Year 1, annual statements for Years 2 and 3, opening and year-end balance sheets, break-even analysis, sensitivity and debt service. The summary below is drawn from them. In Year 1 the business is forecast to earn ${money(y1.revenue_usd)} in revenue with ${y1.operating_income_usd < 0 ? `an operating loss of ${money(Math.abs(y1.operating_income_usd))} while sales build` : `operating income of ${money(y1.operating_income_usd)}`}.`,
      ),
    ),
  );
  const history = ctx.text('historical_financials');
  if (history) parts.push(bpP(esc(`Recent trading: ${bpWords(history, ctx)}.`)));
  parts.push(bpH3('Sales Forecast'));
  parts.push(bpSalesForecast(ctx));
  const expected = ctx.text('revenue_basis');
  if (expected && !ctx.rm) {
    const pieces = answerParts(expected);
    if (pieces.some((x) => x.label)) {
      parts.push(bpP(esc('Management expects the volumes below; the projections are built from the cost base and will be rebuilt product by product from them.')));
      parts.push(bpVoiceParts(expected, ctx));
    } else parts.push(bpP(esc(`Management expects ${bpWords(expected, ctx)}; the projections are built from the cost base and will be rebuilt product by product from those volumes.`)));
  }
  parts.push(bpH3('Projected Profit and Loss'));
  const hasInterest = proj.years.some((y) => y.interest_expense_usd > 0);
  const hasDep = proj.years.some((y) => y.depreciation_usd > 0);
  const net = proj.years.map((y) => wholeDollar(y.operating_income_usd) - wholeDollar(y.interest_expense_usd || 0) - wholeDollar(y.estimated_income_tax_usd));
  parts.push(`<table class="doc-table">
<tr><th></th>${proj.years.map((y) => `<th class="num">Year ${y.year}</th>`).join('')}</tr>
${finRow('Revenue', proj.years.map((y) => y.revenue_usd))}
${finRow('Cost of goods sold', proj.years.map((y) => y.cogs_usd))}
${finRow('Gross profit', proj.years.map((y) => y.gross_profit_usd), 'subtotal')}
${finRow('Operating expenses', proj.years.map((y) => y.opex_usd))}
${hasDep ? finRow('EBITDA', proj.years.map((y) => y.ebitda_usd), 'subtotal') : ''}
${hasDep ? finRow('Depreciation and amortization', proj.years.map((y) => y.depreciation_usd)) : ''}
${finRow('Operating income', proj.years.map((y) => y.operating_income_usd), 'subtotal')}
${hasInterest ? finRow('Interest expense', proj.years.map((y) => wholeDollar(y.interest_expense_usd || 0))) : ''}
${finRow('Estimated income tax', proj.years.map((y) => wholeDollar(y.estimated_income_tax_usd)))}
${finRow('Net income', net, 'grand-total')}
</table>`);
  if (!ctx.revision) {
    parts.push(bpH3('Projected Balance Sheet'));
    parts.push(projectedBalanceSheetHtml(proj));
  }
  const be = proj.break_even;
  parts.push(bpH3('Break-Even'));
  parts.push(
    bpP(
      esc(
        `Break-even monthly revenue is fixed cash operating costs divided by the gross margin: ${money(be.fixed_costs_monthly_usd)} ÷ ${pct(be.contribution_margin_ratio)} = ${money(be.break_even_monthly_revenue_usd)}. ${be.break_even_month ? `The forecast passes it around month ${be.break_even_month}.` : 'The forecast does not reach it within Year 1.'}`,
      ),
    ),
  );
  const sens = sensitivityTableHtml(fin, ctx.kinds.debt);
  if (sens) {
    parts.push(bpH3('Sensitivity'));
    parts.push(sens);
  }
  parts.push(bpH3('Key Assumptions'));
  parts.push(`<ul>${bpKeyAssumptions(ctx).map((a) => `<li>${esc(a)}</li>`).join('')}</ul>`);
  return parts.filter(Boolean).join('\n');
}

function bpKeyAssumptions(ctx) {
  const { fin, proj, cm, rm } = ctx;
  const out = [];
  if (rm) out.push(`Revenue is built from each product’s price and expected monthly volume; direct cost is each product’s unit cost, ${pct(proj.cogs_ratio, 1)} of revenue across the Year 2 mix.`);
  else {
    if (!ctx.revision && proj.assumptions?.[0]) out.push(proj.assumptions[0]);
    out.push(`Cost of goods sold is ${pct(proj.cogs_ratio, 1)} of revenue.`);
  }
  if (cm) out.push(`Payroll is costed role by role at Bureau of Labor Statistics median wages for the area, plus employer payroll taxes and workers’ compensation.`);
  if (cm?.rent?.basis === 'allowance') out.push(`Rent is an allowance of ${money(cm.rent.monthly_usd)} a month for about ${cm.rent.square_feet.toLocaleString('en-US')} square feet of street-front space ($${cm.rent.annual_per_sq_ft_usd.toFixed(2)} per square foot a year), within a planning range of ${money(cm.rent.monthly_low_usd)} to ${money(cm.rent.monthly_high_usd)}. The only published rate for ${cm.rent.published_area}, $${cm.rent.published_per_sq_ft_usd.toFixed(2)}, covers shopping centers, which lease below street-front space in the city center; a lease quote will replace the allowance.`);
  if (cm?.rent?.basis === 'benchmark') out.push(`Rent is ${money(cm.rent.monthly_usd)} a month: about ${cm.rent.square_feet.toLocaleString('en-US')} square feet at $${cm.rent.annual_per_sq_ft_usd.toFixed(2)} per square foot a year, the published asking rate for retail space in the area; the signed lease will replace it.`);
  else if (cm?.rent?.basis === 'founder') out.push(`Rent is ${money(cm.rent.monthly_usd)} a month, as quoted.`);
  if (cm) out.push('Other operating costs are set from published industry ratios; sources are listed in the Financial Statements.');
  const sch = cm?.schedule;
  if (sch && ctx.launch && sch.opening_month > 1) {
    const lease = sch.lease_start_month && sch.lease_start_month < sch.opening_month ? sch.lease_start_month : null;
    out.push(`Before opening (months 1 to ${sch.opening_month - 1}) the business carries only pre-opening costs: the owner's pay${lease ? `, and from the lease start in month ${lease}, rent and insurance, with utilities at a quarter of the running level while the space is built out` : ''}. Staff, marketing and other running costs start at opening, and there are no sales before it.`);
  }
  if (proj.years.some((y) => y.depreciation_usd > 0)) out.push('Equipment, buildout and start-up costs are depreciated or amortized on a straight-line basis over their stated lives.');
  out.push(`Income tax is estimated at a flat ${pct(proj.income_tax_rate)} of positive pre-tax income for planning purposes.`);
  if (proj.loan) out.push(`The loan is repaid in level monthly payments from month 1.`);
  return out;
}

function bpAppendix(ctx) {
  const items = [
    'Financial Statements (accompanying this plan)',
    'Résumé of the owner and key managers',
    'Personal financial statement for each owner of 20% or more (SBA Form 413)',
    'Personal federal tax returns for the last three years',
    ctx.intake.existing_company_deepen?.already_formed === 'yes' ? 'Formation documents and ownership records' : 'Formation documents, once the entity is registered',
    'Lease or letter of intent for the premises',
    'Vendor quotes for equipment and buildout',
    'Copies of license and permit applications',
  ];
  if (ctx.intake.stage === 'existing' || ctx.intake.stage === 'launched') items.splice(4, 0, 'Business tax returns and year-to-date financial statements');
  const extra = ctx.text('supporting_documents');
  const sources = packSources(ctx.fin);
  return `${bpH3('Supporting Documents')}
${bpP(esc('The following documents accompany this plan or will be provided with the loan application:'))}
<ul>${items.map((i) => `<li>${esc(i)}</li>`).join('')}</ul>${extra ? bpP(esc(bpVoice(extra, ctx))) : ''}${sources.length ? `
${bpH3('Sources')}
${conciseSourcesHtml(sources)}` : ''}`;
}

function bpCover(ctx, docName, extraLine) {
  const c = ctx.intake.plan_detail?.company || {};
  const date = (() => {
    const d = ctx.asOf ? new Date(`${ctx.asOf}T12:00:00Z`) : new Date();
    return d.toLocaleDateString('en-US', { month: 'long', year: 'numeric', timeZone: 'UTC' });
  })();
  const nameLine = ctx.named ? companyTitle(ctx.pipeline) : bpVoice(ctx.intake.business_description || 'Business plan', ctx).replace(/\.$/, '');
  const contact = [c.address, c.phone, c.email, c.website].map((x) => String(x || '').trim()).filter(Boolean);
  const prepared = ctx.owner.name ? `Prepared by ${ctx.owner.name}, ${ctx.owner.title}` : '';
  return `<p class="cover-name">${esc(nameLine)}</p>
<p class="cover-doc">${esc(docName)}</p>
${extraLine ? `<p class="cover-line">${esc(extraLine)}</p>` : ''}
${prepared ? `<p class="cover-line">${esc(prepared)}</p>` : ''}
<p class="cover-line">${esc(date)}</p>
${ctx.place ? `<p class="cover-line">${esc(ctx.place)}</p>` : ''}
${contact.length ? `<div class="cover-contact">${contact.map((x) => `<p class="cover-line">${esc(x)}</p>`).join('')}</div>` : ''}
<p class="cover-confidential"><strong>Confidential.</strong> For planning purposes only; not financial, legal, tax, or investment advice. Please read the Important Notice on page 2.</p>`;
}

/**
 * The sections a complete lender business plan carries, in order, by id. Built from the SBA's
 * traditional format (executive summary, company description, market analysis, organization and
 * management, products, marketing and sales, funding request, financial projections, appendix),
 * extended with what SBA 7(a) lenders and equity investors each look for beyond it: a competitive
 * analysis, an operations plan, milestones, a SWOT and a risk register. See
 * docs/BUSINESS_PLAN_COMPLETENESS_2026-09-24.md.
 */
const BUSINESS_PLAN_SECTION_IDS = Object.freeze([
  'cover',
  'executive_summary',
  'company_description',
  'market_analysis',
  'competitive_analysis',
  'organization_management',
  'product_service_line',
  'marketing_sales',
  'operations_plan',
  'milestones',
  'swot_analysis',
  'risks_mitigations',
  'funding_request',
  'financial_projections_narrative',
  'appendix',
  'disclaimer',
]);

/** Section headings, by id. Sub-headings inside sections never repeat one of these. */
const BUSINESS_PLAN_HEADINGS = Object.freeze({
  executive_summary: 'Executive Summary',
  company_description: 'Company Description',
  market_analysis: 'Industry and Market Analysis',
  competitive_analysis: 'Competitive Analysis',
  organization_management: 'Organization and Management',
  product_service_line: 'Products and Services',
  marketing_sales: 'Marketing and Sales Strategy',
  operations_plan: 'Operations Plan',
  milestones: 'Milestones and Timeline',
  swot_analysis: 'SWOT Analysis',
  risks_mitigations: 'Risks and Mitigations',
  funding_request: 'Funding Request',
  financial_projections_narrative: 'Financial Plan',
  appendix: 'Appendix',
  disclaimer: 'Forward-Looking Statements',
});

const BUSINESS_PLAN_WRITERS = Object.freeze({
  executive_summary: bpExecutiveSummary,
  company_description: bpCompanyDescription,
  market_analysis: bpMarketAnalysis,
  competitive_analysis: bpCompetition,
  organization_management: bpManagement,
  product_service_line: bpProducts,
  marketing_sales: bpMarketing,
  operations_plan: bpOperationsPlan,
  milestones: bpMilestones,
  swot_analysis: bpSwot,
  risks_mitigations: bpRisks,
  funding_request: bpFundingRequest,
  financial_projections_narrative: bpFinancialPlan,
  appendix: bpAppendix,
  disclaimer: (ctx) =>
    `${bpP(esc(`This plan contains projections based on management’s assumptions about prices, volumes and costs as of ${ctx.asOf}. Actual results will differ, and the differences may be material. The projections are not a guarantee of performance.`))}${
      ctx.kinds.equity ? bpP(esc('This plan is not an offer to sell, or a solicitation of an offer to buy, any security. Any investment would be made only through definitive documents and in compliance with applicable securities laws.')) : ''
    }`,
});

function confidentialityNotice(pipeline) {
  return `This plan describes ${hasBusinessName(pipeline) ? `the business of ${companyTitle(pipeline)}` : 'a business in formation'} and is provided to the recipient to evaluate it. Please do not reproduce or pass it on without the owner's permission.`;
}

/**
 * @param {object} pipeline
 * @param {string} asOf
 * @param {{ edition?: 'lender' }} [opts]  The edition picks which writers run and at what depth;
 *   only the lender edition exists today.
 */
function buildBusinessPlan(pipeline, asOf, opts = {}) {
  const ctx = { ...bpContext(pipeline), asOf, edition: opts.edition || 'lender', cal: planCalendar(pipeline, asOf) };
  const loc = locationLine(pipeline);
  const sections = [
    { id: 'cover', heading: 'Cover', body_html: bpCover(ctx, 'Business Plan') },
    ...BUSINESS_PLAN_SECTION_IDS.filter((id) => id !== 'cover').map((id) => ({
      id,
      heading: BUSINESS_PLAN_HEADINGS[id],
      body_html: BUSINESS_PLAN_WRITERS[id](ctx),
    })),
  ];
  return {
    id: 'business_plan',
    name: 'Business Plan',
    filename: 'Business Plan.html',
    purpose: catalogEntry('business_plan').purpose,
    status: 'draft',
    cover_kind: 'business',
    confidentiality: confidentialityNotice(pipeline),
    // Outstanding sections show as "Draft" in the running header only; what is outstanding is
    // listed in the To-Do List and Founder's Notes, never in the plan itself.
    draft: planGapsFor(pipeline).some((g) => g.blocking),
    snippet: `Business Plan for ${companyTitle(pipeline)} · ${stageLabel(pipeline)} stage · ${loc}.`,
    sections,
  };
}


/** One line item across a period series, in accounting convention: line items as rows, periods as columns. */
function finRow(label, values, cls, hasTotalCol) {
  const rowCls = cls ? ` class="${cls}"` : '';
  const cells = values
    .map((v, i) => {
      const isTotalCol = hasTotalCol && i === values.length - 1;
      return `<td class="num${isTotalCol ? ' total-col' : ''}">${esc(money(v))}</td>`;
    })
    .join('');
  return `<tr${rowCls}><td>${esc(label)}</td>${cells}</tr>`;
}

// ---------------------------------------------------------------------------------------------
// Calendar. The model counts months from the start of the plan; the documents print real months.
// ---------------------------------------------------------------------------------------------

const MONTH_ABBR = Object.freeze(['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']);
const MONTH_FULL = Object.freeze(['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']);

/**
 * When month 1 of the plan falls. A start date the owner gave is used as given; "immediately"
 * (revenue already coming in, or expected within 30 days) starts the plan the month after the
 * plan date. Otherwise the plan assumes a start three months after the plan date, and Founder's
 * Notes says so.
 */
/**
 * "opens in month 4" -> "opens in month 4 (March 2027)". The finance engine counts plan months and
 * has no calendar; a reader needs the month it falls in. A month already followed by a bracket, or
 * outside the three projected years, is left as it is.
 */
function withCalendarMonths(text, cal) {
  if (!cal) return String(text);
  return String(text).replace(/\bmonth (\d{1,2})\b(?![\d-]| \()/g, (all, n) => {
    const m = Number(n);
    return m >= 1 && m <= 36 ? `month ${m} (${cal.long(m)})` : all;
  });
}

function planCalendar(pipeline, asOf) {
  const intake = pipeline?.intake || {};
  const explicit =
    intake.plan_detail?.operations?.start_date || intake.interview_deepen?.financial?.start_date || intake.interview_deepen?.operational?.start_date || null;
  const plan = new Date(`${String(asOf || new Date().toISOString().slice(0, 10)).slice(0, 10)}T12:00:00Z`);
  let year;
  let month;
  let basis;
  const m = /^(\d{4})-(\d{2})/.exec(String(explicit || ''));
  const timing = intake.interview_deepen?.financial?.first_revenue_timing;
  // The opening question (Instant question 9 or the Guided Interview) counts the plan date's month
  // as month 1 of the model, so the calendar does too; the opening itself is a month of the plan.
  const openingQ = /^(\d{4})-(\d{2})/.exec(String(intake.opening?.plan_date || ''));
  if (m) {
    year = Number(m[1]);
    month = Number(m[2]) - 1;
    basis = 'founder';
  } else if (openingQ) {
    year = Number(openingQ[1]);
    month = Number(openingQ[2]) - 1;
    basis = intake.opening.source === 'founder' ? 'opening' : 'opening_default';
  } else if (timing === 'already' || timing === 'under_30_days' || /^immediate/i.test(String(explicit || ''))) {
    year = plan.getUTCFullYear();
    month = plan.getUTCMonth() + 1;
    basis = 'immediate';
  } else {
    year = plan.getUTCFullYear();
    month = plan.getUTCMonth() + 3;
    basis = 'default';
  }
  year += Math.floor(month / 12);
  month = ((month % 12) + 12) % 12;
  const at = (n) => {
    const idx = month + n - 1;
    return { year: year + Math.floor(idx / 12), month: ((idx % 12) + 12) % 12 };
  };
  return {
    basis,
    start_year: year,
    start_month_index: month,
    start_iso: `${year}-${String(month + 1).padStart(2, '0')}-01`,
    short: (n) => {
      const d = at(n);
      return `${MONTH_ABBR[d.month]} ${String(d.year).slice(2)}`;
    },
    long: (n) => {
      const d = at(n);
      return `${MONTH_FULL[d.month]} ${d.year}`;
    },
  };
}

// ---------------------------------------------------------------------------------------------
// Financial Statements. Set out the way an accountant-prepared projection package is: start-up
// costs and capital required, sources and uses, the sales forecast, the cost build-up, monthly
// Year 1 statements, annual Years 1-3, balance sheets, break-even, sensitivity, debt service,
// assumptions and sources. Conclusions only; checks and advice live in Founder's Notes.
// ---------------------------------------------------------------------------------------------

function fsNote(text) {
  return text ? `<p class="table-note">${esc(text)}</p>` : '';
}

function projectedBalanceSheetHtml(proj) {
  if (!proj?.projected_balance_sheets?.length) return '';
  const bs = proj.projected_balance_sheets;
  const open = proj.balance_sheet;
  const heads = bs.map((b) => `<th class="num">End of Year ${b.year}</th>`).join('');
  const hasDep = bs.some((b) => b.accumulated_depreciation_usd > 0);
  const cost = [open.assets.fixed_assets_cost_usd ?? open.assets.fixed_assets_usd, ...bs.map((b) => b.fixed_assets_cost_usd ?? b.fixed_assets_usd)];
  return `<table class="doc-table">
<tr><th>Balance sheet</th><th class="num">Opening</th>${heads}</tr>
${finRow('Cash', [open.assets.cash_usd, ...bs.map((b) => b.cash_usd)])}
${hasDep ? finRow('Equipment, buildout and start-up assets, at cost', cost) : ''}
${hasDep ? finRow('Less accumulated depreciation and amortization', [0, ...bs.map((b) => -(b.accumulated_depreciation_usd || 0))]) : ''}
${finRow(hasDep ? 'Net fixed and start-up assets' : 'Equipment, buildout and start-up assets', [open.assets.fixed_assets_usd, ...bs.map((b) => b.fixed_assets_usd)], hasDep ? 'subtotal' : null)}
${finRow('Total assets', [open.assets.total_assets_usd, ...bs.map((b) => b.total_assets_usd)], 'subtotal')}
${finRow(open.liabilities.loan_payable_usd > 0 ? 'Loan payable' : 'Financing payable', [open.liabilities.financing_payable_usd, ...bs.map((b) => b.financing_payable_usd)])}
${finRow(open.equity.outside_equity_usd > 0 ? 'Equity (owners and investors)' : "Owner's equity", [open.equity.total_equity_usd, ...bs.map((b) => b.total_equity_usd)])}
${finRow('Total liabilities and equity', [money2Sum(open.liabilities.total_liabilities_usd, open.equity.total_equity_usd), ...bs.map((b) => b.total_liabilities_and_equity_usd)], 'grand-total')}
</table>
${fsNote(`Year-end cash carries forward from the cash flow. Equity is ${open.equity.outside_equity_usd > 0 ? 'owner capital plus equity raised plus' : 'owner capital plus'} cumulative net income.${
    open.liabilities.loan_payable_usd > 0 ? ' The loan balance falls each year by the principal repaid.' : open.liabilities.financing_payable_usd > 0 ? ' Outside financing is shown at the amount required until its type and terms are set.' : ''
  }${hasDep ? ' Fixed and start-up assets are shown at cost less straight-line depreciation and amortization; opening inventory and deposits are not depreciated.' : ''}`)}`;
}

/** Years 1-3 cash, the annual view beside the year-end balance sheets. */
function annualCashSummaryHtml(proj) {
  const rows = proj?.annual_cash_summary;
  if (!rows?.length) return '';
  const heads = rows.map((r) => `<th class="num">Year ${r.year}</th>`).join('');
  const hasDep = rows.some((r) => r.depreciation_usd > 0);
  return `<table class="doc-table">
<tr><th>Annual cash summary</th>${heads}</tr>
${finRow('Beginning cash', rows.map((r) => r.beginning_cash_usd))}
${hasDep ? finRow('Net income', rows.map((r) => r.net_income_usd)) : ''}
${hasDep ? finRow('Add back depreciation and amortization', rows.map((r) => r.depreciation_usd)) : ''}
${finRow('Net cash from operations', rows.map((r) => r.net_cash_from_operations_usd), hasDep ? 'subtotal' : null)}
${rows.some((r) => r.loan_principal_repaid_usd > 0) ? finRow('Loan principal repaid', rows.map((r) => -(r.loan_principal_repaid_usd || 0))) : ''}
${rows.some((r) => r.capital_spending_usd > 0) ? finRow('Second-phase equipment and build-out', rows.map((r) => -(r.capital_spending_usd || 0))) : ''}
${finRow('Ending cash', rows.map((r) => r.ending_cash_usd), 'grand-total')}
</table>
${fsNote('Year 1 matches the monthly cash flow. Cash from operations is net income plus the non-cash depreciation charge; the model carries no receivables, payables or inventory build.')}`;
}

/** Revenue sensitivity, re-run through the same model. Shared by the plan and the statements. */
function sensitivityTableHtml(fin, debtSought) {
  const sens = fin.sensitivity;
  if (!sens?.rows?.length) return '';
  const withDscr = debtSought && sens.dscr_terms != null;
  return `<p>${esc(
    fin.projections?.revenue_basis === 'buildup'
      ? "The forecast re-run with every product's volume 10% and 20% below plan and 10% above, so direct costs move with sales; operating costs and loan payments are held at the base case."
      : 'The forecast re-run with revenue 10% and 20% below plan and 10% above; costs and loan payments are held at the base case.',
  )}</p>
<table class="doc-table">
<tr><th>Sales vs. plan</th><th class="num">Year 1 revenue</th><th class="num">Year 1 operating income</th><th class="num">Lowest Year 1 cash</th><th class="num">Break-even month</th><th class="num">Year 2 operating income</th>${
    withDscr ? '<th class="num">Year 2 coverage</th>' : ''
  }</tr>
${sens.rows
  .map(
    (r) => `<tr${r.revenue_change_pct === 0 ? ' class="subtotal"' : ''}><td>${r.revenue_change_pct === 0 ? 'Base case' : `${r.revenue_change_pct > 0 ? '+' : '−'}${Math.abs(r.revenue_change_pct)}%`}</td><td class="num">${esc(
      money(r.year1_revenue_usd),
    )}</td><td class="num">${esc(money(r.year1_operating_income_usd))}</td><td class="num">${esc(money(r.year1_low_cash_usd))}</td><td class="num">${
      r.break_even_month ? esc(r.break_even_month) : '—'
    }</td><td class="num">${esc(money(r.year2_operating_income_usd))}</td>${withDscr ? `<td class="num">${r.year2_dscr_mid == null ? '—' : `${esc(r.year2_dscr_mid)}×`}</td>` : ''}</tr>`,
  )
  .join('\n')}
</table>`;
}

/** The role-by-role staffing table: occupation, hours, local median wage, employer cost. */
function staffingTableHtml(fin, cal) {
  const cm = fin.cost_model;
  if (!cm?.staffing?.length) return '';
  const rows = cm.staffing
    .map(
      (r) => `<tr><td>${esc(r.title.replace(/^./, (c) => c.toUpperCase()))}${r.count > 1 ? ` (×${esc(r.count)})` : ''}${r.contractor ? ' (contract)' : ''}${
        r.start_month > 1 ? `<br><span class="doc-muted">from month ${esc(r.start_month)}${cal ? ` (${esc(cal.long(r.start_month))})` : ''}</span>` : ''
      }</td><td>${esc(r.occupation)}</td><td class="num">${esc(hoursPerWeek(r.fte))}</td><td class="num">$${esc(r.median_hourly_usd.toFixed(2))}</td><td class="num">${esc(money(r.monthly_employer_cost_usd))}</td></tr>`,
    )
    .join('');
  const levels = [...new Set(cm.staffing.map((r) => r.wage_level))];
  const area = cm.place.status === 'not_decided' ? 'national medians until the location is set' : levels.length === 1 && levels[0] === 'metro' ? `${cm.staffing[0].wage_area} metro-area medians` : `the finest area available for each role (${levels.join(', ')})`;
  return `<table class="doc-table">
<tr><th>Role</th><th>Occupation (BLS)</th><th class="num">Hours</th><th class="num">Median wage</th><th class="num">Employer cost / month</th></tr>
${rows}
<tr class="subtotal"><td colspan="4">Payroll with the full team in place</td><td class="num">${esc(money(cm.payroll.steady_state_monthly_usd))}</td></tr>
</table>
${fsNote(`Wages are Bureau of Labor Statistics May 2025 medians for each occupation, using ${area}. Employer cost adds Social Security and Medicare (7.65%), federal unemployment tax, state unemployment insurance at the ${
    cm.payroll.suta.basis === 'state' ? `${cm.payroll.suta.state} new-employer rate (${pct(cm.payroll.suta.rate, 2)})` : `median published new-employer rate (${pct(cm.payroll.suta.rate, 2)})`
  }, and workers' compensation at $${cm.payroll.workers_comp.per_100_usd.toFixed(2)} per $100 of payroll${cm.payroll.health_benefit_offered ? ', plus the employer share of single health coverage for full-time roles' : ''}. Median wages for tipped roles include tips.`)}`;
}

function fsLineBasis(l, fin) {
  if (l.basis === 'founder') return 'Quoted figure';
  if (l.basis === 'benchmark_rent') {
    const r = fin.cost_model?.rent;
    if (r?.basis === 'allowance') return `Allowance: ${r.square_feet.toLocaleString('en-US')} sq ft × $${r.annual_per_sq_ft_usd.toFixed(2)} per sq ft a year (range $${r.annual_per_sq_ft_low_usd.toFixed(2)} to $${r.annual_per_sq_ft_high_usd.toFixed(2)})`;
    return r ? `${r.square_feet.toLocaleString('en-US')} sq ft × $${r.annual_per_sq_ft_usd.toFixed(2)} per sq ft a year` : 'Local asking rent';
  }
  return `${pct(l.ratio, 2)} of revenue at full operation`;
}

/** The cost build-up: payroll and each overhead line with its basis and source. */
function costBuildUpHtml(fin, cal) {
  const cm = fin.cost_model;
  if (!cm) return '';
  const b = cm.payroll.annual_burden_usd;
  const burdenRows = [
    ['Wages and salaries', cm.payroll.annual_wages_usd],
    ['Social Security and Medicare (employer share)', b.social_security_usd + b.medicare_usd],
    ['Federal unemployment tax', b.futa_usd],
    ['State unemployment insurance', b.suta_usd],
    ["Workers' compensation", b.workers_comp_usd],
    b.health_usd > 0 ? ['Employee health benefits', b.health_usd] : null,
  ]
    .filter(Boolean)
    .map(([k, v]) => `<tr><td>${esc(k)}</td><td class="num">${esc(money(v))}</td></tr>`)
    .join('');
  const lineRows = cm.lines
    .map((l) => `<tr><td>${esc(l.label)}</td><td class="num">${esc(money(l.monthly_usd))}</td><td>${esc(fsLineBasis(l, fin))}</td><td>${esc(l.basis === 'founder' ? 'Founder' : sourcePublisher(fin, l.source))}</td></tr>`)
    .join('');
  const cogsRows = cm.cogs_components
    .map((c) => `<tr><td>${esc(c.label.replace(/^./, (x) => x.toUpperCase()))}</td><td class="num">${esc(pct(c.ratio, 1))}</td><td>${esc(sourcePublisher(fin, c.source))}</td></tr>`)
    .join('');
  return `<p>${esc(`Operating costs are built from the planned team, the location and published benchmarks for ${cm.industry.label.toLowerCase().replace(/\s*\(.*\)$/, '')} businesses${cm.industry.naics ? ` (NAICS ${cm.industry.naics})` : ''}. A quoted figure replaces a benchmark wherever one is available.`)}</p>
<h3>Staffing</h3>
${staffingTableHtml(fin, cal)}
<table class="doc-table">
<tr><th>Annual payroll with the full team</th><th class="num">Amount</th></tr>
${burdenRows}
<tr class="subtotal"><td>Total annual employer payroll cost</td><td class="num">${esc(money(cm.payroll.steady_state_monthly_usd * 12))}</td></tr>
</table>
<h3>Occupancy and Overhead</h3>
<table class="doc-table">
<tr><th>Line</th><th class="num">Monthly</th><th>Basis</th><th>Source</th></tr>
${lineRows}
</table>
<h3>Direct Costs</h3>
<p>${esc(fin.projections?.revenue_basis === 'buildup' ? "Direct costs are each product's unit cost times its volume (see Sales Forecast). The industry benchmark below is shown for comparison." : 'Direct costs move with sales at the industry benchmark below.')}</p>
<table class="doc-table">
<tr><th>Component</th><th class="num">Share of revenue</th><th>Source</th></tr>
${cogsRows}
</table>`;
}

/** Every published source behind the pack's figures, de-duplicated. */
function packSources(fin) {
  const seen = new Set();
  return [...(fin.data_sources || []), ...(fin.market_context?.sources || [])].filter((s) => {
    if (!s?.url || seen.has(s.id)) return false;
    seen.add(s.id);
    return true;
  });
}

/** The year a source refers to, for a short citation. */
function sourceYear(src) {
  const m = String(src.reference_period || '').match(/(20\d\d)/);
  return m ? m[1] : '';
}

/**
 * The concise source list a lender document carries: publisher, title and year. URLs, retrieval
 * dates and verification notes are provenance for the owner and live in Founder's Notes.
 */
function conciseSourcesHtml(sources) {
  if (!sources.length) return '';
  return `<ul class="doc-sources">${sources
    .map((src) => `<li>${esc(src.publisher)}, <em>${esc(src.title)}</em>${sourceYear(src) ? `, ${esc(sourceYear(src))}` : ''}.</li>`)
    .join('')}</ul>`;
}

/** Full provenance for Founder's Notes: URL, reference period and retrieval date for each source. */
function fullSourcesHtml(fin) {
  const sources = packSources(fin);
  if (!sources.length) return '';
  return `<p>Every published figure in the Business Plan and Financial Statements comes from the data table below (version ${esc(fin.benchmarks_version || '')}). Nothing is fetched when the documents are produced. Check a figure at its URL before relying on it, and replace benchmarks with quotes as they arrive.</p>
<ul class="doc-sources">${sources
    .map((src) => `<li>${esc(src.publisher)}, <em>${esc(src.title)}</em> (${esc(src.reference_period)}). ${esc(src.url)}, retrieved ${esc(src.retrieved)}.${src.note ? ` ${esc(src.note)}` : ''}</li>`)
    .join('')}</ul>`;
}

function plTableHtml(proj, cal) {
  if (!proj) return '<p>Profit and loss projections accompany the final plan.</p>';
  const t = proj.year1_totals;
  // Net income derives from the already-rounded cells, so the printed rows subtract exactly.
  const monthlyTax = proj.year1_monthly.map((m) => wholeDollar(m.estimated_income_tax_usd));
  const monthlyOpInc = proj.year1_monthly.map((m) => wholeDollar(m.operating_income_usd));
  const monthlyInterest = proj.year1_monthly.map((m) => wholeDollar(m.interest_expense_usd || 0));
  const monthlyNetIncome = monthlyOpInc.map((oi, i) => oi - monthlyInterest[i] - monthlyTax[i]);
  const totalTax = wholeDollar(t.estimated_income_tax_usd);
  const totalOpInc = wholeDollar(t.operating_income_usd);
  const totalInterest = wholeDollar(t.interest_expense_usd || 0);
  const totalNetIncome = totalOpInc - totalInterest - totalTax;
  const hasInterest = proj.years.some((y) => y.interest_expense_usd > 0);
  const hasDep = proj.years.some((y) => y.depreciation_usd > 0);
  const label = (m) => (cal ? cal.short(m.month) : `M${m.month}`);

  const monthHeaders = proj.year1_monthly.map((m) => `<th class="num">${esc(label(m))}</th>`).join('');
  const monthlyTable = `<table class="doc-table fin-table-wide">
<tr><th>Year 1, by month</th>${monthHeaders}<th class="num total-col">Year 1</th></tr>
${finRow('Revenue', [...proj.year1_monthly.map((m) => m.revenue_usd), t.revenue_usd], null, true)}
${finRow('Cost of goods sold', [...proj.year1_monthly.map((m) => m.cogs_usd), t.cogs_usd], null, true)}
${finRow('Gross profit', [...proj.year1_monthly.map((m) => m.gross_profit_usd), t.gross_profit_usd], 'subtotal', true)}
${finRow('Operating expenses', [...proj.year1_monthly.map((m) => m.opex_usd), t.opex_usd], null, true)}
${hasDep ? finRow('EBITDA', [...proj.year1_monthly.map((m) => m.ebitda_usd), t.ebitda_usd], 'subtotal', true) : ''}
${hasDep ? finRow('Depreciation and amortization', [...proj.year1_monthly.map((m) => m.depreciation_usd), t.depreciation_usd], null, true) : ''}
${finRow('Operating income', [...proj.year1_monthly.map((m) => m.operating_income_usd), t.operating_income_usd], 'subtotal', true)}
${hasInterest ? finRow('Interest expense', [...monthlyInterest, totalInterest], null, true) : ''}
${finRow('Estimated income tax', [...monthlyTax, totalTax], null, true)}
${finRow('Net income', [...monthlyNetIncome, totalNetIncome], 'grand-total', true)}
</table>`;

  const opexCatRows = proj.opex_categories.map((c) => `<tr><td>${esc(c.label)}</td><td class="num">${esc(money(c.monthly_usd))}</td></tr>`).join('');
  const yearsTax = proj.years.map((y) => wholeDollar(y.estimated_income_tax_usd));
  const yearsOpInc = proj.years.map((y) => wholeDollar(y.operating_income_usd));
  const yearsInterest = proj.years.map((y) => wholeDollar(y.interest_expense_usd || 0));
  const yearsNetIncome = yearsOpInc.map((oi, i) => oi - yearsInterest[i] - yearsTax[i]);
  const yearHeaders = proj.years.map((y) => `<th class="num">Year ${y.year}</th>`).join('');
  const yearsTable = `<table class="doc-table">
<tr><th>Years 1 to 3</th>${yearHeaders}</tr>
${finRow('Revenue', proj.years.map((y) => y.revenue_usd))}
${finRow('Cost of goods sold', proj.years.map((y) => y.cogs_usd))}
${finRow('Gross profit', proj.years.map((y) => y.gross_profit_usd), 'subtotal')}
${finRow('Operating expenses', proj.years.map((y) => y.opex_usd))}
${hasDep ? finRow('EBITDA', proj.years.map((y) => y.ebitda_usd), 'subtotal') : ''}
${hasDep ? finRow('Depreciation and amortization', proj.years.map((y) => y.depreciation_usd)) : ''}
${finRow('Operating income', proj.years.map((y) => y.operating_income_usd), 'subtotal')}
${hasInterest ? finRow('Interest expense', yearsInterest) : ''}
${finRow('Estimated income tax', yearsTax)}
${finRow('Net income', yearsNetIncome, 'grand-total')}
</table>`;

  const chart = svgLineChart({
    xLabels: proj.year1_monthly.map((m) => label(m)),
    series: [
      { values: proj.year1_monthly.map((m) => m.revenue_usd), color: ACCENT },
      { values: proj.year1_monthly.map((m) => m.net_income_usd), color: ACCENT_LIGHT },
    ],
  });

  return `<p>${esc(
    `Year 1 is shown month by month${cal ? `, beginning ${cal.long(1)}` : ''}. ${
      proj.revenue_basis === 'buildup'
        ? "Revenue and cost of goods sold come from the sales forecast: each product's price and unit cost times its volume."
        :`${proj.mode === 'launch' ? 'Revenue is implied by costs, not a sales forecast. ' : ''}Cost of goods sold is ${pct(proj.cogs_ratio, 1)} of revenue${proj.mode === 'launch' ? ', the published benchmark for this industry' : ''}.`
    }${hasInterest ? ' Loan interest is charged below operating income from the amortization schedule.' : ''} Estimated income tax is a flat ${pct(proj.income_tax_rate)} of positive pre-tax income.`,
  )}</p>
${monthlyTable}
<figure class="chart-figure">${chart}${chartLegend([
    { color: ACCENT, label: 'Revenue' },
    { color: ACCENT_LIGHT, label: 'Net income' },
  ])}</figure>
<h3>Monthly Operating Expenses</h3>
<p>${esc(proj.mode === 'launch' ? 'Operating expenses by category with the full team in place. The basis and source of each line are in the Operating Cost Build-up.' : 'Operating expenses by category, an indicative split of the current monthly total.')}</p>
<table class="doc-table">
<tr><th>Category</th><th class="num">Monthly</th></tr>
${opexCatRows}
<tr class="subtotal"><td>Total monthly operating expenses</td><td class="num">${esc(money(money2Sum(...proj.opex_categories.map((c) => c.monthly_usd))))}</td></tr>
</table>
<h3>Annual Summary</h3>
${yearsTable}`;
}

function cashFlowTableHtml(proj, cal) {
  if (!proj) return '<p>Cash flow projections accompany the final plan.</p>';
  const label = (m) => (cal ? cal.short(m.month) : `M${m.month}`);
  const monthHeaders = proj.year1_cash_flow.map((m) => `<th class="num">${esc(label(m))}</th>`).join('');
  const hasDebt = proj.year1_cash_flow.some((m) => m.debt_service_paid_usd > 0);
  const table = `<table class="doc-table fin-table-wide">
<tr><th>Year 1, by month</th>${monthHeaders}</tr>
${finRow('Beginning cash', proj.year1_cash_flow.map((m) => m.beginning_cash_usd))}
${finRow('Cash receipts', proj.year1_cash_flow.map((m) => m.cash_receipts_usd))}
${finRow('Operating cash paid out', proj.year1_cash_flow.map((m) => m.cash_paid_out_usd))}
${finRow('Estimated income tax paid', proj.year1_cash_flow.map((m) => m.estimated_income_tax_paid_usd ?? 0))}
${hasDebt ? finRow('Loan interest paid', proj.year1_cash_flow.map((m) => m.interest_paid_usd || 0)) : ''}
${hasDebt ? finRow('Loan principal repaid', proj.year1_cash_flow.map((m) => m.loan_principal_paid_usd || 0)) : ''}
${proj.year1_cash_flow.some((m) => m.capital_spending_usd > 0) ? finRow('Second-phase equipment and build-out', proj.year1_cash_flow.map((m) => m.capital_spending_usd || 0)) : ''}
${finRow('Total cash paid out', proj.year1_cash_flow.map((m) => m.total_cash_paid_out_usd ?? m.cash_paid_out_usd), 'subtotal')}
${finRow('Ending cash', proj.year1_cash_flow.map((m) => m.ending_cash_usd), 'grand-total')}
</table>`;
  const trough = proj.cash_flow_trough_usd;
  const chart = svgLineChart({
    xLabels: proj.year1_cash_flow.map((m) => label(m)),
    series: [{ values: proj.year1_cash_flow.map((m) => m.ending_cash_usd), color: ACCENT, fillNegative: true }],
    zeroLine: true,
  });
  const summary =
    trough < 0
      ? `At the capital shown, cash falls below zero around ${cal ? cal.long(proj.cash_flow_trough_month) : `month ${proj.cash_flow_trough_month}`}, reaching ${money(trough)}; an additional ${money(proj.additional_reserve_needed_usd)} of working capital keeps it positive through the first year.`
      : `Cash stays positive through Year 1; the lowest balance is ${money(trough)}${proj.cash_flow_trough_month ? ` in ${cal ? cal.long(proj.cash_flow_trough_month) : `month ${proj.cash_flow_trough_month}`}` : ''}.`;
  return `<p>${esc(`Cash-basis view of the same Year 1, starting from the opening cash on the balance sheet.${hasDebt ? ' Loan principal and interest are paid monthly from the first month.' : ''} ${summary}`)}</p>
${table}
<figure class="chart-figure">${chart}${chartLegend([{ color: ACCENT, label: 'Ending cash balance' }])}</figure>`;
}

/** Debt service for the modeled loan: terms, amortization by year, and coverage. */
function modeledDebtServiceHtml(ds) {
  const t = ds.terms;
  const a = ds.amortization;
  const primary = primaryDebtScenario(ds);
  const hasExisting = ds.existing_debts_disclosed && ds.existing_annual_debt_service_usd > 0;
  const termsText =
    t.basis === 'founder'
      ? `${pct(t.annual_rate, 2)} over ${t.term_years} years, as quoted`
      : `${pct(t.annual_rate, 2)} over ${t.term_years} years. The rate is the SBA 7(a) maximum variable rate for a loan of this size (prime of ${pct(t.prime_rate, 2)} as of ${t.rate_as_of}, from the Federal Reserve's published series, plus the ${pct(t.spread, 1)} maximum spread); the term is the 7(a) maximum for working capital, equipment and leasehold improvements. A lower quoted rate improves every figure`;
  const amortRows = a.annual
    .map((y) => `<tr><td>Year ${esc(y.year)}</td><td class="num">${esc(money(y.debt_service_usd))}</td><td class="num">${esc(money(y.interest_usd))}</td><td class="num">${esc(money(y.principal_usd))}</td><td class="num">${esc(money(y.ending_balance_usd))}</td></tr>`)
    .join('');
  const covRows = ds.scenarios
    .map(
      (sc) => `<tr${sc.primary ? ' class="subtotal"' : ''}><td>${esc(sc.primary ? 'Modeled terms' : 'Rate two points higher')} · ${esc(pct(sc.annual_rate, 2))} over ${esc(sc.term_years)} years</td><td class="num">${esc(money(sc.monthly_payment_usd))}</td>${
        hasExisting ? `<td class="num">${esc(money(money2Sum(ds.existing_annual_debt_service_usd / 12)))}</td>` : ''
      }<td class="num">${esc(money(sc.annual_debt_service_usd))}</td>${sc.coverage.map((c) => `<td class="num">${c.dscr == null ? '—' : `${esc(String(c.dscr))}×`}</td>`).join('')}</tr>`,
    )
    .join('');
  const yearHeaders = (primary?.coverage || []).map((c) => `<th class="num">Year ${esc(c.year)}</th>`).join('');
  const below = ds.years_below_threshold || [];
  const verdict = below.length
    ? below.includes(1) && below.length === 1
      ? `Coverage is below ${ds.reference_minimum}× in Year 1 while sales build: payments start in the first month, and Year 1 EBITDA falls short of them by ${money(primary.year_one_shortfall_usd)}. Those payments are included in the capital requirement, so cash stays positive, and management will request an interest-only period during the ramp. Coverage is ${primary.coverage.filter((c) => c.year > 1).map((c) => `${c.dscr}× in Year ${c.year}`).join(' and ')}.`
      : `Coverage is below ${ds.reference_minimum}× in Year ${below.join(' and Year ')}. Management will size the loan, term and owner contribution with the lender so that coverage meets the lender's minimum.`
    : `Coverage is at or above ${ds.reference_minimum}× in every projected year.`;
  return `<p>${esc(`The proposed loan of ${money(a.principal_usd)} is modeled at ${termsText}. The level payment is ${money(a.monthly_payment_usd)} a month over ${a.term_months} months, with ${money(a.total_interest_usd)} of interest over the life of the loan. Interest is an expense in the profit and loss; principal and interest are paid in the cash flow from the first month, and the balance sheet loan balance falls by the principal repaid.`)}</p>
<table class="doc-table">
<tr><th>Amortization</th><th class="num">Payments</th><th class="num">Interest</th><th class="num">Principal</th><th class="num">Balance at year end</th></tr>
${amortRows}
</table>
<p>${esc('Debt service coverage is EBITDA (operating income before depreciation and amortization) divided by annual principal and interest. A dash marks a year with negative EBITDA.')}</p>
<table class="doc-table">
<tr><th>Terms</th><th class="num">Monthly payment</th>${hasExisting ? '<th class="num">Existing monthly</th>' : ''}<th class="num">Annual debt service</th>${yearHeaders}</tr>
${covRows}
</table>
<p>${esc(verdict)}</p>
${ds.existing_debts_disclosed ? '' : fsNote('The business carries no other debt; coverage reflects the proposed loan only.')}`;
}

/** Debt service when no loan is modeled, or when coverage is shown across rate scenarios. */
function debtServiceHtml(ds) {
  if (!ds) return '<p>No loan is modeled in these projections.</p>';
  if (!ds.applicable) {
    const why = {
      no_outside_debt_modeled: 'No loan is modeled. Owner capital covers the capital requirement, so there is no debt service.',
      financing_not_debt: 'No loan is modeled: the outside capital is equity, which carries no scheduled repayments.',
      financing_not_decided: 'No loan is modeled; the form of outside financing will be set with the funding source.',
      loan_size_unknown: 'A loan will be sought; its size is set once the owner contribution is final.',
      no_outside_money_sought: 'No loan is modeled; the capital requirement will be met by the owner.',
    }[ds.reason];
    return `<p>${esc(why || 'No loan is modeled in these projections.')}</p>`;
  }
  if (ds.terms) return modeledDebtServiceHtml(ds);
  const hasExisting = ds.existing_debts_disclosed && ds.existing_annual_debt_service_usd > 0;
  const existingMonthly = money2Sum(ds.existing_annual_debt_service_usd / 12);
  const rows = ds.scenarios
    .map(
      (sc) => `<tr><td>${esc(sc.label)} · ${esc((sc.annual_rate * 100).toFixed(1))}% over ${esc(sc.term_years)} years</td><td class="num">${esc(money(sc.monthly_payment_usd))}</td>${
        hasExisting ? `<td class="num">${esc(money(existingMonthly))}</td>` : ''
      }<td class="num">${esc(money(sc.annual_debt_service_usd))}</td>${sc.coverage.map((c) => `<td class="num">${c.dscr == null ? '—' : esc(String(c.dscr))}</td>`).join('')}</tr>`,
    )
    .join('');
  const yearHeaders = (ds.scenarios[0]?.coverage || []).map((c) => `<th class="num">Year ${esc(c.year)}</th>`).join('');
  const existing = ds.existing_debts_disclosed
    ? `<table class="doc-table"><tr><th>Existing obligation</th><th class="num">Monthly</th></tr>${(ds.existing_debts || [])
        .map((d) => `<tr><td>${esc(d.creditor || 'Obligation')}</td><td class="num">${esc(money(d.monthly_payment_usd || 0))}</td></tr>`)
        .join('')}<tr class="subtotal"><td>Annual total</td><td class="num">${esc(money(ds.existing_annual_debt_service_usd))}</td></tr></table>`
    : '';
  return `<p>${esc('Coverage is EBITDA divided by annual debt service. No terms have been quoted, so the payment is shown across a range of rates and terms. A dash marks a year with negative EBITDA.')}</p>
<table class="doc-table">
<tr><th>Terms</th><th class="num">New loan monthly</th>${hasExisting ? '<th class="num">Existing monthly</th>' : ''}<th class="num">Annual debt service</th>${yearHeaders}</tr>
${rows}
</table>
${existing}
<p>${esc(ds.services_debt_from_year_one ? `Year 1 EBITDA covers the payments at or above ${ds.reference_minimum}× under every scenario shown.` : `Year 1 EBITDA does not cover the payments while sales build; the shortfall on the hardest terms shown is ${money(ds.worst_year_one_shortfall_usd)}.`)}</p>`;
}

/**
 * The owner's personal financial statement and collateral, when entered. A blank form is not a
 * statement; the worksheet to complete lives in Founder's Notes.
 */
function lenderWorksheetsHtml(pkg) {
  if (!pkg) return '';
  const pfs = pkg.personal_financial_statement;
  const col = pkg.collateral;
  if (!pfs?.completed && !col?.completed) return '';
  const lineRows = (lines) => lines.filter((l) => l.amount_usd != null).map((l) => `<tr><td>${esc(l.label)}</td><td class="num">${esc(money(l.amount_usd))}</td></tr>`).join('');
  const parts = [];
  if (pfs?.completed) {
    parts.push(`<p>${esc('Summary of the owner’s personal financial position, on the lines of SBA Form 413.')}</p>
<table class="doc-table"><tr><th>Assets</th><th class="num">Amount</th></tr>${lineRows(pfs.assets)}<tr class="subtotal"><td>Total assets</td><td class="num">${esc(money(pfs.total_assets_usd))}</td></tr></table>
<table class="doc-table"><tr><th>Liabilities</th><th class="num">Amount</th></tr>${lineRows(pfs.liabilities)}<tr class="subtotal"><td>Total liabilities</td><td class="num">${esc(money(pfs.total_liabilities_usd))}</td></tr><tr class="grand-total"><td>Net worth</td><td class="num">${esc(money(pfs.net_worth_usd))}</td></tr></table>`);
  }
  if (col?.completed) {
    parts.push(`<p>${esc('Assets offered as security, at stated value net of existing liens.')}</p>
<table class="doc-table"><tr><th>Asset</th><th class="num">Stated value</th><th class="num">Existing lien</th><th class="num">Available equity</th></tr>${col.items
      .map((i) => `<tr><td>${esc(i.description)}</td><td class="num">${esc(money(i.estimated_value_usd))}</td><td class="num">${esc(money(i.existing_lien_usd))}</td><td class="num">${esc(money(i.available_equity_usd))}</td></tr>`)
      .join('')}<tr class="grand-total"><td>Available equity</td><td class="num"></td><td class="num"></td><td class="num">${esc(money(col.available_equity_usd))}</td></tr></table>${
      col.coverage_ratio != null ? `<p>${esc(`Available equity is ${col.coverage_ratio}× the ${money(col.loan_amount_usd)} requested, before the lender's advance rates.`)}</p>` : ''
    }`);
  }
  return parts.join('\n');
}

